        className="flex max-h-[90dvh] w-full max-w-lg flex-col rounded-3xl border border-border/80 bg-background/95 p-5 sm:p-7 shadow-2xl backdrop-blur-md animate-in zoom-in-95 duration-200 overflow-hidden"
        onClick={(e) => e.stopPropagation()}
        dir={isAr ? "rtl" : "ltr"}
      >
        <div className="flex shrink-0 items-start justify-between border-b border-border/60 pb-4">
          <div className="flex items-center gap-3.5">
            <div className="grid size-11 place-items-center rounded-2xl border border-primary/20 bg-primary/10 text-primary shadow-sm">
              <User className="size-5" />
            </div>
            <div>
              <h3 className="text-lg font-bold tracking-tight text-foreground">
                {edit.id
                  ? isAr
                    ? "تعديل بيانات العميل"
                    : "Edit Customer Profile"
                  : isAr
                    ? "إضافة عميل جديد"
                    : "New Customer Registration"}
              </h3>
              <p className="mt-0.5 text-xs text-muted-foreground">
                {isAr
                  ? "سجل البيانات الأساسية ومعلومات التواصل والحد الائتماني"
                  : "Fill in identity, contact info, and credit terms"}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="grid size-8 place-items-center rounded-full bg-surface-2 text-muted-foreground transition hover:text-foreground cursor-pointer"
          >
            <X className="size-4" />
          </button>
        </div>

        <form
          onSubmit={(e) => {
            e.preventDefault();
            void save();
          }}
          className="flex min-h-0 flex-1 flex-col mt-4"
        >
          <div className="flex-1 overflow-y-auto space-y-4 pe-1 custom-scrollbar">
            {/* Section 1: Identity */}
            <div className="space-y-3">
              {isLockedCashCustomer && (
                <div className="flex items-center gap-2 rounded-2xl border border-amber-500/30 bg-amber-500/10 p-3 text-xs font-semibold text-amber-700 dark:text-amber-300">
                  <Lock className="size-4 shrink-0 text-amber-500" />
                  <span>
                    {isAr
                      ? "هذا حساب «العميل النقدي» النظامي المعتمد للمبيعات الفورية، واسمه وحالته محميان لضمان استقرار نقاط البيع."
                      : "This is the official Cash Customer account; name and status are locked for POS integrity."}
                  </span>
                </div>
              )}
              <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                <Sparkles className="size-3.5 text-primary" />
                <span>{isAr ? "البيانات الأساسية" : "Primary Information"}</span>
              </div>
              <div>
                <label className="mb-1.5 block text-xs font-medium text-foreground">
                  {t("common.name")} <span className="text-rose-500">*</span>
                </label>
                <div className="relative">
                  <User className="pointer-events-none absolute start-3.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                  <input
                    required
                    disabled={isLockedCashCustomer}
                    autoFocus={!isLockedCashCustomer}
                    value={edit.name ?? ""}
                    onChange={(e) => setEdit({ ...edit, name: e.target.value })}
                    placeholder={isAr ? "اسم العميل أو المؤسسة" : "Customer or Company Name"}
                    className="h-12 w-full rounded-2xl border border-border/80 bg-surface/80 px-4 ps-10 text-sm font-medium transition placeholder:text-muted-foreground focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20 disabled:cursor-not-allowed disabled:opacity-60"
                  />
                </div>
              </div>
            </div>

            {/* Section 2: Contact */}
            <div className="space-y-3 pt-1">
              <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                <Phone className="size-3.5 text-primary" />
                <span>{isAr ? "بيانات الاتصال والتواصل" : "Contact Details"}</span>
              </div>

              {/* Phone Input with Country Selector */}
              <div>
                <label className="mb-1.5 block text-xs font-medium text-foreground">
                  {isAr ? "رقم الهاتف" : "Phone Number"}
                </label>
                <div className="flex gap-2">
                  <CountrySelector value={country} onChange={setCountry} disabled={saving} />
                  <div className="relative flex-1">
                    <Phone className="pointer-events-none absolute start-3.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                    <input
                      type="tel"
                      dir="ltr"
                      disabled={saving}
                      value={phone}
                      onChange={(e) => setPhone(e.target.value)}
                      placeholder="772217218"
                      maxLength={15}
                      className="h-12 w-full rounded-2xl border border-border/80 bg-surface/80 px-4 ps-10 text-right text-sm font-medium transition placeholder:text-muted-foreground focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
                    />
                  </div>
                </div>
                <p className="mt-1 text-[10px] text-muted-foreground">
                  {isAr
                    ? "الرمز الدولي الافتراضي: اليمن (+967). يمكنك تغيير الدولة من القائمة."
                    : "Default dial code: Yemen (+967). You can select another country."}
                </p>
              </div>

              <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                <div>
                  <label className="mb-1.5 block text-xs font-medium text-foreground">
                    {t("common.email")}
                  </label>
                  <div className="relative">
                    <Mail className="pointer-events-none absolute start-3.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                    <input
                      type="email"
                      dir="ltr"
                      value={edit.email ?? ""}
                      onChange={(e) => setEdit({ ...edit, email: e.target.value })}
                      placeholder="customer@domain.com"
                      className="h-12 w-full rounded-2xl border border-border/80 bg-surface/80 px-4 ps-10 text-right text-sm font-medium transition placeholder:text-muted-foreground focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
                    />
                  </div>
                </div>
                <div>
                  <label className="mb-1.5 block text-xs font-medium text-foreground">
                    {isAr ? "العنوان أو المدينة" : "Address"}
                  </label>
                  <div className="relative">
                    <MapPin className="pointer-events-none absolute start-3.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                    <input
                      value={edit.address ?? ""}
                      onChange={(e) => setEdit({ ...edit, address: e.target.value })}
                      placeholder={isAr ? "المدينة، الحي، الشارع" : "City, District, Street"}
                      className="h-12 w-full rounded-2xl border border-border/80 bg-surface/80 px-4 ps-10 text-sm font-medium transition placeholder:text-muted-foreground focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
                    />
                  </div>
                </div>
              </div>
            </div>

            {/* Section 3: Credit & status */}
            <div className="space-y-3 pt-1">
              <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                <Wallet className="size-3.5 text-primary" />
                <span>{isAr ? "الحد الائتماني والحالة" : "Credit & Status"}</span>
              </div>
              <div>
                <label className="mb-1.5 block text-xs font-medium text-foreground">
                  {isAr ? "حد الائتمان المسموح" : "Credit Limit"}
                </label>
                <AmountInput
                  min={0}
                  showInWords={false}
                  aria-label={isAr ? "حد الائتمان المسموح" : "Credit limit"}
                  value={edit.credit_limit ?? null}
                  onValueChange={(v) => setEdit({ ...edit, credit_limit: v ?? 0 })}
                  className="h-12 rounded-2xl text-sm font-medium"
                />
                <p className="mt-1 text-[10px] text-muted-foreground">
                  {isAr
                    ? "أقصى مبلغ يمكن للعميل شراؤه بالآجل قبل إيقاف الفواتير."
                    : "Maximum allowable credit before blocking future credit sales."}
                </p>
              </div>

              <div className="flex items-center justify-between rounded-2xl border border-border/70 bg-surface/60 p-3.5">
                <div>
                  <p className="text-xs font-bold text-foreground">
                    {isAr ? "حالة تفعيل العميل" : "Customer Active Status"}
                  </p>
                  <p className="mt-0.5 text-[10px] text-muted-foreground">
                    {isAr
                      ? "العميل النشط يظهر تلقائياً في شاشات البيع ونقاط البيع"
                      : "Active customers appear in POS and sales invoices"}
                  </p>
                </div>
                <button
                  type="button"
                  disabled={isLockedCashCustomer}
                  onClick={() =>
                    !isLockedCashCustomer &&
                    setEdit({ ...edit, is_active: !(edit.is_active ?? true) })
                  }
                  className={`relative inline-flex h-6 w-11 shrink-0 rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none ${
                    isLockedCashCustomer ? "cursor-not-allowed opacity-60" : "cursor-pointer"
                  } ${(edit.is_active ?? true) ? "bg-primary" : "bg-muted"}`}
                >
                  <span
                    className={`pointer-events-none inline-block size-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${
                      (edit.is_active ?? true) ? "translate-x-5" : "translate-x-0"
                    }`}
                  />
                </button>
              </div>
            </div>

            {hint ? <p className="text-[11px] text-muted-foreground">{hint}</p> : null}
          </div>

          {/* Footer buttons styled exactly like the filter sheet footer in Vortex UI */}
          <div className="flex items-center gap-2 w-full pt-4 mt-3 border-t border-border/60">
            <button
              type="submit"
              disabled={saving}
              className="flex-1 h-12 rounded-2xl bg-foreground text-background font-bold text-xs sm:text-sm flex items-center justify-center gap-2 shadow-lg shadow-foreground/15 hover:opacity-95 active:scale-[0.98] transition cursor-pointer disabled:opacity-50"
            >
              {saving ? (
                <Loader2 className="size-4 animate-spin text-primary" />
              ) : (
                <Check className="size-4 text-primary" />
              )}
              <span>
                {saving
                  ? isAr
                    ? "جاري الحفظ..."
                    : "Saving..."
                  : edit.id
                    ? isAr
                      ? "حفظ التعديلات"
                      : "Save Changes"
                    : isAr
                      ? "إضافة عميل"
                      : "Add Customer"}
              </span>
            </button>
            <button
              type="button"
              disabled={saving}
              onClick={onClose}
              className="h-12 px-5 sm:px-6 rounded-2xl bg-muted/80 text-muted-foreground hover:text-foreground font-bold text-xs sm:text-sm flex items-center justify-center gap-1.5 transition active:scale-[0.98] cursor-pointer"
            >
              <span>{isAr ? "إلغاء" : "Cancel"}</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import { Building2, X, Loader2, Lock } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useI18n } from "@/lib/i18n";
import { toast } from "sonner";

export function isSystemCashSupplierName(name?: string | null): boolean {
  if (!name) return false;
  const n = name.trim().toLowerCase();
  return n === "مورد نقدي" || n === "cash supplier" || n === "walk-in supplier";
}

export interface SupplierRecord {
  id: string;
  name: string;
  phone: string | null;
  email: string | null;
  address: string | null;
  balance?: number;
  is_active?: boolean;
  created_at?: string;
}

export interface SupplierFormDialogProps {
  open: boolean;
  onClose: () => void;
  initial?: Partial<SupplierRecord> | null;
  onSaved?: (record: SupplierRecord) => void;
  onSavedComplete?: () => void;
  hint?: string;
}

export function SupplierFormDialog({
  open,
  onClose,
  initial,
  onSaved,
  onSavedComplete,
  hint,
}: SupplierFormDialogProps) {
  const { t, lang } = useI18n();
  const isAr = lang === "ar";
  const [edit, setEdit] = useState<Partial<SupplierRecord>>(initial ?? {});
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (open) setEdit(initial ?? {});
  }, [open, initial]);

  if (!open) return null;

  const isLockedCashSupplier = Boolean(edit.id && isSystemCashSupplierName(initial?.name));

  async function save() {
    if (saving) return;
    if (!edit?.name?.trim()) return toast.error(t("suppliers.name_required"));
    if (isLockedCashSupplier) {
      if (edit.name.trim() !== (initial?.name ?? "").trim()) {
        toast.error(
          isAr
            ? "لا يمكن تعديل اسم «المورد النقدي» — حساب نظامي رسمي."
            : "Cannot change cash supplier name.",
        );
        return;
      }
      if (edit.is_active === false) {
        toast.error(
          isAr
            ? "لا يمكن تعطيل «المورد النقدي» — أساسي للمشتريات."
            : "Cannot deactivate cash supplier.",
        );
        return;
      }
    }
    setSaving(true);
    const payload = {
      name: edit.name.trim(),
      phone: edit.phone || null,
      email: edit.email || null,
      address: edit.address || null,
      is_active: isLockedCashSupplier ? true : (edit.is_active ?? true),
    };
    const { data, error } = edit.id
      ? await supabase.from("suppliers").update(payload).eq("id", edit.id).select("*").single()
      : await supabase.from("suppliers").insert(payload).select("*").single();
    setSaving(false);
    if (error) return toast.error(error.message);
    toast.success(edit.id ? t("common.updated") : t("common.created"));
    if (data) onSaved?.(data as SupplierRecord);
    onSavedComplete?.();
    onClose();
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-3 sm:p-4 backdrop-blur-sm animate-in fade-in duration-200 overflow-y-auto"
      onClick={() => !saving && onClose()}
    >
      <div
        className="flex max-h-[90dvh] w-full max-w-md flex-col rounded-3xl border border-border/80 bg-surface p-5 sm:p-6 shadow-2xl backdrop-blur-md overflow-hidden"
        onClick={(e) => e.stopPropagation()}
        dir={isAr ? "rtl" : "ltr"}
      >
        <div className="mb-4 flex shrink-0 items-center justify-between border-b border-border/50 pb-3">
          <div className="flex items-center gap-2">
            <Building2 className="size-4 text-primary" />
            <h3 className="text-lg font-semibold">
              {edit.id ? t("suppliers.edit") : t("suppliers.new")}
            </h3>
          </div>
          <button
            onClick={onClose}
            className="rounded-full p-1.5 hover:bg-surface-2 text-muted-foreground hover:text-foreground transition"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        <form
          onSubmit={(e) => {
            e.preventDefault();
            void save();
          }}
          className="flex min-h-0 flex-1 flex-col"
        >
          <div className="flex-1 overflow-y-auto space-y-3.5 pe-1 custom-scrollbar">
            {isLockedCashSupplier && (
              <div className="flex items-center gap-2 rounded-2xl border border-amber-500/30 bg-amber-500/10 p-3 text-xs font-semibold text-amber-700 dark:text-amber-300">
                <Lock className="size-4 shrink-0 text-amber-500" />
                <span>
                  {isAr
                    ? "هذا حساب «المورد النقدي» النظامي المعتمد للمشتريات النقدية، واسمه وحالته محميان لضمان استقرار العمليات."
                    : "Official Cash Supplier account; name and status are locked for system stability."}
                </span>
              </div>
            )}
            <div>
              <label className="mb-1.5 block text-xs font-medium text-muted-foreground">
                {t("common.name")} *
              </label>
              <input
                disabled={isLockedCashSupplier}
                autoFocus={!isLockedCashSupplier}
                value={edit.name ?? ""}
                onChange={(e) => setEdit({ ...edit, name: e.target.value })}
                className="h-10 w-full rounded-xl border border-input bg-surface px-3 text-sm focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20 disabled:cursor-not-allowed disabled:opacity-60"
              />
            </div>
            <div>
              <label className="mb-1.5 block text-xs font-medium text-muted-foreground">
                {t("common.phone")}
              </label>
              <input
                value={edit.phone ?? ""}
                onChange={(e) => setEdit({ ...edit, phone: e.target.value })}
                className="h-10 w-full rounded-xl border border-input bg-surface px-3 text-sm focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20"
              />
            </div>
            <div>
              <label className="mb-1.5 block text-xs font-medium text-muted-foreground">
                {t("common.email")}
              </label>
              <input
                type="email"
                value={edit.email ?? ""}
                onChange={(e) => setEdit({ ...edit, email: e.target.value })}
                className="h-10 w-full rounded-xl border border-input bg-surface px-3 text-sm focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20"
              />
            </div>
            <div>
              <label className="mb-1.5 block text-xs font-medium text-muted-foreground">
                {t("common.address")}
              </label>
              <input
                value={edit.address ?? ""}
                onChange={(e) => setEdit({ ...edit, address: e.target.value })}
                className="h-10 w-full rounded-xl border border-input bg-surface px-3 text-sm focus:border-ring focus:outline-none focus:ring-2 focus:ring-ring/20"
              />
            </div>
            <label
              className={`flex items-center gap-2 text-sm pt-1 ${isLockedCashSupplier ? "cursor-not-allowed opacity-60" : "cursor-pointer"}`}
            >
              <input
                type="checkbox"
                disabled={isLockedCashSupplier}
                checked={edit.is_active ?? true}
                onChange={(e) =>
                  !isLockedCashSupplier && setEdit({ ...edit, is_active: e.target.checked })
                }
                className="h-4 w-4 rounded border-border text-primary focus:ring-primary/20"
              />
              {t("common.active")}
            </label>

            {hint ? <p className="text-[11px] text-muted-foreground pt-1">{hint}</p> : null}
          </div>

          <div className="mt-4 flex shrink-0 justify-end gap-2 border-t border-border/50 pt-3">
            <button
              type="button"
              onClick={onClose}
              className="h-10 rounded-xl border border-border px-4 text-sm font-medium hover:bg-surface-2"
            >
              {t("common.cancel")}
            </button>
            <button
              type="submit"
              disabled={saving}
              className="flex h-10 items-center justify-center gap-1.5 rounded-xl bg-primary px-5 text-sm font-bold text-primary-foreground transition hover:opacity-90 disabled:pointer-events-none disabled:opacity-50 shadow-md shadow-primary/20"
            >
              {saving && <Loader2 className="h-4 w-4 animate-spin" />}
              <span>{saving ? (isAr ? "جاري الحفظ..." : "Saving...") : t("common.save")}</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

/**
 * Market-Hub ERP — How an item's role is shown, in one place.
 *
 * WHY THIS EXISTS
 * ---------------
 * The data model already separates what a thing IS from what it DOES:
 *
 *   item_nature        GOOD | SERVICE        — is it sellable stock or a service
 *   inventory_policy   TRACKED | UNTRACKED | CUSTOMER_OWNED
 *   item_class         RAW_MATERIAL | FINISHED_GOOD | BY_PRODUCT |
 *                      SERVICE | NON_STOCK_ITEM  — what role it plays
 *
 * A mill's operator does not think in those words. They think "grain", "flour",
 * "bran", "milling fee", "sack". Reading raw enum codes in a table is how a
 * column ends up ignored, and then the operator cannot tell a sack of wheat from
 * a sack of flour at a glance — which is the one distinction that matters most
 * on a screen full of milled goods.
 *
 * So each class gets a colour and an Arabic name, and both the products and
 * inventory screens use these badges. The colour is not decoration: it is how
 * the eye separates raw grain from finished flour without reading a word.
 *
 * THE FOUR ROLES THAT MATTER ON A MILL FLOOR
 *   RAW_MATERIAL    ماكينة     grain received, waiting to be milled
 *   FINISHED_GOOD   منتجات نهائية  flour the mill sells
 *   BY_PRODUCT      نواتج     bran and semolina — produced BY milling
 *   SERVICE         خدمات      the milling fee itself, and sacks sold
 *   NON_STOCK_ITEM  مستهلكات    consumables that are not the product
 */
import type { ReactNode } from "react";

export type ItemClass =
  "RAW_MATERIAL" | "FINISHED_GOOD" | "BY_PRODUCT" | "SERVICE" | "NON_STOCK_ITEM";

export interface ItemRoleStyle {
  labelAr: string;
  labelEn: string;
  /** Tailwind classes. Kept literal so the JIT compiler can see them. */
  chip: string;
  dot: string;
  /** A short glyph so the distinction survives a narrow column. */
  mark: string;
}

export const ITEM_ROLE_STYLES: Record<ItemClass, ItemRoleStyle> = {
  RAW_MATERIAL: {
    labelAr: "مادة خام",
    labelEn: "Raw material",
    chip: "bg-amber-500/15 text-amber-600 border-amber-500/30 dark:text-amber-300",
    dot: "bg-amber-500",
    mark: "◆",
  },
  FINISHED_GOOD: {
    labelAr: "منتج نهائي",
    labelEn: "Finished good",
    chip: "bg-emerald-500/15 text-emerald-600 border-emerald-500/30 dark:text-emerald-300",
    dot: "bg-emerald-500",
    mark: "●",
  },
  BY_PRODUCT: {
    labelAr: "ناتج طحن",
    labelEn: "By-product",
    chip: "bg-orange-500/15 text-orange-600 border-orange-500/30 dark:text-orange-300",
    dot: "bg-orange-500",
    mark: "◐",
  },
  SERVICE: {
    labelAr: "خدمة",
    labelEn: "Service",
    chip: "bg-violet-500/15 text-violet-600 border-violet-500/30 dark:text-violet-300",
    dot: "bg-violet-500",
    mark: "◇",
  },
  NON_STOCK_ITEM: {
    labelAr: "مستهلكات",
    labelEn: "Non-stock",
    chip: "bg-slate-500/15 text-slate-600 border-slate-500/30 dark:text-slate-300",
    dot: "bg-slate-500",
    mark: "○",
  },
};

/**
 * The role to display. Falls back through the two columns that are always
 * present so a legacy product saved before item_class existed still gets a
 * sensible colour rather than a blank.
 */
export function resolveItemClass(
  itemClass: string | null | undefined,
  itemNature: string | null | undefined,
  inventoryPolicy: string | null | undefined,
): ItemClass {
  if (itemClass && itemClass in ITEM_ROLE_STYLES) return itemClass as ItemClass;
  if (itemNature === "SERVICE") return "SERVICE";
  if (inventoryPolicy === "CUSTOMER_OWNED") return "RAW_MATERIAL";
  return "FINISHED_GOOD";
}

export function itemRoleStyle(
  itemClass: string | null | undefined,
  itemNature?: string | null,
  inventoryPolicy?: string | null,
  isRtl = true,
): ItemRoleStyle {
  const s = ITEM_ROLE_STYLES[resolveItemClass(itemClass, itemNature, inventoryPolicy)];
  return { ...s, labelAr: s.labelAr, labelEn: s.labelEn };
}

export function itemRoleLabel(
  itemClass: string | null | undefined,
  itemNature?: string | null,
  inventoryPolicy?: string | null,
  isRtl = true,
): string {
  const s = ITEM_ROLE_STYLES[resolveItemClass(itemClass, itemNature, inventoryPolicy)];
  return isRtl ? s.labelAr : s.labelEn;
}

/** The coloured role badge used in table cells and cards. */
export function ItemRoleBadge({
  itemClass,
  itemNature,
  inventoryPolicy,
  isRtl = true,
  compact = false,
}: {
  itemClass?: string | null;
  itemNature?: string | null;
  inventoryPolicy?: string | null;
  isRtl?: boolean;
  compact?: boolean;
}): ReactNode {
  const style = ITEM_ROLE_STYLES[resolveItemClass(itemClass, itemNature, inventoryPolicy)];
  const label = isRtl ? style.labelAr : style.labelEn;
  return (
    <span
      className={`inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[10px] font-semibold whitespace-nowrap ${style.chip}`}
      title={label}
    >
      <span className="text-[9px] leading-none">{style.mark}</span>
      {/*
        على البطاقات يُرسَل compact لتوفير المساحة، لكن إخفاء النص تماماً
        يترك رمزاً ملوّناً لا يُعرف معناه إلا بتمرير المؤشر. الرمز يبقى،
        والنص يظهر على الشاشات العرضية حيث تسمح المساحة بالقراءة.
      */}
      <span className={compact ? "hidden sm:inline" : undefined}>{label}</span>
    </span>
  );
}

/** A bare colour dot, for dense tables where a full chip would crowd the row. */
export function ItemRoleDot({
  itemClass,
  itemNature,
  inventoryPolicy,
  isRtl = true,
}: {
  itemClass?: string | null;
  itemNature?: string | null;
  inventoryPolicy?: string | null;
  isRtl?: boolean;
}): ReactNode {
  const style = ITEM_ROLE_STYLES[resolveItemClass(itemClass, itemNature, inventoryPolicy)];
  return (
    <span
      className={`inline-block h-2 w-2 shrink-0 rounded-full ${style.dot}`}
      title={isRtl ? style.labelAr : style.labelEn}
    />
  );
}

import React, { useState, useEffect } from "react";
import { Package, Scale, ArrowRightLeft } from "lucide-react";
import { cn } from "@/lib/utils";
import { Mono, fmtNum } from "@/components/milling/milling-ui";

export interface BagWeightValue {
  bags: number;
  capacityKg: number;
  totalKg: number;
  mode: "bags" | "kg";
}

export interface BagWeightInputProps {
  label?: string;
  mode?: "bags" | "kg";
  bags?: number | string;
  capacityKg?: number | string;
  totalKg?: number | string;
  defaultCapacity?: number;
  unitPriceBag?: number;
  unitPriceKg?: number;
  showPricing?: boolean;
  currencySymbol?: string;
  allowCustomCapacity?: boolean;
  className?: string;
  disabled?: boolean;
  onChange: (val: BagWeightValue) => void;
  onPriceChange?: (val: { unitPriceBag: number; unitPriceKg: number }) => void;
}

export const STANDARD_BAG_CAPACITIES = [50, 25, 10, 5];

export function BagWeightInput({
  label,
  mode: initialMode = "bags",
  bags: controlledBags,
  capacityKg: controlledCapacity,
  totalKg: controlledTotalKg,
  defaultCapacity = 50,
  unitPriceBag,
  unitPriceKg,
  showPricing = false,
  currencySymbol = "ريال",
  allowCustomCapacity = true,
  className,
  disabled = false,
  onChange,
  onPriceChange,
}: BagWeightInputProps) {
  const [mode, setMode] = useState<"bags" | "kg">(initialMode);
  const [internalBags, setInternalBags] = useState<string>(
    controlledBags !== undefined ? String(controlledBags) : "",
  );
  const [internalCapacity, setInternalCapacity] = useState<number>(
    Number(controlledCapacity) || defaultCapacity,
  );
  const [customCapacity, setCustomCapacity] = useState<string>("");
  const [isCustomCapacity, setIsCustomCapacity] = useState<boolean>(false);
  const [internalTotalKg, setInternalTotalKg] = useState<string>(
    controlledTotalKg !== undefined ? String(controlledTotalKg) : "",
  );

  // Sync incoming props
  useEffect(() => {
    if (controlledBags !== undefined && String(controlledBags) !== internalBags) {
      setInternalBags(controlledBags ? String(controlledBags) : "");
    }
  }, [controlledBags]);

  useEffect(() => {
    if (controlledTotalKg !== undefined && String(controlledTotalKg) !== internalTotalKg) {
      setInternalTotalKg(controlledTotalKg ? String(controlledTotalKg) : "");
    }
  }, [controlledTotalKg]);

  useEffect(() => {
    if (controlledCapacity !== undefined) {
      const cap = Number(controlledCapacity);
      if (cap > 0) {
        setInternalCapacity(cap);
        if (!STANDARD_BAG_CAPACITIES.includes(cap)) {
          setIsCustomCapacity(true);
          setCustomCapacity(String(cap));
        } else {
          setIsCustomCapacity(false);
        }
      }
    }
  }, [controlledCapacity]);

  const activeCapacity = isCustomCapacity ? Number(customCapacity) || 0 : internalCapacity;

  const handleBagsChange = (bagsStr: string) => {
    setInternalBags(bagsStr);
    const b = Number(bagsStr) || 0;
    const computedTotal = activeCapacity > 0 ? b * activeCapacity : 0;
    setInternalTotalKg(computedTotal > 0 ? String(computedTotal) : "");

    onChange({
      bags: b,
      capacityKg: activeCapacity,
      totalKg: computedTotal,
      mode: "bags",
    });
  };

  const handleCapacityChange = (cap: number, customVal?: string) => {
    if (cap === -1) {
      setIsCustomCapacity(true);
      const customNum = Number(customVal !== undefined ? customVal : customCapacity) || 0;
      setCustomCapacity(customVal !== undefined ? customVal : customCapacity);
      const b = Number(internalBags) || 0;
      const computedTotal = customNum > 0 ? b * customNum : 0;
      setInternalTotalKg(computedTotal > 0 ? String(computedTotal) : "");

      onChange({
        bags: b,
        capacityKg: customNum,
        totalKg: computedTotal,
        mode,
      });
      return;
    }

    setIsCustomCapacity(false);
    setInternalCapacity(cap);
    const b = Number(internalBags) || 0;
    const computedTotal = cap > 0 ? b * cap : 0;
    setInternalTotalKg(computedTotal > 0 ? String(computedTotal) : "");

    onChange({
      bags: b,
      capacityKg: cap,
      totalKg: computedTotal,
      mode,
    });
  };

  const handleTotalKgChange = (kgStr: string) => {
    setInternalTotalKg(kgStr);
    const kg = Number(kgStr) || 0;
    let b = 0;
    if (activeCapacity > 0) {
      b = kg / activeCapacity;
      setInternalBags(b > 0 ? (Number.isInteger(b) ? String(b) : b.toFixed(2)) : "");
    }

    onChange({
      bags: b,
      capacityKg: activeCapacity,
      totalKg: kg,
      mode: "kg",
    });
  };

  const toggleMode = () => {
    const nextMode = mode === "bags" ? "kg" : "bags";
    setMode(nextMode);
  };

  return (
    <div
      className={cn(
        "rounded-2xl border border-border/80 bg-surface/50 p-3.5 space-y-3 transition",
        className,
      )}
    >
      {/* Header with Mode Toggle */}
      <div className="flex items-center justify-between gap-2">
        <div className="flex items-center gap-1.5 text-xs font-bold text-foreground">
          {mode === "bags" ? (
            <Package className="h-4 w-4 text-amber-500" />
          ) : (
            <Scale className="h-4 w-4 text-sky-500" />
          )}
          <span>
            {label || (mode === "bags" ? "إدخال بالأكياس والسعة" : "إدخال بالوزن المباشر")}
          </span>
        </div>

        <button
          type="button"
          disabled={disabled}
          onClick={toggleMode}
          className="inline-flex items-center gap-1.5 rounded-lg border border-border bg-surface px-2.5 py-1 text-[11px] font-semibold text-muted-foreground hover:bg-muted hover:text-foreground transition active:scale-95 disabled:opacity-50"
          title="التبديل بين إدخال الأكياس والوزن المباشر"
        >
          <ArrowRightLeft className="h-3 w-3" />
          <span>{mode === "bags" ? "تحويل لكيلوجرام مباشر" : "تحويل للأكياس"}</span>
        </button>
      </div>

      {mode === "bags" ? (
        <div className="space-y-3">
          <div className="grid gap-3 sm:grid-cols-2">
            {/* Bags Count */}
            <div>
              <label className="mb-1 block text-[11px] font-semibold text-muted-foreground">
                عدد الأكياس *
              </label>
              <input
                type="number"
                min={0}
                step="any"
                inputMode="decimal"
                disabled={disabled}
                placeholder="0"
                value={internalBags}
                onChange={(e) => handleBagsChange(e.target.value)}
                className="h-10 w-full rounded-xl border border-border/80 bg-surface px-3 text-sm font-semibold text-foreground outline-none transition focus:border-amber-500 focus:ring-1 focus:ring-amber-500 disabled:opacity-50"
              />
            </div>

            {/* Bag Capacity Selection */}
            <div>
              <label className="mb-1 block text-[11px] font-semibold text-muted-foreground">
                سعة الكيس (كجم) *
              </label>
              <div className="flex gap-1">
                <select
                  disabled={disabled}
                  value={isCustomCapacity ? "custom" : String(internalCapacity)}
                  onChange={(e) => {
                    const val = e.target.value;
                    if (val === "custom") {
                      handleCapacityChange(-1);
                    } else {
                      handleCapacityChange(Number(val));
                    }
                  }}
                  className="h-10 flex-1 rounded-xl border border-border/80 bg-surface px-2.5 text-xs font-semibold text-foreground outline-none transition focus:border-amber-500 focus:ring-1 focus:ring-amber-500 disabled:opacity-50"
                >
                  {STANDARD_BAG_CAPACITIES.map((cap) => (
                    <option key={cap} value={String(cap)}>
                      كيس {cap} كجم
                    </option>
                  ))}
                  {allowCustomCapacity && <option value="custom">سعة مخصصة...</option>}
                </select>

                {isCustomCapacity && (
                  <input
                    type="number"
                    min={0.1}
                    step="0.1"
                    disabled={disabled}
                    placeholder="كجم"
                    value={customCapacity}
                    onChange={(e) => handleCapacityChange(-1, e.target.value)}
                    className="h-10 w-24 rounded-xl border border-border/80 bg-surface px-2.5 text-xs font-semibold text-foreground outline-none transition focus:border-amber-500 disabled:opacity-50"
                  />
                )}
              </div>
            </div>
          </div>

          {/* Derivation summary strip */}
          <div className="flex flex-wrap items-center justify-between gap-2 rounded-xl bg-amber-500/10 border border-amber-500/20 px-3 py-2 text-xs">
            <span className="text-amber-800 dark:text-amber-200 font-medium">
              إجمالي الوزن المحسوب:
            </span>
            <span className="font-bold text-amber-900 dark:text-amber-100">
              <Mono>{fmtNum(Number(internalTotalKg) || 0)}</Mono> كجم
            </span>
          </div>
        </div>
      ) : (
        /* Direct Kg Mode */
        <div className="space-y-3">
          <div className="grid gap-3 sm:grid-cols-2">
            <div>
              <label className="mb-1 block text-[11px] font-semibold text-muted-foreground">
                الوزن الإجمالي (كجم) *
              </label>
              <input
                type="number"
                min={0}
                step="any"
                inputMode="decimal"
                disabled={disabled}
                placeholder="0.00"
                value={internalTotalKg}
                onChange={(e) => handleTotalKgChange(e.target.value)}
                className="h-10 w-full rounded-xl border border-border/80 bg-surface px-3 text-sm font-semibold text-foreground outline-none transition focus:border-sky-500 focus:ring-1 focus:ring-sky-500 disabled:opacity-50"
              />
            </div>

            <div>
              <label className="mb-1 block text-[11px] font-semibold text-muted-foreground">
                معيار سعة الكيس للتحويل (كجم)
              </label>
              <select
                disabled={disabled}
                value={isCustomCapacity ? "custom" : String(internalCapacity)}
                onChange={(e) => {
                  const val = e.target.value;
                  if (val === "custom") {
                    handleCapacityChange(-1);
                  } else {
                    handleCapacityChange(Number(val));
                  }
                }}
                className="h-10 w-full rounded-xl border border-border/80 bg-surface px-2.5 text-xs font-semibold text-foreground outline-none transition focus:border-sky-500 focus:ring-1 focus:ring-sky-500 disabled:opacity-50"
              >
                {STANDARD_BAG_CAPACITIES.map((cap) => (
                  <option key={cap} value={String(cap)}>
                    كيس {cap} كجم
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Derivation summary strip */}
          <div className="flex flex-wrap items-center justify-between gap-2 rounded-xl bg-sky-500/10 border border-sky-500/20 px-3 py-2 text-xs">
            <span className="text-sky-800 dark:text-sky-200 font-medium">
              العدد المشتق من الأكياس:
            </span>
            <span className="font-bold text-sky-900 dark:text-sky-100">
              <Mono>{fmtNum(Number(internalBags) || 0)}</Mono> كيس سعة {activeCapacity} كجم
            </span>
          </div>
        </div>
      )}

      {/* Pricing Synchronization Section (Optional) */}
      {showPricing && (
        <div className="border-t border-border/60 pt-2.5 grid gap-3 sm:grid-cols-2 text-xs">
          <div>
            <label className="mb-1 block text-[11px] font-semibold text-muted-foreground">
              سعر الكيس ({currencySymbol})
            </label>
            <input
              type="number"
              min={0}
              step="any"
              disabled={disabled}
              placeholder="0.00"
              value={unitPriceBag !== undefined ? unitPriceBag : ""}
              onChange={(e) => {
                const bagP = Number(e.target.value) || 0;
                const kgP = activeCapacity > 0 ? bagP / activeCapacity : 0;
                onPriceChange?.({ unitPriceBag: bagP, unitPriceKg: kgP });
              }}
              className="h-9 w-full rounded-lg border border-border/80 bg-surface px-2.5 text-xs font-mono font-semibold text-foreground outline-none focus:border-primary"
            />
          </div>

          <div>
            <label className="mb-1 block text-[11px] font-semibold text-muted-foreground">
              سعر الكيلو ({currencySymbol}/كجم)
            </label>
            <input
              type="number"
              min={0}
              step="any"
              disabled={disabled}
              placeholder="0.00"
              value={unitPriceKg !== undefined ? unitPriceKg : ""}
              onChange={(e) => {
                const kgP = Number(e.target.value) || 0;
                const bagP = activeCapacity > 0 ? kgP * activeCapacity : 0;
                onPriceChange?.({ unitPriceBag: bagP, unitPriceKg: kgP });
              }}
              className="h-9 w-full rounded-lg border border-border/80 bg-surface px-2.5 text-xs font-mono font-semibold text-foreground outline-none focus:border-primary"
            />
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * خطوات المستند الموحد داخل كاونتر المطحنة.
 * لا تنشئ هذه الواجهة فاتورة أو مخزوناً مستقلاً: كل حركة تمر برقم المستند
 * الذي أُنشئ في الاستلام مع فاتورة المبيعات الرسمية.
 */
import { useState, type Dispatch, type SetStateAction, useEffect } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  Cog,
  PackageCheck,
  Plus,
  Trash2,
  Printer,
  Share2,
  Receipt,
  Scale,
  CheckCircle2,
  Clock,
  ArrowUpRight,
  AlertCircle,
} from "lucide-react";
import { Link } from "@tanstack/react-router";
import { toast } from "sonner";
import {
  deliverMillingServiceDocument,
  fetchMillingDocumentDetails,
  fetchOutputItems,
  processMillingServiceDocument,
  buildMillingDocumentUnifiedDoc,
  type CustodyLine,
  type MillingServiceDocumentCreated,
  type MillingDocumentDetails,
} from "@/lib/milling";
import {
  MillingField,
  MillingPanel,
  MillingSectionTitle,
  MillingSelect,
  MillingTextarea,
  Pill,
  Mono,
  fmtNum,
} from "@/components/milling/milling-ui";
import { QuantityInput } from "@/components/ui/quantity-input";
import { UniversalPrintPreview } from "@/components/universal-print-preview";
import { UnifiedPrintModal, type MillingTicketStage } from "@/components/milling/unified-print-modal";
import { DocumentShareDialog } from "@/components/communication/document-share-dialog";
import type { PrintRequest } from "@/lib/printing";

export function MillingDocumentWorkflow({
  document,
  onClose,
}: {
  document: MillingServiceDocumentCreated;
  onClose?: () => void;
}) {
  const qc = useQueryClient();
  const [grainItemId, setGrainItemId] = useState("");
  const [bagsOut, setBagsOut] = useState("");
  const [kgOut, setKgOut] = useState("");
  const [outputs, setOutputs] = useState<CustodyLine[]>([{ itemId: "", bags: 0, kg: 0 }]);
  const [millingNotes, setMillingNotes] = useState("");
  const [deliveryLines, setDeliveryLines] = useState<CustodyLine[]>([
    { itemId: "", bags: 0, kg: 0 },
  ]);
  const [deliveryNotes, setDeliveryNotes] = useState("");

  // الطباعة والمشاركة
  const [printRequest, setPrintRequest] = useState<PrintRequest | null>(null);
  const [printStage, setPrintStage] = useState<MillingTicketStage>("intake");
  const [shareOpen, setShareOpen] = useState(false);

  const outputsCatalog = useQuery({
    queryKey: ["milling", "output-items"],
    queryFn: fetchOutputItems,
  });

  const docQuery = useQuery({
    queryKey: ["milling", "document-details", document.document_id],
    queryFn: () => fetchMillingDocumentDetails(document.document_id),
  });

  const details = docQuery.data;

  // الضبط التلقائي لصنف الحبوب المطحونة من حبوب المستند المستلمة
  useEffect(() => {
    if (details?.intakeGrain && !grainItemId) {
      setGrainItemId(details.intakeGrain.itemId);
      if (details.intakeGrain.bagsRemaining > 0) {
        setBagsOut(String(details.intakeGrain.bagsRemaining));
      }
      if (details.intakeGrain.kgRemaining > 0) {
        setKgOut(String(details.intakeGrain.kgRemaining));
      }
    }
  }, [details?.intakeGrain, grainItemId]);

  const process = useMutation({
    mutationFn: () =>
      processMillingServiceDocument({
        documentId: document.document_id,
        grainItemId,
        bagsOut: Number(bagsOut) || 0,
        kgOut: Number(kgOut) || 0,
        outputs,
        notes: millingNotes || undefined,
      }),
    onSuccess: (result) => {
      if (!result.ok) return toast.error(result.message || "تعذر تسجيل الطحن.");
      setBagsOut("");
      setKgOut("");
      setOutputs([{ itemId: "", bags: 0, kg: 0 }]);
      setMillingNotes("");
      void qc.invalidateQueries({ queryKey: ["milling"] });
      toast.success("تم تسجيل نواتج الطحن على المستند نفسه.");
    },
    onError: (error) => toast.error(error instanceof Error ? error.message : "خطأ غير متوقع"),
  });

  const deliver = useMutation({
    mutationFn: () =>
      deliverMillingServiceDocument({
        documentId: document.document_id,
        lines: deliveryLines,
        notes: deliveryNotes || undefined,
      }),
    onSuccess: (result) => {
      if (!result.ok) return toast.error(result.message || "تعذر تسجيل التسليم.");
      setDeliveryLines([{ itemId: "", bags: 0, kg: 0 }]);
      setDeliveryNotes("");
      void qc.invalidateQueries({ queryKey: ["milling"] });
      toast.success("تم تسجيل تسليم النواتج للعميل على المستند نفسه.");
    },
    onError: (error) => toast.error(error instanceof Error ? error.message : "خطأ غير متوقع"),
  });

  const hasGrainToProcess = Boolean(
    details?.intakeGrain &&
    (details.intakeGrain.bagsRemaining > 0 || details.intakeGrain.kgRemaining > 0),
  );

  const canProcess = Boolean(
    grainItemId &&
    (Number(bagsOut) > 0 || Number(kgOut) > 0) &&
    outputs.some((line) => line.itemId && (line.bags > 0 || line.kg > 0)),
  );

  const availableOutputsForDelivery = (details?.outputsSummary ?? []).filter(
    (o) => o.bagsRemaining > 0 || o.kgRemaining > 0,
  );

  const canDeliver =
    Boolean(details?.outputsSummary?.length) &&
    deliveryLines.some((line) => line.itemId && (line.bags > 0 || line.kg > 0));

  const handlePrint = (stage: "intake" | "milled" | "delivery") => {
    if (!details) return;
    setPrintStage(stage);
    const docData = buildMillingDocumentUnifiedDoc(details, stage);
    setPrintRequest({
      documentType: stage === "delivery" ? "delivery_note" : "mill_document",
      doc: docData,
    });
  };

  const invoice = details?.sales_invoices;
  const invTotal = Number(invoice?.total ?? 0);
  const invPaid = Number(invoice?.paid ?? 0);
  const invRemaining = Math.max(0, invTotal - invPaid);

  return (
    <section className="space-y-4">
      {/* شريط رأس المستند المفتوح */}
      <div className="flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-primary/30 bg-primary/5 p-4 shadow-xs">
        <div className="flex items-center gap-3">
          <div className="rounded-xl bg-amber-500/15 p-2 text-amber-600 dark:text-amber-400">
            <Scale className="h-5 w-5" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h3 className="text-sm font-bold text-foreground">
                مستند المطحنة:{" "}
                <Mono className="text-primary font-bold">{document.document_number}</Mono>
              </h3>
              {details?.status === "DELIVERED" ? (
                <Pill tone="emerald">تم التسليم بالكامل</Pill>
              ) : details?.status === "PROCESSED" ? (
                <Pill tone="amber">تم الطحن — بانتظار التسليم</Pill>
              ) : (
                <Pill tone="neutral">مستلم — بانتظار الطحن</Pill>
              )}
            </div>
            <p className="text-xs text-muted-foreground mt-0.5">
              العميل: <strong className="text-foreground">{details?.customers?.name || "—"}</strong>
              {details?.customers?.phone ? ` (${details.customers.phone})` : ""} | المخزن:{" "}
              {details?.warehouses?.name_ar || details?.warehouses?.name || "—"}
            </p>
          </div>
        </div>

        {/* أزرار الإجراءات السريعة: طباعة ومشاركة */}
        <div className="flex flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={() =>
              handlePrint(
                details?.status === "DELIVERED"
                  ? "delivery"
                  : details?.status === "PROCESSED"
                    ? "milled"
                    : "intake",
              )
            }
            className="inline-flex items-center gap-1.5 rounded-xl border border-border bg-card px-3 py-1.5 text-xs font-bold text-foreground shadow-xs transition hover:bg-muted"
          >
            <Printer className="h-3.5 w-3.5 text-primary" />
            طباعة المستند
          </button>
          <button
            type="button"
            onClick={() => setShareOpen(true)}
            className="inline-flex items-center gap-1.5 rounded-xl bg-emerald-600 px-3 py-1.5 text-xs font-bold text-white shadow-xs transition hover:bg-emerald-700"
          >
            <Share2 className="h-3.5 w-3.5" />
            واتساب ومشاركة
          </button>
          {onClose && (
            <button
              type="button"
              onClick={onClose}
              className="rounded-xl border border-border px-3 py-1.5 text-xs font-medium text-muted-foreground hover:bg-muted"
            >
              إغلاق المستند
            </button>
          )}
        </div>
      </div>

      {/* بطاقة الفاتورة الرسمية المرتبطة دائماً */}
      <div className="grid gap-3 sm:grid-cols-4 rounded-xl border border-border/80 bg-card p-3.5 text-xs">
        <div>
          <span className="text-muted-foreground block text-[11px]">الفاتورة الرسمية:</span>
          <div className="flex items-center gap-1.5 mt-0.5">
            <Receipt className="h-3.5 w-3.5 text-amber-500" />
            <Mono className="font-bold">#{document.invoice_number}</Mono>
            <Link
              to="/sales"
              className="text-primary hover:underline text-[11px] inline-flex items-center gap-0.5"
            >
              عرض <ArrowUpRight className="h-3 w-3" />
            </Link>
          </div>
        </div>
        <div>
          <span className="text-muted-foreground block text-[11px]">إجمالي الأجور:</span>
          <span className="font-bold text-foreground text-sm">{fmtNum(invTotal)}</span>
        </div>
        <div>
          <span className="text-muted-foreground block text-[11px]">المدفوع:</span>
          <span className="font-bold text-emerald-600">{fmtNum(invPaid)}</span>
        </div>
        <div>
          <span className="text-muted-foreground block text-[11px]">المتبقي (ذمة):</span>
          {invRemaining > 0 ? (
            <span className="font-bold text-rose-600">{fmtNum(invRemaining)}</span>
          ) : (
            <span className="font-bold text-emerald-600">مسدد بالكامل</span>
          )}
        </div>
      </div>

      {/* الحبوب المستلمة في هذا المستند */}
      {details?.intakeGrain && (
        <div className="rounded-xl border border-blue-500/20 bg-blue-500/5 px-4 py-2.5 text-xs flex flex-wrap items-center justify-between gap-2">
          <div className="flex items-center gap-2">
            <span className="font-bold text-blue-900 dark:text-blue-200">
              الحبوب المستلمة في هذا المستند: {details.intakeGrain.nameAr}
            </span>
            {details.intakeGrain.packageWeightKg && (
              <span className="text-muted-foreground">
                (سعة العبوة: {details.intakeGrain.packageWeightKg} كجم)
              </span>
            )}
          </div>
          <div className="flex items-center gap-3 font-mono">
            <span>
              المستلم: {fmtNum(details.intakeGrain.bagsReceived)} كيس /{" "}
              {fmtNum(details.intakeGrain.kgReceived)} كجم
            </span>
            <span className="font-bold text-foreground">
              المتبقي للطحن: {fmtNum(details.intakeGrain.bagsRemaining)} كيس /{" "}
              {fmtNum(details.intakeGrain.kgRemaining)} كجم
            </span>
          </div>
        </div>
      )}

      {/* منطقتا الطحن والتسليم */}
      <div className="grid gap-4 lg:grid-cols-2">
        {/* 2. عملية الطحن */}
        <MillingPanel>
          <MillingSectionTitle
            icon={<Cog className="h-4 w-4" />}
            title="2. عملية الطحن"
            subtitle="تسجيل الحبوب المطحونة ونواتجها تحت نفس المستند والفاتورة."
          />
          <div className="space-y-3 p-4">
            {!hasGrainToProcess ? (
              <div className="flex items-center gap-2 rounded-xl bg-emerald-500/10 p-3 text-xs font-semibold text-emerald-700 dark:text-emerald-300">
                <CheckCircle2 className="h-4 w-4" />
                تم طحن جميع الحبوب المستلمة في هذا المستند بنجاح.
              </div>
            ) : (
              <>
                <MillingField
                  label="الحبوب المطحونة (خاصة بهذا المستند)"
                  hint="لا يُخلط رصيد مستند آخر مع هذا المستند."
                >
                  <MillingSelect
                    value={grainItemId}
                    onChange={(e) => setGrainItemId(e.target.value)}
                  >
                    {details?.intakeGrain && (
                      <option value={details.intakeGrain.itemId}>
                        {details.intakeGrain.nameAr} — المتبقي:{" "}
                        {fmtNum(details.intakeGrain.bagsRemaining)} كيس /{" "}
                        {fmtNum(details.intakeGrain.kgRemaining)} كجم
                      </option>
                    )}
                  </MillingSelect>
                </MillingField>

                <div className="grid grid-cols-2 gap-3">
                  <MillingField label="الأكياس المطحونة">
                    <QuantityInput
                      value={bagsOut === "" ? null : Number(bagsOut)}
                      onValueChange={(v) => setBagsOut(v == null ? "" : String(v))}
                      decimals={0}
                      min={0}
                      placeholder="0"
                    />
                  </MillingField>
                  <MillingField label="الوزن المطحون (كجم)">
                    <QuantityInput
                      value={kgOut === "" ? null : Number(kgOut)}
                      onValueChange={(v) => setKgOut(v == null ? "" : String(v))}
                      decimals={3}
                      min={0}
                      unit="kg"
                      placeholder="0"
                    />
                  </MillingField>
                </div>

                {details?.intakeGrain && (
                  <div className="rounded-xl border border-blue-500/20 bg-blue-500/5 p-2.5 text-xs flex flex-wrap items-center justify-between gap-2">
                    <span className="text-blue-900 dark:text-blue-200">
                      <strong>المتبقي كحبوب خام لم تُطحن:</strong>{" "}
                      {fmtNum(
                        Math.max(0, details.intakeGrain.bagsRemaining - (Number(bagsOut) || 0)),
                      )}{" "}
                      كيس (
                      {fmtNum(Math.max(0, details.intakeGrain.kgRemaining - (Number(kgOut) || 0)))}{" "}
                      كجم)
                    </span>
                    <span className="text-[11px] font-semibold text-blue-700 dark:text-blue-300">
                      ✓ يبقى في رصيد العميل العيني ولا يُسجل كفاقد.
                    </span>
                  </div>
                )}

                <LinesEditor
                  lines={outputs}
                  setLines={setOutputs}
                  items={outputsCatalog.data ?? []}
                  label="نواتج الطحن المسجلة للعميل (دقيق / نخالة / إلخ)"
                />

                <MillingField label="ملاحظات الطحن">
                  <MillingTextarea
                    value={millingNotes}
                    onChange={(e) => setMillingNotes(e.target.value)}
                    placeholder="ملاحظات تشغيلية اختيارية…"
                  />
                </MillingField>

                <button
                  type="button"
                  disabled={!canProcess || process.isPending}
                  onClick={() => process.mutate()}
                  className="w-full rounded-xl bg-amber-500 px-4 py-2.5 text-sm font-bold text-white transition hover:bg-amber-600 disabled:opacity-50"
                >
                  {process.isPending ? "جارٍ تسجيل الطحن…" : "تسجيل نواتج الطحن"}
                </button>
              </>
            )}

            {/* ملخص النواتج المسجلة */}
            {details?.outputsSummary && details.outputsSummary.length > 0 && (
              <div className="mt-3 space-y-1.5 border-t border-border/70 pt-3">
                <span className="text-[11px] font-bold text-muted-foreground block">
                  النواتج المقيدة على هذا المستند:
                </span>
                {details.outputsSummary.map((out) => (
                  <div
                    key={out.itemId}
                    className="flex items-center justify-between rounded-lg bg-surface-2/60 px-2.5 py-1.5 text-xs"
                  >
                    <span className="font-bold text-foreground">{out.nameAr}</span>
                    <Mono>
                      المسجل: {fmtNum(out.bagsProduced)} كيس ({fmtNum(out.kgProduced)} كجم) |
                      المتبقي: {fmtNum(out.bagsRemaining)} كيس
                    </Mono>
                  </div>
                ))}
              </div>
            )}
          </div>
        </MillingPanel>

        {/* 3. تسليم العميل */}
        <MillingPanel>
          <MillingSectionTitle
            icon={<PackageCheck className="h-4 w-4" />}
            title="3. تسليم العميل"
            subtitle="يسلم فقط ما تم طحنه وما تبقى من هذا المستند حصراً."
          />
          <div className="space-y-3 p-4">
            {availableOutputsForDelivery.length === 0 ? (
              <div className="rounded-xl bg-muted/60 p-4 text-center text-xs text-muted-foreground">
                {details?.status === "DELIVERED" ? (
                  <div className="flex items-center justify-center gap-2 font-bold text-emerald-600">
                    <CheckCircle2 className="h-4 w-4" />
                    تم تسليم كل نواتج المستند للعميل بالكامل.
                  </div>
                ) : (
                  "سجّل نواتج الطحن أولاً لتتمكن من تسليمها للعميل."
                )}
              </div>
            ) : (
              <>
                <div className="rounded-xl border border-emerald-500/20 bg-emerald-500/5 p-2.5 text-xs">
                  <span className="font-bold text-emerald-900 dark:text-emerald-200 block mb-1">
                    المتاح للتسليم من هذا المستند:
                  </span>
                  {availableOutputsForDelivery.map((o) => (
                    <div key={o.itemId} className="flex justify-between text-[11px]">
                      <span>{o.nameAr}</span>
                      <Mono>
                        {fmtNum(o.bagsRemaining)} كيس / {fmtNum(o.kgRemaining)} كجم
                      </Mono>
                    </div>
                  ))}
                </div>

                <LinesEditor
                  lines={deliveryLines}
                  setLines={setDeliveryLines}
                  items={availableOutputsForDelivery.map((b) => ({
                    id: b.itemId,
                    name: b.nameAr,
                    name_ar: b.nameAr,
                  }))}
                  label="الأصناف والكميات المسلّمة الآن"
                />

                <MillingField label="ملاحظات التسليم">
                  <MillingTextarea
                    value={deliveryNotes}
                    onChange={(e) => setDeliveryNotes(e.target.value)}
                    placeholder="اسم المستلم، رقم السند اليدوي، إلخ…"
                  />
                </MillingField>

                <button
                  type="button"
                  disabled={!canDeliver || deliver.isPending}
                  onClick={() => deliver.mutate()}
                  className="w-full rounded-xl bg-emerald-600 px-4 py-2.5 text-sm font-bold text-white transition hover:bg-emerald-700 disabled:opacity-50"
                >
                  {deliver.isPending ? "جارٍ تسجيل التسليم…" : "تسجيل تسليم للعميل"}
                </button>
              </>
            )}
          </div>
        </MillingPanel>
      </div>

      {/* قالب فاتورة وإيصال المطحنة الموحد الأنيق */}
      {printRequest && details && (
        <UnifiedPrintModal
          open={Boolean(printRequest)}
          onClose={() => setPrintRequest(null)}
          details={details}
          doc={printRequest.doc}
          stage={printStage}
        />
      )}

      {/* نافذة مشاركة الواتساب الموحدة */}
      {shareOpen && details && (
        <DocumentShareDialog
          open={shareOpen}
          onClose={() => setShareOpen(false)}
          title="مشاركة مستند المطحنة وفاتورة الأجور"
          documentType="milling_document"
          millingDocumentNumber={details.document_number}
          millingStatus={
            details.status === "DELIVERED"
              ? "تم التسليم بالكامل"
              : details.status === "PROCESSED"
                ? "تم الطحن"
                : "مستلم"
          }
          customer={{
            id: details.customer_id,
            name: details.customers?.name || "العميل",
            phone: details.customers?.phone || null,
            balance: invRemaining,
          }}
          invoice={{
            id: details.sales_invoice_id,
            invoiceNumber: document.invoice_number,
            date: new Date(details.received_at).toISOString().split("T")[0],
            subtotal: invTotal,
            total: invTotal,
            paid: invPaid,
            remaining: invRemaining,
          }}
        />
      )}
    </section>
  );
}

function LinesEditor({
  lines,
  setLines,
  items,
  label,
}: {
  lines: CustodyLine[];
  setLines: Dispatch<SetStateAction<CustodyLine[]>>;
  items: { id: string; name: string; name_ar: string | null }[];
  label: string;
}) {
  const update = (index: number, patch: Partial<CustodyLine>) =>
    setLines((rows) => rows.map((row, i) => (i === index ? { ...row, ...patch } : row)));

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        <label className="text-xs font-semibold text-muted-foreground">{label}</label>
        <button
          type="button"
          onClick={() => setLines((rows) => [...rows, { itemId: "", bags: 0, kg: 0 }])}
          className="inline-flex items-center gap-1 text-xs font-bold text-primary hover:underline"
        >
          <Plus className="h-3.5 w-3.5" />
          إضافة سطر
        </button>
      </div>
      {lines.map((line, index) => (
        <div key={index} className="grid grid-cols-[1fr_72px_88px_28px] gap-2 items-center">
          <MillingSelect
            value={line.itemId}
            onChange={(e) => update(index, { itemId: e.target.value })}
          >
            <option value="">اختر الصنف…</option>
            {items.map((item) => (
              <option key={item.id} value={item.id}>
                {item.name_ar || item.name}
              </option>
            ))}
          </MillingSelect>
          <QuantityInput
            decimals={0}
            min={0}
            emptyAsZero
            placeholder="أكياس"
            aria-label="أكياس"
            value={line.bags || null}
            onValueChange={(v) => update(index, { bags: v ?? 0 })}
          />
          <QuantityInput
            decimals={3}
            min={0}
            emptyAsZero
            placeholder="كجم"
            aria-label="كجم"
            unit="kg"
            value={line.kg || null}
            onValueChange={(v) => update(index, { kg: v ?? 0 })}
          />
          <button
            type="button"
            disabled={lines.length === 1}
            onClick={() => setLines((rows) => rows.filter((_, i) => i !== index))}
            className="text-rose-500 hover:text-rose-700 disabled:opacity-30"
            aria-label="حذف السطر"
          >
            <Trash2 className="h-4 w-4" />
          </button>
        </div>
      ))}
    </div>
  );
}

/**
 * Market-Hub ERP — Milling terms, one field set for both counters.
 *
 * WHY THIS IS A COMPONENT AND NOT A FUNCTION
 * ------------------------------------------
 * The immediate-cash counter and the custody counter used to declare their own
 * fields inline, and they drifted. One grew the fee basis and extraction rate;
 * the other grew truck plate and gross/tare weights. An operator learned two
 * different forms for what is physically the same decision — "what are these
 * terms?" — and a merchant's grain could be deposited with terms the cashier
 * had never seen.
 *
 * So the terms live here once, and both counters mount the same component. If a
 * field is added, both counters gain it; if the fee arithmetic changes, there is
 * exactly one place it can be wrong.
 *
 * THE FEE IS READ OUT LOUD AT THE SCALE
 * --------------------------------------
 * That is the whole reason these fields sit on the deposit receipt. A merchant
 * standing at the gate should hear the price per bag now, not argue about it on
 * a later visit. So the basis is explicit (per sack, per ton, or a lump sum
 * agreed once) and the agreed total is shown before anything is saved.
 */
import { useMemo } from "react";
import { AmountInput } from "@/components/ui/amount-input";
import { QuantityInput } from "@/components/ui/quantity-input";

export type MillingFeeBasis = "BAG" | "TON" | "LUMP_SUM";
export type BagSource = "CUSTOMER" | "MILL";
export type MillingOutputChoice = "FLOUR_GRADE_1" | "FLOUR_GRADE_2" | "SEMOLINA" | "BRAN";

/** The sack sizes the module uses everywhere, biggest first. */
export const MILLING_BAG_SIZES = [
  { kg: 50, ar: "شوال 50 كجم", en: "Sack 50 kg" },
  { kg: 40, ar: "كيس 40 كجم", en: "Bag 40 kg" },
  { kg: 25, ar: "كيس 25 كجم", en: "Bag 25 kg" },
  { kg: 10, ar: "كيس 10 كجم", en: "Bag 10 kg" },
] as const;

export const MILLING_OUTPUT_OPTIONS: {
  value: MillingOutputChoice;
  ar: string;
  en: string;
}[] = [
  { value: "FLOUR_GRADE_1", ar: "طحن ناعم (دقيق نمرة 1)", en: "Fine — flour grade 1" },
  { value: "FLOUR_GRADE_2", ar: "طحن بر (دقيق بلدي كامل)", en: "Whole grain — grade 2" },
  { value: "SEMOLINA", ar: "سميد فاخر", en: "Semolina" },
  { value: "BRAN", ar: "جرش نخالة", en: "Bran" },
];

export const MILLING_FEE_BASES: { value: MillingFeeBasis; ar: string; en: string }[] = [
  { value: "BAG", ar: "لكل شوال", en: "Per sack" },
  { value: "TON", ar: "لكل طن", en: "Per ton" },
  { value: "LUMP_SUM", ar: "مبلغ مقطوع", en: "Lump sum" },
];

export interface MillingTermsValue {
  millingType: MillingOutputChoice;
  feeBasis: MillingFeeBasis;
  /** Per-sack fee. Only read when basis is BAG. */
  feePerBag: number;
  /** Per-ton fee. Only read when basis is TON. */
  feePerTon: number;
  /** Whole-agreed amount. Only read when basis is LUMP_SUM. */
  lumpSum: number;
  bagsSource: BagSource;
  bagType: string;
  bagCondition: string;
  extractionRate: string;
  allowedLoss: string;
}

export const EMPTY_MILLING_TERMS: MillingTermsValue = {
  millingType: "FLOUR_GRADE_1",
  feeBasis: "BAG",
  feePerBag: 0,
  feePerTon: 0,
  lumpSum: 0,
  bagsSource: "CUSTOMER",
  bagType: "",
  bagCondition: "سليم",
  extractionRate: "",
  allowedLoss: "",
};

/**
 * The agreed fee, from the basis the operator chose.
 *
 * PER_TON converts through the sack count and the sack size, because that is
 * the only place the total weight is known. A per-ton fee on an empty
 * cartouche is silently zero rather than an error, so the caller passes the
 * same numbers it displays.
 */
export function computeMillingFee(
  terms: Pick<MillingTermsValue, "feeBasis" | "feePerBag" | "feePerTon" | "lumpSum">,
  bagCount: number,
  bagSizeKg: number,
): number {
  const bags = Math.max(0, Number(bagCount) || 0);
  const rate = Math.max(0, Number(terms.feePerBag) || 0);
  switch (terms.feeBasis) {
    case "TON": {
      const tons = (bags * (Number(bagSizeKg) || 0)) / 1000;
      return round2(tons * Math.max(0, Number(terms.feePerTon) || 0));
    }
    case "LUMP_SUM":
      return round2(Math.max(0, Number(terms.lumpSum) || 0));
    default:
      return round2(bags * rate);
  }
}

function round2(v: number) {
  return Math.round(v * 100) / 100;
}

const FIELD =
  "w-full rounded-xl border border-border bg-background px-3 py-2 text-xs text-foreground focus:ring-2 focus:ring-primary/30";
const LABEL = "block text-xs font-bold text-foreground";

export interface MillingTermsFieldsProps {
  value: MillingTermsValue;
  onChange: (next: MillingTermsValue) => void;
  bagCount: number;
  bagSizeKg: number;
  /** Mill bag products, shown when the mill supplies the packaging. */
  packagingProducts?: { id: string; name: string; sale_price: number }[];
  millBagId?: string;
  millBagPrice?: number;
  onMillBagChange?: (id: string, price: number) => void;
  isRtl?: boolean;
  /** Compact spacing for the quick counter. */
  compact?: boolean;
}

/**
 * The terms block. Purely presentational: it owns no state, so the parent
 * document — an intake receipt, a direct ticket — decides what happens to the
 * value it reads back.
 */
export function MillingTermsFields({
  value,
  onChange,
  bagCount,
  bagSizeKg,
  packagingProducts = [],
  millBagId = "",
  millBagPrice = 0,
  onMillBagChange,
  isRtl = true,
  compact = false,
}: MillingTermsFieldsProps) {
  const fee = useMemo(
    () => computeMillingFee(value, bagCount, bagSizeKg),
    [value, bagCount, bagSizeKg],
  );

  const set = <K extends keyof MillingTermsValue>(key: K, v: MillingTermsValue[K]) =>
    onChange({ ...value, [key]: v });

  const gap = compact ? "gap-3" : "gap-4";

  return (
    <div className={`space-y-4 ${compact ? "p-3" : ""}`}>
      {/* What is being produced, and how the price is agreed. */}
      <div className={`grid gap-3 ${gap} sm:grid-cols-3`}>
        <div className="space-y-1.5">
          <label className={LABEL}>{isRtl ? "نوع الطحن المطلوب" : "Milling type"}</label>
          <select
            value={value.millingType}
            onChange={(e) => set("millingType", e.target.value as MillingOutputChoice)}
            className={`${FIELD} font-bold text-amber-600 dark:text-amber-400`}
          >
            {MILLING_OUTPUT_OPTIONS.map((o) => (
              <option key={o.value} value={o.value}>
                {isRtl ? o.ar : o.en}
              </option>
            ))}
          </select>
        </div>

        <div className="space-y-1.5">
          <label className={LABEL}>{isRtl ? "أساس الأجر" : "Fee basis"}</label>
          <select
            value={value.feeBasis}
            onChange={(e) => set("feeBasis", e.target.value as MillingFeeBasis)}
            className={FIELD}
          >
            {MILLING_FEE_BASES.map((b) => (
              <option key={b.value} value={b.value}>
                {isRtl ? b.ar : b.en}
              </option>
            ))}
          </select>
        </div>

        <div className="space-y-1.5">
          <label className={LABEL}>
            {value.feeBasis === "BAG"
              ? isRtl
                ? "أجرة الشوال (ر.ي)"
                : "Fee per sack"
              : value.feeBasis === "TON"
                ? isRtl
                  ? "أجرة الطن (ر.ي)"
                  : "Fee per ton"
                : isRtl
                  ? "مبلغ مقطوع (ر.ي)"
                  : "Lump sum"}
          </label>
          <AmountInput
            value={
              value.feeBasis === "BAG"
                ? value.feePerBag
                : value.feeBasis === "TON"
                  ? value.feePerTon
                  : value.lumpSum
            }
            onValueChange={(n) => {
              const amount = n ?? 0;
              if (value.feeBasis === "BAG") set("feePerBag", amount);
              else if (value.feeBasis === "TON") set("feePerTon", amount);
              else set("lumpSum", amount);
            }}
            min={0}
            className="h-[38px] text-xs"
          />
        </div>
      </div>

      {/* Packaging: whose sacks, what kind, and in what state they arrive. */}
      <div className={`grid gap-3 ${gap} sm:grid-cols-3`}>
        <div className="space-y-1.5">
          <label className={LABEL}>{isRtl ? "مصدر الأكياس" : "Bag source"}</label>
          <select
            value={value.bagsSource}
            onChange={(e) => set("bagsSource", e.target.value as BagSource)}
            className={FIELD}
          >
            <option value="CUSTOMER">{isRtl ? "أكياس العميل" : "Customer's bags"}</option>
            <option value="MILL">
              {isRtl ? "أكياس المطحنة (تُحتسب أجرة)" : "Mill's bags (charged)"}
            </option>
          </select>
        </div>

        <div className="space-y-1.5">
          <label className={LABEL}>{isRtl ? "نوع الكيس" : "Bag type"}</label>
          <input
            value={value.bagType}
            onChange={(e) => set("bagType", e.target.value)}
            placeholder={isRtl ? "خيش طبيعي / بلاستيك" : "Jute / plastic"}
            className={FIELD}
          />
        </div>

        <div className="space-y-1.5">
          <label className={LABEL}>{isRtl ? "حالة الأكياس" : "Bag condition"}</label>
          <input
            value={value.bagCondition}
            onChange={(e) => set("bagCondition", e.target.value)}
            placeholder={isRtl ? "سليم / ممزق جزئياً" : "Sound / partly torn"}
            className={FIELD}
          />
        </div>
      </div>

      {/* What the merchant expects back, and what loss he tolerates. */}
      <div className={`grid gap-3 ${gap} sm:grid-cols-2`}>
        <div className="space-y-1.5">
          <label className={LABEL}>
            {isRtl ? "الاستخلاص المتوقع (%)" : "Expected extraction (%)"}
          </label>
          <QuantityInput
            value={value.extractionRate === "" ? null : Number(value.extractionRate)}
            onValueChange={(v) => set("extractionRate", v == null ? "" : String(v))}
            decimals={2}
            min={0}
            max={100}
            unit="%"
            placeholder={isRtl ? "اختياري" : "optional"}
            className="h-[38px] text-xs"
          />
        </div>
        <div className="space-y-1.5">
          <label className={LABEL}>{isRtl ? "الفاقد المسموح (%)" : "Allowed loss (%)"}</label>
          <QuantityInput
            value={value.allowedLoss === "" ? null : Number(value.allowedLoss)}
            onValueChange={(v) => set("allowedLoss", v == null ? "" : String(v))}
            decimals={2}
            min={0}
            max={100}
            unit="%"
            placeholder={isRtl ? "اختياري" : "optional"}
            className="h-[38px] text-xs"
          />
        </div>
      </div>

      {/* The mill supplying the sacks sells them, so they are a priced line. */}
      {value.bagsSource === "MILL" && packagingProducts.length > 0 && onMillBagChange && (
        <div className={`grid gap-3 ${gap} sm:grid-cols-2`}>
          <div className="space-y-1.5">
            <label className={LABEL}>{isRtl ? "صنف كيس المطحنة" : "Mill bag item"}</label>
            <select
              value={millBagId}
              onChange={(e) => {
                const item = packagingProducts.find((p) => p.id === e.target.value);
                onMillBagChange(e.target.value, Number(item?.sale_price) || 0);
              }}
              className={FIELD}
            >
              <option value="">{isRtl ? "— اختر صنف الكيس —" : "— Select bag item —"}</option>
              {packagingProducts.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.name} ({p.sale_price.toLocaleString()} {isRtl ? "ر.ي" : ""})
                </option>
              ))}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className={LABEL}>{isRtl ? "سعر الكيس الواحد" : "Price per bag"}</label>
            <AmountInput
              value={millBagPrice}
              onValueChange={(n) => onMillBagChange(millBagId, n ?? 0)}
              min={0}
              className="h-[38px] text-xs"
            />
          </div>
        </div>
      )}

      {/* The number the merchant hears before the truck leaves. */}
      <div className="flex items-center justify-between rounded-xl bg-amber-500/10 border border-amber-500/30 px-3 py-2">
        <span className="text-xs font-bold text-foreground">
          {isRtl ? "أجرة الطحن المتفق عليها" : "Agreed milling fee"}
        </span>
        <span className="font-mono text-sm font-bold text-amber-700 dark:text-amber-300">
          {fee.toLocaleString()} {isRtl ? "ر.ي" : ""}
        </span>
      </div>
    </div>
  );
}

/**
 * The bag-size select, shared so both counters offer the same sizes in the same
 * order. The custody form used to omit the 10 kg sack that the direct form
 * offered, which meant a merchant filling small sacks had no choice at that
 * counter.
 */
export function MillingBagSizeSelect({
  value,
  onChange,
  isRtl = true,
}: {
  value: number;
  onChange: (kg: number) => void;
  isRtl?: boolean;
}) {
  return (
    <select
      value={String(value)}
      onChange={(e) => onChange(Number(e.target.value))}
      className={`${FIELD} text-center font-mono font-bold`}
    >
      {MILLING_BAG_SIZES.map((b) => (
        <option key={b.kg} value={String(b.kg)}>
          {isRtl ? b.ar : b.en}
        </option>
      ))}
    </select>
  );
}

