/* ------------------------------------------------------------------ */
/*  Filter/sort helper functions                                      */
/* ------------------------------------------------------------------ */

/**
 * Client-side filter helper.
 *
 * IMPORTANT: filtering happens entirely in the browser over rows already fetched
 * by the page. No query, endpoint or payload is changed.
 */
export function applyFilters<T>(
  rows: T[],
  values: FilterValues,
  accessors: Record<string, (row: T) => string | number | null | undefined>,
  options: { dateAccessors?: Record<string, (row: T) => string | null | undefined> } = {},
): T[] {
  const entries = Object.entries(values).filter(([, v]) => v != null && v !== "");
  if (entries.length === 0) return rows;

  return rows.filter((row) =>
    entries.every(([key, value]) => {
      if (typeof value !== "string") {
        const dateOf = options.dateAccessors?.[key];
        if (!dateOf) return true;
        const raw = dateOf(row);
        if (!raw) return false;
        const time = new Date(raw).getTime();
        if (Number.isNaN(time)) return false;
        const range = value ?? {};
        if (range.from && time < new Date(range.from).getTime()) return false;
        if (range.to) {
          const to = new Date(range.to);
          to.setHours(23, 59, 59, 999);
          if (time > to.getTime()) return false;
        }
        return true;
      }

      const accessor = accessors[key];
      if (!accessor) return true;
      const actual = accessor(row);
      return String(actual ?? "") === value;
    }),
  );
}

/** Simple substring search across fields. */
export function applySearch<T>(
  rows: T[],
  query: string,
  fields: (row: T) => (string | null | undefined)[],
): T[] {
  const q = query.trim().toLowerCase();
  if (!q) return rows;
  return rows.filter((row) => fields(row).some((f) => (f ?? "").toLowerCase().includes(q)));
}

import { memo } from "react";
import { useState, useEffect, useRef, useMemo } from "react";
import { useNavigate } from "@tanstack/react-router";
import { Search, Receipt, Package, Users, X, Sparkles, Loader2, Building2 } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useI18n } from "@/lib/i18n";
import { useAuth } from "@/lib/auth";
import { useModules } from "@/lib/modules";
import { useMillingMode, isRouteVisibleByMillingMode } from "@/lib/milling-mode";
import { canAccessRoute } from "@/lib/route-access";
import { cn } from "@/lib/utils";
import { searchRoutes } from "@/lib/navigation";
import { routeIcon, routeCategoryLabel } from "@/lib/navigation/route-icons";

/**
 * تهيئة قيمة البحث قبل تمريرها إلى PostgREST `.or(...)`.
 *
 * السبب: صيغة الفلتر في PostgREST تفصل الحقول والفلاتر بفواصل وأقواس، وقيمة
 * تحتوي فاصلة أو قوسًا تجعل الطلب غير صالح وتفشل البحث كله. كما أن `%` و `_`
 * محرفان خاصان في `LIKE` — تُهرب بـ `\` حتى لا يتحول بحث المستخدم إلى نمط.
 * هذا تحصين للاستعلام الحالي، لا إعادة بناء لمحرك البحث.
 */
function sanitizeSearchTerm(raw: string): string {
  return raw
    .replace(/[\\"'()]/g, " ") // رموز تكسر صيغة الفلتر
    .replace(/,/g, " ") // الفاصلة تفصل الفلاتر في .or()
    .replace(/[%_]/g, (m) => `\\${m}`) // محارف LIKE الخاصة
    .replace(/\s+/g, " ")
    .trim();
}

/** ترويسة الفاصل بين الفلاتر — ثابت واحد بدل تكرار النص */
const DEBOUNCE_MS = 250;

/** هل الخطأ ناتج عن إلغاء الطلب؟ الإلغاء عملية متوقعة لا خطأ للمستخدم. */
function isAbortError(error: unknown): boolean {
  if (!error) return false;
  const anyErr = error as { name?: string; message?: string; details?: string };
  if (anyErr.name === "AbortError") return true;
  const text = `${anyErr.message ?? ""} ${anyErr.details ?? ""}`.toLowerCase();
  return text.includes("abort");
}

interface SearchResultItem {
  id: string;
  title: string;
  subtitle: string;
  category: "invoice" | "product" | "customer" | "supplier" | "nav";
  to: string;
  badge?: string;
  icon: any;
}

import { useBreakpoint } from "@/design/breakpoints";

export const VortexHeaderOmnisearch = memo(function VortexHeaderOmnisearch({
  onFocusChange,
}: {
  onFocusChange?: (focused: boolean) => void;
}) {
  const { lang } = useI18n();
  const isAr = lang === "ar";
  const navigate = useNavigate();
  const { isModuleEnabled } = useModules();
  const { roles, isPlatformAdmin, isPlatformSuperadmin } = useAuth();
  const { mode: millingMode } = useMillingMode();
  const breakpoint = useBreakpoint();
  const isMobile = breakpoint === "xs" || breakpoint === "sm";

  const [query, setQuery] = useState("");
  const [isOpen, setIsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [dataResults, setDataResults] = useState<SearchResultItem[]>([]);
  const [selectedIndex, setSelectedIndex] = useState(0);

  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  /**
   * فهرس الواجهات الموحد — يُشتق من سجل المسارات المركزي (route-registry)
   * بدل القائمة اليدوية السابقة، ويطبّق الصلاحيات + الوحدات + وضع المطحنة.
   */
  const routeIndex = useMemo(() => {
    return searchRoutes("", isAr, {
      isModuleEnabled,
      isVisibleByMillingMode: (path) => isRouteVisibleByMillingMode(path, millingMode),
      canAccess: (entry) =>
        canAccessRoute(entry.path.split("?")[0], {
          roles,
          isPlatformAdmin,
          isPlatformSuperadmin,
        }),
    });
  }, [isAr, isModuleEnabled, millingMode, roles, isPlatformAdmin, isPlatformSuperadmin]);

  // إغلاق القائمة عند النقر خارجها
  useEffect(() => {
    const handleOutsideClick = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
        onFocusChange?.(false);
      }
    };
    document.addEventListener("mousedown", handleOutsideClick);
    return () => document.removeEventListener("mousedown", handleOutsideClick);
  }, []);

  // اختصار لوحة المفاتيح للبحث الشامل: 'Ctrl+Shift+K' / 'Cmd+Shift+K' حصراً.
  // اختصار واحد فقط للهيدر — لا يتعارض مع '/' (حقول البحث داخل الواجهات)
  // ولا 'Ctrl+Shift+P' (لوحة الأوامر) ولا اختصارات نقطة البيع.
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // اختصار البحث الرئيسي المخصص للهيدر
      if ((e.metaKey || e.ctrlKey) && e.shiftKey && e.key.toLowerCase() === "k") {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        setIsOpen(true);
        setTimeout(() => inputRef.current?.focus(), 50);
      }

      // زر Escape للإغلاق
      if (e.key === "Escape" && isOpen) {
        setIsOpen(false);
        inputRef.current?.blur();
        onFocusChange?.(false);
      }
    };

    window.addEventListener("keydown", handleKeyDown, { capture: true });
    return () => window.removeEventListener("keydown", handleKeyDown, { capture: true });
  }, [isOpen]);

  // البحث التسامحي في البيانات عبر Supabase
  //
  // التصميم:
  //   1) Debounce = 250ms — لا يُرسل طلب أثناء الكتابة السريعة.
  //   2) AbortController لكل طلب — الطلب السابق يُلغى فعليًا على مستوى HTTP
  //      عبر `.abortSignal(signal)` المدعوم في Supabase JS.
  //   3) حرس «أحدث طلب» (requestId) — حتى لو وصل ردّ طلب قديم بعد بدء الجديد،
  //      لا يستطيع أن يكتب النتائج أو حالة التحميل أو الخطأ.
  //   4) التنظيف عند تغيّر الاستعلام وعند إلغاء تركيب المكوّن.
  const requestSeqRef = useRef(0);
  const abortRef = useRef<AbortController | null>(null);

  useEffect(() => {
    const cleanQuery = query.trim();

    // أقل من حرفين: لا بحث — ولا نترك أي طلب أو مؤقّت معلّقًا.
    if (cleanQuery.length < 2) {
      abortRef.current?.abort();
      abortRef.current = null;
      requestSeqRef.current += 1; // يُبطل أي ردّ قادم من طلب سابق
      setDataResults([]);
      setIsLoading(false);
      return;
    }

    // ابدأ مؤقت الانتظار بعد إلغاء أي طلب سابق فورًا
    const seq = ++requestSeqRef.current;
    setIsLoading(true);

    const handler = setTimeout(async () => {
      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;

      // هل ما زال هذا الطلب هو الأحدث؟ لا يكتب شيئًا بعده إلا هو.
      const isLatest = () => seq === requestSeqRef.current;

      try {
        const term = sanitizeSearchTerm(cleanQuery);
        if (!term) {
          if (isLatest()) {
            setDataResults([]);
            setIsLoading(false);
          }
          return;
        }

        // Taken from the other branch, and kept because it is a real
        // improvement: an operator typing a phone number should match on the
        // digits alone, so "0771234567" finds "+967 771 234 567". A term that
        // is entirely digits searches the phone column; otherwise it searches
        // the name. Note the queries below select `customers(name, phone)` and
        // read `total` — the columns this schema actually has. The other
        // branch's `customer_name` / `total_amount` do not exist here, so its
        // version of this query fails at runtime rather than merely reading
        // old data.
        const digitsOnly = cleanQuery.replace(/\D/g, "");
        const phoneMatchable = digitsOnly.length >= 3;

        // جلب متزامن فائق السرعة من المنتجات، الفواتير، العملاء، والموردين
        const [productsRes, invoicesRes, customersRes, suppliersRes] = await Promise.all([
          supabase
            .from("products")
            .select("id, name, name_ar, barcode, sku, sale_price")
            .or(
              `name.ilike.%${term}%,name_ar.ilike.%${term}%,barcode.ilike.%${term}%,sku.ilike.%${term}%`,
            )
            .limit(6)
            .abortSignal(controller.signal),
          supabase
            .from("sales_invoices")
            .select("id, invoice_number, total, created_at, customers(name, phone)")
            .or(`invoice_number.ilike.%${term}%`)
            .order("created_at", { ascending: false })
            .limit(6)
            .abortSignal(controller.signal),
          supabase
            .from("customers")
            .select("id, name, phone, balance")
            .or(
              phoneMatchable
                ? `phone.ilike.%${digitsOnly}%,name.ilike.%${term}%`
                : `name.ilike.%${term}%`,
            )
            .limit(6)
            .abortSignal(controller.signal),
          supabase
            .from("suppliers")
            .select("id, name, phone, balance")
            .or(
              phoneMatchable
                ? `phone.ilike.%${digitsOnly}%,name.ilike.%${term}%`
                : `name.ilike.%${term}%`,
            )
            .limit(6)
            .abortSignal(controller.signal),
        ]);

        // طلب قديم: لا يلمس أي state
        if (!isLatest()) return;

        const results: SearchResultItem[] = [];

        // 1) فواتير — اسم العميل من العلاقة (لا يوجد عمود customer_name في الجدول)
        (invoicesRes.data || []).forEach((inv: any) => {
          const customerName = inv.customers?.name || (isAr ? "عميل نقدي" : "Cash");
          results.push({
            id: `inv-${inv.id}`,
            title: `${isAr ? "فاتورة رقم" : "Invoice #"} ${inv.invoice_number}`,
            subtitle: `${customerName} • ${Number(inv.total ?? 0).toLocaleString()} ${isAr ? "ر.ي" : "YER"}`,
            category: "invoice",
            to: `/sales?invoiceId=${inv.id}`,
            badge: isAr ? "فاتورة" : "Invoice",
            icon: Receipt,
          });
        });

        // 2) منتجات — عمود السعر الصحيح هو sale_price
        (productsRes.data || []).forEach((p: any) => {
          results.push({
            id: `prod-${p.id}`,
            title: p.name_ar || p.name,
            subtitle: `${p.barcode ? `[${p.barcode}] • ` : ""}${isAr ? "السعر:" : "Price:"} ${Number(p.sale_price ?? 0).toLocaleString()} ${isAr ? "ر.ي" : "YER"}`,
            category: "product",
            to: `/products?search=${encodeURIComponent(p.barcode || p.name)}`,
            badge: isAr ? "منتج" : "Product",
            icon: Package,
          });
        });

        // 3) عملاء
        (customersRes.data || []).forEach((c: any) => {
          results.push({
            id: `cust-${c.id}`,
            title: c.name,
            subtitle: `${c.phone ? `${c.phone} • ` : ""}${isAr ? "الرصيد:" : "Balance:"} ${Number(c.balance ?? 0).toLocaleString()} ${isAr ? "ر.ي" : "YER"}`,
            category: "customer",
            to: `/customers?search=${encodeURIComponent(c.name)}`,
            badge: isAr ? "عميل" : "Customer",
            icon: Users,
          });
        });

        // 4) موردين
        (suppliersRes.data || []).forEach((s: any) => {
          results.push({
            id: `supp-${s.id}`,
            title: s.name,
            subtitle: `${s.phone ? `${s.phone} • ` : ""}${isAr ? "الرصيد للمورد:" : "Supplier balance:"} ${Number(s.balance ?? 0).toLocaleString()} ${isAr ? "ر.ي" : "YER"}`,
            category: "supplier",
            to: `/suppliers?search=${encodeURIComponent(s.name)}`,
            badge: isAr ? "مورد" : "Supplier",
            icon: Building2,
          });
        });

        setDataResults(results);
      } catch (err) {
        // الإلغاء ليس خطأ: لا Toast ولا رسالة للمستخدم
        if (isAbortError(err)) return;
        // خطأ حقيقي من Supabase/الشبكة — ولا يُكتب إن كان الطلب قديمًا
        if (!isLatest()) return;
        console.warn("[Omnisearch] Error searching:", err);
        setDataResults([]);
      } finally {
        // الطلب القديم لا يُطفئ مؤشر تحميل الطلب الأحدث
        if (isLatest()) setIsLoading(false);
      }
    }, DEBOUNCE_MS);

    return () => {
      clearTimeout(handler);
      abortRef.current?.abort();
      abortRef.current = null;
    };
  }, [query, isAr]);

  // تصفية الواجهات حسب البحث — من السجل المركزي (يدعم العربية/الإنجليزية والمرادفات)
  const filteredNav = useMemo(() => {
    if (!query.trim()) return routeIndex.slice(0, 8); // الافتراضي
    return searchRoutes(query, isAr, {
      isModuleEnabled,
      isVisibleByMillingMode: (path) => isRouteVisibleByMillingMode(path, millingMode),
      canAccess: (entry) =>
        canAccessRoute(entry.path.split("?")[0], {
          roles,
          isPlatformAdmin,
          isPlatformSuperadmin,
        }),
    });
  }, [
    query,
    routeIndex,
    isAr,
    isModuleEnabled,
    millingMode,
    roles,
    isPlatformAdmin,
    isPlatformSuperadmin,
  ]);

  // دمج كافة النتائج
  const allResults = useMemo(() => {
    const list: { to: string }[] = [];
    dataResults.forEach((d) => list.push(d));
    filteredNav.forEach((n) => list.push({ to: n.path }));
    return list;
  }, [dataResults, filteredNav]);

  // التنقل السريع عند الضغط على عنصر (يدعم مسارات تحتوي query مثل /settings?section=printing)
  const handleSelect = (to: string) => {
    setIsOpen(false);
    setQuery("");
    const [pathname, search] = to.split("?");
    if (search) {
      navigate({ to: pathname, search: Object.fromEntries(new URLSearchParams(search)) } as never);
    } else {
      navigate({ to: pathname } as never);
    }
  };

  // التحكم بالأسهم للأسفل والأعلى وEnter
  const handleKeyDownInput = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setSelectedIndex((prev) => (prev + 1 < allResults.length ? prev + 1 : 0));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setSelectedIndex((prev) => (prev - 1 >= 0 ? prev - 1 : allResults.length - 1));
    } else if (e.key === "Enter") {
      e.preventDefault();
      const current = allResults[selectedIndex];
      if (current) {
        handleSelect(current.to);
      }
    }
  };

  return (
    <div ref={containerRef} className="relative flex-1 w-full min-w-0 max-w-none">
      {/* Search Input Bar in Header */}
      <div
        className={cn(
          "group relative flex h-10 w-full items-center gap-2.5 rounded-full border bg-surface/90 px-3.5 text-sm transition-all duration-200",
          isOpen
            ? "border-primary/60 bg-surface shadow-md shadow-primary/10 ring-2 ring-primary/20"
            : "border-border/60 hover:border-ring/40 hover:bg-surface",
        )}
      >
        <Search
          className={cn(
            "h-4 w-4 shrink-0 transition-colors",
            isOpen
              ? "text-primary stroke-[2.5]"
              : "text-muted-foreground group-hover:text-foreground",
          )}
        />

        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            if (!isOpen) setIsOpen(true);
            setSelectedIndex(0);
          }}
          onFocus={() => {
            setIsOpen(true);
            onFocusChange?.(true);
          }}
          onBlur={() => {
            // Delay to allow click events on dropdown items
            setTimeout(() => onFocusChange?.(false), 200);
          }}
          onKeyDown={handleKeyDownInput}
          placeholder={
            isMobile
              ? isAr
                ? "بحث..."
                : "Search..."
              : isAr
                ? "ابحث عن فاتورة، عميل، منتج، مورد..."
                : "Search invoices, products, customers..."
          }
          className="h-full flex-1 min-w-0 bg-transparent text-sm font-medium text-foreground placeholder:text-muted-foreground/75 placeholder:truncate focus:outline-none"
        />

        {isLoading ? (
          <Loader2 className="h-4 w-4 shrink-0 animate-spin text-primary" />
        ) : query ? (
          <button
            type="button"
            onClick={() => {
              setQuery("");
              inputRef.current?.focus();
            }}
            className="grid h-6 w-6 place-items-center rounded-full text-muted-foreground hover:bg-surface-2 hover:text-foreground"
          >
            <X className="h-3.5 w-3.5" />
          </button>
        ) : isMobile && isOpen ? (
          <button
            type="button"
            onClick={() => {
              setIsOpen(false);
              inputRef.current?.blur();
              onFocusChange?.(false);
            }}
            className="grid h-6 w-6 place-items-center rounded-full text-muted-foreground hover:bg-surface-2 hover:text-foreground"
            title={isAr ? "إغلاق البحث" : "Close search"}
          >
            <X className="h-3.5 w-3.5" />
          </button>
        ) : (
          <div className="flex items-center gap-1.5" />
        )}
      </div>

      {/* Floating Expansive Results Dropdown anchored directly below header */}
      {isOpen && (
        <div
          className={cn(
            "fixed inset-x-2.5 top-[68px] z-50 max-h-[75vh] overflow-hidden rounded-2xl border border-border/80 bg-popover/95 p-2 shadow-2xl backdrop-blur-2xl transition-all animate-in fade-in-0 zoom-in-95 sm:absolute sm:top-full sm:inset-x-auto sm:mt-2 sm:w-[580px] md:w-[680px] lg:w-[760px]",
            isAr ? "sm:right-0" : "sm:left-0",
          )}
        >
          {/* Header indicator */}
          <div className="flex items-center justify-between border-b border-border/50 px-3 py-2 text-xs text-muted-foreground">
            <span className="flex items-center gap-1.5 font-semibold text-foreground/80">
              <Sparkles className="h-3.5 w-3.5 text-primary" />
              {query
                ? isAr
                  ? `نتائج البحث عن: "${query}"`
                  : `Search results for: "${query}"`
                : isAr
                  ? "البحث الذكي الشامل في النظام"
                  : "Vortex OmniSearch"}
            </span>
            <span className="text-[11px] font-mono opacity-80">
              {isAr ? "استخدم الأسهم ↑ ↓ ثم Enter" : "Use ↑ ↓ then Enter"}
            </span>
          </div>

          <div className="overflow-y-auto max-h-[60vh] p-1.5 space-y-3 custom-scrollbar">
            {/* 1) نتائج البيانات الحية: فواتير، منتجات، عملاء */}
            {dataResults.length > 0 && (
              <div className="space-y-1">
                <div className="px-2.5 py-1 text-[11px] font-bold uppercase tracking-wider text-muted-foreground">
                  {isAr ? "البيانات والسجلات المطابقة" : "Matching Records"}
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-1.5">
                  {dataResults.map((item, idx) => {
                    const isSelected = selectedIndex === idx;
                    const Icon = item.icon;
                    return (
                      <div
                        key={item.id}
                        onClick={() => handleSelect(item.to)}
                        onMouseEnter={() => setSelectedIndex(idx)}
                        className={cn(
                          "group flex items-center justify-between gap-3 rounded-xl border p-2.5 cursor-pointer transition-all duration-150",
                          isSelected
                            ? "border-primary/50 bg-primary/10 shadow-sm"
                            : "border-border/40 bg-surface/60 hover:border-border hover:bg-surface",
                        )}
                      >
                        <div className="flex items-center gap-2.5 min-w-0">
                          <div
                            className={cn(
                              "grid h-8 w-8 shrink-0 place-items-center rounded-lg border",
                              item.category === "invoice"
                                ? "bg-emerald-500/15 border-emerald-500/20 text-emerald-500"
                                : item.category === "product"
                                  ? "bg-teal-500/15 border-teal-500/20 text-teal-500"
                                  : "bg-blue-500/15 border-blue-500/20 text-blue-500",
                            )}
                          >
                            <Icon className="h-4 w-4" />
                          </div>
                          <div className="min-w-0">
                            <div className="font-semibold text-xs text-foreground truncate">
                              {item.title}
                            </div>
                            <div className="text-[11px] text-muted-foreground truncate">
                              {item.subtitle}
                            </div>
                          </div>
                        </div>
                        {item.badge && (
                          <span className="shrink-0 rounded-md bg-surface-2 px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground border border-border/50">
                            {item.badge}
                          </span>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            {/* 2) الواجهات والصفحات والإعدادات */}
            {filteredNav.length > 0 && (
              <div className="space-y-1">
                <div className="px-2.5 py-1 text-[11px] font-bold uppercase tracking-wider text-muted-foreground">
                  {isAr ? "الواجهات والإعدادات السريعة" : "Navigation & Settings"}
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-1.5">
                  {filteredNav.map((nav, nIdx) => {
                    const actualIdx = dataResults.length + nIdx;
                    const isSelected = selectedIndex === actualIdx;
                    const Icon = routeIcon(nav.id);
                    const title = isAr ? nav.titleAr : nav.titleEn;
                    const sub = isAr ? nav.descriptionAr : nav.descriptionEn;
                    return (
                      <div
                        key={nav.id}
                        onClick={() => handleSelect(nav.path)}
                        onMouseEnter={() => setSelectedIndex(actualIdx)}
                        className={cn(
                          "group flex items-center justify-between gap-3 rounded-xl border p-2.5 cursor-pointer transition-all duration-150",
                          isSelected
                            ? "border-primary/50 bg-primary/10 shadow-sm"
                            : "border-border/40 bg-surface/50 hover:border-border hover:bg-surface",
                        )}
                      >
                        <div className="flex items-center gap-2.5 min-w-0">
                          <div className="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-surface-2 border border-border/50 text-foreground group-hover:text-primary transition-colors">
                            <Icon className="h-4 w-4" />
                          </div>
                          <div className="min-w-0">
                            <div className="font-semibold text-xs text-foreground truncate">
                              {title}
                            </div>
                            <div className="text-[11px] text-muted-foreground truncate">{sub}</div>
                          </div>
                        </div>
                        <span className="shrink-0 rounded-md bg-surface-2 px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground/80 border border-border/50">
                          {routeCategoryLabel(nav.category, isAr)}
                        </span>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

            {/* في حال عدم وجود نتائج */}
            {dataResults.length === 0 && filteredNav.length === 0 && (
              <div className="py-8 text-center text-muted-foreground">
                <p className="text-sm font-medium">
                  {isAr ? "لم نجد نتائج مطابقة لبحثك" : "No matching results found"}
                </p>
                <p className="mt-1 text-xs text-muted-foreground/75">
                  {isAr
                    ? "جرّب البحث باسم العميل، رقم الفاتورة، أو اسم الشاشة"
                    : "Try searching by invoice number, product name, or module"}
                </p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
});

import { useState, useEffect, useTransition } from "react";
import { useRouter } from "@tanstack/react-router";
import {
  RotateCcw,
  Home,
  ShieldCheck,
  ChevronDown,
  Copy,
  Check,
  MessageSquare,
  Phone,
  Database,
  ShieldAlert,
  Server,
  WifiOff,
  Code2,
  AlertTriangle,
  Loader2,
  Sparkles,
  Terminal,
  Activity,
} from "lucide-react";
import { reportLovableError } from "../lib/lovable-error-reporting";
import { getCachedCompanyProfile, DEFAULT_COMPANY_PROFILE } from "@/lib/printing/company-profile";

export type ErrorLayer =
  | "database"
  | "auth_permissions"
  | "backend_network"
  | "frontend_ui"
  | "data_validation"
  | "unknown";

export interface DiagnosticResult {
  layer: ErrorLayer;
  title: string;
  badge: string;
  badgeCls: string;
  icon: typeof Database;
  isTransient: boolean;
  userExplanation: string;
  devRecommendation: string;
  technicalCode: string;
}

export function diagnoseSystemError(error: any): DiagnosticResult {
  const errName = (error?.name || "").toString();
  const errMsg = (error?.message || "").toString();
  const errStack = (error?.stack || "").toString();
  const errCode = (error?.code || error?.status || "").toString();
  const fullText = `${errName} ${errMsg} ${errStack} ${errCode}`.toLowerCase();

  // 1. Auth & Permissions (RLS, JWT, 401, 403)
  if (
    fullText.includes("401") ||
    fullText.includes("403") ||
    fullText.includes("permission denied") ||
    fullText.includes("row-level security") ||
    fullText.includes("rls") ||
    fullText.includes("jwt") ||
    fullText.includes("not authorized") ||
    fullText.includes("unauthorized") ||
    fullText.includes("forbidden") ||
    fullText.includes("invalid claim") ||
    fullText.includes("session expired")
  ) {
    return {
      layer: "auth_permissions",
      title: "صلاحيات الوصول والمصادقة (Auth & Security)",
      badge: "صلاحيات وأمان • RLS",
      badgeCls: "border-amber-500/30 bg-amber-500/10 text-amber-600 dark:text-amber-400",
      icon: ShieldAlert,
      isTransient: false,
      userExplanation:
        "حسابك لا يمتلك الصلاحية الكافية للوصول إلى هذا السجل أو انتهت جلسة الدخول الحالية.",
      devRecommendation:
        "تحقق من سياسات الأمان RLS للجداول في Supabase وصلاحيات الدور (Role) للمستخدم المسجل.",
      technicalCode: errCode || "AUTH_PERMISSION_DENIED",
    };
  }

  // 2. Database (PostgreSQL / Supabase PostgREST)
  if (
    fullText.includes("pgrst") ||
    fullText.includes("postgres") ||
    fullText.includes("supabase") ||
    fullText.includes("relation") ||
    fullText.includes("23505") ||
    fullText.includes("foreign key") ||
    fullText.includes("violates not-null") ||
    fullText.includes("violates foreign key") ||
    fullText.includes("column does not exist") ||
    fullText.includes("table does not exist") ||
    fullText.includes("database") ||
    fullText.includes("duplicate key")
  ) {
    return {
      layer: "database",
      title: "قواعد البيانات (Database / PostgreSQL)",
      badge: "قاعدة البيانات • Supabase / DB",
      badgeCls: "border-cyan-500/30 bg-cyan-500/10 text-cyan-600 dark:text-cyan-400",
      icon: Database,
      isTransient: false,
      userExplanation:
        "تعذر قراءة أو تخزين السجل في قاعدة البيانات بسبب عدم اكتمال الحقول أو تكرار سجل فريد.",
      devRecommendation:
        "تحقق من مطابقة الحقول ومخطط الجداول (Schema/Migrations) وقيود الحقول الفريدة في قاعدة البيانات.",
      technicalCode: errCode || "DB_QUERY_EXCEPTION",
    };
  }

  // 3. Backend & Network (Server 500s, fetch failed, timeouts)
  if (
    fullText.includes("failed to fetch") ||
    fullText.includes("networkerror") ||
    fullText.includes("econnrefused") ||
    fullText.includes("cors") ||
    fullText.includes("500") ||
    fullText.includes("502") ||
    fullText.includes("503") ||
    fullText.includes("504") ||
    fullText.includes("timeout") ||
    fullText.includes("aborted") ||
    fullText.includes("aborterror") ||
    fullText.includes("offline") ||
    fullText.includes("load failed")
  ) {
    const isTransient =
      fullText.includes("timeout") ||
      fullText.includes("failed to fetch") ||
      fullText.includes("networkerror") ||
      fullText.includes("aborted") ||
      fullText.includes("aborterror") ||
      fullText.includes("load failed");

    return {
      layer: "backend_network",
      title: "الخادم والشبكة (Backend API / Network)",
      badge: isTransient ? "تأخر شبكة مؤقت • Network" : "خادم السيرفر • Backend",
      badgeCls: "border-rose-500/30 bg-rose-500/10 text-rose-600 dark:text-rose-400",
      icon: isTransient ? WifiOff : Server,
      isTransient,
      userExplanation: isTransient
        ? "تأخر لحظي في استجابة الشبكة أو تعثر مؤقت في جلب البيانات من الخادم."
        : "واجه خادم النظام تعثراً داخلياً أثناء معالجة الطلب.",
      devRecommendation:
        "تحقق من استقرار اتصال الإنترنت، أو سجلات دوال Edge Functions وخادم الـ API.",
      technicalCode: errCode || (isTransient ? "NETWORK_TIMEOUT_DELAY" : "SERVER_INTERNAL_ERROR"),
    };
  }

  // 4. Data Validation (Zod, missing contract)
  if (fullText.includes("zod") || fullText.includes("validation") || fullText.includes("schema")) {
    return {
      layer: "data_validation",
      title: "صحة البيانات والمدخلات (Data Validation)",
      badge: "التحقق من البيانات • Validation",
      badgeCls: "border-orange-500/30 bg-orange-500/10 text-orange-600 dark:text-orange-400",
      icon: AlertTriangle,
      isTransient: false,
      userExplanation: "البيانات المدخلة أو المسترجعة لا تطابق النمط المطلوب للنظام المحاسبي.",
      devRecommendation: "تحقق من مخطط Zod وصيغة الكائنات المرسلة لضمان توافق الحقول المطلوبة.",
      technicalCode: errCode || "DATA_VALIDATION_ERROR",
    };
  }

  // 5. Frontend UI / Runtime (TypeError, ReferenceError)
  if (
    fullText.includes("typeerror") ||
    fullText.includes("referenceerror") ||
    fullText.includes("syntaxerror") ||
    fullText.includes("cannot read properties") ||
    fullText.includes("undefined is not") ||
    fullText.includes("null is not") ||
    fullText.includes("is not a function")
  ) {
    return {
      layer: "frontend_ui",
      title: "واجهة المستخدم (Frontend Runtime)",
      badge: "كود الواجهة • Client Runtime",
      badgeCls: "border-purple-500/30 bg-purple-500/10 text-purple-600 dark:text-purple-400",
      icon: Code2,
      isTransient: false,
      userExplanation:
        "حدث خطأ أثناء عرض عناصر الصفحة نتيجة متغير مالي أو نصي غير مكتمل في الواجهة.",
      devRecommendation:
        "تحقق من قراءة الخصائص المحمية (Optional Chaining ?.) وتوفر القيم الافتراضية في مكونات React.",
      technicalCode: errCode || "FRONTEND_RENDER_EXCEPTION",
    };
  }

  // Default / General
  return {
    layer: "unknown",
    title: "خطأ عام في النظام (System Generic Error)",
    badge: "نظام عام • General",
    badgeCls: "border-zinc-500/30 bg-zinc-500/10 text-muted-foreground",
    icon: Activity,
    isTransient: true,
    userExplanation: "حدث استثناء غير متوقع أثناء معالجة العملية، وبياناتك وسجلاتك المالية بأمان.",
    devRecommendation:
      "فحص سجل التتبع (Stack Trace) بالأسفل لتحديد السطر والمكون المسبب للاستثناء.",
    technicalCode: errCode || "SYSTEM_RUNTIME_ERROR",
  };
}

export function VortexSmartError({ error, reset }: { error: any; reset: () => void }) {
  const router = useRouter();
  const [showDetails, setShowDetails] = useState(false);
  const [copied, setCopied] = useState(false);
  const [isRetrying, setIsRetrying] = useState(false);
  const [autoRecovering, setAutoRecovering] = useState(false);
  const [countdown, setCountdown] = useState(3);
  const [isPending, startTransition] = useTransition();

  const diagnostic = diagnoseSystemError(error);
  const LayerIcon = diagnostic.icon;

  useEffect(() => {
    reportLovableError(error, {
      boundary: "tanstack_root_smart_error_component",
      layer: diagnostic.layer,
      code: diagnostic.technicalCode,
    });
  }, [error, diagnostic]);

  // Smart Auto-Recovery for Transient/Delay Errors
  useEffect(() => {
    if (diagnostic.isTransient) {
      setAutoRecovering(true);
      const timer = setInterval(() => {
        setCountdown((prev) => {
          if (prev <= 1) {
            clearInterval(timer);
            // Attempt silent recovery
            try {
              router.invalidate();
              reset();
            } catch (e) {
              console.warn("Silent recovery attempt completed");
            }
            setAutoRecovering(false);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);

      return () => clearInterval(timer);
    }
  }, [diagnostic.isTransient, reset, router]);

  const handleManualRetry = () => {
    setIsRetrying(true);
    startTransition(() => {
      try {
        router.invalidate();
        reset();
      } finally {
        setTimeout(() => setIsRetrying(false), 800);
      }
    });
  };

  /* رقم الدعم يبقى في الخلفية فقط (زر واتساب) — لا يُعرض على الشاشة أبداً.
   * المصدر الرسمي: Company Profile (footerContact)، ثم متغير البيئة،
   * ثم fallback ثابت حتى يعمل الزر حتى بدون أي إعداد.
   * (حوكمة المحور 11.2: ممنوع عرض الأرقام نصاً في أي شاشة — هذا الزر يفتح واتساب فقط). */
  const supportPhone =
    (import.meta as { env?: Record<string, string | undefined> }).env?.VITE_SUPPORT_WHATSAPP ??
    (getCachedCompanyProfile().footerContact || DEFAULT_COMPANY_PROFILE.footerContact || "")
      .split(" · ")[0]
      .replace(/[^+\\d]/g, "");

  const errorSummary =
    `*تقرير فحص فني ذكي - Vortex ERP*
` +
    `• طبقة الخطأ: ${diagnostic.title}
` +
    `• كود التشخيص: ${diagnostic.technicalCode}
` +
    `• اسم الخطأ: ${error?.name || "خطأ عام"}
` +
    `• الرسالة: ${error?.message || "لا توجد رسالة"}
` +
    `• الرابط: ${typeof window !== "undefined" ? window.location.href : "غير محدد"}
` +
    `• التوصية للمبرمج: ${diagnostic.devRecommendation}
` +
    `• التوقيت: ${new Date().toLocaleString("ar-YE")}`;

  const copyErrorDetails = async () => {
    const fullText = `${errorSummary}

*سجل التتبع الفني (Stack Trace):*
${error?.stack || "لا يوجد"}`;
    if (typeof navigator !== "undefined" && navigator.clipboard) {
      await navigator.clipboard.writeText(fullText);
      setCopied(true);
      setTimeout(() => setCopied(false), 3000);
    }
  };

  const whatsappUrl = `https://wa.me/${supportPhone.replace(/\D/g, "")}?text=${encodeURIComponent(
    `${errorSummary}

يرجى فحص المشكلة البرمجية أعلاه.`,
  )}`;

  return (
    <div
      className="flex min-h-screen items-center justify-center bg-gradient-to-b from-background via-background/95 to-surface-2/40 px-4 py-8 selection:bg-primary/20"
      dir="rtl"
    >
      <div className="relative max-w-xl w-full p-6 sm:p-8 rounded-3xl border border-border/80 bg-card/90 dark:bg-zinc-950/90 backdrop-blur-2xl shadow-2xl space-y-6 text-center overflow-hidden">
        {/* Ambient Top Glow according to layer */}
        <div className="pointer-events-none absolute -top-20 inset-x-0 mx-auto size-60 rounded-full bg-amber-500/10 blur-3xl opacity-70" />

        {/* Transient Auto-Recovery Banner */}
        {autoRecovering && (
          <div className="relative -mx-6 -mt-6 sm:-mx-8 sm:-mt-8 mb-4 px-4 py-2.5 bg-gradient-to-r from-amber-500/15 via-emerald-500/15 to-amber-500/15 border-b border-border/60 flex items-center justify-center gap-2 text-xs font-semibold text-foreground animate-pulse">
            <Loader2 className="size-3.5 animate-spin text-amber-500" />
            <span>
              رُصد تأخر لحظي في استجابة البيانات • جاري المحاولة الذكية تلقائياً خلال ({countdown})
              ثوانٍ...
            </span>
          </div>
        )}

        {/* Dynamic Architectural Layer Icon Badge */}
        <div className="mx-auto relative">
          <div className="size-16 sm:size-20 mx-auto grid place-items-center rounded-3xl bg-gradient-to-tr from-card via-surface/80 to-surface-2 border border-border/80 shadow-xl group transition-transform hover:scale-105">
            <LayerIcon className="size-8 sm:size-10 text-amber-500 dark:text-amber-400 filter drop-shadow-md" />
          </div>
          <span className="absolute -bottom-1 -end-1 sm:end-44 flex size-5 items-center justify-center">
            <span className="absolute inline-flex size-full animate-ping rounded-full bg-emerald-400 opacity-60" />
            <span className="relative inline-flex size-3.5 rounded-full bg-emerald-500 ring-2 ring-card shadow-xs" />
          </span>
        </div>

        {/* Category & Status Badges */}
        <div className="flex flex-wrap items-center justify-center gap-2">
          <span
            className={`inline-flex items-center gap-1.5 rounded-full border px-3 py-1 text-xs font-bold shadow-xs ${diagnostic.badgeCls}`}
          >
            <LayerIcon className="size-3.5" />
