          )}
        </div>
      </div>
    </div>
  );
}

import {
  AtSign,
  Barcode,
  Boxes,
  Calendar,
  CircleDollarSign,
  Clock,
  FileText,
  Hash,
  KeyRound,
  MapPin,
  Package,
  Palette,
  Percent,
  Phone,
  Search,
  ShieldCheck,
  Tag,
  TextCursorInput,
  Truck,
  User,
  Warehouse,
  type LucideIcon,
} from "lucide-react";

/**
 * Default field icons.
 *
 * Requirement: form fields should carry an icon. Rather than forcing every call
 * site to choose one, `FormField` can infer a sensible default from the field's
 * semantic kind, labels, or name. An explicit `icon` always wins.
 *
 * This keeps the whole system visually consistent: every input has an icon, and
 * an author only has to think about it when the default is wrong.
 */
export type FieldKind =
  | "text"
  | "name"
  | "email"
  | "phone"
  | "password"
  | "number"
  | "integer"
  | "currency"
  | "percent"
  | "date"
  | "time"
  | "search"
  | "barcode"
  | "sku"
  | "address"
  | "notes"
  | "quantity"
  | "unit"
  | "category"
  | "brand"
  | "supplier"
  | "customer"
  | "warehouse"
  | "product"
  | "tax"
  | "code"
  | "color";

const KIND_ICONS: Record<FieldKind, LucideIcon> = {
  text: TextCursorInput,
  name: User,
  email: AtSign,
  phone: Phone,
  password: KeyRound,
  number: Hash,
  integer: Hash,
  currency: CircleDollarSign,
  percent: Percent,
  date: Calendar,
  time: Clock,
  search: Search,
  barcode: Barcode,
  sku: Barcode,
  address: MapPin,
  notes: FileText,
  quantity: Boxes,
  unit: Boxes,
  category: Tag,
  brand: Palette,
  supplier: Truck,
  customer: User,
  warehouse: Warehouse,
  product: Package,
  tax: Percent,
  code: ShieldCheck,
  color: Palette,
};

/** The generic fallback: a neutral text-field icon. */
export const DEFAULT_FIELD_ICON = TextCursorInput;

/**
 * Infer a field kind from a set of hints (the field `name`, its `label`, its
 * placeholder, and the HTML input type).
 *
 * Deliberately keyword-based and bilingual, because the app mixes Arabic and
 * English labels freely.
 */
export function inferFieldKind(hints: {
  name?: string;
  label?: string;
  placeholder?: string;
  type?: string;
}): FieldKind {
  const type = (hints.type ?? "").toLowerCase();
  if (type === "email") return "email";
  if (type === "tel" || type === "phone") return "phone";
  if (type === "password") return "password";
  if (type === "date" || type === "datetime-local") return "date";
  if (type === "time") return "time";
  if (type === "search") return "search";
  if (type === "currency") return "currency";
  if (type === "percent") return "percent";
  if (type === "integer") return "integer";
  if (type === "number" || type === "decimal") return "number";

  const haystack = [hints.name, hints.label, hints.placeholder]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();

  const has = (...words: string[]) => words.some((w) => haystack.includes(w));

  if (has("barcode", "باركود", "الباركود")) return "barcode";
  if (has("sku", "رمز المنتج", "الرمز")) return "sku";
  if (has("email", "البريد", "ايميل", "إيميل")) return "email";
  if (has("phone", "mobile", "هاتف", "جوال", "الهاتف", "الجوال")) return "phone";
  if (has("password", "كلمة المرور", "كلمه المرور")) return "password";
  if (
    has(
      "price",
      "cost",
      "amount",
      "total",
      "salary",
      "balance",
      "paid",
      "سعر",
      "السعر",
      "تكلفة",
      "التكلفة",
      "مبلغ",
      "المبلغ",
      "الاجمالي",
      "الإجمالي",
      "رصيد",
      "الرصيد",
      "مدفوع",
    )
  )
    return "currency";
  if (has("tax", "discount", "rate %", "ضريبة", "الضريبة", "خصم", "الخصم", "نسبة"))
    return "percent";
  if (
    has(
      "quantity",
      "qty",
      "stock",
      "min",
      "count",
      "الكمية",
      "كمية",
      "المخزون",
      "الحد الأدنى",
      "العدد",
    )
  )
    return "quantity";
  if (has("unit", "الوحدة", "وحدة")) return "unit";
  if (has("category", "التصنيف", "الفئة")) return "category";
  if (has("brand", "الماركة", "العلامة")) return "brand";
  if (has("supplier", "vendor", "المورد", "مورد")) return "supplier";
  if (has("customer", "client", "العميل", "عميل")) return "customer";
  if (has("warehouse", "store", "المستودع", "المخزن")) return "warehouse";
  if (has("product", "item", "المنتج", "منتج", "الصنف")) return "product";
  if (has("date", "expiry", "التاريخ", "تاريخ", "الانتهاء")) return "date";
  if (has("address", "location", "city", "العنوان", "الموقع", "المدينة", "موقع الرف"))
    return "address";
  if (has("note", "description", "remark", "ملاحظة", "ملاحظات", "الوصف")) return "notes";
  if (has("code", "serial", "الرمز", "الكود")) return "code";
  if (has("name", "اسم", "الاسم")) return "name";
  if (has("color", "colour", "اللون")) return "color";

  return "text";
}

/** Resolve the icon component for a field kind. */
export function fieldIcon(kind: FieldKind): LucideIcon {
  return KIND_ICONS[kind] ?? DEFAULT_FIELD_ICON;
}

/**
 * Convenience: infer the kind and return the icon component in one call.
 * Returns `null` when an explicit icon was already supplied by the caller.
 */
export function resolveFieldIcon(props: {
  explicit?: React.ReactNode;
  name?: string;
  label?: string;
  placeholder?: string;
  type?: string;
}): React.ReactNode | null {
  if (props.explicit) return props.explicit;
  const kind = inferFieldKind(props);
  const Icon = fieldIcon(kind);
  return <Icon />;
}

/* eslint-disable react-refresh/only-export-components -- يصدّر AuthProvider مع useAuth والثوابت عمداً */
import { createContext, useContext, useEffect, useRef, useState, type ReactNode } from "react";
import type { Session, User } from "@supabase/supabase-js";
import { useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { clearSessionQueryCache } from "@/lib/query-keys";

type Role = "owner" | "manager" | "accountant" | "cashier" | "warehouse";

interface CachedAuthData {
  userId: string;
  roles: Role[];
  isAdmin: boolean;
  isSuperadmin: boolean;
  isActive: boolean;
  cachedAt: number;
}

const AUTH_CACHE_KEY = "vortex_auth_permissions_cache";
const CACHE_TTL_MS = 1000 * 60 * 60 * 24; // 24 hours

function readCachedAuth(userId: string): CachedAuthData | null {
  if (typeof window === "undefined") return null;
  try {
    const raw = localStorage.getItem(AUTH_CACHE_KEY);
    if (!raw) return null;
    const parsed: CachedAuthData = JSON.parse(raw);
    if (parsed.userId !== userId) return null;
    if (Date.now() - parsed.cachedAt > CACHE_TTL_MS) return null;
    return parsed;
  } catch {
    return null;
  }
}

function writeCachedAuth(data: CachedAuthData) {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(AUTH_CACHE_KEY, JSON.stringify(data));
  } catch {
    /* localStorage unavailable (private mode / quota) — cache is best-effort */
  }
}

function clearCachedAuth() {
  if (typeof window === "undefined") return;
  try {
    localStorage.removeItem(AUTH_CACHE_KEY);
  } catch {
    /* localStorage unavailable — cache is best-effort */
  }
}

interface AuthCtx {
  session: Session | null;
  user: User | null;
  roles: Role[];
  isPlatformAdmin: boolean;
  isPlatformSuperadmin: boolean;
  isActive: boolean;
  loading: boolean;
  isRefreshingPermissions: boolean;
  hasRole: (r: Role) => boolean;
  signOut: () => Promise<void>;
}

const Ctx = createContext<AuthCtx | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const queryClient = useQueryClient();
  const [session, setSession] = useState<Session | null>(null);
  const [roles, setRoles] = useState<Role[]>([]);
  const [isPlatformAdmin, setIsPlatformAdmin] = useState(false);
  const [isPlatformSuperadmin, setIsPlatformSuperadmin] = useState(false);
  const [isActive, setIsActive] = useState(true);
  const [loading, setLoading] = useState(true);
  const [isRefreshingPermissions, setIsRefreshingPermissions] = useState(false);
  const loadSeq = useRef(0);
  /**
   * Identity the in-memory Query cache currently belongs to. The query cache is
   * session memory with a 2-minute stale window, so a second user signing in on
   * the same terminal would otherwise see the previous user's rows until the
   * first refetch resolves. The cache is dropped whenever this changes.
   */
  const scopedUserIdRef = useRef<string | null>(null);

  useEffect(() => {
    let alive = true;

    async function applySession(nextSession: Session | null, isInitial = false) {
      const seq = ++loadSeq.current;
      const nextUserId = nextSession?.user?.id ?? null;

      // Drop cached business rows as soon as the identity changes — sign-out
      // (null), a different user, or an inactive account. React Query keys are
      // not user-scoped, so this is the only boundary that keeps them honest.
      if (nextUserId !== scopedUserIdRef.current) {
        clearSessionQueryCache(queryClient);
        scopedUserIdRef.current = nextUserId;
      }

      if (!nextSession?.user) {
        clearCachedAuth();
        if (alive && seq === loadSeq.current) {
          setSession(null);
          setRoles([]);
          setIsPlatformAdmin(false);
          setIsPlatformSuperadmin(false);
          setIsActive(true);
          setLoading(false);
          setIsRefreshingPermissions(false);
        }
        return;
      }

      const userId = nextSession.user.id;
      const cached = readCachedAuth(userId);

      // ضبط الجلسة فوراً لمنع حراس المسارات من طرد المستخدم أثناء جلب الصلاحيات
      setSession(nextSession);

      if (cached) {
        setRoles(cached.roles);
        setIsPlatformAdmin(cached.isAdmin);
        setIsPlatformSuperadmin(cached.isSuperadmin);
        setIsActive(cached.isActive);
        setLoading(false);
        setIsRefreshingPermissions(true);
      } else {
        // إذا لم توجد صلاحيات مخزنة مسبقاً، نبقي التحميل شغالاً حتى تنتهي الاستعلامات
        setLoading(true);
      }

      let nextRoles: Role[] = [];
      let adminFlags = { isAdmin: false, isSuperadmin: false };
      let nextIsActive = true;

      try {
        [nextRoles, adminFlags, nextIsActive] = await Promise.all([
          fetchRoles(userId),
          fetchAdminFlags(userId),
          fetchIsActive(userId),
        ]);
      } catch (err) {
        console.error("Failed to resolve session permissions", err);
        if (cached) {
          nextRoles = cached.roles;
          adminFlags = { isAdmin: cached.isAdmin, isSuperadmin: cached.isSuperadmin };
          nextIsActive = cached.isActive;
        }
      }

      if (!alive || seq !== loadSeq.current) return;

      if (!nextIsActive && !adminFlags.isAdmin) {
        clearCachedAuth();
        setSession(null);
        setRoles([]);
        setIsPlatformAdmin(false);
        setIsPlatformSuperadmin(false);
        setIsActive(false);
        setLoading(false);
        setIsRefreshingPermissions(false);
        void supabase.auth.signOut();
        return;
      }

      writeCachedAuth({
        userId,
        roles: nextRoles,
        isAdmin: adminFlags.isAdmin,
        isSuperadmin: adminFlags.isSuperadmin,
        isActive: nextIsActive,
        cachedAt: Date.now(),
      });

      setSession(nextSession);
      setRoles(nextRoles);
      setIsPlatformAdmin(adminFlags.isAdmin);
      setIsPlatformSuperadmin(adminFlags.isSuperadmin);
      setIsActive(nextIsActive);
      setLoading(false);
      setIsRefreshingPermissions(false);
    }

    const { data: sub } = supabase.auth.onAuthStateChange((event, s) => {
      setTimeout(() => void applySession(s, event === "INITIAL_SESSION"), 0);
    });

    supabase.auth
      .getSession()
      .then(({ data }) => applySession(data.session, true))
      .catch(() => {
        if (!alive) return;
        setSession(null);
        setRoles([]);
        setIsPlatformAdmin(false);
        setIsPlatformSuperadmin(false);
        setLoading(false);
      });

    return () => {
      alive = false;
      sub.subscription.unsubscribe();
    };
    // `queryClient` is a stable reference for the app's lifetime (created once in
    // `createQueryClient`), so this effect still runs exactly once on mount.
  }, [queryClient]);

  async function fetchRoles(userId: string): Promise<Role[]> {
    const { data, error } = await supabase.from("user_roles").select("role").eq("user_id", userId);
    if (error) {
      console.error("Failed to load user roles", error);
      return [];
    }
    return (data ?? []).map((r: { role: Role }) => r.role);
  }

  /*
   * بعض قواعد البيانات المستضافة لم تُطبّق ترحيل profiles.is_active بعد
   * (خطأ 42703). نحاول مرة واحدة فقط، وإذا كان العمود غائبًا نُعطّل الاستعلام
   * لجلسة الصفحة كاملة بدل تكرار طلبات 400 في الكونسول مع كل تحديث حالة.
   */
  let profilesIsActiveColumnMissing = false;
  async function fetchIsActive(userId: string): Promise<boolean> {
    if (profilesIsActiveColumnMissing) return true;
    try {
      const { data, error } = await supabase
        .from("profiles")
        .select("is_active")
        .eq("id", userId)
        .maybeSingle();
      if (error) {
        if ((error as { code?: string }).code === "42703") {
          profilesIsActiveColumnMissing = true;
          console.warn(
            "profiles.is_active column is missing — run migration 20260918000100_add_profiles_is_active.sql",
          );
          return true;
        }
        return true;
      }
      if (!data) return true;
      return (data as { is_active?: boolean }).is_active !== false;
    } catch {
      return true;
    }
  }

  async function fetchAdminFlags(
    userId: string,
  ): Promise<{ isAdmin: boolean; isSuperadmin: boolean }> {
    try {
      const { data, error } = await (supabase as any)
        .from("platform_admins")
        .select("role, is_active")
        .eq("user_id", userId)
        .eq("is_active", true)
        .maybeSingle();

      if (error || !data) return { isAdmin: false, isSuperadmin: false };

      // The table stores exactly two roles: 'superadmin' and 'support'.
      // 'support' is a platform admin but not a superadmin — it must not
      // satisfy superadmin-only policies or reveal the platform screens.
      return {
        isAdmin: true,
        isSuperadmin: data.role === "superadmin",
      };
    } catch {
      return { isAdmin: false, isSuperadmin: false };
    }
  }

  const value: AuthCtx = {
    session,
    user: session?.user ?? null,
    roles,
    isPlatformAdmin,
    isPlatformSuperadmin,
    isActive,
    loading,
    isRefreshingPermissions,
    hasRole: (r) => roles.includes(r),
    signOut: async () => {
      clearCachedAuth();
      clearSessionQueryCache(queryClient);
      scopedUserIdRef.current = null;
      await supabase.auth.signOut();
    },
  };
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useAuth() {
  const c = useContext(Ctx);
  if (!c) throw new Error("useAuth must be used inside <AuthProvider>");
  return c;
}

/**
 * v3.1 — Custom Local Backup Directories (File System Access API)
 * ---------------------------------------------------------------
 * تسمح للمالك بإضافة مجلدات/أقراص محلية على جهازه، وتُكتب كل نسخة احتياطية
 * (يدوية أو مجدولة) تلقائياً في كل المسارات المضافة بالإضافة إلى التنزيل والسحابة.
 *
 * التخزين: قائمة أسماء المسارات تُحفظ في localStorage، و FileSystemDirectoryHandle
 * يُحفظ في IndexedDB (المتصفح لا يسمح بحفظه في localStorage) مع طلب إذن الوصول
 * عند أول كتابة في الجلسة.
 */

const DIRS_LIST_KEY = "vortex_backup_custom_dirs";
const HANDLE_DB_NAME = "vortex_backup_dir_handles";
const HANDLE_STORE = "handles";

type CustomDirMeta = { id: number; name: string; added_at: string };

let handleDbPromise: Promise<IDBDatabase> | null = null;

function openHandleDb(): Promise<IDBDatabase> {
  if (!handleDbPromise) {
    handleDbPromise = new Promise((resolve, reject) => {
      const req = indexedDB.open(HANDLE_DB_NAME, 1);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(HANDLE_STORE)) {
          db.createObjectStore(HANDLE_STORE);
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }
  return handleDbPromise;
}

async function putHandle(id: number, handle: any): Promise<void> {
  const db = await openHandleDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(HANDLE_STORE, "readwrite");
    tx.objectStore(HANDLE_STORE).put(handle, id);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function getHandle(id: number): Promise<any | null> {
  const db = await openHandleDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(HANDLE_STORE, "readonly");
    const req = tx.objectStore(HANDLE_STORE).get(id);
    req.onsuccess = () => resolve(req.result ?? null);
    req.onerror = () => reject(req.error);
  });
}

async function deleteHandle(id: number): Promise<void> {
  const db = await openHandleDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(HANDLE_STORE, "readwrite");
    tx.objectStore(HANDLE_STORE).delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function readDirList(): CustomDirMeta[] {
  try {
    return JSON.parse(localStorage.getItem(DIRS_LIST_KEY) || "[]") as CustomDirMeta[];
  } catch {
    return [];
  }
}

function writeDirList(dirs: CustomDirMeta[]): void {
  localStorage.setItem(DIRS_LIST_KEY, JSON.stringify(dirs));
}

/** هل يدعم المتصفح File System Access API؟ */
export function customDirSupported(): boolean {
  return typeof window !== "undefined" && "showDirectoryPicker" in window;
}

/** كل المسارات المخصصة المسجلة */
export async function listCustomBackupDirectories(): Promise<CustomDirMeta[]> {
  return readDirList();
}

/** يطلب من المستخدم اختيار مجلد ويسجله كموجه نسخ */
export async function addCustomBackupDirectory(): Promise<string> {
  if (!customDirSupported()) {
    throw new Error("المتصفح لا يدعم اختيار مجلدات النظام (File System Access API) — استخدم Chrome أو Edge.");
  }
  // @ts-expect-error — showDirectoryPicker غير معرّف في TypeScript DOM lib بعد
  const handle = await window.showDirectoryPicker({ mode: "readwrite" });
  const meta: CustomDirMeta = {
    id: Date.now(),
    name: handle.name,
    added_at: new Date().toISOString(),
  };
  await putHandle(meta.id, handle);
  const dirs = readDirList();
  dirs.push(meta);
  writeDirList(dirs);
  return handle.name;
}

/** يزيل مساراً من القائمة */
export async function removeCustomBackupDirectory(id: number): Promise<void> {
  writeDirList(readDirList().filter((d) => d.id !== id));
  await deleteHandle(id);
}

/** يطلب إذن القراءة/الكتابة للمسار في بداية الجلسة (يدوي) */
async function ensurePermission(handle: any): Promise<boolean> {
  if ((await handle.queryPermission?.({ mode: "readwrite" })) === "granted") return true;
  return (await handle.requestPermission?.({ mode: "readwrite" })) === "granted";
}

/**
 * يكتب محتوى ملف النسخة في كل المسارات المخصصة المسجلة.
 * المسارات التي يُرفض إذنها أو تفشل تُعاد في قائمة الأخطاء.
 */
export async function writeBackupToCustomDirs(
  content: string,
  fileName: string,
): Promise<{ ok: number; failed: string[] }> {
  const dirs = readDirList();
  let ok = 0;
  const failed: string[] = [];

  for (const dir of dirs) {
    try {
      const handle = await getHandle(dir.id);
      if (!handle) {
        failed.push(`${dir.name} (غير متاح)`);
        continue;
      }
      if (!(await ensurePermission(handle))) {
        failed.push(`${dir.name} (إذن مرفوض)`);
        continue;
      }
      const fileHandle = await handle.getFileHandle(fileName, { create: true });
      const writable = await fileHandle.createWritable();
      await writable.write(content);
      await writable.close();
      ok++;
    } catch (e) {
      failed.push(`${dir.name} (${(e as Error).message})`);
    }
  }

  return { ok, failed };
}

/**
 * Market-Hub ERP — Milling Operational Mode Management.
 *
 * Controls whether the application acts as:
 * 1. 'none'          - General enterprise/store (Supermarket, retail). Completely hides all milling features.
 * 2. 'simplified'    - Simplified mill: Direct intake, milling, single-screen billing & delivery, basic expenses.
 * 3. 'manufacturing' - Industrial mill: Production orders, BOM recipes, joint costing, work-in-progress ledger.
 * 4. 'hybrid'        - Dual-track: Both simplified express counter AND industrial production active simultaneously.
 *
 * Configurable strictly by Super Admin (Owner / Manager).
 */

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";

export type MillingMode = "none" | "simplified";
/** @deprecated الأوضاع القديمة — تُقرأ كـ 'simplified' للتوافق فقط. */
