  const [dateFilter, setDateFilter] = useState<string>("all");
  const [filterSheetOpen, setFilterSheetOpen] = useState(false);

  const fetchLogs = async () => {
    if (!allowed) return;
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("audit_logs")
        .select("*")
        .order("created_at", { ascending: false })
        .limit(500);

      if (error) throw error;
      setRows((data ?? []) as Log[]);

      const ids = Array.from(new Set((data ?? []).map((r: any) => r.actor_id).filter(Boolean)));
      if (ids.length) {
        const { data: ps } = await supabase
          .from("profiles")
          .select("id,full_name")
          .in("id", ids as string[]);
        const m: Record<string, string> = {};
        (ps ?? []).forEach((p: any) => {
          m[p.id] = p.full_name ?? t("audit.unknown_actor");
        });
        setProfiles(m);
      }
    } catch (err: any) {
      toast.error(err.message || t("audit.load_failed"));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLogs();
  }, [allowed]);

  // Unique entities & actors for filters
  const uniqueEntities = useMemo(() => {
    return Array.from(new Set(rows.map((r) => r.entity_type))).filter(Boolean);
  }, [rows]);

  const uniqueActors = useMemo(() => {
    return Array.from(new Set(rows.map((r) => r.actor_id).filter(Boolean))) as string[];
  }, [rows]);

  // Filtered rows
  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    const now = new Date();

    return rows.filter((r) => {
      // Search
      if (q) {
        const actorName =
          r.actor_id && profiles[r.actor_id] ? profiles[r.actor_id].toLowerCase() : "";
        const entityTranslated =
          ENTITY_TRANSLATIONS[r.entity_type.toLowerCase()]?.label.toLowerCase() || "";
        const actionMeta = getActionMeta(r.action);
        const matchesAction =
          r.action.toLowerCase().includes(q) || actionText(r.action).toLowerCase().includes(q);
        const matchesEntity =
          r.entity_type.toLowerCase().includes(q) || entityTranslated.includes(q);
        const matchesActor =
          actorName.includes(q) || (r.actor_id && r.actor_id.toLowerCase().includes(q));
        const matchesEntityId = r.entity_id && r.entity_id.toLowerCase().includes(q);
        if (!matchesAction && !matchesEntity && !matchesActor && !matchesEntityId) return false;
      }

      // Action type
      if (actionFilter !== "all") {
        const meta = getActionMeta(r.action);
        if (meta.type !== actionFilter) return false;
      }

      // Entity
      if (entityFilter !== "all" && r.entity_type !== entityFilter) return false;

      // Actor
      if (actorFilter !== "all" && r.actor_id !== actorFilter) return false;

      // Date
      if (dateFilter !== "all") {
        const logDate = new Date(r.created_at);
        const diffHours = (now.getTime() - logDate.getTime()) / (1000 * 3600);
        if (dateFilter === "today" && diffHours > 24) return false;
        if (dateFilter === "week" && diffHours > 24 * 7) return false;
        if (dateFilter === "month" && diffHours > 24 * 30) return false;
      }

      return true;
    });
  }, [rows, search, actionFilter, entityFilter, actorFilter, dateFilter, profiles, actionText]);

  // Statistics
  const stats = useMemo(() => {
    const total = rows.length;
    const now = new Date();
    const todayCount = rows.filter((r) => {
      const d = new Date(r.created_at);
      return d.toDateString() === now.toDateString();
    }).length;

    const criticalCount = rows.filter((r) => {
      const m = getActionMeta(r.action);
      return m.type === "delete" || m.type === "update";
    }).length;

    const activeUsersCount = new Set(rows.map((r) => r.actor_id).filter(Boolean)).size;

    return { total, todayCount, criticalCount, activeUsersCount };
  }, [rows]);

  const activeFiltersCount = useMemo(() => {
    let count = 0;
    if (actionFilter !== "all") count++;
    if (entityFilter !== "all") count++;
    if (actorFilter !== "all") count++;
    if (dateFilter !== "all") count++;
    return count;
  }, [actionFilter, entityFilter, actorFilter, dateFilter]);

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    toast.success(t("audit.copied_id"));
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleExportCSV = () => {
    if (filtered.length === 0) {
      toast.info(t("audit.export_empty"));
      return;
    }
    const headers = [
      t("audit.id"),
      t("audit.detail.timestamp"),
      t("audit.actor"),
      t("audit.field.action"),
      t("audit.entity"),
      t("audit.detail.entity_id"),
    ];
    const csvRows = filtered.map((r) => [
      r.id,
      new Date(r.created_at).toISOString(),
      r.actor_id ? (profiles[r.actor_id] ?? r.actor_id) : "—",
      r.action,
      r.entity_type,
      r.entity_id ?? "—",
    ]);

    const csvContent =
      "\uFEFF" + [headers.join(","), ...csvRows.map((e) => e.join(","))].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.setAttribute("download", `audit-logs-${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    toast.success(t("audit.export_done"));
  };

  if (!allowed) {
    return (
      <div className="space-y-6">
        <PageHeader title={t("audit.title")} subtitle={t("audit.subtitle")} />
        <Card className="border-border/60 shadow-sm rounded-3xl">
          <CardContent className="p-12 text-center">
            <div className="mx-auto mb-4 grid size-14 place-items-center rounded-2xl bg-rose-500/10 text-rose-600">
              <Shield className="size-7" />
            </div>
            <h3 className="text-lg font-bold text-foreground mb-1">
              {t("audit.restricted_title")}
            </h3>
            <p className="text-sm text-muted-foreground">{t("audit.restricted")}</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-12">
      {/* Header with actions */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-black tracking-tight text-foreground">
            {t("audit.title")}
          </h1>
          <p className="text-xs sm:text-sm text-muted-foreground mt-1">
            {t("audit.subtitle.long")}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={fetchLogs}
            disabled={loading}
            className="rounded-2xl gap-2 h-10 px-3.5 border-border/70 hover:bg-muted"
          >
            <RefreshCw className={cn("size-4", loading && "animate-spin text-primary")} />
            <span className="hidden sm:inline">{t("audit.refresh")}</span>
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={handleExportCSV}
            className="rounded-2xl gap-2 h-10 px-3.5 border-border/70 hover:bg-muted"
          >
            <Download className="size-4 text-emerald-600" />
            <span>{t("audit.export_csv")}</span>
          </Button>
        </div>
      </div>

      {/* Metrics Row */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <VortexMetricCard
          title={t("audit.kpi.total")}
          value={toSystemDigits(stats.total)}
          currency=""
          subtitle={t("audit.kpi.total_hint")}
          icon={<History className="size-5" />}
          iconClassName="bg-primary/10 text-primary"
        />
        <VortexMetricCard
          title={t("audit.kpi.today")}
          value={toSystemDigits(stats.todayCount)}
          currency=""
          subtitle={t("audit.kpi.today_hint")}
          icon={<Calendar className="size-5" />}
          iconClassName="bg-emerald-500/10 text-emerald-600"
          highlight={stats.todayCount > 0}
        />
        <VortexMetricCard
          title={t("audit.kpi.critical")}
          value={toSystemDigits(stats.criticalCount)}
          currency=""
          subtitle={t("audit.kpi.critical_hint")}
          icon={<AlertTriangle className="size-5" />}
          iconClassName="bg-amber-500/10 text-amber-600"
        />
        <VortexMetricCard
          title={t("audit.kpi.users")}
          value={toSystemDigits(stats.activeUsersCount)}
          currency=""
          subtitle={t("audit.kpi.users_hint")}
          icon={<User className="size-5" />}
          iconClassName="bg-purple-500/10 text-purple-600"
        />
      </div>

      {/* Search & Filter Toolbar */}
      <div className="flex flex-col sm:flex-row items-center gap-3">
        <div className="w-full sm:flex-1">
          <VortexSearchInput
            value={search}
            onValueChange={setSearch}
            placeholder={t("audit.search_long")}
            className="w-full"
          />
        </div>

        {/* Action quick filter pills */}
        <div className="flex items-center gap-1.5 overflow-x-auto w-full sm:w-auto pb-1 sm:pb-0 scrollbar-none">
          <Button
            size="sm"
            variant={actionFilter === "all" ? "default" : "outline"}
            onClick={() => setActionFilter("all")}
            className="rounded-full text-xs h-9 px-3 shrink-0"
          >
            {t("audit.filter.all")}
          </Button>
          <Button
            size="sm"
            variant={actionFilter === "create" ? "default" : "outline"}
            onClick={() => setActionFilter("create")}
            className="rounded-full text-xs h-9 px-3 shrink-0 gap-1"
          >
            <PlusCircle className="size-3.5 text-emerald-500" />
            {t("audit.filter.create")}
          </Button>
          <Button
            size="sm"
            variant={actionFilter === "update" ? "default" : "outline"}
            onClick={() => setActionFilter("update")}
            className="rounded-full text-xs h-9 px-3 shrink-0 gap-1"
          >
            <Edit3 className="size-3.5 text-blue-500" />
            {t("audit.filter.update")}
          </Button>
          <Button
            size="sm"
            variant={actionFilter === "delete" ? "default" : "outline"}
            onClick={() => setActionFilter("delete")}
            className="rounded-full text-xs h-9 px-3 shrink-0 gap-1"
          >
            <Trash2 className="size-3.5 text-rose-500" />
            {t("audit.filter.delete")}
          </Button>

          <Button
            size="sm"
            variant="outline"
            onClick={() => setFilterSheetOpen(true)}
            className={cn(
              "rounded-full text-xs h-9 px-3.5 shrink-0 gap-1.5 border-dashed border-border/80",
              activeFiltersCount > 0 && "border-primary bg-primary/10 text-primary font-bold",
            )}
          >
            <Filter className="size-3.5" />
            <span>{t("audit.filter.advanced")}</span>
            {activeFiltersCount > 0 && (
              <span className="grid size-5 place-items-center rounded-full bg-primary text-primary-foreground text-[10px] font-black">
                {toSystemDigits(activeFiltersCount)}
              </span>
            )}
          </Button>
        </div>
      </div>

      {/* Audit List Table / Cards */}
      <Card className="rounded-3xl border border-border/70 shadow-sm overflow-hidden bg-card">
        <CardContent className="p-0">
          {filtered.length === 0 ? (
            <div className="p-16 text-center">
              <div className="mx-auto mb-4 grid size-16 place-items-center rounded-3xl bg-muted/60 text-muted-foreground">
                <History className="size-8 opacity-60" />
              </div>
              <h3 className="text-base font-bold text-foreground mb-1">{t("audit.empty.title")}</h3>
              <p className="text-xs text-muted-foreground max-w-sm mx-auto">
                {t("audit.empty.hint")}
              </p>
              {(search || activeFiltersCount > 0) && (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    setSearch("");
                    setActionFilter("all");
                    setEntityFilter("all");
                    setActorFilter("all");
                    setDateFilter("all");
                  }}
                  className="mt-4 rounded-2xl text-xs"
                >
                  {t("audit.filter.reset")}
                </Button>
              )}
            </div>
          ) : (
            <div className="divide-y divide-border/50">
              {filtered.map((log) => {
                const actionMeta = getActionMeta(log.action);
                const ActionIcon = actionMeta.icon;
                const entityName =
                  ENTITY_TRANSLATIONS[log.entity_type.toLowerCase()]?.label || log.entity_type;
                const actorName = log.actor_id
                  ? (profiles[log.actor_id] ?? log.actor_id.slice(0, 8))
                  : t("audit.system_actor");
                const isCopied = copiedId === log.id;

                return (
                  <div
                    key={log.id}
                    onClick={() => setSelectedLog(log)}
                    className="group relative flex flex-col sm:flex-row sm:items-center justify-between gap-3 p-4 sm:p-5 hover:bg-muted/40 transition-colors cursor-pointer"
                  >
                    {/* Left/Main Column: Actor + Action + Entity */}
                    <div className="flex items-start sm:items-center gap-3.5">
                      {/* Action Icon Badge */}
                      <div
                        className={cn(
                          "grid size-11 place-items-center rounded-2xl shrink-0 border transition-transform group-hover:scale-105",
                          actionMeta.badgeClass,
                        )}
                      >
                        <ActionIcon className="size-5" />
                      </div>

                      {/* Info details */}
                      <div className="space-y-1">
                        <div className="flex flex-wrap items-center gap-2">
                          <span className="text-sm font-black text-foreground">
                            {actionLabel(actionMeta, t)}
                          </span>
                          <span className="text-muted-foreground/60 text-xs">•</span>
                          <Badge
                            variant="secondary"
                            className="rounded-lg text-[11px] font-bold px-2 py-0.5 bg-muted/80 text-foreground"
                          >
                            {entityName}
                          </Badge>
                          {log.entity_id && (
                            <span
                              onClick={(e) => {
                                e.stopPropagation();
                                handleCopy(log.entity_id!, log.id + "_entity");
                              }}
                              className="inline-flex items-center gap-1 font-mono text-[11px] text-muted-foreground hover:text-foreground bg-muted/40 px-1.5 py-0.5 rounded-md border border-border/40"
                              title={t("audit.copy_entity_id")}
                            >
                              <span>#{log.entity_id.slice(0, 8)}</span>
                              {copiedId === log.id + "_entity" ? (
                                <Check className="size-3 text-emerald-500" />
                              ) : (
                                <Copy className="size-3 opacity-60" />
                              )}
                            </span>
                          )}
                        </div>

                        <div className="flex items-center gap-3 text-xs text-muted-foreground">
                          <span className="flex items-center gap-1 font-medium text-foreground/80">
                            <User className="size-3 text-primary" />
                            {actorName}
                          </span>
                          <span className="text-muted-foreground/40">•</span>
                          <span className="flex items-center gap-1 text-[11px]">
                            <Clock className="size-3 text-muted-foreground" />
                            {getRelativeTime(log.created_at, t)}
                          </span>
                        </div>
                      </div>
                    </div>

                    {/* Right Column: Luxury Date Badge & View button */}
                    <div className="flex items-center justify-between sm:justify-end gap-3 pt-2 sm:pt-0 border-t sm:border-t-0 border-border/30">
                      <VortexDateBadge date={log.created_at} size="sm" variant="subtle" showTime />
                      <Button
                        variant="ghost"
                        size="icon"
                        className="size-8 rounded-xl text-muted-foreground group-hover:text-foreground group-hover:bg-muted"
                      >
                        <Eye className="size-4" />
                      </Button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Advanced Filters Sheet */}
      <VortexFilterSheet
        open={filterSheetOpen}
        onOpenChange={setFilterSheetOpen}
        title={t("audit.filter.sheet_title")}
        subtitle={t("audit.filter.sheet_subtitle")}
        activeFiltersCount={activeFiltersCount}
        onReset={() => {
          setActionFilter("all");
          setEntityFilter("all");
          setActorFilter("all");
          setDateFilter("all");
          setFilterSheetOpen(false);
        }}
        onApply={() => setFilterSheetOpen(false)}
      >
        <div className="space-y-6">
          {/* Action Filter */}
          <VortexFilterSection
            title={t("audit.filter.action_title")}
            description={t("audit.filter.action_desc")}
          >
            <div className="grid grid-cols-2 gap-2">
              {[
                { id: "all", label: t("audit.filter.action.all") },
                { id: "create", label: t("audit.filter.action.create") },
                { id: "update", label: t("audit.filter.action.update") },
                { id: "delete", label: t("audit.filter.action.delete") },
                { id: "auth", label: t("audit.filter.action.auth") },
              ].map((opt) => (
                <button
                  key={opt.id}
                  type="button"
                  onClick={() => setActionFilter(opt.id)}
                  className={cn(
                    "flex items-center justify-between p-3 rounded-2xl border text-xs font-bold transition-all text-right",
                    actionFilter === opt.id
                      ? "border-primary bg-primary/10 text-primary shadow-sm"
                      : "border-border/60 hover:bg-muted text-muted-foreground",
                  )}
                >
                  <span>{opt.label}</span>
                  {actionFilter === opt.id && <Check className="size-4 text-primary" />}
                </button>
              ))}
            </div>
          </VortexFilterSection>

          {/* Date Filter */}
          <VortexFilterSection
            title={t("audit.filter.date_title")}
            description={t("audit.filter.date_desc")}
          >
            <div className="grid grid-cols-2 gap-2">
              {[
                { id: "all", label: t("audit.filter.date.all") },
                { id: "today", label: t("audit.filter.date.today") },
                { id: "week", label: t("audit.filter.date.week") },
                { id: "month", label: t("audit.filter.date.month") },
              ].map((opt) => (
                <button
                  key={opt.id}
                  type="button"
                  onClick={() => setDateFilter(opt.id)}
                  className={cn(
                    "flex items-center justify-between p-3 rounded-2xl border text-xs font-bold transition-all text-right",
                    dateFilter === opt.id
                      ? "border-primary bg-primary/10 text-primary shadow-sm"
                      : "border-border/60 hover:bg-muted text-muted-foreground",
                  )}
                >
                  <span>{opt.label}</span>
                  {dateFilter === opt.id && <Check className="size-4 text-primary" />}
                </button>
              ))}
            </div>
          </VortexFilterSection>

          {/* Entity Filter */}
          {uniqueEntities.length > 0 && (
            <VortexFilterSection
              title={t("audit.filter.entity_title")}
              description={t("audit.filter.entity_desc")}
            >
              <div className="flex flex-wrap gap-2">
                <button
                  type="button"
                  onClick={() => setEntityFilter("all")}
                  className={cn(
                    "px-3 py-1.5 rounded-full text-xs font-bold border transition-colors",
                    entityFilter === "all"
                      ? "border-primary bg-primary text-primary-foreground"
                      : "border-border/60 hover:bg-muted text-muted-foreground",
                  )}
                >
                  {t("audit.filter.all")} ({toSystemDigits(rows.length)})
                </button>
                {uniqueEntities.map((ent) => {
                  const entLabel = ENTITY_TRANSLATIONS[ent.toLowerCase()]?.label || ent;
                  const count = rows.filter((r) => r.entity_type === ent).length;
                  return (
                    <button
                      key={ent}
                      type="button"
                      onClick={() => setEntityFilter(ent)}
                      className={cn(
                        "px-3 py-1.5 rounded-full text-xs font-bold border transition-colors",
                        entityFilter === ent
                          ? "border-primary bg-primary text-primary-foreground"
                          : "border-border/60 hover:bg-muted text-muted-foreground",
                      )}
                    >
                      {entLabel} ({toSystemDigits(count)})
                    </button>
                  );
                })}
              </div>
            </VortexFilterSection>
          )}

          {/* Actor Filter */}
          {uniqueActors.length > 0 && (
            <VortexFilterSection
              title={t("audit.filter.actor_title")}
              description={t("audit.filter.actor_desc")}
            >
              <div className="space-y-1.5">
                <button
                  type="button"
                  onClick={() => setActorFilter("all")}
                  className={cn(
                    "w-full flex items-center justify-between p-2.5 rounded-2xl border text-xs font-bold transition-all",
                    actorFilter === "all"
                      ? "border-primary bg-primary/10 text-primary"
                      : "border-border/60 hover:bg-muted text-muted-foreground",
                  )}
                >
                  <span>{t("audit.filter.actor.all")}</span>
                  {actorFilter === "all" && <Check className="size-4 text-primary" />}
                </button>
                {uniqueActors.map((actorId) => {
                  const name = profiles[actorId] || actorId.slice(0, 8);
                  const count = rows.filter((r) => r.actor_id === actorId).length;
                  return (
                    <button
                      key={actorId}
                      type="button"
                      onClick={() => setActorFilter(actorId)}
                      className={cn(
                        "w-full flex items-center justify-between p-2.5 rounded-2xl border text-xs font-bold transition-all",
                        actorFilter === actorId
                          ? "border-primary bg-primary/10 text-primary"
                          : "border-border/60 hover:bg-muted text-muted-foreground",
                      )}
                    >
                      <span className="flex items-center gap-2">
                        <User className="size-3.5 text-primary" />
                        {name}
                      </span>
                      <span className="text-[11px] text-muted-foreground font-mono">
                        {t("audit.filter.events_count", toSystemDigits(count))}
                      </span>
                    </button>
                  );
                })}
              </div>
            </VortexFilterSection>
          )}
        </div>
      </VortexFilterSheet>

      {/* Log Detail Sheet */}
      <Sheet open={Boolean(selectedLog)} onOpenChange={(open) => !open && setSelectedLog(null)}>
        <SheetContent side="left" className="sm:max-w-xl w-full p-0 flex flex-col">
          {selectedLog && (
            <>
              {/* Sheet Header */}
              <div className="p-6 border-b border-border/60 bg-muted/20">
                <div className="flex items-center justify-between gap-3 mb-3">
                  <div className="flex items-center gap-2">
                    {(() => {
                      const meta = getActionMeta(selectedLog.action);
                      const Icon = meta.icon;
                      return (
                        <div
                          className={cn(
                            "grid size-10 place-items-center rounded-2xl border",
                            meta.badgeClass,
                          )}
                        >
                          <Icon className="size-5" />
                        </div>
                      );
                    })()}
                    <div>
                      <SheetTitle className="text-lg font-black text-foreground">
                        {actionLabel(getActionMeta(selectedLog.action), t)}
                      </SheetTitle>
                      <SheetDescription className="text-xs text-muted-foreground">
                        {t("audit.detail.log_id")} {selectedLog.id}
                      </SheetDescription>
                    </div>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => handleCopy(selectedLog.id, "sheet_id")}
                    className="rounded-xl h-8 px-2.5 gap-1.5 text-xs"
                  >
                    {copiedId === "sheet_id" ? (
                      <Check className="size-3.5 text-emerald-500" />
                    ) : (
                      <Copy className="size-3.5 text-muted-foreground" />
                    )}
                    <span>{t("audit.copy_id")}</span>
                  </Button>
                </div>
              </div>

              {/* Sheet Body */}
              <div className="flex-1 overflow-y-auto p-6 space-y-6">
                {/* Meta details card */}
                <div className="grid grid-cols-2 gap-3 p-4 rounded-3xl bg-card border border-border/70">
                  <div>
                    <span className="text-[11px] font-bold text-muted-foreground block mb-1">
                      {t("audit.detail.actor")}
                    </span>
                    <span className="text-sm font-black text-foreground flex items-center gap-1.5">
                      <User className="size-4 text-primary" />
                      {selectedLog.actor_id
                        ? (profiles[selectedLog.actor_id] ?? selectedLog.actor_id.slice(0, 8))
                        : t("audit.system_actor")}
                    </span>
                  </div>

                  <div>
                    <span className="text-[11px] font-bold text-muted-foreground block mb-1">
                      {t("audit.detail.entity")}
                    </span>
                    <span className="text-sm font-black text-foreground flex items-center gap-1.5">
                      <Layers className="size-4 text-blue-500" />
                      {ENTITY_TRANSLATIONS[selectedLog.entity_type.toLowerCase()]?.label ||
                        selectedLog.entity_type}
                    </span>
                  </div>

                  <div>
                    <span className="text-[11px] font-bold text-muted-foreground block mb-1">
                      {t("audit.detail.entity_id")}
                    </span>
                    <span className="font-mono text-xs text-foreground/80 break-all">
                      {selectedLog.entity_id ?? "—"}
                    </span>
                  </div>

                  <div>
                    <span className="text-[11px] font-bold text-muted-foreground block mb-1">
                      {t("audit.detail.timestamp")}
                    </span>
                    <span className="text-xs font-bold text-foreground">
                      {formatLuxuryDate(selectedLog.created_at, { showDayName: true }).full}
                      {" - "}
                      {new Date(selectedLog.created_at).toLocaleTimeString("ar-YE")}
                    </span>
                  </div>
                </div>

                {/* Payload Changes Card */}
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-black text-foreground flex items-center gap-1.5">
                      <FileText className="size-4 text-primary" />
                      {t("audit.detail.payload")}
                    </span>
                    {selectedLog.payload && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() =>
                          handleCopy(JSON.stringify(selectedLog.payload, null, 2), "payload_copy")
                        }
                        className="h-7 text-[11px] rounded-lg gap-1 text-muted-foreground hover:text-foreground"
                      >
                        {copiedId === "payload_copy" ? (
                          <Check className="size-3 text-emerald-500" />
                        ) : (
                          <Copy className="size-3" />
                        )}
                        <span>{t("audit.copy_json")}</span>
                      </Button>
                    )}
                  </div>

                  {selectedLog.payload ? (
                    typeof selectedLog.payload === "object" &&
                    Object.keys(selectedLog.payload).length > 0 ? (
                      <div className="space-y-3">
                        {/* Fully Translated Field Table */}
                        <div className="rounded-2xl border border-border/70 overflow-hidden bg-card text-xs shadow-xs">
                          <div className="bg-muted/50 px-3.5 py-2 border-b border-border/60 flex items-center justify-between text-[11px] font-bold text-muted-foreground">
                            <span>{t("audit.detail.field")}</span>
                            <span>{t("audit.detail.value")}</span>
                          </div>
                          <div className="divide-y divide-border/40">
                            {Object.entries(selectedLog.payload).map(([k, v]) => {
                              const arabicField = translateFieldKeyI18n(k, t);
                              const isComplex = typeof v === "object" && v !== null;
                              const translatedVal = isComplex
                                ? JSON.stringify(v)
                                : translateValueI18n(v, t);

                              return (
                                <div
                                  key={k}
                                  className="p-3 flex flex-col sm:flex-row sm:items-center justify-between gap-1.5 hover:bg-muted/30 transition"
                                >
                                  <div className="flex flex-col">
                                    <span className="font-bold text-foreground text-[12px]">
                                      {arabicField}
                                    </span>
                                    <span className="font-mono text-[10px] text-muted-foreground dir-ltr text-right">
                                      {k}
                                    </span>
                                  </div>
                                  <div className="sm:text-end">
                                    {isComplex ? (
                                      <pre className="inline-block max-w-full p-2 rounded-lg bg-muted text-[11px] font-mono text-foreground/90 overflow-x-auto dir-ltr text-left">
                                        {translatedVal}
                                      </pre>
                                    ) : (
                                      <span className="inline-flex items-center gap-1 font-semibold text-foreground text-[12px] bg-muted/50 px-2.5 py-1 rounded-lg">
                                        {translatedVal}
                                      </span>
                                    )}
                                  </div>
                                </div>
                              );
                            })}
                          </div>
                        </div>

                        {/* Raw JSON viewer toggle / block */}
                        <details className="text-xs rounded-2xl border border-border/50 p-3 bg-muted/20 group">
                          <summary className="font-bold cursor-pointer text-muted-foreground select-none flex items-center justify-between hover:text-foreground">
                            <span>{t("audit.detail.raw_json")}</span>
                            <span className="text-[10px] text-muted-foreground font-mono">
                              Payload Code
                            </span>
                          </summary>
                          <pre className="mt-3 p-3 rounded-xl bg-background border border-border/40 font-mono text-[11px] overflow-x-auto text-foreground/90 dir-ltr text-left">
                            {JSON.stringify(selectedLog.payload, null, 2)}
                          </pre>
                        </details>
                      </div>
                    ) : (
                      <pre className="p-4 rounded-2xl bg-muted/40 border border-border/50 font-mono text-xs overflow-x-auto text-foreground dir-ltr text-left">
                        {JSON.stringify(selectedLog.payload, null, 2)}
                      </pre>
                    )
                  ) : (
                    <div className="p-8 text-center rounded-2xl border border-dashed border-border/70 text-muted-foreground text-xs">
                      {t("audit.detail.payload_empty")}
                    </div>
                  )}
                </div>
              </div>
            </>
          )}
        </SheetContent>
      </Sheet>
    </div>
  );
}

/**
 * /milling/customer-statement — واجهة الأمانات الشاملة (Customer Custody Hub).
 *
 * مصممة بذات مستوى الفخامة والترتيب المعتمد في واجهة المخزون:
 *   1. بطاقات إحصائية فخمة (KPIs) ترصد إجمالي الأمانات، الحبوب، والنواتج.
 *   2. أنماط عرض متعددة (جدول بيانات متقدم، بطاقات تفاعلية، عرض مضغوط).
 *   3. شريط فلاتر وبحث لحظي ذكي (بالعميل، بالصنف، بالكود، بالمستودع، ونوع الأمانة).
 *   4. اختصارات ذكية للإجراءات السريعة:
 *      - فورم طحن فوري أنيق وعالي الدقة لحبوب العميل.
 *      - فورم تسليم نواتج مباشر بنقرة زر وسند تسليم رسمي.
 *      - كشف حركات تفصيلي لكل عميل مع خيارات الطباعة الفاخرة والمشاركة عبر واتساب.
 */
import { createFileRoute, useSearch, useNavigate } from "@tanstack/react-router";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useState, useMemo, useEffect } from "react";
import {
  Scale,
  Cog,
  PackageCheck,
  Search,
  Filter,
  LayoutGrid,
  List,
  TableProperties,
  Sparkles,
  Plus,
  Trash2,
  ChevronLeft,
  Check,
  AlertCircle,
  Phone,
  Warehouse,
  User,
  RefreshCw,
  Printer,
  Share2,
  Eye,
  CheckCircle2,
  FileText,
  Clock,
  X,
  Wheat,
  Boxes,
  ArrowRight,
  TrendingDown,
  Layers,
} from "lucide-react";
import { toast } from "sonner";
import { PageHeader } from "@/components/page-header";
import { ModuleGuard } from "@/lib/modules";
import { LuxuryPrintPreviewModal } from "@/components/luxury-print-preview-modal";
import { UnifiedPrintModal } from "@/components/milling/unified-print-modal";
import { DocumentShareDialog } from "@/components/communication/document-share-dialog";
import { supabase } from "@/integrations/supabase/client";
import {
  fetchCustodyStatement,
  fetchCustodyServiceMoney,
  fetchOutputItems,
  fetchGrainItems,
  custodyMilling,
  custodyDelivery,
  capacityKgOf,
  buildMillingDocumentUnifiedDoc,
  buildCustodyDeliveryDoc,
  type CustodyStatementRow,
  type CustodyMoneyRow,
  type CustodyLine,
  type ProductOption,
} from "@/lib/milling";
import {
  MillingPanel,
  MillingField,
  MillingInput,
  MillingSelect,
  MillingTextarea,
  Pill,
  Mono,
  MillingEmpty,
  fmtNum,
} from "@/components/milling/milling-ui";
import { QuantityInput } from "@/components/ui/quantity-input";
import { getCompanyCurrencySymbol } from "@/lib/format";
import { usePersistedViewMode } from "@/hooks/use-persisted-view-mode";
import type { RecordsViewMode } from "@/components/ui/records-view";
import type { UnifiedDocumentData } from "@/lib/templates/types";

export const Route = createFileRoute("/_app/milling/customer-statement")({
  validateSearch: (search: Record<string, unknown>): { customerId?: string } => ({
    customerId: typeof search.customerId === "string" ? search.customerId : undefined,
  }),
  head: () => ({ meta: [{ title: "الأمانات — فورتكس ERP" }] }),
  component: CustomerCustodyPage,
});

type TypeFilter = "ALL" | "RAW" | "OUTPUT" | "ACTIVE" | "ZERO";

const PRESET_CAPACITIES = [50, 40, 25, 20, 10];

function CustomerCustodyPage() {
  const qc = useQueryClient();
  const navigate = useNavigate();
  const currencySymbol = useMemo(() => getCompanyCurrencySymbol(), []);
  const { customerId: preselectedCustomerId } = useSearch({
    from: "/_app/milling/customer-statement",
  });

  /* Unified records vocabulary: cards | list (was "compact") | table — persisted per screen. */
  const [viewMode, setViewMode] = usePersistedViewMode("milling-custody", "table");

  function changeViewMode(mode: RecordsViewMode) {
    setViewMode(mode);
  }

  // معايير البحث والفلترة
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedWarehouse, setSelectedWarehouse] = useState("ALL");
  const [selectedCustomer, setSelectedCustomer] = useState(preselectedCustomerId || "ALL");
  const [typeFilter, setTypeFilter] = useState<TypeFilter>("ACTIVE");

  // حالات النوافذ المنبثقة
  const [millingModalOpen, setMillingModalOpen] = useState(false);
  const [deliveryModalOpen, setDeliveryModalOpen] = useState(false);
  const [historyModalOpen, setHistoryModalOpen] = useState(false);
  const [selectedRow, setSelectedRow] = useState<CustodyStatementRow | null>(null);

  // حالات الطباعة والمشاركة
  const [printDoc, setPrintDoc] = useState<UnifiedDocumentData | null>(null);
  const [printModalOpen, setPrintModalOpen] = useState(false);
  const [shareDialogOpen, setShareDialogOpen] = useState(false);
  const [shareData, setShareData] = useState<{
    customerName: string;
    phone?: string;
    docNumber?: string;
  } | null>(null);

  // استعلام سجلات كشف الأمانات
  const statementQuery = useQuery({
    queryKey: ["milling", "custody-statement"],
    queryFn: () => fetchCustodyStatement(),
  });

  // استعلام المستودعات للفلترة
  const warehousesQuery = useQuery({
    queryKey: ["milling", "warehouses"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("warehouses")
        .select("id, name, name_ar")
        .eq("is_active", true)
        .order("name");
      if (error) throw error;
      return data ?? [];
    },
  });

  // استعلام العملاء للفلترة
  const customersQuery = useQuery({
    queryKey: ["milling", "customers-list"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("customers")
        .select("id, name, phone")
        .eq("is_active", true)
        .order("name");
      if (error) throw error;
      return data ?? [];
    },
  });

  // استعلام أصناف النواتج والحبوب لنماذج الطحن والتسليم
  const outputItemsQuery = useQuery({
    queryKey: ["milling", "output-items"],
    queryFn: fetchOutputItems,
  });

  const grainItemsQuery = useQuery({
    queryKey: ["milling", "grain-items"],
    queryFn: fetchGrainItems,
  });

  const rawRows = statementQuery.data ?? [];

  // الإحصائيات العلوية (KPIs)
  const stats = useMemo(() => {
    let totalRemainingBags = 0;
    let totalRemainingKg = 0;
    let rawBags = 0;
    let rawKg = 0;
    let outputBags = 0;
    let outputKg = 0;
    const activeCustomers = new Set<string>();
    const activeWarehouses = new Set<string>();

    for (const r of rawRows) {
      const remB = Number(r.remaining_bags ?? 0);
      const remK = Number(r.remaining_kg ?? 0);

      if (remB > 0 || remK > 0) {
        totalRemainingBags += remB;
        totalRemainingKg += remK;
        activeCustomers.add(r.customer_id);
        activeWarehouses.add(r.warehouse_id);

        if (r.item_class === "RAW_MATERIAL") {
          rawBags += remB;
          rawKg += remK;
        } else {
          outputBags += remB;
          outputKg += remK;
        }
      }
    }

    return {
      totalRemainingBags,
      totalRemainingKg,
      rawBags,
      rawKg,
      outputBags,
      outputKg,
      activeCustomersCount: activeCustomers.size,
      activeWarehousesCount: activeWarehouses.size,
    };
  }, [rawRows]);

  // تصفية السجلات
  const filteredRows = useMemo(() => {
    let list = rawRows;

    // تصفية العميل
    if (selectedCustomer !== "ALL") {
      list = list.filter((r) => r.customer_id === selectedCustomer);
    }

    // تصفية المستودع
    if (selectedWarehouse !== "ALL") {
      list = list.filter((r) => r.warehouse_id === selectedWarehouse);
    }

    // تصفية نوع الأمانة والرصيد
    if (typeFilter === "RAW") {
      list = list.filter(
        (r) => r.item_class === "RAW_MATERIAL" && (r.remaining_bags > 0 || r.remaining_kg > 0),
      );
    } else if (typeFilter === "OUTPUT") {
      list = list.filter(
        (r) => r.item_class !== "RAW_MATERIAL" && (r.remaining_bags > 0 || r.remaining_kg > 0),
      );
    } else if (typeFilter === "ACTIVE") {
      list = list.filter((r) => Number(r.remaining_bags) > 0 || Number(r.remaining_kg) > 0);
    } else if (typeFilter === "ZERO") {
      list = list.filter((r) => Number(r.remaining_bags) <= 0 && Number(r.remaining_kg) <= 0);
    }

    // البحث النصي
    if (searchTerm.trim()) {
      const q = searchTerm.trim().toLowerCase();
      list = list.filter(
        (r) =>
          (r.customer_name_ar || "").toLowerCase().includes(q) ||
          (r.item_name_ar || "").toLowerCase().includes(q) ||
          (r.sku || "").toLowerCase().includes(q) ||
          (r.warehouse_name_ar || "").toLowerCase().includes(q),
      );
    }

    return list;
  }, [rawRows, selectedCustomer, selectedWarehouse, typeFilter, searchTerm]);

  // فتح نافذة الطحن المباشر لصنف محدد
  function openMilling(row: CustodyStatementRow) {
    setSelectedRow(row);
    setMillingModalOpen(true);
  }

  // فتح نافذة التسليم المباشر لصنف محدد
  function openDelivery(row: CustodyStatementRow) {
    setSelectedRow(row);
    setDeliveryModalOpen(true);
  }

  // فتح سجل حركات العميل
  function openHistory(row: CustodyStatementRow) {
    setSelectedRow(row);
    setHistoryModalOpen(true);
  }

  return (
    <ModuleGuard moduleId="milling_operations">
      <div className="mx-auto max-w-7xl space-y-4 p-4">
        {/* رأس الصفحة مع أزرار الإجراءات السريعة */}
        <PageHeader
          title="الأمانات"
          subtitle="متابعة وإدارة أمانات العملاء العينية، الأرصدة المتبقية، الطحن المباشر، وتسليم النواتج."
          actions={
            <div className="flex flex-wrap items-center gap-2">
              <button
                type="button"
                onClick={() => {
                  setSelectedRow(null);
                  setMillingModalOpen(true);
                }}
                className="inline-flex items-center gap-1.5 rounded-xl bg-amber-500 px-3.5 py-2 text-xs font-bold text-white shadow-xs transition hover:bg-amber-600 active:scale-95"
              >
                <Cog className="h-4 w-4" />
                طحن أمانة حبوب
              </button>

              <button
                type="button"
                onClick={() => {
                  setSelectedRow(null);
                  setDeliveryModalOpen(true);
                }}
                className="inline-flex items-center gap-1.5 rounded-xl bg-emerald-600 px-3.5 py-2 text-xs font-bold text-white shadow-xs transition hover:bg-emerald-700 active:scale-95"
              >
                <PackageCheck className="h-4 w-4" />
                تسليم نواتج أمانة
              </button>

              <button
                type="button"
                onClick={() => void qc.invalidateQueries({ queryKey: ["milling"] })}
                className="inline-flex items-center gap-1.5 rounded-xl border border-border bg-card px-3 py-2 text-xs font-semibold text-muted-foreground transition hover:bg-muted hover:text-foreground"
                title="تحديث البيانات"
              >
                <RefreshCw className="h-3.5 w-3.5" />
                <span className="hidden sm:inline">تحديث</span>
              </button>
            </div>
          }
        />

        {/* بطاقات الإحصائيات العلوية الفخمة (KPIs) */}
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          {/* إجمالي رصيد الأمانات */}
          <div className="rounded-2xl border border-border/80 bg-surface-1/90 p-4 shadow-sm">
            <div className="flex items-center justify-between">
              <span className="text-xs font-semibold text-muted-foreground">
                إجمالي رصيد الأمانات
              </span>
              <div className="grid h-8 w-8 place-items-center rounded-xl bg-primary/10 text-primary">
                <Scale className="h-4 w-4" />
              </div>
            </div>
            <div className="mt-2 flex items-baseline gap-2">
              <span className="text-2xl font-black tabular-nums text-foreground">
                {fmtNum(stats.totalRemainingBags)}
              </span>
              <span className="text-xs font-bold text-muted-foreground">كيس</span>
            </div>
            <p className="mt-1 text-xs text-muted-foreground">
              الوزن الصافي:{" "}
              <strong className="text-foreground">{fmtNum(stats.totalRemainingKg)}</strong> كجم
            </p>
          </div>

          {/* حبوب خام بانتظار الطحن */}
          <div className="rounded-2xl border border-amber-500/20 bg-amber-500/5 p-4 shadow-sm">
            <div className="flex items-center justify-between">
              <span className="text-xs font-semibold text-amber-700 dark:text-amber-300">
                حبوب خام (بانتظار الطحن)
              </span>
              <div className="grid h-8 w-8 place-items-center rounded-xl bg-amber-500/15 text-amber-600 dark:text-amber-400">
                <Wheat className="h-4 w-4" />
              </div>
            </div>
            <div className="mt-2 flex items-baseline gap-2">
              <span className="text-2xl font-black tabular-nums text-amber-600 dark:text-amber-400">
                {fmtNum(stats.rawBags)}
              </span>
              <span className="text-xs font-bold text-muted-foreground">كيس</span>
            </div>
            <p className="mt-1 text-xs text-muted-foreground">
              الوزن: <strong className="text-foreground">{fmtNum(stats.rawKg)}</strong> كجم بانتظار
              الطحن
            </p>
          </div>

          {/* نواتج جاهزة للتسليم */}
          <div className="rounded-2xl border border-emerald-500/20 bg-emerald-500/5 p-4 shadow-sm">
            <div className="flex items-center justify-between">
              <span className="text-xs font-semibold text-emerald-700 dark:text-emerald-300">
                نواتج (جاهزة للتسليم)
              </span>
              <div className="grid h-8 w-8 place-items-center rounded-xl bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
                <Boxes className="h-4 w-4" />
              </div>
            </div>
            <div className="mt-2 flex items-baseline gap-2">
              <span className="text-2xl font-black tabular-nums text-emerald-600 dark:text-emerald-400">
                {fmtNum(stats.outputBags)}
              </span>
              <span className="text-xs font-bold text-muted-foreground">كيس</span>
            </div>
            <p className="mt-1 text-xs text-muted-foreground">
              الوزن: <strong className="text-foreground">{fmtNum(stats.outputKg)}</strong> كجم دقيق
              ونخالة
            </p>
          </div>

          {/* العملاء والمستودعات */}
          <div className="rounded-2xl border border-border/80 bg-surface-1/90 p-4 shadow-sm">
            <div className="flex items-center justify-between">
              <span className="text-xs font-semibold text-muted-foreground">العملاء النشطون</span>
              <div className="grid h-8 w-8 place-items-center rounded-xl bg-sky-500/10 text-sky-600 dark:text-sky-400">
                <User className="h-4 w-4" />
              </div>
            </div>
            <div className="mt-2 flex items-baseline gap-2">
              <span className="text-2xl font-black tabular-nums text-foreground">
                {fmtNum(stats.activeCustomersCount)}
              </span>
              <span className="text-xs font-bold text-muted-foreground">عميل له أمانات</span>
            </div>
            <p className="mt-1 text-xs text-muted-foreground">
              موزعة في <strong className="text-foreground">{stats.activeWarehousesCount}</strong>{" "}
              مستودعات
            </p>
          </div>
        </div>

        {/* شريط الأدوات والفلاتر والبحث اللحظي */}
        <div className="rounded-2xl border border-border/80 bg-surface-1/90 p-4 shadow-sm space-y-3">
          <div className="flex flex-wrap items-center justify-between gap-3">
            {/* حقل البحث */}
            <div className="relative w-full sm:w-80">
              <Search className="pointer-events-none absolute start-3 top-2.5 h-4 w-4 text-muted-foreground" />
              <MillingInput
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="بحث بالعميل، الصنف، الكود، المستودع…"
                className="ps-9 font-medium"
              />
              {searchTerm && (
                <button
                  type="button"
                  onClick={() => setSearchTerm("")}
                  className="absolute end-2.5 top-2.5 text-muted-foreground hover:text-foreground"
                >
                  <X className="h-4 w-4" />
                </button>
              )}
            </div>

            {/* الفلاتر المنسدلة: المستودع والعميل */}
            <div className="flex flex-wrap items-center gap-2">
              <div className="w-44">
                <MillingSelect
                  value={selectedWarehouse}
                  onChange={(e) => setSelectedWarehouse(e.target.value)}
                  className="text-xs font-semibold"
                >
                  <option value="ALL">كل المستودعات</option>
                  {(warehousesQuery.data ?? []).map((w) => (
                    <option key={w.id} value={w.id}>
                      {w.name_ar || w.name}
                    </option>
                  ))}
                </MillingSelect>
              </div>

              <div className="w-48">
                <MillingSelect
                  value={selectedCustomer}
                  onChange={(e) => setSelectedCustomer(e.target.value)}
                  className="text-xs font-semibold"
                >
                  <option value="ALL">كل العملاء</option>
                  {(customersQuery.data ?? []).map((c) => (
                    <option key={c.id} value={c.id}>
                      {c.name}
                    </option>
                  ))}
                </MillingSelect>
              </div>

              {/* أزرار تبديل نمط العرض (مثل المخزون) */}
              <div className="flex rounded-xl bg-muted p-1 border border-border">
                <button
                  type="button"
                  onClick={() => changeViewMode("table")}
                  className={`p-1.5 rounded-lg transition ${
                    viewMode === "table"
                      ? "bg-background text-foreground shadow-xs"
                      : "text-muted-foreground hover:text-foreground"
                  }`}
                  title="عرض جدول البيانات"
                >
                  <TableProperties className="h-4 w-4" />
                </button>
                <button
                  type="button"
                  onClick={() => changeViewMode("cards")}
                  className={`p-1.5 rounded-lg transition ${
                    viewMode === "cards"
                      ? "bg-background text-foreground shadow-xs"
                      : "text-muted-foreground hover:text-foreground"
                  }`}
                  title="عرض البطاقات"
                >
                  <LayoutGrid className="h-4 w-4" />
                </button>
                <button
                  type="button"
                  onClick={() => changeViewMode("list")}
                  className={`p-1.5 rounded-lg transition ${
                    viewMode === "list"
                      ? "bg-background text-foreground shadow-xs"
                      : "text-muted-foreground hover:text-foreground"
                  }`}
                  title="عرض مضغوط مكثف"
                >
                  <List className="h-4 w-4" />
                </button>
              </div>
            </div>
          </div>

          {/* أزرار التصفية السريعة (Filter Chips) */}
          <div className="flex flex-wrap items-center gap-1.5 pt-1 border-t border-border/60">
            {[
              { id: "ACTIVE", label: "أرصدة متبقية نشطة" },
              { id: "RAW", label: "حبوب خام (للطحن)" },
              { id: "OUTPUT", label: "نواتج (للتسليم)" },
              { id: "ALL", label: "جميع السجلات" },
              { id: "ZERO", label: "مصفاة بالكامل (0)" },
            ].map((f) => (
              <button
                key={f.id}
                type="button"
                onClick={() => setTypeFilter(f.id as TypeFilter)}
                className={`rounded-xl px-3 py-1 text-xs font-semibold transition ${
                  typeFilter === f.id
                    ? "bg-primary text-primary-foreground shadow-xs"
                    : "border border-border/80 bg-surface-2/60 text-muted-foreground hover:bg-muted hover:text-foreground"
                }`}
              >
                {f.label}
              </button>
            ))}

            <span className="ms-auto text-xs text-muted-foreground">
              عرض {filteredRows.length} صنف أمانة
            </span>
          </div>
        </div>

        {/* عرض البيانات حسب النمط المختار */}
        {statementQuery.isLoading ? (
          <div className="rounded-2xl border border-border p-12 text-center">
            <RefreshCw className="h-6 w-6 animate-spin mx-auto text-primary" />
            <p className="mt-2 text-xs font-semibold text-muted-foreground">
              جارٍ تحميل أرصدة وسجلات الأمانات…
            </p>
          </div>
        ) : filteredRows.length === 0 ? (
          <div className="rounded-2xl border border-dashed border-border/80 p-12 text-center">
            <MillingEmpty
              title="لا توجد أمانات مطابقة لمعايير البحث الحالية"
              hint="غيّر معايير الفلترة أو اختر مستودعاً أو عميلاً آخر."
            />
          </div>
        ) : viewMode === "table" ? (
          /* نمط الجدول الرئيسي المتقدم */
          <div className="overflow-hidden rounded-2xl border border-border/80 bg-surface-1/90 shadow-sm">
            <div className="overflow-x-auto">
              <table className="w-full text-xs">
                <thead>
                  <tr className="border-b border-border/70 text-muted-foreground bg-muted/40 font-bold">
                    <th className="px-4 py-3 text-start">العميل صاحب الأمانة</th>
                    <th className="px-3 py-3 text-start">صنف الأمانة</th>
                    <th className="px-3 py-3 text-start">المستودع</th>
                    <th className="px-3 py-3 text-center">الوارد (المستلم)</th>
                    <th className="px-3 py-3 text-center">المنصرف (المطحون/المسلّم)</th>
                    <th className="px-4 py-3 text-center bg-primary/5 text-primary">
                      الرصيد المتبقي الحالي
                    </th>
                    <th className="px-3 py-3 text-center">آخر حركة</th>
                    <th className="px-4 py-3 text-end">الإجراءات السريعة</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/40">
                  {filteredRows.map((r, idx) => {
                    const remB = Number(r.remaining_bags ?? 0);
                    const remK = Number(r.remaining_kg ?? 0);
                    const isRaw = r.item_class === "RAW_MATERIAL";
                    const isZero = remB <= 0 && remK <= 0;

                    return (
                      <tr
                        key={`${r.customer_id}-${r.item_id}-${r.warehouse_id}-${idx}`}
                        className="transition hover:bg-muted/40"
                      >
                        {/* العميل */}
                        <td className="px-4 py-3 font-bold text-foreground">
                          <div>{r.customer_name_ar || "—"}</div>
                        </td>

                        {/* الصنف وشارة التصنيف */}
                        <td className="px-3 py-3">
                          <div className="flex items-center gap-2">
                            <span className="font-bold text-foreground">{r.item_name_ar}</span>
                            <span
                              className={`rounded-md px-1.5 py-0.5 text-[10px] font-bold ${
                                isRaw
                                  ? "bg-amber-500/15 text-amber-700 dark:text-amber-300"
                                  : "bg-emerald-500/15 text-emerald-700 dark:text-emerald-300"
                              }`}
                            >
                              {isRaw ? "حبوب خام" : "ناتج طحن"}
                            </span>
                          </div>
                          {r.sku && (
                            <span className="text-[10px] font-mono text-muted-foreground">
                              {r.sku}
                            </span>
                          )}
                        </td>

                        {/* المستودع */}
                        <td className="px-3 py-3 text-muted-foreground">
                          {r.warehouse_name_ar || "—"}
                        </td>

                        {/* الوارد */}
                        <td className="px-3 py-3 text-center tabular-nums text-muted-foreground">
                          <div>{fmtNum(r.received_bags)} كيس</div>
                          <div className="text-[10px]">({fmtNum(r.received_kg)} كجم)</div>
                        </td>

                        {/* المنصرف */}
                        <td className="px-3 py-3 text-center tabular-nums text-muted-foreground">
                          <div>{fmtNum(r.issued_bags)} كيس</div>
                          <div className="text-[10px]">({fmtNum(r.issued_kg)} كجم)</div>
                        </td>

                        {/* الرصيد المتبقي الحالي */}
                        <td className="px-4 py-3 text-center tabular-nums bg-primary/5">
                          {isZero ? (
                            <span className="rounded-md bg-muted px-2 py-0.5 text-[11px] font-bold text-muted-foreground">
                              تم التسليم بالكامل
                            </span>
                          ) : (
                            <div className="space-y-0.5">
                              <span className="text-sm font-black text-primary">
                                {fmtNum(remB)} كيس
                              </span>
                              <div className="text-[11px] font-bold text-foreground">
                                {fmtNum(remK)} كجم
                              </div>
                            </div>
                          )}
                        </td>

                        {/* آخر حركة */}
                        <td className="px-3 py-3 text-center text-muted-foreground text-[11px]">
                          {r.last_movement_at
                            ? new Date(r.last_movement_at).toLocaleDateString("ar-EG")
                            : "—"}
                        </td>

                        {/* الإجراءات السريعة */}
                        <td className="px-4 py-3 text-end">
                          <div className="inline-flex items-center gap-1.5">
                            {/* زر طحن إذا كان الصنف مادة خام وله رصيد */}
                            {isRaw && !isZero && (
                              <button
                                type="button"
                                onClick={() => openMilling(r)}
                                className="inline-flex items-center gap-1 rounded-xl bg-amber-500/15 px-2.5 py-1 text-xs font-bold text-amber-700 dark:text-amber-300 hover:bg-amber-500/25 transition"
                                title="طحن من رصيد حبوب هذا العميل"
                              >
                                <Cog className="h-3.5 w-3.5" />
                                <span>طحن</span>
                              </button>
                            )}

                            {/* زر تسليم إذا كان له رصيد */}
                            {!isZero && (
                              <button
                                type="button"
                                onClick={() => openDelivery(r)}
                                className="inline-flex items-center gap-1 rounded-xl bg-emerald-500/15 px-2.5 py-1 text-xs font-bold text-emerald-700 dark:text-emerald-300 hover:bg-emerald-500/25 transition"
                                title="تسليم الأمانة للعميل"
                              >
                                <PackageCheck className="h-3.5 w-3.5" />
                                <span>تسليم</span>
                              </button>
                            )}

                            {/* زر عرض الكشف */}
                            <button
                              type="button"
                              onClick={() => openHistory(r)}
                              className="inline-flex items-center gap-1 rounded-xl border border-border bg-card px-2 py-1 text-xs font-medium text-foreground hover:bg-muted transition"
                              title="كشف حساب الأمانة للعميل"
                            >
                              <FileText className="h-3.5 w-3.5 text-muted-foreground" />
                              <span className="hidden sm:inline">الكشف</span>
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        ) : viewMode === "cards" ? (
          /* نمط البطاقات التفاعلية (Cards Grid) */
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {filteredRows.map((r, idx) => {
              const remB = Number(r.remaining_bags ?? 0);
              const remK = Number(r.remaining_kg ?? 0);
              const isRaw = r.item_class === "RAW_MATERIAL";
              const isZero = remB <= 0 && remK <= 0;

              return (
                <div
                  key={`${r.customer_id}-${r.item_id}-${r.warehouse_id}-${idx}`}
                  className="rounded-2xl border border-border/80 bg-surface-1/90 p-4 shadow-sm flex flex-col justify-between space-y-3 transition hover:border-primary/40 hover:shadow-md"
                >
                  <div>
                    {/* رأس البطاقة: العميل ونوع الصنف */}
                    <div className="flex items-start justify-between gap-2 border-b border-border/60 pb-2.5">
                      <div>
                        <h4 className="font-bold text-sm text-foreground">
                          {r.customer_name_ar || "—"}
                        </h4>
                        <span className="text-[11px] text-muted-foreground">
                          مستودع: {r.warehouse_name_ar || "—"}
                        </span>
                      </div>
                      <span
                        className={`rounded-lg px-2 py-0.5 text-[10px] font-bold ${
                          isRaw
                            ? "bg-amber-500/15 text-amber-700 dark:text-amber-300"
                            : "bg-emerald-500/15 text-emerald-700 dark:text-emerald-300"
                        }`}
                      >
                        {isRaw ? "حبوب خام" : "ناتج طحن"}
                      </span>
                    </div>

                    {/* الصنف والرصيد المتبقي الرئيسي */}
                    <div className="mt-3 flex items-center justify-between">
                      <div>
                        <span className="text-xs text-muted-foreground">صنف الأمانة:</span>
                        <p className="font-bold text-sm text-foreground">{r.item_name_ar}</p>
                      </div>

                      <div className="text-end">
                        <span className="text-[11px] text-muted-foreground">الرصيد المتبقي:</span>
                        {isZero ? (
                          <p className="text-xs font-bold text-muted-foreground">مصفاة بالكامل</p>
                        ) : (
                          <div>
                            <span className="text-xl font-black text-primary">
                              {fmtNum(remB)}{" "}
                              <span className="text-xs font-semibold text-muted-foreground">
                                كيس
                              </span>
                            </span>
                            <div className="text-xs font-bold text-foreground">
                              {fmtNum(remK)} كجم
                            </div>
                          </div>
                        )}
                      </div>
                    </div>

                    {/* ملخص الوارد والمنصرف */}
                    <div className="mt-3 grid grid-cols-2 gap-2 rounded-xl bg-muted/40 p-2.5 text-[11px]">
                      <div>
                        <span className="text-muted-foreground">المستلم (وارد):</span>
                        <div className="font-bold text-foreground">
                          {fmtNum(r.received_bags)} كيس ({fmtNum(r.received_kg)} كجم)
                        </div>
                      </div>
                      <div>
                        <span className="text-muted-foreground">المصروف (صادر):</span>
                        <div className="font-bold text-foreground">
                          {fmtNum(r.issued_bags)} كيس ({fmtNum(r.issued_kg)} كجم)
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* أزرار العمليات السريعة بأسفل البطاقة */}
                  <div className="pt-2 border-t border-border/60 flex items-center justify-between gap-2">
                    <button
                      type="button"
                      onClick={() => openHistory(r)}
                      className="inline-flex items-center gap-1 text-xs font-semibold text-muted-foreground hover:text-foreground"
                    >
                      <FileText className="h-3.5 w-3.5" />
                      كشف الحركات
                    </button>

                    <div className="flex items-center gap-1.5">
                      {isRaw && !isZero && (
                        <button
                          type="button"
                          onClick={() => openMilling(r)}
                          className="inline-flex items-center gap-1 rounded-xl bg-amber-500/15 px-3 py-1.5 text-xs font-bold text-amber-700 dark:text-amber-300 hover:bg-amber-500/25 transition"
                        >
                          <Cog className="h-3.5 w-3.5" />
                          طحن
                        </button>
                      )}

                      {!isZero && (
                        <button
                          type="button"
                          onClick={() => openDelivery(r)}
                          className="inline-flex items-center gap-1 rounded-xl bg-emerald-500 px-3 py-1.5 text-xs font-bold text-white shadow-xs hover:bg-emerald-600 transition"
                        >
                          <PackageCheck className="h-3.5 w-3.5" />
                          تسليم
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          /* نمط العرض المضغوط عالي الكثافة (Compact View) */
          <div className="overflow-hidden rounded-2xl border border-border/80 bg-surface-1/90 shadow-sm">
            <div className="divide-y divide-border/40">
              {filteredRows.map((r, idx) => {
                const remB = Number(r.remaining_bags ?? 0);
                const remK = Number(r.remaining_kg ?? 0);
                const isRaw = r.item_class === "RAW_MATERIAL";
                const isZero = remB <= 0 && remK <= 0;

                return (
                  <div
                    key={`${r.customer_id}-${r.item_id}-${r.warehouse_id}-${idx}`}
                    className="flex flex-wrap items-center justify-between gap-3 px-4 py-2.5 text-xs hover:bg-muted/40 transition"
                  >
                    <div className="flex items-center gap-3 min-w-56">
                      <span className="font-bold text-foreground">{r.customer_name_ar}</span>
                      <span className="text-muted-foreground">•</span>
                      <span className="font-semibold text-muted-foreground">{r.item_name_ar}</span>
                      <span
                        className={`rounded-md px-1.5 py-0.2 text-[10px] font-bold ${
                          isRaw
                            ? "bg-amber-500/15 text-amber-700 dark:text-amber-300"
                            : "bg-emerald-500/15 text-emerald-700 dark:text-emerald-300"
                        }`}
                      >
                        {isRaw ? "خام" : "ناتج"}
                      </span>
                    </div>

                    <div className="flex items-center gap-4">
                      <div className="text-muted-foreground">
                        المستودع: <span className="font-semibold">{r.warehouse_name_ar}</span>
                      </div>

                      <div className="tabular-nums">
                        الرصيد:{" "}
                        {isZero ? (
                          <span className="text-muted-foreground font-semibold">مصفاة</span>
                        ) : (
                          <strong className="text-primary font-black">
                            {fmtNum(remB)} كيس ({fmtNum(remK)} كجم)
                          </strong>
                        )}
                      </div>

                      <div className="flex items-center gap-1.5">
                        {isRaw && !isZero && (
                          <button
                            type="button"
                            onClick={() => openMilling(r)}
                            className="rounded-lg bg-amber-500/15 px-2 py-0.5 text-[11px] font-bold text-amber-700 dark:text-amber-300"
                          >
                            طحن
                          </button>
                        )}
                        {!isZero && (
                          <button
                            type="button"
                            onClick={() => openDelivery(r)}
                            className="rounded-lg bg-emerald-500/15 px-2 py-0.5 text-[11px] font-bold text-emerald-700 dark:text-emerald-300"
                          >
                            تسليم
                          </button>
                        )}
                        <button
                          type="button"
                          onClick={() => openHistory(r)}
                          className="rounded-lg border border-border px-2 py-0.5 text-[11px] font-semibold text-muted-foreground hover:text-foreground"
                        >
                          كشف
                        </button>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* ─── مودال الطحن السريع (Quick Milling Dialog) المصلح بالكامل ─── */}
        {millingModalOpen && (
          <QuickMillingModal
            open={millingModalOpen}
            onClose={() => setMillingModalOpen(false)}
            initialRow={selectedRow}
            outputItems={outputItemsQuery.data ?? []}
            grainItems={grainItemsQuery.data ?? []}
            customers={customersQuery.data ?? []}
            warehouses={warehousesQuery.data ?? []}
            onSuccess={() => {
              void qc.invalidateQueries({ queryKey: ["milling"] });
              setMillingModalOpen(false);
            }}
          />
        )}

        {/* ─── مودال التسليم السريع (Quick Delivery Dialog) ─── */}
        {deliveryModalOpen && (
          <QuickDeliveryModal
            open={deliveryModalOpen}
            onClose={() => setDeliveryModalOpen(false)}
            initialRow={selectedRow}
            customers={customersQuery.data ?? []}
            warehouses={warehousesQuery.data ?? []}
            onSuccess={(voucherDoc) => {
              void qc.invalidateQueries({ queryKey: ["milling"] });
              setDeliveryModalOpen(false);
              if (voucherDoc) {
                setPrintDoc(voucherDoc);
                setPrintModalOpen(true);
              }
            }}
          />
        )}

        {/* ─── مودال كشف حركات أمانة العميل ─── */}
        {historyModalOpen && selectedRow && (
          <CustomerCustodyHistoryModal
            open={historyModalOpen}
            onClose={() => setHistoryModalOpen(false)}
            row={selectedRow}
            onPrint={(doc) => {
              setPrintDoc(doc);
              setPrintModalOpen(true);
            }}
            onShare={(data) => {
              setShareData(data);
              setShareDialogOpen(true);
            }}
          />
        )}

        {/* نافذة الطباعة الفاخرة الموحدة لسندات وفواتير المطحنة */}
        {printDoc && (
          <UnifiedPrintModal
            open={printModalOpen}
            onClose={() => {
              setPrintModalOpen(false);
              setPrintDoc(null);
            }}
            doc={printDoc}
            stage={printDoc.docType === "delivery_note" ? "delivery" : "intake"}
          />
        )}

        {/* نافذة المشاركة الفورية عبر واتساب */}
        <DocumentShareDialog
          open={shareDialogOpen}
          onClose={() => setShareDialogOpen(false)}
          title="مشاركة كشف وسند الأمانة"
          documentType="milling_document"
          millingDocumentNumber={shareData?.docNumber || ""}
          customer={
            shareData
              ? {
                  id: selectedRow?.customer_id || "",
                  name: shareData.customerName,
                  phone: shareData.phone || undefined,
                  balance: 0,
                }
              : undefined
          }
        />
      </div>
    </ModuleGuard>
  );
}

/* =========================================================================
   مكون مودال الطحن السريع (Quick Milling Modal) المصلح بالكامل
   ========================================================================= */
function QuickMillingModal({
  open,
  onClose,
  initialRow,
  outputItems,
  grainItems,
  customers,
  warehouses,
  onSuccess,
}: {
  open: boolean;
  onClose: () => void;
  initialRow: CustodyStatementRow | null;
  outputItems: ProductOption[];
  grainItems: ProductOption[];
  customers: { id: string; name: string; phone?: string | null }[];
  warehouses: { id: string; name: string; name_ar: string | null }[];
  onSuccess: () => void;
}) {
  const [customerId, setCustomerId] = useState(initialRow?.customer_id || "");
  const [warehouseId, setWarehouseId] = useState(initialRow?.warehouse_id || "");
  const [grainItemId, setGrainItemId] = useState(initialRow?.item_id || "");
  const [grainCapacityKg, setGrainCapacityKg] = useState<string>("50");

  // الحبوب المطحونة (الأكياس والوزن تبدأ فارغة لتفادي الـ 0 المزعج)
  const [bagsOut, setBagsOut] = useState("");
  const [kgOut, setKgOut] = useState("");
  const [kgAuto, setKgAuto] = useState(true);

  // نواتج الطحن (الدقيق والنخالة)
  const [outputs, setOutputs] = useState<
    { itemId: string; bags: string; kg: string; capacity: number }[]
  >([{ itemId: "", bags: "", kg: "", capacity: 50 }]);

  const [notes, setNotes] = useState("");

  // رصيد الحبوب المتاح لهذا العميل والصنف
  const maxAvailableBags = initialRow ? Number(initialRow.remaining_bags ?? 0) : 9999;
  const maxAvailableKg = initialRow ? Number(initialRow.remaining_kg ?? 0) : 999999;

  // عند تغيير عدد الأكياس المطحونة
  function handleBagsOutChange(v: string) {
    setBagsOut(v);
    const n = Number(v) || 0;
    const cap = Number(grainCapacityKg) || 0;
    if (cap > 0 && (kgAuto || kgOut === "")) {
      setKgOut(n > 0 ? String(n * cap) : "");
      setKgAuto(true);
    }
  }

  // إضافة ناتج جديد
  function addOutputLine() {
    setOutputs((prev) => [...prev, { itemId: "", bags: "", kg: "", capacity: 50 }]);
  }

  // حذف سطر ناتج
  function removeOutputLine(index: number) {
    setOutputs((prev) => prev.filter((_, i) => i !== index));
  }

  // تعديل سطر ناتج
  function updateOutputLine(index: number, field: "itemId" | "bags" | "kg" | "capacity", val: any) {
    setOutputs((prev) => {
      const copy = [...prev];
      const cur = { ...copy[index], [field]: val };

      // إذا غيّر الصنف أو السعة، نحسب الوزن تلقائياً إن وجدت أكياس
      if (field === "itemId") {
        const item = outputItems.find((o) => o.id === val);
        if (item?.package_weight_kg) {
          cur.capacity = item.package_weight_kg;
          if (Number(cur.bags) > 0) cur.kg = String(Number(cur.bags) * cur.capacity);
        }
      } else if (field === "capacity") {
        const cap = Number(val) || 0;
        if (cap > 0 && Number(cur.bags) > 0) {
          cur.kg = String(Number(cur.bags) * cap);
        }
      } else if (field === "bags") {
        const b = Number(val) || 0;
        if (cur.capacity > 0) {
          cur.kg = b > 0 ? String(b * cur.capacity) : "";
        }
      }

      copy[index] = cur;
      return copy;
    });
  }

  // حساب إجمالي النواتج لمقارنتها بوزن الحبوب المطحونة
  const totalOutputsKg = useMemo(() => {
    return outputs.reduce((acc, line) => acc + (Number(line.kg) || 0), 0);
  }, [outputs]);

  const totalGrainKg = Number(kgOut) || 0;
  const extractionRatio = totalGrainKg > 0 ? Math.round((totalOutputsKg / totalGrainKg) * 100) : 0;

  const millingMutation = useMutation({
    mutationFn: async () => {
      const validOutputs: CustodyLine[] = outputs
        .filter((o) => o.itemId && (Number(o.bags) > 0 || Number(o.kg) > 0))
        .map((o) => ({
          itemId: o.itemId,
          bags: Number(o.bags) || 0,
          kg: Number(o.kg) || 0,
        }));

      return custodyMilling({
        customerId,
        warehouseId,
        grainItemId,
        bagsOut: Number(bagsOut) || 0,
        kgOut: Number(kgOut) || 0,
        outputs: validOutputs,
        notes: notes.trim() || undefined,
      });
    },
    onSuccess: (res) => {
      if (!res.ok) {
        toast.error(res.message || "تعذر تسجيل عملية الطحن.");
        return;
      }
      toast.success("تم تسجيل عملية الطحن وإيداع النواتج في أمانات العميل بنجاح.");
      onSuccess();
    },
    onError: (err) => toast.error(err instanceof Error ? err.message : "خطأ غير متوقع"),
  });

  const canSubmit =
    Boolean(customerId && warehouseId && grainItemId) &&
    (Number(bagsOut) > 0 || Number(kgOut) > 0) &&
    outputs.some((o) => o.itemId && (Number(o.bags) > 0 || Number(o.kg) > 0));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-xs overflow-y-auto">
      <div className="w-full max-w-2xl rounded-2xl border border-border bg-card shadow-2xl overflow-hidden my-8">
        {/* رأس المودال */}
        <div className="flex items-center justify-between border-b border-border/70 p-4 bg-muted/40">
          <div className="flex items-center gap-2">
            <div className="grid h-9 w-9 place-items-center rounded-xl bg-amber-500/15 text-amber-600 dark:text-amber-400">
              <Cog className="h-5 w-5" />
            </div>
            <div>
              <h3 className="font-bold text-sm text-foreground">طحن أمانة حبوب العميل</h3>
              <p className="text-xs text-muted-foreground">
                خصم الحبوب المطحونة وإيداع الدقيق والنخالة في رصيد أمانات العميل.
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg p-1.5 text-muted-foreground hover:bg-muted hover:text-foreground"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* جسم المودال */}
        <div className="space-y-4 p-5 max-h-[80vh] overflow-y-auto">
          {/* معلومات العميل والمستودع والصنف */}
          <div className="grid gap-3 sm:grid-cols-3">
            <MillingField label="العميل *">
              <MillingSelect
                value={customerId}
                onChange={(e) => setCustomerId(e.target.value)}
                disabled={Boolean(initialRow)}
                className="font-semibold text-xs"
              >
                <option value="">اختر العميل…</option>
                {customers.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </MillingSelect>
            </MillingField>

            <MillingField label="المستودع *">
              <MillingSelect
                value={warehouseId}
                onChange={(e) => setWarehouseId(e.target.value)}
                disabled={Boolean(initialRow)}
                className="font-semibold text-xs"
              >
                <option value="">اختر المستودع…</option>
                {warehouses.map((w) => (
                  <option key={w.id} value={w.id}>
                    {w.name_ar || w.name}
                  </option>
                ))}
              </MillingSelect>
            </MillingField>

            <MillingField label="صنف الحبوب المطحونة *">
              <MillingSelect
                value={grainItemId}
                onChange={(e) => setGrainItemId(e.target.value)}
                disabled={Boolean(initialRow)}
                className="font-semibold text-xs"
              >
                <option value="">اختر الحبوب…</option>
                {grainItems.map((g) => (
                  <option key={g.id} value={g.id}>
                    {g.name_ar || g.name}
                  </option>
                ))}
              </MillingSelect>
            </MillingField>
          </div>

          {/* بطاقة الرصيد المتاح للحبوب */}
          {initialRow && (
            <div className="flex items-center justify-between rounded-xl border border-amber-500/25 bg-amber-500/5 px-3.5 py-2 text-xs">
              <span className="font-semibold text-muted-foreground">رصيد الحبوب المتاح للطحن:</span>
              <div className="flex items-center gap-2">
                <span className="font-bold text-amber-700 dark:text-amber-300">
                  {fmtNum(initialRow.remaining_bags)} كيس
                </span>
                <span>•</span>
                <span className="font-bold text-foreground">
                  {fmtNum(initialRow.remaining_kg)} كجم
                </span>
              </div>
            </div>
          )}

          {/* كمية الحبوب المطحونة (أكياس ووزن) */}
          <div className="rounded-xl border border-border/80 bg-surface-2/40 p-3.5 space-y-3">
            <div className="flex items-center justify-between text-xs font-bold text-foreground">
              <span>كمية الحبوب المراد طحنها (المنصرف من الخام):</span>
              <div className="flex items-center gap-1.5">
                <span className="text-[11px] font-normal text-muted-foreground">سعة الكيس:</span>
                {PRESET_CAPACITIES.slice(0, 3).map((cap) => (
                  <button
                    key={cap}
                    type="button"
                    onClick={() => {
                      setGrainCapacityKg(String(cap));
                      if (Number(bagsOut) > 0) setKgOut(String(Number(bagsOut) * cap));
                    }}
                    className={`rounded-md px-2 py-0.5 text-[10px] font-bold ${
                      Number(grainCapacityKg) === cap
                        ? "bg-amber-500 text-white"
                        : "border border-border bg-card"
                    }`}
                  >
                    {cap}كجم
                  </button>
                ))}
              </div>
            </div>

            <div className="grid gap-3 sm:grid-cols-2">
              <MillingField label="عدد الأكياس المطحونة *">
                <QuantityInput
                  decimals={0}
                  min={1}
                  max={maxAvailableBags}
                  placeholder="0"
                  aria-label="عدد الأكياس المطحونة"
                  value={bagsOut === "" ? null : Number(bagsOut)}
                  onValueChange={(v) => handleBagsOutChange(v == null ? "" : String(v))}
                  className="font-bold text-amber-600 dark:text-amber-400"
                />
              </MillingField>

              <MillingField label="الوزن الإجمالي بالكجم *">
                <QuantityInput
                  decimals={2}
                  min={0.1}
                  unit="kg"
                  placeholder="0.00"
                  aria-label="الوزن الإجمالي بالكجم"
                  value={kgOut === "" ? null : Number(kgOut)}
                  onValueChange={(v) => {
                    setKgOut(v == null ? "" : String(v));
                    setKgAuto(false);
                  }}
                  className="font-bold"
                />
              </MillingField>
            </div>
          </div>

          {/* قسم نواتج الطحن المودعة في الأمانات */}
          <div className="space-y-2.5">
            <div className="flex items-center justify-between">
              <span className="text-xs font-bold text-foreground">
                نواتج الطحن المودعة في رصيد العميل:
              </span>
              <button
                type="button"
                onClick={addOutputLine}
                className="inline-flex items-center gap-1 rounded-lg border border-primary/30 bg-primary/10 px-2.5 py-1 text-xs font-bold text-primary hover:bg-primary/20 transition"
              >
                <Plus className="h-3.5 w-3.5" />
                إضافة ناتج
              </button>
            </div>

            <div className="space-y-2">
              {outputs.map((line, idx) => (
                <div
                  key={idx}
                  className="grid grid-cols-12 gap-2 items-center rounded-xl border border-border/80 bg-surface-2/60 p-2 text-xs"
                >
                  {/* صنف الناتج */}
                  <div className="col-span-5">
                    <MillingSelect
                      value={line.itemId}
                      onChange={(e) => updateOutputLine(idx, "itemId", e.target.value)}
                      className="font-semibold text-xs"
                    >
                      <option value="">اختر الناتج (دقيق/نخالة)…</option>
                      {outputItems.map((item) => (
                        <option key={item.id} value={item.id}>
                          {item.name_ar || item.name}
                        </option>
                      ))}
                    </MillingSelect>
                  </div>

                  {/* سعة الكيس */}
                  <div className="col-span-2">
                    <MillingSelect
                      value={line.capacity}
                      onChange={(e) => updateOutputLine(idx, "capacity", Number(e.target.value))}
                      className="text-center font-bold text-xs"
                    >
                      <option value={50}>50 كجم</option>
                      <option value={25}>25 كجم</option>
                      <option value={20}>20 كجم</option>
                      <option value={10}>10 كجم</option>
                    </MillingSelect>
                  </div>

                  {/* عدد الأكياس */}
                  <div className="col-span-2">
                    <QuantityInput
                      decimals={0}
                      min={0}
                      placeholder="أكياس"
                      aria-label="عدد الأكياس"
                      value={line.bags === "" ? null : Number(line.bags)}
                      onValueChange={(v) =>
                        updateOutputLine(idx, "bags", v == null ? "" : String(v))
                      }
                      className="font-bold text-center text-xs"
                    />
                  </div>

                  {/* الوزن كجم */}
                  <div className="col-span-2">
                    <QuantityInput
                      decimals={2}
                      min={0}
                      placeholder="كجم"
                      aria-label="الوزن كجم"
                      value={line.kg === "" ? null : Number(line.kg)}
                      onValueChange={(v) => updateOutputLine(idx, "kg", v == null ? "" : String(v))}
                      className="font-bold text-center text-xs"
                    />
                  </div>

                  {/* حذف */}
                  <div className="col-span-1 text-center">
                    {outputs.length > 1 && (
                      <button
                        type="button"
                        onClick={() => removeOutputLine(idx)}
                        className="rounded-lg p-1 text-rose-500 hover:bg-rose-500/10 transition"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>

            {/* شريط المطابقة الذكي */}
            <div className="flex flex-wrap items-center justify-between gap-2 rounded-xl bg-muted/60 p-3 text-xs">
              <div className="flex items-center gap-3">
                <span>
                  حبوب خام مطحونة: <strong className="text-foreground">{totalGrainKg}</strong> كجم
                </span>
                <span>•</span>
                <span>
                  إجمالي النواتج: <strong className="text-foreground">{totalOutputsKg}</strong> كجم
                </span>
              </div>
              <div className="flex items-center gap-1.5">
                <span className="text-muted-foreground">نسبة الاستخراج:</span>
                <span
                  className={`font-black tabular-nums ${
                    extractionRatio > 105
                      ? "text-rose-600"
                      : extractionRatio >= 90
                        ? "text-emerald-600"
                        : "text-amber-600"
                  }`}
                >
                  {extractionRatio}%
                </span>
              </div>
            </div>
          </div>

          {/* ملاحظات الطحن */}
          <MillingField label="ملاحظات تشغيلية">
            <MillingInput
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="مثال: طحن ناعم درجة أولى — مشغل الوردية الصباحية"
            />
          </MillingField>
        </div>

        {/* أزرار الإجراءات */}
        <div className="flex items-center justify-end gap-2 border-t border-border/70 p-4 bg-muted/30">
          <button
            type="button"
            onClick={onClose}
            className="rounded-xl border border-border px-4 py-2 text-xs font-semibold text-muted-foreground hover:bg-muted"
          >
            إلغاء
          </button>
          <button
            type="button"
            disabled={!canSubmit || millingMutation.isPending}
            onClick={() => millingMutation.mutate()}
            className="inline-flex items-center gap-1.5 rounded-xl bg-amber-500 px-5 py-2 text-xs font-bold text-white shadow-xs transition hover:bg-amber-600 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {millingMutation.isPending ? (
              <>
                <RefreshCw className="h-3.5 w-3.5 animate-spin" />
                جارٍ تنفيذ الطحن…
              </>
            ) : (
              <>
                <Check className="h-4 w-4" />
                تأكيد وقيد عملية الطحن
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

/* =========================================================================
   مكون مودال التسليم السريع (Quick Delivery Modal)
   ========================================================================= */
function QuickDeliveryModal({
  open,
  onClose,
  initialRow,
  customers,
  warehouses,
  onSuccess,
}: {
  open: boolean;
  onClose: () => void;
  initialRow: CustodyStatementRow | null;
  customers: { id: string; name: string }[];
  warehouses: { id: string; name: string; name_ar: string | null }[];
  onSuccess: (doc?: UnifiedDocumentData) => void;
}) {
  const [customerId, setCustomerId] = useState(initialRow?.customer_id || "");
  const [warehouseId, setWarehouseId] = useState(initialRow?.warehouse_id || "");
  const [itemId, setItemId] = useState(initialRow?.item_id || "");
  const [bags, setBags] = useState("");
  const [kg, setKg] = useState("");
  const [notes, setNotes] = useState("");

  const maxBags = initialRow ? Number(initialRow.remaining_bags ?? 0) : 9999;
  const maxKg = initialRow ? Number(initialRow.remaining_kg ?? 0) : 999999;

  // زر بنقرة واحدة لتسليم كامل الرصيد المتبقي
  function handleDeliverAll() {
    if (initialRow) {
      setBags(String(initialRow.remaining_bags));
      setKg(String(initialRow.remaining_kg));
    }
  }

  const deliveryMutation = useMutation({
    mutationFn: async () => {
      return custodyDelivery({
        customerId,
        warehouseId,
        lines: [
          {
            itemId,
            bags: Number(bags) || 0,
            kg: Number(kg) || 0,
          },
        ],
        notes: notes.trim() || undefined,
      });
    },
    onSuccess: (res) => {
      if (!res.ok) {
        toast.error(res.message || "تعذر تسجيل التسليم.");
        return;
      }
      toast.success("تم تسجيل تسليم الأمانة للعميل بنجاح.");

      const docNumber = (res.data as string) || `DEL-${Date.now().toString().slice(-6)}`;
      const selectedCust = customers.find((c) => c.id === customerId);
      const selectedWh = warehouses.find((w) => w.id === warehouseId);
      const prevBags = Number(initialRow?.remaining_bags ?? bags);
      const prevKg = Number(initialRow?.remaining_kg ?? kg);
      const delBags = Number(bags) || 0;
      const delKg = Number(kg) || 0;
      const remBags = Math.max(0, prevBags - delBags);
      const remKg = Math.max(0, prevKg - delKg);

      const voucherDoc = buildCustodyDeliveryDoc({
        docNumber,
        customerName: selectedCust?.name || initialRow?.customer_name_ar || "عميل أمانة",
        warehouseName:
          selectedWh?.name_ar ||
          selectedWh?.name ||
          initialRow?.warehouse_name_ar ||
          "المستودع الرئيسي",
        lines: [
          {
            itemName: initialRow?.item_name_ar || "صنف ناتج",
            previousBags: prevBags,
            previousKg: prevKg,
            deliveredBags: delBags,
            deliveredKg: delKg,
            remainingBags: remBags,
            remainingKg: remKg,
            unit: delBags > 0 ? "كيس" : "كجم",
            note: notes.trim() || undefined,
          },
        ],
        notes: notes.trim() || undefined,
      });

      onSuccess(voucherDoc);
    },
    onError: (err) => toast.error(err instanceof Error ? err.message : "خطأ غير متوقع"),
  });

  const canSubmit =
    Boolean(customerId && warehouseId && itemId) && (Number(bags) > 0 || Number(kg) > 0);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-xs">
      <div className="w-full max-w-lg rounded-2xl border border-border bg-card shadow-2xl overflow-hidden">
        {/* الرأس */}
        <div className="flex items-center justify-between border-b border-border/70 p-4 bg-muted/40">
          <div className="flex items-center gap-2">
            <div className="grid h-9 w-9 place-items-center rounded-xl bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
              <PackageCheck className="h-5 w-5" />
            </div>
            <div>
              <h3 className="font-bold text-sm text-foreground">تسليم أمانة للعميل</h3>
              <p className="text-xs text-muted-foreground">
                صرف وخروج الأمانات من المستودع لصاحب الأمانة.
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-lg p-1.5 text-muted-foreground hover:bg-muted hover:text-foreground"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* النموذج */}
        <div className="space-y-4 p-5">
          <div className="grid gap-3 sm:grid-cols-2">
            <MillingField label="العميل المستلم *">
              <MillingSelect
                value={customerId}
                onChange={(e) => setCustomerId(e.target.value)}
                disabled={Boolean(initialRow)}
                className="font-semibold text-xs"
              >
                <option value="">اختر العميل…</option>
                {customers.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </MillingSelect>
            </MillingField>

            <MillingField label="المستودع *">
              <MillingSelect
                value={warehouseId}
                onChange={(e) => setWarehouseId(e.target.value)}
                disabled={Boolean(initialRow)}
                className="font-semibold text-xs"
              >
                <option value="">اختر المستودع…</option>
                {warehouses.map((w) => (
                  <option key={w.id} value={w.id}>
                    {w.name_ar || w.name}
                  </option>
                ))}
              </MillingSelect>
            </MillingField>
          </div>

          {/* بطاقة الرصيد المتاح للصنف المسلم */}
          {initialRow && (
            <div className="flex items-center justify-between rounded-xl border border-emerald-500/25 bg-emerald-500/5 p-3 text-xs">
              <div>
                <span className="text-muted-foreground">صنف الأمانة:</span>
                <p className="font-bold text-foreground text-sm">{initialRow.item_name_ar}</p>
              </div>

              <div className="text-end">
                <span className="text-muted-foreground">الرصيد المتاح للتسليم:</span>
                <div className="font-black text-emerald-700 dark:text-emerald-300">
                  {fmtNum(initialRow.remaining_bags)} كيس ({fmtNum(initialRow.remaining_kg)} كجم)
                </div>
              </div>
            </div>
          )}

          {/* كمية التسليم وزر تسليم كامل الرصيد */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <label className="text-xs font-semibold text-muted-foreground">
                الكمية المراد تسليمها للعميل:
              </label>
              {initialRow && (
                <button
                  type="button"
                  onClick={handleDeliverAll}
                  className="rounded-lg bg-emerald-500/10 px-2.5 py-0.5 text-[11px] font-bold text-emerald-700 dark:text-emerald-300 hover:bg-emerald-500/20"
                >
                  تسليم كامل الرصيد
                </button>
              )}
            </div>

            <div className="grid gap-3 sm:grid-cols-2">
              <MillingField label="عدد الأكياس المسلمة">
                <QuantityInput
                  decimals={0}
                  min={1}
                  max={maxBags}
                  placeholder="0"
                  aria-label="عدد الأكياس المسلمة"
                  value={bags === "" ? null : Number(bags)}
                  onValueChange={(v) => setBags(v == null ? "" : String(v))}
                  className="font-bold text-emerald-600 dark:text-emerald-400"
                />
              </MillingField>

              <MillingField label="الوزن الإجمالي بالكجم">
                <QuantityInput
                  decimals={2}
                  min={0.1}
                  unit="kg"
                  placeholder="0.00"
                  aria-label="الوزن الإجمالي بالكجم"
                  value={kg === "" ? null : Number(kg)}
                  onValueChange={(v) => setKg(v == null ? "" : String(v))}
                  className="font-bold"
                />
              </MillingField>
            </div>
          </div>

          <MillingField label="ملاحظات التسليم والمستلم">
            <MillingInput
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="مثال: استلم بواسطة السائق / رقم الشاحنة أو الإشعار"
            />
          </MillingField>
        </div>

        {/* الإجراءات */}
        <div className="flex items-center justify-end gap-2 border-t border-border/70 p-4 bg-muted/30">
          <button
            type="button"
            onClick={onClose}
            className="rounded-xl border border-border px-4 py-2 text-xs font-semibold text-muted-foreground hover:bg-muted"
          >
            إلغاء
          </button>
          <button
            type="button"
            disabled={!canSubmit || deliveryMutation.isPending}
            onClick={() => deliveryMutation.mutate()}
            className="inline-flex items-center gap-1.5 rounded-xl bg-emerald-600 px-5 py-2 text-xs font-bold text-white shadow-xs transition hover:bg-emerald-700 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {deliveryMutation.isPending ? (
              <>
                <RefreshCw className="h-3.5 w-3.5 animate-spin" />
                جارٍ تسجيل التسليم…
              </>
            ) : (
              <>
                <Check className="h-4 w-4" />
                تأكيد تسليم الأمانة
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

/* =========================================================================
   مكون مودال كشف حركات أمانة العميل وتاريخها
   ========================================================================= */
function CustomerCustodyHistoryModal({
  open,
  onClose,
  row,
  onPrint,
  onShare,
}: {
  open: boolean;
  onClose: () => void;
  row: CustodyStatementRow;
  onPrint: (doc: UnifiedDocumentData) => void;
  onShare: (data: { customerName: string; phone?: string; docNumber?: string }) => void;
}) {
  // جلب سجل الحركات للعميل والصنف
  const ledgerQuery = useQuery({
    queryKey: ["milling", "customer-ledger", row.customer_id, row.item_id],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("custody_ledger")
        .select("*")
        .eq("customer_id", row.customer_id)
        .eq("item_id", row.item_id)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return (data ?? []) as any[];
    },
  });

  const lines = ledgerQuery.data ?? [];

  // إعداد مستند للطباعة الموحدة
  function handlePrintStatement() {
    const doc: UnifiedDocumentData = {
      docType: "mill_document",
      title: "كشف حساب أمانات العميل العيني",
      number: `CUST-${row.customer_id.slice(0, 8).toUpperCase()}`,
      date: new Date().toLocaleDateString("ar-YE"),
      partyLabel: "صاحب الأمانة / العميل:",
      partyName: row.customer_name_ar,
      warehouse: row.warehouse_name_ar || "المستودع الرئيسي",
      movementType: `حركات الصنف: ${row.item_name_ar} (${row.item_class === "RAW_MATERIAL" ? "حبوب خام" : "نواتج"})`,
      status: Number(row.remaining_bags) > 0 ? "رصيد أمانات قائم" : "تم تسليم كامل الأمانة",
      lines: lines.map((l: any) => ({
        product: `${l.entry_type === "INTAKE" ? "استلام" : l.entry_type === "MILLING" ? "طحن" : "تسليم"} [${l.doc_number || "—"}]`,
        qty: Number(l.bags_in || l.bags_out || 0),
        unit: "كيس",
        price: 0,
        total: 0,
        note: `${Number(l.kg_in || l.kg_out || 0)} كجم | ${l.notes || ""}`,
      })),
      subtotal: 0,
      total: 0,
      paid: 0,
      balance: 0,
      notes: `الرصيد المتبقي الحالي في المستودع: ${fmtNum(row.remaining_bags)} كيس (${fmtNum(row.remaining_kg)} كجم). أمانات عينية خاصة بالعميل.`,
    };
    onPrint(doc);
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-xs">
      <div className="w-full max-w-3xl rounded-2xl border border-border bg-card shadow-2xl overflow-hidden my-8">
        {/* الرأس */}
        <div className="flex items-center justify-between border-b border-border/70 p-4 bg-muted/40">
          <div className="flex items-center gap-2">
            <div className="grid h-9 w-9 place-items-center rounded-xl bg-primary/10 text-primary">
              <FileText className="h-5 w-5" />
            </div>
            <div>
              <h3 className="font-bold text-sm text-foreground">
                كشف حركات الأمانة: {row.customer_name_ar}
              </h3>
              <p className="text-xs text-muted-foreground">
                صنف: {row.item_name_ar} • المستودع: {row.warehouse_name_ar}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={handlePrintStatement}
              className="inline-flex items-center gap-1 rounded-xl bg-primary px-3 py-1.5 text-xs font-bold text-primary-foreground hover:bg-primary/90"
            >
              <Printer className="h-3.5 w-3.5" />
              طباعة الكشف
            </button>
            <button
              type="button"
              onClick={() =>
                onShare({
                  customerName: row.customer_name_ar,
                  docNumber: `CUST-${row.customer_id.slice(0, 8)}`,
                })
              }
              className="inline-flex items-center gap-1 rounded-xl border border-border bg-card px-3 py-1.5 text-xs font-bold text-foreground hover:bg-muted"
            >
              <Share2 className="h-3.5 w-3.5 text-emerald-600" />
              واتساب
            </button>
            <button
              type="button"
              onClick={onClose}
              className="rounded-lg p-1.5 text-muted-foreground hover:bg-muted hover:text-foreground"
            >
              <X className="h-4 w-4" />
            </button>
          </div>
        </div>

        {/* ملخص الرصيد الحالي */}
        <div className="grid grid-cols-3 gap-3 p-4 bg-surface-2/40 border-b border-border/60 text-xs text-center">
          <div>
            <span className="text-muted-foreground">إجمالي الوارد (مستلم):</span>
            <p className="font-bold text-foreground mt-0.5">
              {fmtNum(row.received_bags)} كيس ({fmtNum(row.received_kg)} كجم)
            </p>
          </div>
          <div>
            <span className="text-muted-foreground">إجمالي المنصرف (صادر):</span>
            <p className="font-bold text-foreground mt-0.5">
              {fmtNum(row.issued_bags)} كيس ({fmtNum(row.issued_kg)} كجم)
            </p>
          </div>
          <div className="bg-primary/10 rounded-xl p-1.5">
            <span className="text-primary font-bold">الرصيد المتبقي حالياً:</span>
            <p className="font-black text-primary text-sm mt-0.5">
              {fmtNum(row.remaining_bags)} كيس ({fmtNum(row.remaining_kg)} كجم)
            </p>
          </div>
        </div>

        {/* جدول الحركات */}
        <div className="p-4 max-h-96 overflow-y-auto">
          {ledgerQuery.isLoading ? (
            <div className="p-8 text-center text-xs text-muted-foreground">
              جارٍ تحميل سجل الحركات…
            </div>
          ) : lines.length === 0 ? (
            <div className="p-8 text-center text-xs text-muted-foreground">
              لا توجد حركات مسجلة لهذا الصنف.
            </div>
          ) : (
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-border/60 text-muted-foreground font-bold">
                  <th className="pb-2 text-start">نوع الحركة</th>
                  <th className="pb-2 text-start">رقم السند/المستند</th>
                  <th className="pb-2 text-center">وارد (داخل)</th>
                  <th className="pb-2 text-center">منصرف (خارج)</th>
                  <th className="pb-2 text-start">الملاحظات</th>
                  <th className="pb-2 text-end">التاريخ والوقت</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border/30">
                {lines.map((l: any) => (
                  <tr key={l.id} className="hover:bg-muted/30">
                    <td className="py-2.5 font-bold">
                      {l.entry_type === "INTAKE" ? (
                        <span className="text-emerald-600">استلام أمانة</span>
                      ) : l.entry_type === "MILLING" ? (
                        <span className="text-amber-600">طحن</span>
                      ) : l.entry_type === "DELIVERY" ? (
                        <span className="text-blue-600">تسليم ناتج</span>
                      ) : (
                        <span>تعديل</span>
                      )}
                    </td>
                    <td className="py-2.5 font-mono text-foreground font-semibold">
                      {l.doc_number || "—"}
                    </td>
                    <td className="py-2.5 text-center tabular-nums font-semibold text-emerald-600">
                      {Number(l.bags_in) > 0 || Number(l.kg_in) > 0
                        ? `${fmtNum(l.bags_in)} كيس (${fmtNum(l.kg_in)} كجم)`
                        : "—"}
                    </td>
                    <td className="py-2.5 text-center tabular-nums font-semibold text-rose-600">
                      {Number(l.bags_out) > 0 || Number(l.kg_out) > 0
                        ? `${fmtNum(l.bags_out)} كيس (${fmtNum(l.kg_out)} كجم)`
                        : "—"}
                    </td>
                    <td className="py-2.5 text-muted-foreground">{l.notes || "—"}</td>
                    <td className="py-2.5 text-end text-muted-foreground text-[11px]">
                      {new Date(l.created_at).toLocaleString("ar-EG")}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>

        {/* الإغلاق */}
        <div className="flex justify-end border-t border-border/70 p-3 bg-muted/20">
          <button
            type="button"
            onClick={onClose}
            className="rounded-xl border border-border px-4 py-1.5 text-xs font-semibold text-muted-foreground hover:bg-muted"
          >
            إغلاق
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * /milling/manufacture — زر التصنيع الذكي المطور (طحن منتجات المنشأة).
 *
 * وثيقة الماستر بلان الشاملة (DOC-MILLING-ERP-MASTER-2026-V2-AUDITED):
 * 1. مدخلات الحبوب بالأكياس وسعة الكيس أو بالكيلو مع الرصيد اللحظي.
 * 2. الفاقد التشغيلي المرن والاختياري (إدخال يدوي أو احتساب تلقائي عند تركه فارغاً).
 * 3. المساعد الذكي المقترح ⚡ لحساب الأكياس بنقرة واحدة (اختياري).
 * 4. توزيع التكلفة النسبي حسب القيمة البيعية مع عرض تكلفة الكيس وهامش الربح.
 * 5. فحص وتحققات تمنع التجاوزات والأخطاء المحاسبية.
 */
import { createFileRoute, Link } from "@tanstack/react-router";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useEffect, useMemo, useState } from "react";
import {
  Factory,
  Plus,
  Trash2,
  ArrowLeft,
  Info,
  Package,
  AlertTriangle,
  CheckCircle2,
  TrendingDown,
  PieChart,
  Warehouse as WarehouseIcon,
  Layers,
  Sparkles,
  Zap,
  TrendingUp,
} from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { PageHeader } from "@/components/page-header";
import { ModuleGuard } from "@/lib/modules";
import { supabase } from "@/integrations/supabase/client";
import {
  smartManufacture,
  fetchGrainItems,
  fetchOutputItems,
  type ProductOption,
} from "@/lib/milling";
import {
  MillingPanel,
  MillingSectionTitle,
  MillingField,
  MillingInput,
  MillingSelect,
  MillingTextarea,
  Mono,
  fmtNum,
} from "@/components/milling/milling-ui";
import { QuantityInput } from "@/components/ui/quantity-input";
import { BagWeightInput } from "@/components/milling/bag-weight-input";

export const Route = createFileRoute("/_app/milling/manufacture")({
  head: () => ({ meta: [{ title: "التصنيع الذكي وطحن منتجات المنشأة — فورتكس ERP" }] }),
  component: SmartManufacturePage,
});

interface WarehouseOption {
  id: string;
  name_ar: string | null;
  name: string;
  is_default: boolean | null;
}

interface OutputLine {
  itemId: string;
  packageType: "bulk" | "50" | "25" | "10" | "5" | "custom";
  customPackageKg?: string;
  bagsCount?: string;
  qty: string; // Net weight in kg
}

export function SmartManufacturePage() {
  const qc = useQueryClient();
  const [warehouseId, setWarehouseId] = useState("");
  const [grainItemId, setGrainItemId] = useState("");
  const [grainBags, setGrainBags] = useState("");
  const [grainCapacityKg, setGrainCapacityKg] = useState("50");
  const [grainQty, setGrainQty] = useState("");
  const [batchRef, setBatchRef] = useState("");
  const [notes, setNotes] = useState("");
  const [manualWasteKg, setManualWasteKg] = useState("");

  const [outputs, setOutputs] = useState<OutputLine[]>([
    { itemId: "", packageType: "50", bagsCount: "", qty: "" },
  ]);

  // مستودعات النظام
  const warehouses = useQuery({
    queryKey: ["milling", "warehouses"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("warehouses")
        .select("id, name, name_ar, is_default")
        .eq("is_active", true)
        .order("is_default", { ascending: false });
      if (error) throw error;
      return (data ?? []) as WarehouseOption[];
    },
  });

  // تحديد المستودع الافتراضي تلقائياً
  useEffect(() => {
    if (warehouseId) return;
    const list = warehouses.data ?? [];
    const preferred = list.find((w) => w.is_default) ?? list[0];
    if (preferred) setWarehouseId(preferred.id);
  }, [warehouses.data, warehouseId]);

  // قائمة أصناف الحبوب المتاحة
  const grainItems = useQuery({
    queryKey: ["milling", "grain-items"],
    queryFn: fetchGrainItems,
  });

  // قائمة النواتج المتاحة
  const outputItems = useQuery({
    queryKey: ["milling", "output-items"],
    queryFn: fetchOutputItems,
  });

  const allItems = [...(grainItems.data ?? []), ...(outputItems.data ?? [])];
  const selectedGrain = grainItems.data?.find((g) => g.id === grainItemId);

  // تحديث سعة كيس القمح تلقائياً عند تغيير الصنف
  useEffect(() => {
    if (selectedGrain?.package_weight_kg) {
      setGrainCapacityKg(String(selectedGrain.package_weight_kg));
    }
  }, [selectedGrain]);

  // الرصيد المخزني المتاح للقمح في المستودع المختار
  const grainStockQuery = useQuery({
    queryKey: ["milling", "grain-stock", warehouseId, grainItemId],
    queryFn: async () => {
      if (!warehouseId || !grainItemId) return 0;
      const { data, error } = await supabase
        .from("inventory")
        .select("quantity")
        .eq("warehouse_id", warehouseId)
        .eq("product_id", grainItemId)
        .maybeSingle();

      if (error) {
        console.error("Error fetching grain stock:", error);
        return 0;
      }
      return Number(data?.quantity ?? 0);
    },
    enabled: Boolean(warehouseId && grainItemId),
  });

  const availableStock = grainStockQuery.data ?? 0;
  const numGrainQty = Number(grainQty) || 0;
  const isOverStock = availableStock > 0 && numGrainQty > availableStock;

  // احتساب إجمالي النواتج بالكجم
  const totalOutputKg = useMemo(() => {
    return outputs.reduce((sum, l) => sum + (Number(l.qty) || 0), 0);
  }, [outputs]);

  // معالجة الفاقد التشغيلي المرن: إدخال يدوي أو احتساب تلقائي
  const hasManualWaste = manualWasteKg.trim() !== "";
  const parsedManualWaste = Number(manualWasteKg) || 0;
  const autoWasteKg = Math.max(0, numGrainQty - totalOutputKg);
  const effectiveWasteKg = hasManualWaste ? parsedManualWaste : autoWasteKg;

  const isOutputsOverGrain = numGrainQty > 0 && totalOutputKg > numGrainQty;
  const isOutputsPlusWasteOverGrain =
    numGrainQty > 0 && hasManualWaste && totalOutputKg + parsedManualWaste > numGrainQty + 0.001;

  const wastePercent = numGrainQty > 0 ? (effectiveWasteKg / numGrainQty) * 100 : 0;
  const yieldPercent = numGrainQty > 0 ? (totalOutputKg / numGrainQty) * 100 : 0;

  // أسعار البيع والتكلفة
  const priceOf = (id: string) => allItems.find((p) => p.id === id)?.sale_price ?? 0;
  const costOfGrain = selectedGrain?.cost_price ?? selectedGrain?.sale_price ?? 0;
  const totalInputCost = numGrainQty * costOfGrain;

  // إجمالي قيمة النواتج بسعر البيع (أساس التوزيع النسبي)
  const totalOutputValue = useMemo(() => {
    return outputs.reduce((s, l) => s + (Number(l.qty) || 0) * priceOf(l.itemId), 0);
  }, [outputs, allItems]);

  // تكلفة الفاقد التشغيلي
  const wasteCost = Math.round(effectiveWasteKg * costOfGrain * 100) / 100;
  // التكلفة الصافية الموزعة على النواتج
  const allocatableCost = Math.max(0, totalInputCost - (hasManualWaste ? wasteCost : 0));

  // معالجة تغيير نوع التعبئة أو عدد الأكياس
  const handlePackageChange = (
    idx: number,
    packageType: OutputLine["packageType"],
    customKg?: string,
  ) => {
    setOutputs((prev) =>
      prev.map((line, i) => {
        if (i !== idx) return line;
        let bagWeight = 0;
        if (packageType === "50") bagWeight = 50;
        else if (packageType === "25") bagWeight = 25;
        else if (packageType === "10") bagWeight = 10;
        else if (packageType === "5") bagWeight = 5;
        else if (packageType === "custom") bagWeight = Number(customKg) || 0;

        const bags = Number(line.bagsCount) || 0;
        const newQty =
          packageType === "bulk" ? line.qty : bags > 0 ? String(bags * bagWeight) : line.qty;

        return {
          ...line,
          packageType,
          customPackageKg: customKg !== undefined ? customKg : line.customPackageKg,
          qty: newQty,
        };
      }),
    );
  };

  const handleBagsCountChange = (idx: number, bagsCount: string) => {
    setOutputs((prev) =>
      prev.map((line, i) => {
        if (i !== idx) return line;
        let bagWeight = 0;
        if (line.packageType === "50") bagWeight = 50;
        else if (line.packageType === "25") bagWeight = 25;
        else if (line.packageType === "10") bagWeight = 10;
        else if (line.packageType === "5") bagWeight = 5;
        else if (line.packageType === "custom") bagWeight = Number(line.customPackageKg) || 0;

        const bags = Number(bagsCount) || 0;
        const calculatedQty = bagWeight > 0 && bags > 0 ? String(bags * bagWeight) : line.qty;

        return {
          ...line,
          bagsCount,
          qty: bagWeight > 0 ? calculatedQty : line.qty,
        };
      }),
    );
  };

  // المساعد الذكي المقترح ⚡ لحساب الأكياس بنقرة واحدة
  const canSuggestBags = useMemo(() => {
    if (numGrainQty <= 0) return false;
    const remainingKg = Math.max(0, numGrainQty - (hasManualWaste ? parsedManualWaste : 0));
    return remainingKg > 0 && outputs.some((l) => l.itemId && l.packageType !== "bulk");
  }, [numGrainQty, hasManualWaste, parsedManualWaste, outputs]);

  const handleSmartSuggestBags = () => {
    const remainingKg = Math.max(0, numGrainQty - (hasManualWaste ? parsedManualWaste : 0));
    if (remainingKg <= 0) return;

    if (outputs.length === 1) {
      const line = outputs[0];
      let bagWeight = 50;
      if (line.packageType === "50") bagWeight = 50;
      else if (line.packageType === "25") bagWeight = 25;
      else if (line.packageType === "10") bagWeight = 10;
      else if (line.packageType === "5") bagWeight = 5;
      else if (line.packageType === "custom") bagWeight = Number(line.customPackageKg) || 50;

      const suggestedBags = Math.floor(remainingKg / bagWeight);
      if (suggestedBags > 0) {
        setOutputs([
          {
            ...line,
            bagsCount: String(suggestedBags),
            qty: String(suggestedBags * bagWeight),
          },
        ]);
        toast.success(`تم اقتراح ${suggestedBags} كيس سعة ${bagWeight} كجم.`);
      }
    } else {
      toast.info("اقتراح الأكياس التلقائي السريع يملأ السطر الأول بالكمية المتاحة.");
      const line = outputs[0];
      let bagWeight = 50;
      if (line.packageType === "50") bagWeight = 50;
      else if (line.packageType === "25") bagWeight = 25;
      else if (line.packageType === "10") bagWeight = 10;
      else if (line.packageType === "5") bagWeight = 5;
      else if (line.packageType === "custom") bagWeight = Number(line.customPackageKg) || 50;

      const suggestedBags = Math.floor(remainingKg / bagWeight);
      if (suggestedBags > 0) {
        setOutputs((prev) =>
          prev.map((l, i) =>
            i === 0
              ? {
                  ...l,
                  bagsCount: String(suggestedBags),
                  qty: String(suggestedBags * bagWeight),
                }
              : l,
          ),
        );
      }
    }
  };

  // تنفيذ عملية التصنيع
  const submit = useMutation({
    mutationFn: () => {
      const fullNotes = [
        batchRef ? `تشغيلة: ${batchRef.trim()}` : "",
        hasManualWaste ? `فاقد مدخل يدوياً: ${parsedManualWaste} كجم` : "",
        notes ? notes.trim() : "",
      ]
        .filter(Boolean)
        .join(" — ");

      return smartManufacture({
        warehouseId,
        grainItemId,
        grainQty: numGrainQty,
        outputs: outputs.map((l) => ({ itemId: l.itemId, qty: Number(l.qty) || 0 })),
        notes: fullNotes || undefined,
      });
    },
    onSuccess: (res) => {
      if (!res.ok) {
        toast.error(res.message || "تعذر تنفيذ التصنيع.");
        return;
      }
      toast.success(`تم التصنيع وترحيل القيود بنجاح — مستند ${res.data ?? ""}`);
      setGrainQty("");
      setGrainBags("");
      setBatchRef("");
      setOutputs([{ itemId: "", packageType: "50", bagsCount: "", qty: "" }]);
      setManualWasteKg("");
      setNotes("");
      void qc.invalidateQueries({ queryKey: ["milling"] });
      void qc.invalidateQueries({ queryKey: ["inventory"] });
    },
    onError: (err) => toast.error(err instanceof Error ? err.message : "خطأ غير متوقع"),
  });

  // شروط تفعيل زر التنفيذ
  const canSubmit = Boolean(
    warehouseId &&
    grainItemId &&
    numGrainQty > 0 &&
    !isOverStock &&
    !isOutputsOverGrain &&
    !isOutputsPlusWasteOverGrain &&
    outputs.length > 0 &&
    outputs.every((l) => l.itemId && (Number(l.qty) || 0) > 0) &&
    totalOutputValue > 0,
  );

  return (
    <ModuleGuard moduleId="milling_operations">
      <div className="mx-auto max-w-5xl space-y-5 p-3 sm:p-5">
        <PageHeader
          title="التصنيع الذكي وطحن منتجات المنشأة"
          subtitle="تحويل مخزون الحبوب (القمح) إلى منتجات تامة ونواتج جانبية بتكلفة موزعة آلياً حسب القيمة النسبية."
          actions={
            <div className="flex items-center gap-2">
              <Link
                to="/milling/consumables"
                className="inline-flex items-center gap-1.5 rounded-xl border border-border bg-surface px-3 py-2 text-xs font-bold text-foreground transition hover:bg-muted"
              >
                صرف مستهلكات تشغيلية <ArrowLeft className="h-3.5 w-3.5" />
              </Link>
            </div>
          }
        />

        {/* تنبيه الإيضاح المحاسبي المريح */}
        <div className="flex items-start gap-2.5 rounded-2xl border border-sky-500/20 bg-sky-500/10 p-3.5 text-xs font-medium text-sky-800 dark:text-sky-200">
          <Info className="mt-0.5 h-4 w-4 shrink-0 text-sky-600 dark:text-sky-400" />
          <p className="leading-relaxed">
            <strong>نظام التوزيع النسبي المعتمد:</strong> يتم خصم القمح من المخزون بتكلفته الفعلية،
            وتُوزع التكلفة بالكامل على النواتج بحسب نسبة القيمة السوقية لكل منتج (دقيق، سميد،
            نخالة)، مع إثبات الفاقد التشغيلي في دفتر الأستاذ العام (حـ/ 5921).
          </p>
        </div>

        {/* ─── اللوحة الأولى: مدخلات القمح والمستودع ─── */}
        <MillingPanel>
          <MillingSectionTitle
            icon={<WarehouseIcon className="h-4 w-4 text-amber-500" />}
            title="1. مدخلات المادة الخام (القمح / الحبوب)"
            subtitle="حدد المستودع ونوع القمح والكمية بالأكياس أو الوزن المباشر"
          />
          <div className="space-y-4 p-4 sm:p-5">
            <div className="grid gap-4 sm:grid-cols-2">
              <MillingField label="مستودع السحب *">
                <MillingSelect value={warehouseId} onChange={(e) => setWarehouseId(e.target.value)}>
                  <option value="">اختر المخزن…</option>
                  {(warehouses.data ?? []).map((w) => (
                    <option key={w.id} value={w.id}>
                      {w.name_ar || w.name} {w.is_default ? "★ (الرئيسي)" : ""}
                    </option>
                  ))}
                </MillingSelect>
              </MillingField>

              <MillingField label="صنف الحبوب (القمح) *">
                <MillingSelect value={grainItemId} onChange={(e) => setGrainItemId(e.target.value)}>
                  <option value="">اختر الصنف…</option>
                  {(grainItems.data ?? []).map((g: ProductOption) => (
                    <option key={g.id} value={g.id}>
                      {g.name_ar || g.name} ({g.sku})
                    </option>
                  ))}
                </MillingSelect>
              </MillingField>
            </div>

            {/* محول الأكياس والسعة المشترك لمدخلات القمح */}
            <BagWeightInput
              label="كمية القمح المراد طحنها (أكياس أو كجم)"
              bags={grainBags}
              capacityKg={grainCapacityKg}
              totalKg={grainQty}
              defaultCapacity={selectedGrain?.package_weight_kg || 50}
              onChange={(val) => {
                setGrainBags(val.bags > 0 ? String(val.bags) : "");
                setGrainCapacityKg(String(val.capacityKg));
                setGrainQty(val.totalKg > 0 ? String(val.totalKg) : "");
              }}
            />

            {/* شريط حالة الرصيد المخزني الفعلي */}
            {grainItemId && warehouseId && (
              <div className="flex flex-wrap items-center justify-between gap-2 rounded-xl border border-border/70 bg-surface/80 p-3 text-xs">
                <div className="flex flex-wrap items-center gap-2">
                  <Package className="h-4 w-4 text-muted-foreground" />
                  <span>
                    الرصيد المتاح بالمخزن:{" "}
                    <strong className={availableStock > 0 ? "text-foreground" : "text-rose-500"}>
                      <Mono>{fmtNum(availableStock)}</Mono> كجم
                    </strong>
                  </span>
                  {Number(grainCapacityKg) > 0 && availableStock > 0 && (
                    <span className="text-muted-foreground">
                      (يعادل تقريباً{" "}
                      <Mono>{(availableStock / Number(grainCapacityKg)).toFixed(1)}</Mono> كيس سعة{" "}
                      {grainCapacityKg} كجم)
                    </span>
                  )}
                  {selectedGrain?.cost_price && selectedGrain.cost_price > 0 && (
                    <span className="text-muted-foreground">
                      · متوسط التكلفة: <Mono>{fmtNum(selectedGrain.cost_price)}</Mono>
                    </span>
                  )}
                </div>

                <div className="flex items-center gap-2">
                  {availableStock > 0 && (
                    <button
                      type="button"
                      onClick={() => {
                        const cap = Number(grainCapacityKg) || 50;
                        setGrainQty(String(availableStock));
                        setGrainBags(String((availableStock / cap).toFixed(2)));
                      }}
                      className="rounded-lg border border-border bg-surface px-2.5 py-1 text-[11px] font-bold text-primary transition hover:bg-muted active:scale-95"
                    >
                      تعبئة كامل الرصيد المتاح
                    </button>
                  )}
                </div>
              </div>
            )}

            {/* تحذير تجاوز الرصيد المتاح */}
            {isOverStock && (
              <div className="flex items-center gap-2 rounded-xl border border-rose-500/30 bg-rose-500/10 p-3 text-xs font-semibold text-rose-700 dark:text-rose-300">
                <AlertTriangle className="h-4 w-4 shrink-0 text-rose-500" />
                <span>
                  تنبيه: الكمية المدخلة (<Mono>{grainQty}</Mono> كجم) أكبر من الرصيد المتوفر في
                  المخزن (<Mono>{fmtNum(availableStock)}</Mono> كجم)! يرجى تقليل الكمية.
                </span>
              </div>
            )}
          </div>
        </MillingPanel>

        {/* ─── اللوحة الثانية: النواتج وتعبئة الأكياس ─── */}
        <MillingPanel>
          <div className="flex flex-wrap items-center justify-between gap-2 border-b border-border/70 p-4">
            <MillingSectionTitle
              icon={<Factory className="h-4 w-4 text-emerald-500" />}
              title="2. المنتجات والنواتج المستخرجة"
              subtitle="أضف الأصناف الناتجة مع تحديد الأكياس وسعاتها أو الأوزان المباشرة"
            />
            <div className="flex items-center gap-2">
              {canSuggestBags && (
                <button
                  type="button"
                  onClick={handleSmartSuggestBags}
                  className="inline-flex items-center gap-1.5 rounded-xl border border-amber-500/30 bg-amber-500/10 px-3 py-1.5 text-xs font-bold text-amber-700 dark:text-amber-300 transition hover:bg-amber-500/20 active:scale-95"
                  title="اقتراح حساب الأكياس بناءً على القمح المدخل"
                >
                  <Zap className="h-3.5 w-3.5 text-amber-500" />
                  <span>⚡ اقتراح حساب الأكياس</span>
                </button>
              )}
              <button
                type="button"
                onClick={() =>
                  setOutputs((o) => [
                    ...o,
                    { itemId: "", packageType: "50", bagsCount: "", qty: "" },
                  ])
                }
                className="inline-flex items-center gap-1.5 rounded-xl border border-primary/30 bg-primary/10 px-3 py-1.5 text-xs font-bold text-primary transition hover:bg-primary/20 active:scale-95"
              >
                <Plus className="h-3.5 w-3.5" /> إضافة سطر ناتج
              </button>
            </div>
          </div>

          <div className="space-y-3.5 p-4 sm:p-5">
            {outputs.map((line, idx) => {
              const selectedProd = outputItems.data?.find((p) => p.id === line.itemId);
              const lineQtyNum = Number(line.qty) || 0;
              const salePrice = selectedProd?.sale_price ?? 0;
              const lineValue = lineQtyNum * salePrice;
              const valueRatio = totalOutputValue > 0 ? (lineValue / totalOutputValue) * 100 : 0;

              // تكلفة الكيلو الموزعة
              const estimatedUnitCostKg =
                lineQtyNum > 0 && totalOutputValue > 0 && allocatableCost > 0
                  ? (allocatableCost * (lineValue / totalOutputValue)) / lineQtyNum
                  : 0;

              // سعة الكيس الحالية للسطر
              let bagCapacity = 0;
              if (line.packageType === "50") bagCapacity = 50;
              else if (line.packageType === "25") bagCapacity = 25;
              else if (line.packageType === "10") bagCapacity = 10;
              else if (line.packageType === "5") bagCapacity = 5;
              else if (line.packageType === "custom")
                bagCapacity = Number(line.customPackageKg) || 0;

              const estimatedBagCost = estimatedUnitCostKg * bagCapacity;
              const bagSalePrice = salePrice * bagCapacity;
              const marginPerBag = bagSalePrice - estimatedBagCost;
              const marginPercent = bagSalePrice > 0 ? (marginPerBag / bagSalePrice) * 100 : 0;

              return (
                <div
                  key={idx}
                  className="rounded-2xl border border-border/80 bg-surface/50 p-3 sm:p-4 space-y-3 transition hover:border-border"
                >
                  <div className="grid gap-3 sm:grid-cols-[1.5fr_1.2fr_1fr_40px] items-start">
                    {/* اختيار صنف الناتج */}
                    <div>
                      <label className="mb-1 block text-[11px] font-semibold text-muted-foreground">
                        صنف الناتج *
                      </label>
                      <MillingSelect
                        value={line.itemId}
                        onChange={(e) => {
                          const val = e.target.value;
                          const prod = outputItems.data?.find((p) => p.id === val);
                          setOutputs((o) =>
                            o.map((l, i) =>
                              i === idx
                                ? {
                                    ...l,
                                    itemId: val,
                                    packageType:
                                      prod?.package_weight_kg === 50
                                        ? "50"
                                        : prod?.package_weight_kg === 25
                                          ? "25"
                                          : prod?.package_weight_kg === 10
                                            ? "10"
                                            : prod?.package_weight_kg === 5
                                              ? "5"
                                              : "50",
                                  }
                                : l,
                            ),
                          );
                        }}
                      >
                        <option value="">اختر الناتج…</option>
                        {(outputItems.data ?? []).map((p: ProductOption) => (
                          <option key={p.id} value={p.id}>
                            {p.name_ar || p.name} — سعر بيع {fmtNum(p.sale_price)}/كجم
                          </option>
                        ))}
                      </MillingSelect>
                    </div>

                    {/* نمط التعبئة (سائب أو أكياس معيارية) */}
                    <div>
                      <label className="mb-1 block text-[11px] font-semibold text-muted-foreground">
                        نوع التعبئة والسعة
                      </label>
                      <select
                        className="h-10 w-full rounded-xl border border-border bg-surface px-2.5 text-xs font-semibold text-foreground outline-none transition focus:border-primary/60"
                        value={line.packageType}
                        onChange={(e) =>
                          handlePackageChange(idx, e.target.value as OutputLine["packageType"])
                        }
                      >
                        <option value="50">كيس 50 كجم</option>
                        <option value="25">كيس 25 كجم</option>
                        <option value="10">كيس 10 كجم</option>
                        <option value="5">كيس 5 كجم</option>
                        <option value="custom">سعة كيس مخصصة</option>
                        <option value="bulk">سائب (كجم مباشر)</option>
                      </select>
                    </div>

                    {/* الكمية والوزن */}
                    <div>
                      <div className="flex items-center justify-between mb-1">
                        <label className="text-[11px] font-semibold text-muted-foreground">
                          {line.packageType === "bulk" ? "الكمية (كجم) *" : "عدد الأكياس *"}
                        </label>
                        {line.packageType !== "bulk" && (
                          <span className="text-[10px] text-muted-foreground">
                            = <Mono>{line.qty || "0"}</Mono> كجم
                          </span>
                        )}
                      </div>

                      {line.packageType === "bulk" ? (
                        <QuantityInput
                          decimals={3}
                          min={0}
                          emptyAsZero
                          unit="kg"
                          placeholder="كجم"
                          aria-label="الكمية كجم"
                          value={line.qty ? Number(line.qty) : null}
                          onValueChange={(v) =>
                            setOutputs((o) =>
                              o.map((l, i) =>
                                i === idx ? { ...l, qty: v == null ? "" : String(v) } : l,
                              ),
                            )
                          }
                        />
                      ) : (
                        <div className="space-y-1.5">
                          <QuantityInput
                            decimals={0}
                            min={0}
                            emptyAsZero
                            placeholder="عدد الأكياس"
                            aria-label="عدد الأكياس"
                            value={line.bagsCount ? Number(line.bagsCount) : null}
                            onValueChange={(v) =>
                              handleBagsCountChange(idx, v == null ? "" : String(v))
                            }
                          />
                          {line.packageType === "custom" && (
                            <QuantityInput
                              decimals={3}
                              min={0}
                              emptyAsZero
                              unit="kg"
                              placeholder="وزن الكيس كجم"
                              aria-label="وزن الكيس كجم"
                              value={line.customPackageKg ? Number(line.customPackageKg) : null}
                              onValueChange={(v) =>
                                handlePackageChange(idx, "custom", v == null ? "" : String(v))
                              }
                            />
                          )}
                        </div>
                      )}
                    </div>

                    {/* زر حذف السطر */}
                    <div className="pt-6 flex justify-end">
                      <button
                        type="button"
                        disabled={outputs.length === 1}
                        onClick={() => setOutputs((o) => o.filter((_, i) => i !== idx))}
                        className="grid h-10 w-10 place-items-center rounded-xl text-rose-500 transition hover:bg-rose-500/10 disabled:opacity-30"
                        aria-label="حذف السطر"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </div>
                  </div>

                  {/* ملخص السطر المالي والنسبي وهامش الربح */}
                  {lineQtyNum > 0 && selectedProd && (
                    <div className="flex flex-wrap items-center justify-between gap-3 border-t border-border/50 pt-2 text-[11px] text-muted-foreground">
                      <div className="flex flex-wrap items-center gap-3">
                        <span>
                          القيمة الإجمالية:{" "}
                          <strong>
                            <Mono>{fmtNum(lineValue)}</Mono>
                          </strong>
                        </span>
                        <span>
                          نسبة القيمة:{" "}
                          <strong>
                            <Mono>{valueRatio.toFixed(1)}%</Mono>
                          </strong>
                        </span>
                        {estimatedUnitCostKg > 0 && (
                          <span className="text-emerald-600 dark:text-emerald-400 font-semibold">
                            تكلفة الكيلو: <Mono>{fmtNum(estimatedUnitCostKg)}</Mono>
                          </span>
                        )}
                      </div>
                      {bagCapacity > 0 && estimatedBagCost > 0 && (
                        <div className="flex items-center gap-2">
                          <span className="text-foreground font-semibold">
                            تكلفة الكيس ({bagCapacity} كجم):{" "}
                            <Mono className="text-amber-600 dark:text-amber-400 font-bold">
                              {fmtNum(estimatedBagCost)}
                            </Mono>
                          </span>
                          <span
                            className={cn(
                              "font-bold px-1.5 py-0.5 rounded",
                              marginPerBag >= 0
                                ? "bg-emerald-500/15 text-emerald-700 dark:text-emerald-300"
                                : "bg-rose-500/15 text-rose-700 dark:text-rose-300",
                            )}
                            title="هامش الربح المتوقع لكل كيس"
                          >
                            هامش: <Mono>{fmtNum(marginPerBag)}</Mono> ({marginPercent.toFixed(1)}%)
                          </span>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </MillingPanel>

        {/* ─── اللوحة الثالثة: الفاقد التشغيلي المرن وتوازن الطحن ─── */}
        <MillingPanel>
          <MillingSectionTitle
            icon={<TrendingDown className="h-4 w-4 text-rose-500" />}
            title="3. الفاقد التشغيلي المرن وحساب التوازن"
            subtitle="يمكن إدخال الفاقد يدوياً أو تركه فارغاً لاحتسابه تلقائياً من الفرق"
          />
          <div className="p-4 sm:p-5 space-y-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <MillingField
                label="الفاقد التشغيلي اليدوي (كجم)"
                hint="اختياري — اتركه فارغاً ليقوم النظام بحساب الفاقد آلياً"
              >
                <QuantityInput
                  min={0}
                  decimals={2}
                  unit="kg"
                  placeholder={`تلقائي (${fmtNum(autoWasteKg)} كجم)`}
                  aria-label="الفاقد التشغيلي اليدوي (كلجم)"
                  value={manualWasteKg === "" ? null : Number(manualWasteKg)}
                  onValueChange={(v) => setManualWasteKg(v == null ? "" : String(v))}
                />
              </MillingField>

              <div className="rounded-xl border border-border/70 bg-surface/80 p-3 text-xs flex flex-col justify-center">
                <span className="text-muted-foreground">حالة الفاقد المعتمد:</span>
                <p className="mt-1 font-bold text-foreground">
                  {hasManualWaste ? "محدد يدوياً من المستخدم" : "محسوب تلقائياً من فرق الأوزان"}
                  {" — "}
                  <Mono className="text-rose-600 dark:text-rose-400 font-black">
                    {fmtNum(effectiveWasteKg)} كجم
                  </Mono>
                  {numGrainQty > 0 && ` (${wastePercent.toFixed(1)}%)`}
                </p>
              </div>
            </div>

            {/* بطاقات توازن الطحن */}
            <div className="grid gap-3 sm:grid-cols-4 pt-2">
              <div className="rounded-xl border border-border/80 bg-surface/70 p-3 space-y-1">
                <span className="text-xs text-muted-foreground flex items-center gap-1.5">
                  <Layers className="h-3.5 w-3.5 text-amber-500" /> إجمالي القمح المدخل
                </span>
                <p className="text-lg font-black text-foreground">
                  <Mono>{fmtNum(numGrainQty)}</Mono>{" "}
                  <span className="text-xs font-normal">كجم</span>
                </p>
              </div>

              <div className="rounded-xl border border-border/80 bg-surface/70 p-3 space-y-1">
                <span className="text-xs text-muted-foreground flex items-center gap-1.5">
                  <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500" /> إجمالي النواتج
                </span>
                <p className="text-lg font-black text-foreground">
                  <Mono>{fmtNum(totalOutputKg)}</Mono>{" "}
                  <span className="text-xs font-normal">كجم</span>
                </p>
              </div>

              <div className="rounded-xl border border-border/80 bg-surface/70 p-3 space-y-1">
                <span className="text-xs text-muted-foreground flex items-center gap-1.5">
                  <TrendingDown className="h-3.5 w-3.5 text-rose-500" /> الفاقد التشغيلي
                </span>
                <p className="text-lg font-black text-rose-600 dark:text-rose-400">
                  <Mono>{fmtNum(effectiveWasteKg)}</Mono>{" "}
                  <span className="text-xs font-semibold text-muted-foreground">
                    ({wastePercent.toFixed(1)}%)
                  </span>
                </p>
              </div>

              <div className="rounded-xl border border-border/80 bg-surface/70 p-3 space-y-1">
                <span className="text-xs text-muted-foreground flex items-center gap-1.5">
                  <PieChart className="h-3.5 w-3.5 text-sky-500" /> نسبة الاستخلاص (Yield)
                </span>
                <p className="text-lg font-black text-foreground">
                  <Mono>{yieldPercent.toFixed(1)}%</Mono>
                </p>
              </div>
            </div>

            {/* تنبيهات أمان الأوزان */}
            {isOutputsOverGrain && (
              <div className="flex items-center gap-2 rounded-xl border border-rose-500/30 bg-rose-500/10 p-3 text-xs font-bold text-rose-700 dark:text-rose-300">
                <AlertTriangle className="h-4 w-4 shrink-0 text-rose-500" />
                <span>
                  خطأ في الأوزان: إجمالي وزن النواتج المستخرجة (<Mono>{fmtNum(totalOutputKg)}</Mono>{" "}
                  كجم) أكبر من كمية القمح المطحون (<Mono>{fmtNum(numGrainQty)}</Mono> كجم)! لا يمكن
                  أن تزيد النواتج عن المدخلات.
                </span>
              </div>
            )}

            {isOutputsPlusWasteOverGrain && (
              <div className="flex items-center gap-2 rounded-xl border border-rose-500/30 bg-rose-500/10 p-3 text-xs font-bold text-rose-700 dark:text-rose-300">
                <AlertTriangle className="h-4 w-4 shrink-0 text-rose-500" />
                <span>
                  تنبيه: مجموع النواتج (<Mono>{fmtNum(totalOutputKg)}</Mono> كجم) مع الفاقد اليدوي (
                  <Mono>{fmtNum(parsedManualWaste)}</Mono> كجم) يتجاوز وزن القمح المدخل (
                  <Mono>{fmtNum(numGrainQty)}</Mono> كجم)! يرجى ضبط الفاقد أو كميات النواتج.
                </span>
              </div>
            )}
          </div>
        </MillingPanel>

        {/* ─── اللوحة الرابعة: العرض المالي الذكي والتسعير للمالك ─── */}
        {totalOutputValue > 0 && totalInputCost > 0 && (
          <div className="rounded-2xl border border-border/80 bg-surface/70 p-4 sm:p-5 space-y-3">
            <div className="flex items-center justify-between border-b border-border/60 pb-3">
              <div className="flex items-center gap-2">
                <TrendingUp className="h-4 w-4 text-emerald-500" />
                <h3 className="text-sm font-bold text-foreground">
                  ملخص التكلفة والتسعير وهوامش الربح المتوقعة
                </h3>
              </div>
              <span className="text-xs text-muted-foreground">
                إجمالي تكلفة المادة الخام:{" "}
                <strong className="text-foreground">
                  <Mono>{fmtNum(totalInputCost)}</Mono>
                </strong>
              </span>
            </div>

            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3 pt-1">
              {outputs.map((line, i) => {
                const prod = outputItems.data?.find((p) => p.id === line.itemId);
                if (!prod || !Number(line.qty)) return null;

                const lineQty = Number(line.qty);
                const lineVal = lineQty * (prod.sale_price ?? 0);
                const unitCostKg =
                  allocatableCost > 0
                    ? (allocatableCost * (lineVal / totalOutputValue)) / lineQty
                    : 0;

                let bagWeight = 0;
                if (line.packageType === "50") bagWeight = 50;
                else if (line.packageType === "25") bagWeight = 25;
                else if (line.packageType === "10") bagWeight = 10;
                else if (line.packageType === "5") bagWeight = 5;
                else if (line.packageType === "custom")
                  bagWeight = Number(line.customPackageKg) || 0;

                const costPerBag = unitCostKg * bagWeight;
                const salePerBag = (prod.sale_price ?? 0) * bagWeight;
                const profitPerBag = salePerBag - costPerBag;

                return (
                  <div
                    key={i}
                    className="rounded-xl border border-border/60 bg-surface/60 p-3 space-y-2 text-xs"
                  >
                    <div className="flex items-center justify-between">
                      <span className="font-bold text-foreground">{prod.name_ar || prod.name}</span>
                      <span className="text-[10px] text-muted-foreground">
                        {line.packageType !== "bulk" ? `سعة ${bagWeight} كجم` : "سائب"}
                      </span>
                    </div>

                    <div className="space-y-1 text-[11px]">
                      <div className="flex justify-between">
                        <span className="text-muted-foreground">تكلفة الكيلو:</span>
                        <strong>
                          <Mono>{fmtNum(unitCostKg)}</Mono>
                        </strong>
                      </div>
                      {bagWeight > 0 && (
                        <>
                          <div className="flex justify-between">
                            <span className="text-muted-foreground">تكلفة الكيس التقديرية:</span>
                            <strong className="text-amber-600 dark:text-amber-400">
                              <Mono>{fmtNum(costPerBag)}</Mono>
                            </strong>
                          </div>
                          <div className="flex justify-between">
                            <span className="text-muted-foreground">سعر بيع الكيس:</span>
                            <strong>
                              <Mono>{fmtNum(salePerBag)}</Mono>
                            </strong>
                          </div>
                          <div className="flex justify-between border-t border-border/40 pt-1">
                            <span className="text-muted-foreground">هامش ربح الكيس:</span>
                            <strong
                              className={profitPerBag >= 0 ? "text-emerald-600" : "text-rose-600"}
                            >
                              <Mono>{fmtNum(profitPerBag)}</Mono>
                            </strong>
                          </div>
                        </>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* ─── اللوحة الخامسة: رقم التشغيلة والملاحظات ─── */}
        <MillingPanel>
          <div className="p-4 sm:p-5 space-y-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <MillingField label="رقم الدفعة / التشغيلة" hint="اختياري للربط والتتبع">
                <MillingInput
                  placeholder="مثال: BATCH-2026-10-A"
                  value={batchRef}
                  onChange={(e) => setBatchRef(e.target.value)}
                />
              </MillingField>

              <MillingField label="ملاحظات تشغيلية" hint="اختيارية">
                <MillingTextarea
                  placeholder="مثال: تشغيل صباحي — فحص نقاوة 98%..."
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  rows={2}
                />
              </MillingField>
            </div>

            {/* زر الاعتماد والتنفيذ */}
            <div className="pt-2 border-t border-border/70 flex flex-col sm:flex-row items-center justify-between gap-3">
              <div className="text-xs text-muted-foreground">
                {totalOutputValue > 0 && (
                  <span>
                    إجمالي القيمة السوقية للنواتج:{" "}
                    <strong className="text-foreground">
                      <Mono>{fmtNum(totalOutputValue)}</Mono>
                    </strong>
                  </span>
                )}
              </div>

              <button
                type="button"
                disabled={!canSubmit || submit.isPending}
                onClick={() => submit.mutate()}
                className="w-full sm:w-auto min-w-[200px] flex items-center justify-center gap-2 rounded-xl bg-amber-500 px-6 py-3 text-sm font-bold text-white shadow-md shadow-amber-500/20 transition hover:bg-amber-600 active:scale-95 disabled:cursor-not-allowed disabled:opacity-50"
              >
                <Sparkles className="h-4 w-4" />
                {submit.isPending
                  ? "جارٍ تسجيل التصنيع والحركات…"
                  : "تنفيذ أمر التصنيع وترحيل القيود"}
              </button>
            </div>
          </div>
        </MillingPanel>
      </div>
    </ModuleGuard>
  );
}

/**
 * /opening-balances — إدارة وترحيل الأرصدة الافتتاحية.
 *
 * مراجعة وإصلاح شامل طبقاً لخطة الماستر بلان (DOC-MILLING-ERP-MASTER-2026-V2-AUDITED):
 * 1. دعم إدخال أرصدة المخزون بالأكياس وسعة الكيس أو بالكيلو مع الحساب التلقائي للوزن والتكلفة.
 * 2. الحساب التلقائي لمبلغ البند (الكمية × التكلفة) لمنع أخطاء الإدخال اليدوي.
 * 3. زر موازنة القيد التلقائي برأس المال (حـ/ 3111) بنقرة واحدة لتسوية الفرق فوراً وتسهيل الترحيل.
 * 4. إمكانية حذف أي سطر من المسودة بنقرة واحدة.
 * 5. ربط دقيق مع دليل الحسابات لحسابات الصندوق، البنوك، والأصول الثابتة.
 * 6. تصميم فخم يتماشى مع لغة تصميم كروت وبطاقات وأزرار المنتجات الحديثة.
 */
import { createFileRoute } from "@tanstack/react-router";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useMemo, useState, useEffect } from "react";
import {
  BookOpen,
  CheckCircle2,
  Scale,
  TriangleAlert,
  Undo2,
  Trash2,
  Plus,
  Sparkles,
  Package,
  Layers,
  Landmark,
  ArrowRightLeft,
  Building2,
  Wallet,
  Coins,
  ShieldCheck,
  FileCheck,
} from "lucide-react";

import { ModuleGuard } from "@/lib/modules";
import {
  OPENING_SECTIONS,
  createOpeningDocument,
  fetchCustomers,
  fetchOpeningDocuments,
  fetchOpeningLines,
  fetchStockableItems,
  fetchSuppliers,
  fetchWarehouses,
  fetchAccounts,
  postOpeningDocument,
  reverseOpeningDocument,
  yer,
  type OpeningLineDraft,
  type OpeningSection,
  type OpeningSummary,
} from "@/lib/opening-balances";
import { PageHeader } from "@/components/page-header";
import { AmountInput } from "@/components/ui/amount-input";
import { QuantityInput } from "@/components/ui/quantity-input";
import {
  Cell,
  MillingEmpty,
  MillingPanel,
  MillingRow,
  MillingSectionTitle,
  MillingTable,
  Mono,
  Pill,
  QueryErrorGuard,
  StatTile,
} from "@/components/milling/milling-ui";
import { cn } from "@/lib/utils";

export const Route = createFileRoute("/_app/opening-balances")({
  component: OpeningBalancesPage,
});

export function OpeningBalancesPage() {
  const qc = useQueryClient();
  const [draft, setDraft] = useState<OpeningLineDraft[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const [section, setSection] = useState<OpeningSection>("STOCK");
  const [amount, setAmount] = useState("");
  const [qty, setQty] = useState("");
  const [unitCost, setUnitCost] = useState("");
  const [refId, setRefId] = useState("");
  const [warehouseId, setWarehouseId] = useState("");
  const [selectedAccountCode, setSelectedAccountCode] = useState("");
  const [effectiveDate, setEffectiveDate] = useState(new Date().toISOString().slice(0, 10));

  // إدارة الأكياس للمخزون
  const [stockInputMode, setStockInputMode] = useState<"bags" | "kg">("bags");
  const [bagsCount, setBagsCount] = useState("");
  const [bagCapacityKg, setBagCapacityKg] = useState("50");
  const [bagCost, setBagCost] = useState("");

  const documents = useQuery({
    queryKey: ["opening", "documents"],
    queryFn: fetchOpeningDocuments,
  });
  const items = useQuery({ queryKey: ["opening", "items"], queryFn: fetchStockableItems });
  const customers = useQuery({ queryKey: ["opening", "customers"], queryFn: fetchCustomers });
  const suppliers = useQuery({ queryKey: ["opening", "suppliers"], queryFn: fetchSuppliers });
  const warehouses = useQuery({ queryKey: ["opening", "warehouses"], queryFn: fetchWarehouses });
  const accounts = useQuery({ queryKey: ["opening", "accounts"], queryFn: fetchAccounts });

  const lines = useQuery({
    queryKey: ["opening", "lines", selectedId],
    queryFn: () => fetchOpeningLines(selectedId!),
    enabled: Boolean(selectedId),
  });

  const selected = documents.data?.find((d) => d.id === selectedId) ?? null;
  const meta = OPENING_SECTIONS.find((s) => s.value === section)!;
  const selectedItem = items.data?.find((i) => i.id === refId);

  // تعيين المستودع الافتراضي تلقائياً
  useEffect(() => {
    if (!warehouseId && warehouses.data?.length) {
      setWarehouseId(warehouses.data[0].id);
    }
  }, [warehouses.data, warehouseId]);

  // تحديث سعة الكيس التلقائية عند اختيار الصنف
  useEffect(() => {
    if (selectedItem?.package_weight_kg) {
      setBagCapacityKg(String(selectedItem.package_weight_kg));
    }
    if (selectedItem?.cost_price && !unitCost) {
      setUnitCost(String(selectedItem.cost_price));
    }
  }, [selectedItem]);

  // احتساب كمية وتكلفة المخزون تلقائياً عند تغيير الأكياس
  useEffect(() => {
    if (section !== "STOCK" || stockInputMode !== "bags") return;
    const bags = Number(bagsCount) || 0;
    const cap = Number(bagCapacityKg) || 50;
    const bCost = Number(bagCost) || 0;

    if (bags > 0 && cap > 0) {
      const calculatedKg = bags * cap;
      setQty(String(calculatedKg));

      if (bCost > 0) {
        const costPerKg = bCost / cap;
        setUnitCost(String(roundNum(costPerKg)));
        setAmount(String(roundNum(bags * bCost)));
      }
    }
  }, [bagsCount, bagCapacityKg, bagCost, section, stockInputMode]);

  // احتساب المبلغ التلقائي عند تغيير الكمية والتكلفة المباشرة
  const handleQtyOrCostChange = (newQty: string, newCost: string) => {
    setQty(newQty);
    setUnitCost(newCost);
    const q = Number(newQty) || 0;
    const c = Number(newCost) || 0;
    if (q > 0 && c > 0) {
      setAmount(String(roundNum(q * c)));
    }
  };

  const draftTotals = useMemo(() => {
    const debitSections: OpeningSection[] = ["STOCK", "RECEIVABLE", "CASH", "BANK", "ASSET"];
    const debit = draft
      .filter((l) => debitSections.includes(l.section))
      .reduce((s, l) => s + (Number(l.amount) || 0), 0);
    const credit = draft
      .filter((l) => !debitSections.includes(l.section))
      .reduce((s, l) => s + (Number(l.amount) || 0), 0);
    return { debit, credit, diff: debit - credit };
  }, [draft]);

  const run = <TData, TVars>(fn: (v: TVars) => Promise<TData>, okMessage: string) => ({
    mutationFn: fn,
    onSuccess: () => {
      setError(null);
      setNotice(okMessage);
      void qc.invalidateQueries({ queryKey: ["opening"] });
    },
    onError: (e: Error) => {
      setNotice(null);
      setError(e.message);
    },
  });

  const save = useMutation(
    run<string, void>(async () => {
      if (draft.length === 0) throw new Error("أضف بنداً واحداً على الأقل إلى القيد الافتتاحي");
      return createOpeningDocument({ effectiveDate, lines: draft });
    }, "تم حفظ مسودة القيد الافتتاحي بنجاح"),
  );

  const post = useMutation(
    run<void, string>(
      async (id) => postOpeningDocument(id),
      "تم ترحيل القيد الافتتاحي بنجاح إلى دفتر الأستاذ والمخازن",
    ),
  );

  const reverse = useMutation(
    run<void, { id: string; reason: string }>(
      async (v) => reverseOpeningDocument(v.id, v.reason),
      "تم عكس القيد الافتتاحي بنجاح",
    ),
  );

  // إضافة سطر جديد للمسودة
  const addLine = () => {
    const val = Number(amount);
    if (!val || val <= 0) {
      setError("المبلغ يجب أن يكون أكبر من صفر");
      return;
    }
    if (meta.needsRef === "item" && (!refId || !warehouseId)) {
      setError("بند المخزون يتطلب تحديد الصنف والمستودع");
      return;
    }
    if (meta.needsRef === "customer" && !refId) {
      setError("بند ذمم العملاء يتطلب اختيار العميل");
      return;
    }
    if (meta.needsRef === "supplier" && !refId) {
      setError("بند ذمم الموردين يتطلب اختيار المورد");
      return;
    }

    const q = Number(qty) || null;
    const uc = Number(unitCost) || null;

    let desc = meta.label;
    if (section === "STOCK" && selectedItem) {
      const itemTitle = selectedItem.name_ar || selectedItem.name || selectedItem.sku;
      if (stockInputMode === "bags" && Number(bagsCount) > 0) {
        desc = `مخزون افتتاحي: ${bagsCount} كيس سعة ${bagCapacityKg} كجم — ${itemTitle}`;
      } else {
        desc = `مخزون افتتاحي: ${q} كجم — ${itemTitle}`;
      }
    } else if (section === "RECEIVABLE") {
      const c = customers.data?.find((x) => x.id === refId);
      desc = `رصيد افتتاحي عميل: ${c?.name ?? ""}`;
    } else if (section === "PAYABLE") {
      const s = suppliers.data?.find((x) => x.id === refId);
      desc = `رصيد افتتاحي مورد: ${s?.name ?? ""}`;
    } else if (section === "CASH") {
      desc = "رصيد نقدية الصندوق الافتتاحي (حـ/ 1101)";
    } else if (section === "BANK") {
      const acct = accounts.data?.find((a) => a.code === selectedAccountCode);
      desc = `رصيد بنكي / محفظة: ${acct ? `${acct.name_ar} (${acct.code})` : "حـ/ 1111"}`;
    } else if (section === "ASSET") {
      const acct = accounts.data?.find((a) => a.code === selectedAccountCode);
      desc = `أصول ثابتة: ${acct ? `${acct.name_ar} (${acct.code})` : "حـ/ 1411"}`;
    }

    setDraft((d) => [
      ...d,
      {
        section,
        description: desc,
        amount: val,
        quantity: q,
        unit_cost: uc,
        product_id: meta.needsRef === "item" ? refId : null,
        warehouse_id: meta.needsRef === "item" ? warehouseId : null,
        customer_id: meta.needsRef === "customer" ? refId : null,
        supplier_id: meta.needsRef === "supplier" ? refId : null,
        ledger_account_code: selectedAccountCode || meta.defaultAccountCode,
      },
    ]);

    setError(null);
    setAmount("");
    setQty("");
    setUnitCost("");
    setBagsCount("");
    setBagCost("");
    setRefId("");
    setSelectedAccountCode("");
  };

  // زر الموازنة التلقائية السريعة برأس المال
  const handleAutoBalanceCapital = () => {
    if (draftTotals.diff === 0) return;
    const balanceAmount = Math.abs(draftTotals.diff);

    setDraft((d) => [
      ...d,
      {
        section: "CAPITAL",
        description: "رأس المال الافتتاحي الموازن للقيد (حـ/ 3111)",
        amount: balanceAmount,
        ledger_account_code: "3111",
      },
    ]);
    setNotice("تمت موازنة القيد الافتتاحي برأس المال بنجاح");
  };

  const removeDraftLine = (index: number) => {
    setDraft((d) => d.filter((_, i) => i !== index));
  };

  // فلترة الحسابات حسب القسم
  const relevantAccounts = useMemo(() => {
    if (!accounts.data) return [];
    if (section === "BANK") {
      return accounts.data.filter(
        (a) => a.code.startsWith("111") || a.code.startsWith("112") || a.code.startsWith("113"),
      );
    }
    if (section === "ASSET") {
      return accounts.data.filter((a) => a.code.startsWith("14"));
    }
    if (section === "LIABILITY") {
      return accounts.data.filter((a) => a.code.startsWith("21") || a.code.startsWith("22"));
    }
    return [];
  }, [accounts.data, section]);

  return (
    <ModuleGuard moduleId="accounting">
      <div className="mx-auto max-w-6xl space-y-5 p-3 sm:p-5">
        <PageHeader
          title="الأرصدة الافتتاحية للمنشأة"
          subtitle="تسجيل وموازنة قيد افتتاح الدفاتر المحاسبية والمخازن لضبط الجرد المستمر وحسابات الأستاذ العام."
        />

        <QueryErrorGuard
          error={
            documents.error ?? items.error ?? customers.error ?? suppliers.error ?? warehouses.error
          }
        />

        {/* ─── البطاقة العلوية: إضافة بند جديد ─── */}
        <MillingPanel>
          <div className="border-b border-border/70 p-4 sm:p-5">
            <MillingSectionTitle
              icon={<BookOpen className="h-4 w-4 text-primary" />}
              title="إعداد القيد الافتتاحي وإضافة البنود"
              subtitle="اختر القسم ثم أدخل الأرصدة (المخزون يدعم الأكياس والكيلو وحساب التكلفة تلقائياً)"
            />
          </div>

          <div className="space-y-4 p-4 sm:p-5">
            {/* الصف الأول: التاريخ والقسم */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              <div>
                <label className="mb-1.5 block text-xs font-bold text-foreground">
                  تاريخ سريان القيد الافتتاحي *
                </label>
                <input
                  type="date"
                  value={effectiveDate}
                  onChange={(e) => setEffectiveDate(e.target.value)}
                  className="h-10 w-full rounded-xl border border-border bg-surface px-3 text-xs font-semibold text-foreground outline-none transition focus:border-primary/60"
                />
              </div>

              <div>
                <label className="mb-1.5 block text-xs font-bold text-foreground">
                  قسم الرصيد الافتتاحي *
                </label>
                <select
                  value={section}
                  onChange={(e) => {
                    const next = e.target.value as OpeningSection;
                    setSection(next);
                    setRefId("");
                    setAmount("");
                    setQty("");
                    setUnitCost("");
                    setSelectedAccountCode("");
                  }}
                  className="h-10 w-full rounded-xl border border-border bg-surface px-3 text-xs font-semibold text-foreground outline-none transition focus:border-primary/60"
                >
                  {OPENING_SECTIONS.map((s) => (
                    <option key={s.value} value={s.value}>
                      {s.label} ({s.defaultAccountCode})
                    </option>
                  ))}
                </select>
              </div>

              <div className="flex flex-col justify-end text-xs text-muted-foreground bg-muted/40 p-2.5 rounded-xl border border-border/60">
                <span className="font-semibold text-foreground">التوجيه المحاسبي:</span>
                <span className="text-[11px] leading-relaxed mt-0.5">{meta.hint}</span>
              </div>
            </div>

            {/* تفاصيل بند المخزون (أكياس وسعة وكيلو) */}
            {section === "STOCK" && (
              <div className="rounded-2xl border border-primary/20 bg-primary/5 p-4 space-y-4">
                <div className="flex flex-wrap items-center justify-between gap-2 border-b border-primary/15 pb-3">
                  <div className="flex items-center gap-2">
                    <Package className="h-4 w-4 text-primary" />
                    <span className="text-xs font-bold text-foreground">
                      بيانات مخزون الصنف والمستودع
                    </span>
                  </div>

                  {/* تبديل نمط الإدخال: أكياس أو كجم */}
                  <div className="flex items-center rounded-xl border border-border bg-surface p-1">
                    <button
                      type="button"
                      onClick={() => setStockInputMode("bags")}
                      className={cn(
                        "rounded-lg px-2.5 py-1 text-xs font-bold transition",
                        stockInputMode === "bags"
                          ? "bg-primary text-primary-foreground shadow-xs"
                          : "text-muted-foreground hover:text-foreground",
                      )}
                    >
                      بالأكياس والسعة
                    </button>
                    <button
                      type="button"
                      onClick={() => setStockInputMode("kg")}
                      className={cn(
                        "rounded-lg px-2.5 py-1 text-xs font-bold transition",
                        stockInputMode === "kg"
                          ? "bg-primary text-primary-foreground shadow-xs"
                          : "text-muted-foreground hover:text-foreground",
                      )}
                    >
                      بالكيلوجرام مباشر
                    </button>
                  </div>
                </div>

                <div className="grid gap-3 sm:grid-cols-2">
                  <div>
                    <label className="mb-1 block text-xs font-bold text-foreground">
                      صنف المخزون *
                    </label>
                    <select
                      value={refId}
                      onChange={(e) => setRefId(e.target.value)}
                      className="h-10 w-full rounded-xl border border-border bg-surface px-3 text-xs font-semibold text-foreground outline-none transition focus:border-primary/60"
                    >
                      <option value="">— اختر الصنف —</option>
                      {(items.data ?? []).map((i) => (
                        <option key={i.id} value={i.id}>
                          {i.sku} · {i.name_ar || i.name}
                        </option>
                      ))}
                    </select>
                  </div>

                  <div>
                    <label className="mb-1 block text-xs font-bold text-foreground">
                      المستودع المستلم *
                    </label>
                    <select
                      value={warehouseId}
                      onChange={(e) => setWarehouseId(e.target.value)}
                      className="h-10 w-full rounded-xl border border-border bg-surface px-3 text-xs font-semibold text-foreground outline-none transition focus:border-primary/60"
                    >
                      <option value="">— اختر المستودع —</option>
                      {(warehouses.data ?? []).map((w) => (
                        <option key={w.id} value={w.id}>
                          {w.name_ar || w.name}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

                {stockInputMode === "bags" ? (
                  <div className="grid grid-cols-3 gap-3">
                    <div>
                      <label className="mb-1 block text-xs font-bold text-foreground">
                        عدد الأكياس *
                      </label>
                      <QuantityInput
                        min={0}
                        decimals={0}
                        placeholder="مثال: 100"
                        aria-label="عدد الأكياس"
                        value={toNumberOrNull(bagsCount)}
                        onValueChange={(v) => setBagsCount(v == null ? "" : String(v))}
                      />
                    </div>

                    <div>
                      <label className="mb-1 block text-xs font-bold text-foreground">
                        سعة الكيس (كجم) *
                      </label>
                      <QuantityInput
                        min={0}
                        decimals={3}
                        unit="kg"
                        placeholder="50"
                        aria-label="سعة الكيس (كجم)"
                        value={toNumberOrNull(bagCapacityKg)}
                        onValueChange={(v) => setBagCapacityKg(v == null ? "" : String(v))}
                      />
                    </div>

                    <div>
                      <label className="mb-1 block text-xs font-bold text-foreground">
                        تكلفة الكيس الواحد *
                      </label>
                      <AmountInput
                        min={0}
                        placeholder="مثال: 22000"
                        aria-label="تكلفة الكيس الواحد"
                        value={toNumberOrNull(bagCost)}
                        onValueChange={(v) => setBagCost(v == null ? "" : String(v))}
                        wordsClassName="text-[10px] leading-3"
                      />
                    </div>
                  </div>
                ) : (
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="mb-1 block text-xs font-bold text-foreground">
                        الوزن الإجمالي (كجم) *
                      </label>
                      <QuantityInput
                        min={0}
                        decimals={3}
                        placeholder="مثال: 5000"
                        aria-label="الوزن الإجمالي (كجم)"
                        value={toNumberOrNull(qty)}
                        onValueChange={(v) =>
                          handleQtyOrCostChange(v == null ? "" : String(v), unitCost)
                        }
                      />
                    </div>

                    <div>
                      <label className="mb-1 block text-xs font-bold text-foreground">
                        تكلفة الكيلوجرام الواحد *
                      </label>
                      <AmountInput
                        min={0}
                        placeholder="مثال: 440"
                        aria-label="تكلفة الكيلوجرام الواحد"
                        value={toNumberOrNull(unitCost)}
                        onValueChange={(v) =>
                          handleQtyOrCostChange(qty, v == null ? "" : String(v))
                        }
                        wordsClassName="text-[10px] leading-3"
                      />
                    </div>
                  </div>
                )}

                {/* شريط الإيضاح المخزني اللحظي */}
                {Number(qty) > 0 && (
                  <div className="flex flex-wrap items-center justify-between gap-2 rounded-xl bg-surface/80 p-2.5 text-xs text-muted-foreground border border-border/60">
                    <span>
                      إجمالي الوزن المخزني:{" "}
                      <strong className="text-foreground">
                        <Mono>{qty}</Mono> كجم
                      </strong>
                      {unitCost && (
                        <span>
                          {" "}
                          (تكلفة الكيلو:{" "}
                          <strong className="text-foreground">
                            <Mono>{unitCost}</Mono>
                          </strong>
                          )
                        </span>
                      )}
                    </span>
                    <span>
                      القيمة الإجمالية:{" "}
                      <strong className="text-primary font-mono text-sm">
                        {yer(Number(amount))}
                      </strong>
                    </span>
                  </div>
                )}
              </div>
            )}

            {/* تفاصيل العملاء والموردين والبنوك والأصول */}
            {section !== "STOCK" && (
              <div className="grid gap-4 sm:grid-cols-2">
                {meta.needsRef === "customer" && (
                  <div>
                    <label className="mb-1.5 block text-xs font-bold text-foreground">
                      العميل المستحق عليه *
                    </label>
                    <select
                      value={refId}
                      onChange={(e) => setRefId(e.target.value)}
                      className="h-10 w-full rounded-xl border border-border bg-surface px-3 text-xs font-semibold text-foreground outline-none transition focus:border-primary/60"
                    >
                      <option value="">— اختر العميل —</option>
                      {(customers.data ?? []).map((c) => (
                        <option key={c.id} value={c.id}>
                          {c.name}
                        </option>
                      ))}
                    </select>
                  </div>
                )}

                {meta.needsRef === "supplier" && (
                  <div>
                    <label className="mb-1.5 block text-xs font-bold text-foreground">
                      المورد الدائن *
                    </label>
                    <select
                      value={refId}
                      onChange={(e) => setRefId(e.target.value)}
                      className="h-10 w-full rounded-xl border border-border bg-surface px-3 text-xs font-semibold text-foreground outline-none transition focus:border-primary/60"
                    >
                      <option value="">— اختر المورد —</option>
                      {(suppliers.data ?? []).map((s) => (
                        <option key={s.id} value={s.id}>
                          {s.name}
                        </option>
                      ))}
                    </select>
                  </div>
                )}

                {relevantAccounts.length > 0 && (
                  <div>
                    <label className="mb-1.5 block text-xs font-bold text-foreground">
                      تحديد الحساب المالي المحدد من دليل الحسابات
                    </label>
                    <select
                      value={selectedAccountCode}
                      onChange={(e) => setSelectedAccountCode(e.target.value)}
                      className="h-10 w-full rounded-xl border border-border bg-surface px-3 text-xs font-semibold text-foreground outline-none transition focus:border-primary/60"
                    >
                      <option value="">— الحساب الافتراضي ({meta.defaultAccountCode}) —</option>
                      {relevantAccounts.map((a) => (
                        <option key={a.id} value={a.code}>
                          {a.code} — {a.name_ar}
                        </option>
                      ))}
                    </select>
                  </div>
                )}
              </div>
            )}

            {/* صف المبلغ النهائي وزر الإضافة */}
            <div className="flex flex-col sm:flex-row items-end justify-between gap-3 pt-2">
              <div className="w-full sm:w-72">
                <label className="mb-1 block text-xs font-bold text-foreground">
                  المبلغ المالي للبند (ر.ي) *
                </label>
                {/* المبلغ المُوحّد: فاصلة آلاف + تفقيط + رمز العملة من الإعدادات. */}
                <AmountInput
                  min={0}
                  aria-label="المبلغ المالي للبند"
                  value={toNumberOrNull(amount)}
                  onValueChange={(v) => setAmount(v == null ? "" : String(v))}
                  placeholder="0.00"
                  wordsClassName="text-xs"
                  containerClassName="[&_input]:h-12 [&_input]:rounded-xl [&_input]:px-4 [&_input]:text-lg [&_input]:font-black"
                />
              </div>

              <button
                type="button"
                onClick={addLine}
                className="w-full sm:w-auto h-12 inline-flex items-center justify-center gap-2 rounded-xl bg-primary px-6 text-xs font-bold text-primary-foreground shadow-md shadow-primary/20 transition hover:bg-primary/90 active:scale-95"
              >
                <Plus className="h-4 w-4" /> إضافة البند إلى مسودة القيد
              </button>
            </div>
          </div>

          {/* ── جدول المسودة والتوازن ── */}
          {draft.length > 0 && (
            <div className="border-t border-border/70 p-4 sm:p-5 space-y-4">
              <div className="flex items-center justify-between">
                <h4 className="text-sm font-bold text-foreground flex items-center gap-2">
                  <Layers className="h-4 w-4 text-primary" />
                  بنود مسودة القيد الحالية ({draft.length})
                </h4>
                {draftTotals.diff !== 0 && (
                  <button
                    type="button"
                    onClick={handleAutoBalanceCapital}
