function PurchasePOSPage() {
  const { isModuleEnabled } = useModules();
  const { t, lang, dir } = useI18n();
  const { config: catalogConfig } = useCatalogModules();
  const navigate = useNavigate();
  const { roles } = useAuth();
  // Suppliers are RLS-restricted to owner/manager/accountant; cashiers must not
  // be shown an "add supplier" action they cannot complete.
  const canManageSuppliers =
    roles.includes("owner") || roles.includes("manager") || roles.includes("accountant");

  const [products, setProducts] = useState<Product[]>([]);
  const [stockMap, setStockMap] = useState<Record<string, number>>({});
  const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);

  // Catalog Filters
  const [categories, setCategories] = useState<MetaOption[]>([]);
  const [brands, setBrands] = useState<MetaOption[]>([]);
  const [units, setUnits] = useState<MetaOption[]>([]);
  const [origins, setOrigins] = useState<MetaOption[]>([]);
  const [qualities, setQualities] = useState<MetaOption[]>([]);
  const [makes, setMakes] = useState<MetaOption[]>([]);
  const [models, setModels] = useState<MetaOption[]>([]);
  const [compatibilities, setCompatibilities] = useState<Compatibility[]>([]);

  const [warehouseId, setWarehouseId] = useState<string>("");
  const [supplierId, setSupplierId] = useState<string>("");
  const [search, setSearch] = useState("");
  const [filterOpen, setFilterOpen] = useState(false);

  // Filter States
  const [selectedCategory, setSelectedCategory] = useState("");
  const [selectedBrand, setSelectedBrand] = useState("");
  const [selectedUnit, setSelectedUnit] = useState("");
  const [selectedOrigin, setSelectedOrigin] = useState("");
  const [selectedQuality, setSelectedQuality] = useState("");
  const [selectedMake, setSelectedMake] = useState("");
  const [selectedModel, setSelectedModel] = useState("");

  const [cart, setCart] = useState<CartLine[]>([]);
  const [paid, setPaid] = useState<string>("");
  const [discount, setDiscount] = useState<string>("");
  const [paymentMethod, setPaymentMethod] = useState<
    "cash" | "mobile_money" | "bank_transfer" | "credit"
  >("cash");
  const [note, setNote] = useState("");
  const [purchaseDate, setPurchaseDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [transferRef, setTransferRef] = useState("");

  // Mobile workspace: cart-first, catalogue opened on demand.
  const isDesktop = useIsDesktop();
  const [mobilePickerOpen, setMobilePickerOpen] = useState(false);

  // Modals
  const [newSupplierOpen, setNewSupplierOpen] = useState(false);

  const [loading, setLoading] = useState(false);
  const [scannerOpen, setScannerOpen] = useState(false);
  const [successInvoice, setSuccessInvoice] = useState<{
    id: string;
    number?: string;
    total: number;
    paid: number;
    supplierName: string;
  } | null>(null);
  const [quoteRequest, setQuoteRequest] = useState<PrintRequest | null>(null);

  const searchRef = useRef<HTMLInputElement>(null);
  const scanHandlerRef = useRef<(code: string) => void>(() => undefined);

  useEffect(() => {
    void loadAll();
  }, []);

  useEffect(() => {
    if (warehouseId) void loadStock(warehouseId);
  }, [warehouseId]);

  async function loadAll() {
    try {
      const [
        { data: ws },
        { data: sups },
        { data: ps },
        { data: cats },
        { data: brs },
        { data: uns },
        { data: origs },
        { data: quals },
        { data: vMakes },
        { data: vModels },
        { data: compats },
      ] = await Promise.all([
        supabase.from("warehouses").select("id,name,name_ar").eq("is_active", true).order("name"),
        supabase.from("suppliers").select("id,name,phone").order("name"),
        supabase
          .from("products")
          .select(
            "id,sku,barcode,name,name_ar,cost_price,sale_price,tax_rate,image_url,category_id,brand_id,unit_id,origin_id,quality_grade_id,unit:units!products_unit_id_fkey(short_name,name,name_ar),category:categories(name,name_ar),brand:brands!products_brand_id_fkey(name,name_ar),origin:countries_of_origin(name,name_ar,code),quality:quality_grades(name,name_ar,code)",
          )
          .eq("is_active", true)
          .order("name")
          .limit(500),
        supabase.from("categories").select("id,name,name_ar").order("name"),
        supabase.from("brands").select("id,name,name_ar").order("name"),
        supabase.from("units").select("id,name,name_ar,short_name").order("name"),
        (supabase as any).from("countries_of_origin").select("id,name,name_ar,code").order("name"),
        (supabase as any)
          .from("quality_grades")
          .select("id,name,name_ar,code,sort_order")
          .order("sort_order"),
        (supabase as any).from("vehicle_makes").select("id,name,name_ar").order("name"),
        (supabase as any).from("vehicle_models").select("id,name,name_ar,make_id").order("name"),
        (supabase as any).from("product_compatibilities").select("product_id,vehicle_model_id"),
      ]);

      const loadedWarehouses = ws ?? [];
      const loadedSuppliers = sups ?? [];
      setWarehouses(loadedWarehouses);
      setSuppliers(loadedSuppliers);
      setProducts((ps as any) ?? []);
      setCategories(cats ?? []);
      setBrands(brs ?? []);
      setUnits(uns ?? []);
      setOrigins(origs ?? []);
      setQualities(quals ?? []);
      setMakes(vMakes ?? []);
      setModels(vModels ?? []);
      setCompatibilities(compats ?? []);

      // Auto-select warehouse
      if (loadedWarehouses.length > 0) {
        setWarehouseId(loadedWarehouses[0].id);
      }

      // Auto-select "مورد نقدي" or default first supplier.
      // A cash purchase still needs a real supplier_id (create_purchase rejects
      // NULL and posts the payable balance), so we reuse ONE stable cash-supplier
      // record rather than creating a new supplier per transaction.
      if (loadedSuppliers.length > 0) {
        const normalized = (s: string) => s.trim().toLowerCase();
        const cashSup = loadedSuppliers.find((s) => {
          const n = normalized(s.name);
          return (
            n.includes("نقدي") ||
            n.includes("كاش") ||
            n.includes("cash") ||
            n.includes("walk-in") ||
            n.includes("نقد")
          );
        });
        setSupplierId(cashSup ? cashSup.id : loadedSuppliers[0].id);
      }
    } catch (err: any) {
      console.error("Error loading POP meta:", err);
    }
  }

  async function loadStock(whId: string) {
    const { data } = await supabase
      .from("inventory")
      .select("product_id,quantity")
      .eq("warehouse_id", whId);
    const map: Record<string, number> = {};
    (data ?? []).forEach((r) => {
      map[r.product_id] = Number(r.quantity);
    });
    setStockMap(map);
  }

  // Active filters count
  const activeFiltersCount = useMemo(() => {
    return [
      selectedCategory,
      catalogConfig.enableBrands ? selectedBrand : "",
      catalogConfig.enableUnits ? selectedUnit : "",
      catalogConfig.enableOrigins ? selectedOrigin : "",
      catalogConfig.enableQualityGrades ? selectedQuality : "",
      catalogConfig.enableMakesAndModels ? selectedMake : "",
      catalogConfig.enableMakesAndModels ? selectedModel : "",
    ].filter(Boolean).length;
  }, [
    selectedCategory,
    selectedBrand,
    selectedUnit,
    selectedOrigin,
    selectedQuality,
    selectedMake,
    selectedModel,
    catalogConfig,
  ]);

  const clearAllFilters = () => {
    setSelectedCategory("");
    setSelectedBrand("");
    setSelectedUnit("");
    setSelectedOrigin("");
    setSelectedQuality("");
    setSelectedMake("");
    setSelectedModel("");
    setSearch("");
  };

  // Add to purchase cart
  function addToCart(p: Product) {
    const pName = lang === "ar" ? p.name_ar || p.name : p.name || p.name_ar || p.name;
    const unitCost = Number(p.cost_price || 0);
    setCart((prev) => {
      const existing = prev.find((l) => l.product_id === p.id);
      if (existing) {
        return prev.map((l) => (l.product_id === p.id ? { ...l, quantity: l.quantity + 1 } : l));
      }
      return [
        ...prev,
        {
          product_id: p.id,
          name: pName,
          sku: p.sku,
          unit_cost: unitCost,
          tax_rate: Number(p.tax_rate || 0),
          quantity: 1,
        },
      ];
    });
  }

  function updateCartLine(productId: string, patch: Partial<CartLine>) {
    setCart((prev) =>
      prev.map((line) => {
        if (line.product_id !== productId) return line;
        return { ...line, ...patch };
      }),
    );
  }

  /** Commit a quantity. `null` (empty field mid-edit) leaves the line intact. */
  function setQty(productId: string, qty: number | null) {
    if (qty === null || Number.isNaN(qty)) return;
    if (qty <= 0) {
      setCart((prev) => prev.filter((l) => l.product_id !== productId));
    } else {
      setCart((prev) =>
        prev.map((l) => (l.product_id === productId ? { ...l, quantity: qty } : l)),
      );
    }
  }

  function setCost(productId: string, cost: number) {
    setCart((prev) =>
      prev.map((l) => (l.product_id === productId ? { ...l, unit_cost: Math.max(0, cost) } : l)),
    );
  }

  // Barcode Handler
  const handleBarcode = (code: string) => {
    const trimmed = code.trim();
    if (!trimmed) return;
    const found = products.find(
      (p) =>
        (p.barcode && p.barcode.toLowerCase() === trimmed.toLowerCase()) ||
        (p.sku && p.sku.toLowerCase() === trimmed.toLowerCase()),
    );
    if (found) {
      addToCart(found);
      toast.success(
        lang === "ar"
          ? `تمت إضافة: ${found.name_ar || found.name}`
          : `Added: ${found.name || found.name_ar}`,
      );
    } else {
      toast.error(
        lang === "ar" ? "لم يتم العثور على الصنف بالباركود" : "Product barcode not found",
      );
    }
  };

  useEffect(() => {
    scanHandlerRef.current = handleBarcode;
  });

  useKeyboardWedge({
    onScan: (scanned) => {
      scanHandlerRef.current(scanned);
    },
  });

  // Hotkeys: F2 search, F4 submit, Esc clear
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "F2") {
        e.preventDefault();
        searchRef.current?.focus();
      } else if (e.key === "F4") {
        e.preventDefault();
        void submitPurchase();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [cart, warehouseId, supplierId, paymentMethod, paid, discount, note]);

  // Financial calculations
  const subtotal = cart.reduce((s, l) => s + l.unit_cost * l.quantity, 0);
  const taxTotal = cart.reduce((s, l) => s + l.unit_cost * l.quantity * (l.tax_rate / 100), 0);
  const discountN = Number(discount || 0);
  const total = Math.max(0, subtotal + taxTotal - discountN);
  const paidN = paymentMethod === "credit" ? 0 : paid !== "" ? Number(paid) : total;
  const isOverpaid = Number.isFinite(paidN) && paidN > total;

  // Filter products
  const filtered = useMemo(() => {
    return products.filter((p) => {
      if (search) {
        const s = search.toLowerCase();
        const matchesName = (p.name || "").toLowerCase().includes(s);
        const matchesNameAr = (p.name_ar || "").toLowerCase().includes(s);
        const matchesSku = (p.sku || "").toLowerCase().includes(s);
        const matchesBarcode = (p.barcode || "").toLowerCase().includes(s);
        if (!matchesName && !matchesNameAr && !matchesSku && !matchesBarcode) return false;
      }
      if (selectedCategory && p.category_id !== selectedCategory) return false;
      if (catalogConfig.enableBrands && selectedBrand && p.brand_id !== selectedBrand) return false;
      if (catalogConfig.enableUnits && selectedUnit && p.unit_id !== selectedUnit) return false;
      if (catalogConfig.enableOrigins && selectedOrigin && p.origin_id !== selectedOrigin)
        return false;
      if (
        catalogConfig.enableQualityGrades &&
        selectedQuality &&
        p.quality_grade_id !== selectedQuality
      )
        return false;
      return true;
    });
  }, [
    products,
    search,
    selectedCategory,
    selectedBrand,
    selectedUnit,
    selectedOrigin,
    selectedQuality,
    catalogConfig,
  ]);

  // Create Supplier — the SAME form used by the Suppliers page.
  function handleSupplierSaved(record: { id: string; name: string; phone?: string | null }) {
    setSuppliers((prev) => [record as Supplier, ...prev]);
    setSupplierId(record.id);
    toast.success(lang === "ar" ? "تمت إضافة المورد بنجاح" : "Supplier added successfully");
  }

  // Submit Purchase Invoice
  async function submitPurchase() {
    if (loading) return;
    if (!warehouseId) {
      return toast.error(
        lang === "ar" ? "يرجى تحديد مستودع الاستلام" : "Please select receiving warehouse",
      );
    }
    if (!supplierId) {
      return toast.error(lang === "ar" ? "يرجى اختيار المورد" : "Please select a supplier");
    }
    if (cart.length === 0) {
      return toast.error(lang === "ar" ? "سلة المشتريات فارغة" : "Purchase cart is empty");
    }
    if (!Number.isFinite(paidN) || paidN < 0 || isOverpaid) {
      return toast.error(
        lang === "ar"
          ? "يجب أن يكون المبلغ المدفوع بين صفر وإجمالي الفاتورة"
          : "Paid amount must be between zero and the invoice total",
      );
    }

    const invalid = cart.find((l) => l.quantity <= 0 || l.unit_cost < 0);
    if (invalid) {
      return toast.error(
        lang === "ar"
          ? "يجب أن تكون الكمية موجبة وتكلفة الوحدة صحيحة"
          : "Invalid quantity or cost price",
      );
    }

    setLoading(true);
    try {
      const currentSup = suppliers.find((s) => s.id === supplierId);

      // Carry an electronic payment reference in the existing note so the RPC
      // contract and offline sync format stay unchanged.
      const composedNote = (() => {
        const parts: string[] = [];
        if (note.trim()) parts.push(note.trim());
        if (
          (paymentMethod === "bank_transfer" || paymentMethod === "mobile_money") &&
          transferRef.trim()
        ) {
          parts.push(
            `${paymentMethod === "mobile_money" ? (lang === "ar" ? "مرجع المحفظة" : "Wallet reference") : lang === "ar" ? "رقم الحوالة" : "Transfer no."}: ${transferRef.trim()}`,
          );
        }
        return parts.length ? parts.join(" — ") : null;
      })();

      const { data: invoiceId, error } = await supabase.rpc("create_purchase", {
        _warehouse_id: warehouseId,
        _supplier_id: supplierId,
        _payment_method: paymentMethod,
        _paid: paidN,
        _discount: discountN,
        _note: composedNote as any,
        _items: cart.map((l) => ({
          product_id: l.product_id,
          quantity: Number(l.quantity),
          unit_cost: Number(l.unit_cost),
          tax_rate: Number(l.tax_rate),
        })),
      });

      if (error) throw error;

      // Update local stock map with added quantities
      setStockMap((prev) => {
        const next = { ...prev };
        cart.forEach((c) => {
          next[c.product_id] = (next[c.product_id] ?? 0) + Number(c.quantity);
        });
        return next;
      });

      toast.success(
        lang === "ar"
          ? "تم تسجيل فاتورة الشراء وتحديث المخزون بنجاح"
          : "Purchase recorded successfully",
      );

      setSuccessInvoice({
        id: invoiceId || "recorded",
        total,
        paid: paidN,
        supplierName: currentSup?.name || (lang === "ar" ? "مورد نقدي" : "Cash Supplier"),
      });

      // Reset cart and payment
      setCart([]);
      setPaid("");
      setDiscount("");
      setNote("");
      setTransferRef("");
    } catch (e: any) {
      toast.error(
        e.message || (lang === "ar" ? "حدث خطأ أثناء حفظ الفاتورة" : "Failed to record purchase"),
      );
    } finally {
      setLoading(false);
    }
  }

  const selectedSupplier = suppliers.find((s) => s.id === supplierId);

  function openPurchaseQuotation() {
    if (cart.length === 0) {
      return toast.error(lang === "ar" ? "السلة فارغة" : "Purchase cart is empty");
    }
    setQuoteRequest({
      doc: {
        docType: "quotation",
        title: lang === "ar" ? "عرض أسعار شراء" : "Purchase Price Preview",
        number: lang === "ar" ? "عرض أسعار" : "QUOTE",
        date: purchaseDate,
        partyLabel: lang === "ar" ? "المورد" : "Supplier",
        partyName:
          selectedSupplier?.name ?? (lang === "ar" ? "لم يتم اختيار مورد" : "No supplier selected"),
        status: lang === "ar" ? "معاينة فقط" : "Preview only",
        currency: "",
        subtotal,
        tax: taxTotal,
        discount: discountN,
        total,
        paid: 0,
        balance: total,
        notes:
          lang === "ar"
            ? "هذه معاينة لأسعار الشراء فقط ولا تسجل أي عملية."
            : "Preview only. No purchase is recorded.",
        lines: cart.map((line) => ({
          product: line.name,
          qty: line.quantity,
          price: line.unit_cost,
          total: line.unit_cost * line.quantity * (1 + line.tax_rate / 100),
        })),
      },
      documentType: "quotation",
      rtl: lang === "ar",
    });
  }

  return (
    <div className="grid h-full min-h-0 flex-1 grid-rows-[auto_minmax(0,1fr)] gap-2 overflow-hidden bg-[radial-gradient(ellipse_at_top,_color-mix(in_oklab,var(--primary)_10%,transparent),transparent_48%)] lg:grid-cols-[minmax(0,1fr)_minmax(400px,460px)] lg:grid-rows-[auto_minmax(0,1fr)]">
      {/* Top Bar / Header */}
      <div className="m-1.5 flex shrink-0 flex-col items-stretch gap-2 rounded-2xl border border-border/80 bg-surface/95 px-3 py-2 shadow-sm backdrop-blur-md sm:m-2 sm:px-4 lg:col-start-1 lg:row-start-1">
        <div className="flex items-center gap-3">
          <Link
            to="/purchases"
            className="grid h-9 w-9 place-items-center rounded-xl border border-border/80 bg-surface-2/60 text-muted-foreground transition hover:bg-surface-2 hover:text-foreground"
            title={lang === "ar" ? "العودة إلى سجل المشتريات" : "Back to purchases list"}
          >
            <ArrowRight className={`h-4 w-4 ${dir === "rtl" ? "" : "rotate-180"}`} />
          </Link>
          <div className="flex items-center gap-2">
            <div className="grid h-10 w-10 place-items-center rounded-2xl border border-primary/25 bg-primary text-primary-foreground shadow-sm">
              <PackagePlus className="h-5 w-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-sm font-extrabold tracking-tight text-foreground">
                  {lang === "ar" ? "نقطة المشتريات السريعة" : "Point of Purchase (POP)"}
                </h1>
                <span className="rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-bold text-primary">
                  {lang === "ar" ? "مساحة المشتريات" : "Purchase workspace"}
                </span>
              </div>
              <p className="text-[11px] text-muted-foreground">
                {lang === "ar"
                  ? "تسجيل مشتريات وتحديث فوري للمخزون مع إسناد المورد النقدي"
                  : "Rapid purchase receiving & stock increment"}
              </p>
            </div>
          </div>
        </div>

        {/* Global Toolbar Selectors */}
        <div className="flex w-full flex-wrap items-center gap-1.5 border-t border-border/60 pt-2">
          {/* Warehouse Selector */}
          <div className="order-2 flex h-9 min-w-0 items-center gap-1.5 rounded-xl border border-border/80 bg-surface px-2.5 text-xs shadow-2xs">
            <Building2 className="h-3.5 w-3.5 text-primary shrink-0" />
            <span className="text-muted-foreground font-medium hidden sm:inline">
              {lang === "ar" ? "المستودع:" : "Warehouse:"}
            </span>
            <select
              value={warehouseId}
              onChange={(e) => setWarehouseId(e.target.value)}
              className="bg-transparent font-medium text-foreground outline-none text-xs cursor-pointer"
            >
              {warehouses.map((w) => (
                <option key={w.id} value={w.id}>
                  {lang === "ar" ? w.name_ar || w.name : w.name || w.name_ar}
                </option>
              ))}
            </select>
          </div>

          {/* Supplier Selector with Cash Supplier Default */}
          <div className="order-1 flex h-9 min-w-0 items-center gap-1.5 rounded-xl border border-border/80 bg-surface px-2.5 text-xs shadow-2xs">
            <Truck className="h-3.5 w-3.5 text-primary shrink-0" />
            <span className="text-muted-foreground font-medium hidden sm:inline">
              {lang === "ar" ? "المورد:" : "Supplier:"}
            </span>
            <select
              value={supplierId}
              onChange={(e) => setSupplierId(e.target.value)}
              className="h-8 w-72 max-w-[48vw] bg-transparent px-1 text-sm font-medium text-foreground outline-none cursor-pointer"
            >
              {suppliers.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.name}
                </option>
              ))}
            </select>
            <button
              type="button"
              onClick={() => setNewSupplierOpen(true)}
              title={lang === "ar" ? "إضافة مورد جديد" : "Add new supplier"}
              className="grid h-8 w-8 place-items-center rounded-full bg-primary/10 text-primary hover:bg-primary/20 transition disabled:opacity-40"
              disabled={!canManageSuppliers}
            >
              <UserPlus className="h-3 w-3" />
            </button>
          </div>

          {/* Purchase Date */}
          <div className="order-3 flex h-9 items-center gap-1.5 rounded-xl border border-border/80 bg-surface px-2.5 text-xs shadow-2xs">
            <CalendarDays className="h-3.5 w-3.5 text-primary shrink-0" />
            <input
              type="date"
              value={purchaseDate}
              onChange={(e) => setPurchaseDate(e.target.value)}
              className="bg-transparent text-xs text-foreground outline-none cursor-pointer font-mono"
            />
          </div>

          {/* Page Guide Button */}
          <PageGuideButton config={purchasePosGuideConfig} className="order-4 !h-9 !w-9" />

          {/* Barcode Camera Modal Trigger */}
          <button
            type="button"
            onClick={() => setScannerOpen(true)}
            className="order-5 grid h-9 w-9 place-items-center rounded-xl border border-border/80 bg-surface text-muted-foreground hover:text-foreground hover:bg-surface-2 transition shadow-2xs"
            title={lang === "ar" ? "مسح الباركود بالكاميرا" : "Scan barcode with camera"}
          >
            <ScanBarcode className="h-4 w-4" />
          </button>
        </div>
      </div>

      {/* Main Content Area: Products Grid (Left) + Cart & Totals (Right) */}
      <div className="flex min-h-0 flex-col gap-2 overflow-hidden px-1.5 pb-1.5 sm:px-2 sm:pb-2 lg:contents">
        {/* Left Column: Search, Filters & Product Grid — desktop only. */}
        {isDesktop && (
          <div className="flex min-h-0 flex-1 flex-col overflow-hidden rounded-3xl border border-border/80 bg-surface/95 shadow-sm ring-1 ring-background/40 lg:col-start-1 lg:row-start-2 lg:mx-2 lg:mb-2">
            {/* Search & Filter Bar */}
            <div className="p-3 border-b border-border/60 bg-surface/50 space-y-2">
              <div className="flex items-center gap-2">
                <div className="relative flex-1">
                  <Search className="absolute start-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <input
                    ref={searchRef}
                    type="text"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") {
                        e.preventDefault();
                        handleBarcode(search);
                      }
                    }}
                    placeholder={
                      lang === "ar"
                        ? "ابحث باسم المنتج، الكود SKU، أو امسح الباركود (F2)..."
                        : "Search by product name, SKU, or scan barcode (F2)..."
                    }
                    className="h-10 w-full rounded-2xl border border-border/80 bg-surface pe-9 ps-9 text-xs text-foreground placeholder:text-muted-foreground/70 outline-none focus:border-primary focus:ring-2 focus:ring-primary/20 transition"
                  />
                  {search && (
                    <button
                      onClick={() => setSearch("")}
                      className="absolute end-3 top-1/2 -translate-y-1/2 rounded-full p-0.5 hover:bg-surface-2 text-muted-foreground"
                    >
                      <X className="h-3.5 w-3.5" />
                    </button>
                  )}
                </div>

                {/* Toggle Filter Panel */}
                <button
                  type="button"
                  onClick={() => setFilterOpen((o) => !o)}
                  className={`relative flex h-10 items-center gap-1.5 rounded-2xl border px-3 text-xs font-semibold transition ${
                    filterOpen || activeFiltersCount > 0
                      ? "border-primary bg-primary/10 text-primary"
                      : "border-border/80 bg-surface text-muted-foreground hover:bg-surface-2 hover:text-foreground"
                  }`}
                >
                  <Filter className="h-3.5 w-3.5" />
                  <span className="hidden sm:inline">{lang === "ar" ? "تصفية" : "Filter"}</span>
                  {activeFiltersCount > 0 && (
                    <span className="grid h-4 w-4 place-items-center rounded-full bg-primary text-[10px] font-bold text-primary-foreground">
                      {activeFiltersCount}
                    </span>
                  )}
                </button>
              </div>

              {/* Collapsible Filter Panel */}
              {filterOpen && (
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2 pt-2 border-t border-border/60">
                  {/* Category */}
                  <div>
                    <label className="text-[10px] font-semibold text-muted-foreground mb-1 block">
                      {lang === "ar" ? "التصنيف" : "Category"}
                    </label>
                    <select
                      value={selectedCategory}
                      onChange={(e) => setSelectedCategory(e.target.value)}
                      className="h-8 w-full rounded-xl border border-border/80 bg-surface px-2 text-xs text-foreground outline-none"
                    >
                      <option value="">{lang === "ar" ? "الكل" : "All"}</option>
                      {categories.map((c) => (
                        <option key={c.id} value={c.id}>
                          {lang === "ar" ? c.name_ar || c.name : c.name || c.name_ar}
                        </option>
                      ))}
                    </select>
                  </div>

                  {/* Brand */}
                  {catalogConfig.enableBrands && (
                    <div>
                      <label className="text-[10px] font-semibold text-muted-foreground mb-1 block">
                        {lang === "ar" ? "الماركة" : "Brand"}
                      </label>
                      <select
                        value={selectedBrand}
                        onChange={(e) => setSelectedBrand(e.target.value)}
                        className="h-8 w-full rounded-xl border border-border/80 bg-surface px-2 text-xs text-foreground outline-none"
                      >
                        <option value="">{lang === "ar" ? "الكل" : "All"}</option>
                        {brands.map((b) => (
                          <option key={b.id} value={b.id}>
                            {lang === "ar" ? b.name_ar || b.name : b.name || b.name_ar}
                          </option>
                        ))}
                      </select>
                    </div>
                  )}

                  {/* Quality */}
                  {catalogConfig.enableQualityGrades && (
                    <div>
                      <label className="text-[10px] font-semibold text-muted-foreground mb-1 block">
                        {lang === "ar" ? "درجة الجودة" : "Quality Grade"}
                      </label>
                      <select
                        value={selectedQuality}
                        onChange={(e) => setSelectedQuality(e.target.value)}
                        className="h-8 w-full rounded-xl border border-border/80 bg-surface px-2 text-xs text-foreground outline-none"
                      >
                        <option value="">{lang === "ar" ? "الكل" : "All"}</option>
                        {qualities.map((q) => (
                          <option key={q.id} value={q.id}>
                            {lang === "ar" ? q.name_ar || q.name : q.name || q.name_ar}
                          </option>
                        ))}
                      </select>
                    </div>
                  )}

                  {/* Origin */}
                  {catalogConfig.enableOrigins && (
                    <div>
                      <label className="text-[10px] font-semibold text-muted-foreground mb-1 block">
                        {lang === "ar" ? "بلد المنشأ" : "Origin"}
                      </label>
                      <select
                        value={selectedOrigin}
                        onChange={(e) => setSelectedOrigin(e.target.value)}
                        className="h-8 w-full rounded-xl border border-border/80 bg-surface px-2 text-xs text-foreground outline-none"
                      >
                        <option value="">{lang === "ar" ? "الكل" : "All"}</option>
                        {origins.map((o) => (
                          <option key={o.id} value={o.id}>
                            {lang === "ar" ? o.name_ar || o.name : o.name || o.name_ar}
                          </option>
                        ))}
                      </select>
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Products Grid */}
            <div className="flex-1 min-h-0 overflow-y-auto p-3 custom-scrollbar">
              {filtered.length === 0 ? (
                <div className="grid place-items-center py-16 text-center text-muted-foreground">
                  <ShoppingBag className="h-10 w-10 opacity-30 mb-2" />
                  <p className="text-sm font-semibold">
                    {lang === "ar"
                      ? "لم يتم العثور على أي منتجات مطابقة"
                      : "No matching products found"}
                  </p>
                  <button
                    type="button"
                    onClick={clearAllFilters}
                    className="mt-2 text-xs text-primary underline"
                  >
                    {lang === "ar" ? "إعادة ضبط الفلاتر" : "Reset filters"}
                  </button>
                </div>
              ) : (
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-3 lg:grid-cols-3 xl:grid-cols-4 gap-2.5">
                  {filtered.map((p) => {
                    const stock = stockMap[p.id] ?? 0;
                    const catLabel =
                      lang === "ar"
                        ? p.category?.name_ar || p.category?.name
                        : p.category?.name || p.category?.name_ar;
                    const qualityLabel =
                      lang === "ar"
                        ? p.quality?.name_ar || p.quality?.name
                        : p.quality?.name || p.quality?.name_ar;

                    return (
                      <button
                        key={p.id}
                        type="button"
                        onClick={() => addToCart(p)}
                        className="group flex flex-col justify-between rounded-2xl border border-border/80 bg-surface/90 p-3 text-start transition-all hover:border-primary/60 hover:bg-surface-2 hover:shadow-md active:scale-[0.98]"
                      >
                        <div className="w-full">
                          {/* Quality & Category Badges */}
                          <div className="mb-1.5 flex flex-wrap items-center gap-1 text-[10px]">
                            {qualityLabel && (
                              <span className="rounded bg-primary/10 px-1.5 py-0.5 font-bold text-primary border border-primary/20">
                                {qualityLabel}
                              </span>
                            )}
                            {catLabel && (
                              <span className="rounded bg-surface-2 px-1.5 py-0.5 text-muted-foreground font-medium border border-border/60 truncate max-w-[100px]">
                                {catLabel}
                              </span>
                            )}
                          </div>

                          {/* Product Title */}
                          <h4 className="text-xs font-bold text-foreground leading-snug line-clamp-2 group-hover:text-primary transition-colors">
                            {lang === "ar" ? p.name_ar || p.name : p.name || p.name_ar}
                          </h4>

                          {/* SKU & Barcode */}
                          <div className="mt-1 flex items-center gap-2 text-[10px] text-muted-foreground font-mono">
                            {p.sku && <span>SKU: {p.sku}</span>}
                            {p.barcode && <span>#{p.barcode}</span>}
                          </div>
                        </div>

                        {/* Financials & Stock */}
                        <div className="mt-2.5 pt-2 border-t border-border/60 w-full flex items-center justify-between">
                          <div>
                            <span className="text-[10px] text-muted-foreground block">
                              {lang === "ar" ? "سعر التكلفة:" : "Cost:"}
                            </span>
                            <span className="font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400">
                              {money(p.cost_price || 0)}
                            </span>
                          </div>

                          {/* Warehouse Stock */}
                          <div className="text-end">
                            <span className="text-[10px] text-muted-foreground block">
                              {lang === "ar" ? "المخزون:" : "Stock:"}
                            </span>
                            <span
                              className={`font-mono text-xs font-semibold ${stock <= 0 ? "text-amber-500" : "text-muted-foreground"}`}
                            >
                              {stock}
                            </span>
                          </div>
                        </div>
                      </button>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        )}

        {/* Right Column: Purchase Cart & Invoicing — the primary workspace. */}
        <div className="flex min-h-0 w-full shrink-0 flex-col overflow-hidden rounded-3xl border border-primary/15 bg-surface/95 p-2.5 shadow-xl ring-1 ring-border/50 backdrop-blur-md sm:p-3 lg:col-start-2 lg:row-span-2 lg:row-start-1 lg:mx-2 lg:mb-2">
          {/* Cart Header */}
          <div className="mb-2 flex shrink-0 items-center justify-between border-b border-border/60 px-1 pb-2">
            <div className="flex items-center gap-2">
              <ShoppingBag className="h-4 w-4 text-primary" />
              <span className="text-xs font-bold text-foreground">
                {lang === "ar" ? "أصناف أمر الشراء" : "Purchase Items"}
              </span>
              <span className="rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-bold text-primary">
                {cart.length}
              </span>
            </div>
            {isDesktop ? (
              cart.length > 0 && (
                <button
                  type="button"
                  onClick={() => setCart([])}
                  className="flex items-center gap-1 text-[11px] text-destructive hover:underline"
                >
                  <Trash2 className="h-3 w-3" />
                  {lang === "ar" ? "إفراغ السلة" : "Clear cart"}
                </button>
              )
            ) : (
              <button
                type="button"
                onClick={() => setMobilePickerOpen(true)}
                className="inline-flex items-center gap-1.5 rounded-full bg-primary px-3 py-1.5 text-xs font-semibold text-primary-foreground shadow-sm active:scale-95"
              >
                <Plus className="h-3.5 w-3.5" />
                <span>{t("pos.add_product")}</span>
              </button>
            )}
          </div>

          {/* Cart Lines Scrollable Area */}
          <div className="my-1 min-h-0 flex-1 space-y-2 overflow-y-auto pr-1 custom-scrollbar">
            {cart.length === 0 ? (
              <div className="grid place-items-center py-14 text-center text-sm text-muted-foreground">
                <div className="grid h-12 w-12 place-items-center rounded-2xl border border-dashed border-border bg-surface-2/50 mb-2">
                  <ShoppingBag className="h-6 w-6 opacity-40 text-muted-foreground" />
                </div>
                <p className="text-xs font-semibold">
                  {lang === "ar" ? "سلة المشتريات فارغة" : "Purchase cart is empty"}
                </p>
                <p className="text-[11px] text-muted-foreground/80 mt-1 max-w-[200px]">
                  {lang === "ar"
                    ? "انقر على أي منتج أو امسح الباركود لإضافته لأمر الشراء"
                    : "Click any item or scan barcode to add to purchase order"}
                </p>
              </div>
            ) : (
              cart.map((line) => (
                <CartLineRow
                  key={line.product_id}
                  line={{
                    id: line.product_id,
                    name: line.name,
                    quantity: line.quantity,
                    unitPrice: line.unit_cost,
                    taxRate: line.tax_rate,
                    stock: stockMap[line.product_id],
                  }}
                  labels={{
                    price: lang === "ar" ? "سعر الشراء" : "Cost",
                    quantity: lang === "ar" ? "الكمية" : "Qty",
                    remove: lang === "ar" ? "حذف" : "Remove",
                  }}
                  formatMoney={money}
                  onQuantityCommit={(next) => setQty(line.product_id, next)}
                  onPriceChange={(next) => setCost(line.product_id, next)}
                  onRemove={() => setCart((c) => c.filter((x) => x.product_id !== line.product_id))}
                />
              ))
            )}

            {/* Payment and totals share this same cart scroll area. */}
            <div className="mt-3 space-y-2 border-t border-border/70 bg-surface/95 pt-2.5 pr-1">
              {/* Payment Method Selector — 4 clear options incl. wallet & transfer. */}
              <div className="grid grid-cols-[minmax(0,1fr)_7rem] gap-2">
                <label className="relative min-w-0">
                  <span className="sr-only">
                    {lang === "ar" ? "طريقة الدفع" : "Payment method"}
                  </span>
                  <select
                    value={paymentMethod}
                    onChange={(e) => {
                      const method = e.target.value as typeof paymentMethod;
                      setPaymentMethod(method);
                      setPaid(method === "credit" ? "0" : "");
                    }}
                    className="h-10 w-full appearance-none rounded-xl border border-border/80 bg-surface px-3 text-xs font-semibold text-foreground outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/20"
                  >
                    <option value="cash">{lang === "ar" ? "نقدًا" : "Cash"}</option>
                    <option value="mobile_money">{lang === "ar" ? "محفظة" : "Wallet"}</option>
                    <option value="bank_transfer">{lang === "ar" ? "حوالة" : "Transfer"}</option>
                    <option value="credit">{lang === "ar" ? "آجل" : "Credit"}</option>
                  </select>
                  <ChevronDown className="pointer-events-none absolute end-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                </label>
                <AmountInput
                  min={0}
                  hideClear
                  value={discount === "" ? null : Number(discount)}
                  onValueChange={(v) => setDiscount(v == null ? "" : String(v))}
                  placeholder={lang === "ar" ? "الخصم" : "Discount"}
                  aria-label={lang === "ar" ? "الخصم" : "Discount"}
                  wordsClassName="text-[10px] leading-3"
                  containerClassName="[&_input]:h-10 [&_input]:rounded-xl [&_input]:bg-surface [&_input]:text-xs"
                />
              </div>

              {/* Transfer reference — shown only for bank transfers. */}
              {(paymentMethod === "bank_transfer" || paymentMethod === "mobile_money") && (
                <input
                  type="text"
                  value={transferRef}
                  onChange={(e) => setTransferRef(e.target.value)}
                  placeholder={
                    paymentMethod === "mobile_money"
                      ? lang === "ar"
                        ? "رقم عملية المحفظة / المرجع"
                        : "Wallet transaction / reference number"
                      : t("pos.pm.transfer_ref")
                  }
                  aria-label={
                    paymentMethod === "mobile_money"
                      ? lang === "ar"
                        ? "مرجع المحفظة"
                        : "Wallet reference"
                      : t("pos.pm.transfer_ref")
                  }
                  className="h-8 w-full rounded-xl border border-border/80 bg-surface px-2.5 text-xs text-foreground outline-none transition focus:border-primary"
                />
              )}

              {/* Paid Amount */}
              {paymentMethod !== "cash" && (
                <div className="rounded-2xl border border-border/70 bg-surface-2/30 p-2.5">
                  <div className="mb-1.5 flex items-center justify-between text-xs">
                    <span className="font-semibold text-muted-foreground">
                      {lang === "ar" ? "المبلغ المدفوع" : "Amount paid"}
                    </span>
                    <span className="font-mono font-bold text-primary">{money(total)}</span>
                  </div>
                  <AmountInput
                    min={0}
                    showInWords={false}
                    value={paid === "" ? null : Number(paid)}
                    onValueChange={(v) => setPaid(v == null ? "" : String(v))}
                    placeholder={total.toFixed(2)}
                    aria-label={lang === "ar" ? "المبلغ المدفوع" : "Amount paid"}
                    containerClassName={`[&_input]:h-10 [&_input]:rounded-xl [&_input]:bg-surface [&_input]:text-sm [&_input]:font-bold ${
                      isOverpaid
                        ? "[&_input]:border-destructive [&_input]:text-destructive"
                        : "[&_input]:border-border"
                    }`}
                  />
                </div>
              )}

              {isOverpaid && (
                <p className="rounded-xl border border-destructive/30 bg-destructive/10 px-2.5 py-1.5 text-[11px] font-medium text-destructive">
                  {lang === "ar"
                    ? "المبلغ المدفوع أكبر من إجمالي الفاتورة"
                    : "Paid amount exceeds the invoice total"}
                </p>
              )}

              {/* Note Input */}
              <input
                type="text"
                value={note}
                onChange={(e) => setNote(e.target.value)}
                placeholder={
                  lang === "ar" ? "ملاحظة على فاتورة الشراء (اختياري)..." : "Note (optional)..."
                }
                className="h-8 w-full rounded-xl border border-border/80 bg-surface px-2.5 text-xs text-foreground placeholder:text-muted-foreground/70 outline-none focus:border-primary"
              />

              <div className="space-y-1.5 rounded-2xl border border-primary/20 bg-primary/5 p-3">
                <div className="flex items-center justify-between text-xs text-muted-foreground">
                  <span>{lang === "ar" ? "المجموع الفرعي" : "Subtotal"}</span>
                  <span className="font-mono font-semibold text-foreground">{money(subtotal)}</span>
                </div>

                {discountN > 0 && (
                  <div className="flex items-center justify-between text-xs text-emerald-600 dark:text-emerald-400">
                    <span className="font-medium">{lang === "ar" ? "الخصم" : "Discount"}</span>
                    <span className="font-mono font-bold [unicode-bidi:isolate]">
                      −{money(discountN)}
                    </span>
                  </div>
                )}

                {taxTotal > 0 && (
                  <div className="flex items-center justify-between text-xs text-muted-foreground">
                    <span>{lang === "ar" ? "الضريبة" : "Tax"}</span>
                    <span className="font-mono font-semibold text-foreground">
                      {money(taxTotal)}
                    </span>
                  </div>
                )}

                <div className="flex items-center justify-between border-t border-primary/20 pt-2">
                  <span className="text-xs font-bold text-foreground">
                    {lang === "ar" ? "الإجمالي" : "Total"}
                  </span>
                  <span className="font-mono text-base font-extrabold tracking-tight text-primary">
                    <span dir="ltr" className="[unicode-bidi:isolate]">
                      {money(total)}
                    </span>
                  </span>
                </div>
              </div>
            </div>
          </div>

          {/* Actions stay outside the only scroll region. */}
          <div className="mt-2 flex shrink-0 gap-2 border-t border-border/70 bg-surface/95 pb-1 pt-2">
            <button
              type="button"
              onClick={openPurchaseQuotation}
              disabled={cart.length === 0}
              className="flex h-11 shrink-0 items-center justify-center gap-2 rounded-2xl border border-transparent bg-foreground px-4 text-sm font-semibold text-background transition hover:opacity-90 active:scale-[0.99] disabled:opacity-50"
            >
              <FileText className="h-4 w-4" />
              <span className="hidden sm:inline">
                {lang === "ar" ? "عرض الأسعار" : "Price preview"}
              </span>
            </button>
            <button
              type="button"
              onClick={submitPurchase}
              disabled={loading || cart.length === 0 || isOverpaid}
              className="flex h-11 min-w-0 flex-1 items-center justify-center gap-2 rounded-2xl bg-gradient-to-r from-primary to-primary/90 px-4 text-sm font-semibold text-primary-foreground shadow-lg shadow-primary/25 transition hover:shadow-primary/35 active:scale-[0.99] disabled:pointer-events-none disabled:opacity-50"
            >
              {loading ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" />
                  <span>{lang === "ar" ? "جاري تسجيل الشراء..." : "Recording purchase..."}</span>
                </>
              ) : (
                <span>{lang === "ar" ? "تسجيل فاتورة الشراء" : "Save Purchase Order"}</span>
              )}
            </button>
          </div>
        </div>
      </div>

      {/* New Supplier — the SAME form used by the Suppliers page. */}
      <SupplierFormDialog
        open={newSupplierOpen}
        onClose={() => setNewSupplierOpen(false)}
        onSaved={(record) => handleSupplierSaved(record)}
      />

      {/* Success Modal */}
      {successInvoice && (
        <div className="fixed inset-0 z-50 grid place-items-center bg-background/80 backdrop-blur-sm p-4">
          <div className="panel-elevated w-full max-w-sm rounded-2xl p-6 border border-border/80 bg-surface text-center space-y-4 shadow-2xl">
            <div className="mx-auto grid h-14 w-14 place-items-center rounded-full bg-emerald-500/10 text-emerald-500 border border-emerald-500/20">
              <CheckCircle2 className="h-8 w-8" />
            </div>

            <div>
              <h3 className="text-base font-bold text-foreground">
                {lang === "ar"
                  ? "تم تسجيل فاتورة الشراء بنجاح!"
                  : "Purchase Recorded Successfully!"}
              </h3>
              <p className="text-xs text-muted-foreground mt-1">
                {lang === "ar"
                  ? `المورد: ${successInvoice.supplierName}`
                  : `Supplier: ${successInvoice.supplierName}`}
              </p>
            </div>

            <div className="rounded-xl border border-border/70 bg-surface-2/40 p-3 space-y-1 text-xs">
              <div className="flex justify-between text-muted-foreground">
                <span>{lang === "ar" ? "إجمالي الفاتورة:" : "Total:"}</span>
                <span className="font-mono font-bold text-foreground">
                  {money(successInvoice.total)}
                </span>
              </div>
              <div className="flex justify-between text-muted-foreground">
                <span>{lang === "ar" ? "المسدد نقداً:" : "Paid:"}</span>
                <span className="font-mono font-bold text-emerald-500">
                  {money(successInvoice.paid)}
                </span>
              </div>
              {successInvoice.total > successInvoice.paid && (
                <div className="flex justify-between text-amber-500 font-semibold pt-1 border-t border-border/60">
                  <span>{lang === "ar" ? "المتبقي (آجل):" : "Balance Due:"}</span>
                  <span className="font-mono">
                    {money(successInvoice.total - successInvoice.paid)}
                  </span>
                </div>
              )}
            </div>

            <div className="flex flex-col gap-2 pt-2">
              <button
                type="button"
                onClick={() => setSuccessInvoice(null)}
                className="h-10 w-full rounded-xl bg-primary text-primary-foreground text-xs font-bold hover:bg-primary/90 transition shadow-sm"
              >
                {lang === "ar" ? "فاتورة شراء جديدة" : "New Purchase"}
              </button>
              <Link
                to="/purchases"
                className="h-9 w-full grid place-items-center rounded-xl border border-border text-xs font-semibold text-muted-foreground hover:bg-surface-2 transition"
              >
                {lang === "ar" ? "عرض في سجل المشتريات" : "View in Purchases Register"}
              </Link>
            </div>
          </div>
        </div>
      )}

      {/* Barcode Camera Scanner */}
      {scannerOpen && (
        <BarcodeScanner
          open={scannerOpen}
          onDetected={(code) => {
            setScannerOpen(false);
            handleBarcode(code);
          }}
          onClose={() => setScannerOpen(false)}
        />
      )}

      {/* Mobile product picker — reuses the SAME search state and filtering. */}
      <MobileProductPicker
        open={mobilePickerOpen && !isDesktop}
        onClose={() => setMobilePickerOpen(false)}
        search={search}
        onSearchChange={setSearch}
        title={t("pos.add_product_title")}
        searchPlaceholder={t("pos.search_product")}
        emptyLabel={lang === "ar" ? "لا توجد منتجات مطابقة" : "No matching products"}
        inputRef={searchRef}
        products={filtered.slice(0, 200).map((p) => ({
          id: p.id,
          name: (lang === "ar" ? p.name_ar || p.name : p.name || p.name_ar) || "—",
          meta: p.sku || p.barcode || null,
          value: money(Number(p.cost_price || 0)),
          sub: `${t("pos.stock")}: ${stockMap[p.id] ?? 0}`,
        }))}
        onSelect={(id) => {
          const product = products.find((p) => p.id === id);
          if (product) addToCart(product);
          setMobilePickerOpen(false);
        }}
      />
      {quoteRequest ? (
        <UniversalPrintPreview
          open
          onOpenChange={(open) => {
            if (!open) setQuoteRequest(null);
          }}
          request={quoteRequest}
          title={lang === "ar" ? "معاينة عرض أسعار الشراء" : "Purchase price preview"}
          rtl={lang === "ar"}
        />
      ) : null}
    </div>
  );
}

import { PrimaryAction } from "@/components/ui/primary-action";
import { usePersistedViewMode } from "@/hooks/use-persisted-view-mode";
import { cn } from "@/lib/utils";
import { ModuleGuard, useModules } from "@/lib/modules";
import { createFileRoute, Link } from "@tanstack/react-router";
import { useEffect, useMemo, useState, useCallback } from "react";
import {
  ShoppingCart,
  Plus,
  Eye,
  X,
  Loader2,
  Trash2,
  LayoutGrid,
  List,
  TableProperties,
  Wallet,
  PackageCheck,
  TrendingDown,
  Clock,
  CheckCircle2,
  Printer,
  Receipt,
  FileDown,
  Copy,
  Check,
  MessageSquare,
  RefreshCw,
  FileText,
  AlertCircle,
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useI18n } from "@/lib/i18n";
import { money } from "@/lib/format";
import { toSystemDigits } from "@/lib/format-preferences";
import { Ltr } from "@/components/ltr-value";
import { LuxuryPrintPreviewModal } from "@/components/luxury-print-preview-modal";
import { WhatsAppIcon } from "@/components/whatsapp-icon";
import {
  VortexMetricCard,
  VortexDateBadge,
  VortexInvoiceDetailsSheet,
} from "@/components/vortex-ui";
import {
  TableToolbar,
  ToolbarAction,
  type FilterDefinition,
  type FilterValues,
  type SortOption,
} from "@/components/ui/table-toolbar";
import { RecordsViewToggle } from "@/components/ui/records-view-toggle";
import { DataTable, type DataTableColumn, type DataTableSort } from "@/components/ui/data-table";
import { IconButton } from "@/components/ui/icon-button";
import { useBreakpoint } from "@/design/breakpoints";
import { toast } from "sonner";
import { PaymentMethodPicker } from "@/components/ui/payment-method";
import { AmountInput } from "@/components/ui/amount-input";
import { QuantityInput } from "@/components/ui/quantity-input";
import {
  getPaymentMethodDefinition,
  paymentMethodLabel,
  toLegacyPaymentValue,
} from "@/lib/payments/payment-methods";

export const Route = createFileRoute("/_app/purchases")({
  head: () => ({ meta: [{ title: "Purchases — Vortex ERP" }] }),
  component: () => (
    <ModuleGuard moduleId="purchases">
      <PurchasesPage />
    </ModuleGuard>
  ),
});

interface Invoice {
  id: string;
  invoice_number: string;
  status: string;
  subtotal: number;
  discount: number;
  tax: number;
  total: number;
  paid: number;
  payment_method: string;
  created_at: string;
  note?: string | null;
  suppliers: { name: string; phone?: string | null } | null;
  warehouses: { name: string; name_ar: string | null } | null;
}

type ViewMode = "cards" | "list" | "table";
type StatusTab = "all" | "paid" | "partial" | "unpaid" | "cancelled";

interface Line {
  id: string;
  quantity: number;
  unit_cost: number;
  tax: number;
  total: number;
  products: { id?: string; name: string; name_ar?: string | null; sku: string | null } | null;
}

interface Product {
  id: string;
  name: string;
  name_ar: string | null;
  sku: string | null;
  barcode: string | null;
  cost_price: number;
  tax_rate: number;
  unit?: { short_name?: string | null; name?: string | null; name_ar?: string | null } | null;
  category?: { name?: string | null; name_ar?: string | null } | null;
  inventory?: { warehouse_id: string; quantity: number }[] | null;
}

interface Supplier {
  id: string;
  name: string;
}

interface Warehouse {
  id: string;
  name: string;
  name_ar: string | null;
}

interface CartLine {
  product_id: string;
  name: string;
  unit_cost: number;
  tax_rate: number;
  quantity: number;
}

function PurchasesPage() {
  const { isModuleEnabled } = useModules();
  const hasMultiWarehouse = isModuleEnabled("multi_warehouse");
  const { t, lang } = useI18n();
  const isRtl = lang === "ar";
  const whName = (w?: { name: string; name_ar: string | null } | null) =>
    !w ? "—" : lang === "ar" ? w.name_ar || w.name : w.name || w.name_ar || "—";
  const [rows, setRows] = useState<Invoice[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [statusTab, setStatusTab] = useState<StatusTab>("all");
  const [filters, setFilters] = useState<FilterValues>({});
  const [sortKey, setSortKey] = useState<string>("date_desc");
  const [viewMode, setViewMode] = usePersistedViewMode("purchases", "cards");
  const [selected, setSelected] = useState<Invoice | null>(null);
  const [lines, setLines] = useState<Line[]>([]);
  const [loadingLines, setLoadingLines] = useState(false);
  const [creating, setCreating] = useState(false);
  const [copiedInvoiceId, setCopiedInvoiceId] = useState<string | null>(null);
  const [directPrintInvoice, setDirectPrintInvoice] = useState<Invoice | null>(null);
  const [directPrintLines, setDirectPrintLines] = useState<Line[]>([]);

  /*
   * Column-header sorting for the classic table, kept separate from the
   * toolbar preset (`sortKey`).
   */
  const [sort, setSort] = useState<DataTableSort | null>(null);
  const breakpoint = useBreakpoint();
  const tableUsesHorizontalScroll =
    breakpoint === "xs" || breakpoint === "sm" || breakpoint === "md";

  const copyInvoiceNumber = (invoiceNumber: string, id: string) => {
    navigator.clipboard.writeText(invoiceNumber);
    setCopiedInvoiceId(id);
    toast.success(isRtl ? "تم نسخ رقم الفاتورة" : "Invoice number copied");
    setTimeout(() => setCopiedInvoiceId(null), 2000);
  };

  const shareInvoiceWhatsApp = (inv: Invoice) => {
    const phone = inv.suppliers?.phone;
    if (!phone || !phone.trim()) {
      toast.warning(
        isRtl
          ? "هذا المورد لا يوجد لديه رقم هاتف مسجل في النظام"
          : "This supplier has no phone number registered",
      );
      return;
    }
    const remaining = Math.max(0, Number(inv.total) - Number(inv.paid));
    const text = isRtl
      ? `فاتورة مشتريات رقم ${inv.invoice_number}\nالمورد: ${inv.suppliers?.name || ""}\nالتاريخ: ${new Date(inv.created_at).toLocaleDateString("ar-YE")}\nالإجمالي: ${money(Number(inv.total))}\nالمدفوع: ${money(Number(inv.paid))}${remaining > 0 ? `\nالمتبقي: ${money(remaining)}` : ""}`
      : `Purchase Invoice #${inv.invoice_number}\nSupplier: ${inv.suppliers?.name || ""}\nTotal: ${money(Number(inv.total))}\nPaid: ${money(Number(inv.paid))}${remaining > 0 ? `\nRemaining: ${money(remaining)}` : ""}`;
    const clean = phone.replace(/[^\d+]/g, "");
    const target = clean.startsWith("+") ? clean.slice(1) : clean;
    window.open(`https://wa.me/${target}?text=${encodeURIComponent(text)}`, "_blank");
  };

  const shareInvoiceSms = (inv: Invoice) => {
    const phone = inv.suppliers?.phone;
    if (!phone || !phone.trim()) {
      toast.warning(
        isRtl
          ? "هذا المورد لا يوجد لديه رقم هاتف مسجل في النظام"
          : "This supplier has no phone number registered",
      );
      return;
    }
    const remaining = Math.max(0, Number(inv.total) - Number(inv.paid));
    const text = isRtl
      ? `فاتورة مشتريات #${inv.invoice_number} - المورد: ${inv.suppliers?.name || ""} - الإجمالي: ${money(Number(inv.total))} - المتبقي: ${money(remaining)}`
      : `Purchase #${inv.invoice_number} - Total: ${money(Number(inv.total))} - Due: ${money(remaining)}`;
    const clean = phone.replace(/[^\d+]/g, "");
    window.open(`sms:${clean}?body=${encodeURIComponent(text)}`, "_blank");
  };

  async function load() {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("purchase_invoices")
        .select(
          "id,invoice_number,status,subtotal,discount,tax,total,paid,payment_method,created_at,note,suppliers(name,phone),warehouses(name,name_ar)",
        )
        .order("created_at", { ascending: false })
        .limit(200);
      if (error) {
        console.error("Error loading purchases:", error);
        toast.error(isRtl ? "تعذر تحميل فواتير المشتريات" : "Failed to load purchases");
      }
      setRows((data ?? []) as any);
    } catch (err) {
      console.error("Failed to load purchases:", err);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    void load();
  }, []);

  async function openInvoice(inv: Invoice) {
    setSelected(inv);
    setLoadingLines(true);
    try {
      const { data, error } = await supabase
        .from("purchase_invoice_items")
        .select("id,quantity,unit_cost,tax,total,products(id,name,name_ar,sku)")
        .eq("invoice_id", inv.id);
      if (error) {
        console.error("Error loading purchase items:", error);
      }
      setLines((data ?? []) as any);
    } catch (err) {
      console.error("Failed to load invoice items:", err);
      setLines([]);
    } finally {
      setLoadingLines(false);
    }
  }

  async function openDirectPrint(inv: Invoice) {
    setDirectPrintInvoice(inv);
    try {
      const { data } = await supabase
        .from("purchase_invoice_items")
        .select("id,quantity,unit_cost,tax,total,products(id,name,name_ar,sku)")
        .eq("invoice_id", inv.id);
      setDirectPrintLines((data ?? []) as any);
    } catch (err) {
      console.error("Failed to load print items:", err);
      setDirectPrintLines([]);
    }
  }

  const pmLabel = useCallback(
    (m: string) => paymentMethodLabel(m, lang === "ar" ? "ar" : "en"),
    [lang],
  );

  const statusLabel = useCallback(
    (s: string) => {
      const map: Record<string, string> = {
        paid: t("sales.status.paid"),
        partial: t("sales.status.partial"),
        unpaid: t("sales.status.unpaid"),
        cancelled: t("sales.status.cancelled"),
      };
      return map[s] ?? s;
    },
    [t],
  );

  const statusBadge = (s: string) => {
    const map: Record<string, { bg: string; text: string; dot: string; label: string }> = {
      paid: {
        bg: "bg-emerald-500/10 border-emerald-500/30",
        text: "text-emerald-500",
        dot: "bg-emerald-500",
        label: t("sales.status.paid"),
      },
      partial: {
        bg: "bg-amber-500/10 border-amber-500/30",
        text: "text-amber-500",
        dot: "bg-amber-500",
        label: t("sales.status.partial"),
      },
      unpaid: {
        bg: "bg-rose-500/10 border-rose-500/30",
        text: "text-rose-500",
        dot: "bg-rose-500",
        label: t("sales.status.unpaid"),
      },
      cancelled: {
        bg: "bg-muted/40 border-border/80",
        text: "text-muted-foreground",
        dot: "bg-muted-foreground",
        label: t("sales.status.cancelled"),
      },
    };
    const c = map[s] ?? {
      bg: "bg-surface-2",
      text: "text-foreground",
      dot: "bg-foreground",
      label: s,
    };
    return (
      <span
        className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-0.5 text-[11px] font-semibold ${c.bg} ${c.text}`}
      >
        <span className={`size-1.5 rounded-full ${c.dot}`} />
        <span>{c.label}</span>
      </span>
    );
  };

  const purchaseFilterDefinitions: FilterDefinition[] = useMemo(
    () => [
      {
        key: "created_at",
        label: isRtl ? "تاريخ الفاتورة" : "Invoice Date",
        type: "date-range",
      },
      {
        key: "payment_method",
        label: isRtl ? "طريقة السداد" : "Payment Method",
        type: "select",
        options: [
          { value: "cash", label: t("pos.pm.cash") },
          { value: "card", label: t("pos.pm.card") },
          { value: "bank_transfer", label: t("pos.pm.bank") },
          { value: "credit", label: t("pos.pm.credit") },
        ],
      },
      {
        key: "status",
        label: t("common.status"),
        type: "select",
        options: [
          { value: "paid", label: t("sales.status.paid") },
          { value: "partial", label: t("sales.status.partial") },
          { value: "unpaid", label: t("sales.status.unpaid") },
          { value: "cancelled", label: t("sales.status.cancelled") },
        ],
      },
    ],
    [isRtl, t],
  );

  const purchaseSortOptions: SortOption[] = useMemo(
    () => [
      { value: "date_desc", label: isRtl ? "الأحدث أولاً" : "Newest first" },
      { value: "date_asc", label: isRtl ? "الأقدم أولاً" : "Oldest first" },
      { value: "total_desc", label: isRtl ? "الأعلى قيمة" : "Highest value" },
      { value: "total_asc", label: isRtl ? "الأقل قيمة" : "Lowest value" },
    ],
    [isRtl],
  );

  const filtered = useMemo(() => {
    let list = rows;

    if (search.trim()) {
      const q = search.toLowerCase();
      list = list.filter((r) => {
        const invNum = r.invoice_number?.toLowerCase() || "";
        const sup = r.suppliers?.name?.toLowerCase() || "";
        const phone = r.suppliers?.phone?.toLowerCase() || "";
        const note = r.note?.toLowerCase() || "";
        return invNum.includes(q) || sup.includes(q) || phone.includes(q) || note.includes(q);
      });
    }

    if (statusTab !== "all") {
      list = list.filter((r) => r.status === statusTab);
    }

    if (filters.status) {
      list = list.filter((r) => r.status === filters.status);
    }

    if (filters.payment_method) {
      list = list.filter((r) => r.payment_method === filters.payment_method);
    }

    if (filters.created_at && typeof filters.created_at === "object") {
      const { from, to } = filters.created_at as { from?: string; to?: string };
      if (from) {
        const fromDate = new Date(from).getTime();
        list = list.filter((r) => new Date(r.created_at).getTime() >= fromDate);
      }
      if (to) {
        const toDate = new Date(to).getTime();
        list = list.filter((r) => new Date(r.created_at).getTime() <= toDate);
      }
    }

    list = [...list].sort((a, b) => {
      if (sort) {
        const aVal =
          sort.key === "created_at" ? new Date(a.created_at).getTime() : (a as any)[sort.key];
        const bVal =
          sort.key === "created_at" ? new Date(b.created_at).getTime() : (b as any)[sort.key];
        if (aVal == null && bVal == null) return 0;
        if (aVal == null) return 1;
        if (bVal == null) return -1;
        const cmp = aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
        return sort.direction === "asc" ? cmp : -cmp;
      }

      switch (sortKey) {
        case "date_asc":
          return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
        case "total_desc":
          return Number(b.total) - Number(a.total);
        case "total_asc":
          return Number(a.total) - Number(b.total);
        case "date_desc":
        default:
          return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
      }
    });

    return list;
  }, [rows, search, statusTab, filters, sort, sortKey]);

  const metrics = useMemo(() => {
    let totalValue = 0;
    let totalPaid = 0;
    let totalPending = 0;
    let paidCount = 0;
    let partialCount = 0;
    let unpaidCount = 0;
    let cancelledCount = 0;

    for (const r of rows) {
      const tot = Number(r.total) || 0;
      const pd = Number(r.paid) || 0;
      const rem = Math.max(0, tot - pd);

      if (r.status !== "cancelled") {
        totalValue += tot;
        totalPaid += pd;
        totalPending += rem;
      }

      if (r.status === "paid") paidCount++;
      else if (r.status === "partial") partialCount++;
      else if (r.status === "unpaid") unpaidCount++;
      else if (r.status === "cancelled") cancelledCount++;
    }

    const activeCount = rows.length - cancelledCount;
    const avgTicket = activeCount > 0 ? totalValue / activeCount : 0;

    return {
      totalCount: rows.length,
      totalValue,
      totalPaid,
      totalPending,
      paidCount,
      partialCount,
      unpaidCount,
      cancelledCount,
      avgTicket,
    };
  }, [rows]);

  const columns: DataTableColumn<Invoice>[] = useMemo(() => {
    const cols: DataTableColumn<Invoice>[] = [
      {
        key: "invoice_number",
        header: isRtl ? "رقم الفاتورة" : "Invoice #",
        sortable: true,
        width: "w-[190px]",
        sortValue: (inv) => inv.invoice_number,
        cell: (inv) => (
          <div className="flex flex-col py-0.5">
            <div className="flex items-center gap-1.5 font-mono text-xs font-bold text-foreground">
              <span>{inv.invoice_number}</span>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  copyInvoiceNumber(inv.invoice_number, inv.id);
                }}
                className="rounded p-1 text-muted-foreground hover:text-foreground"
                title={isRtl ? "نسخ" : "Copy"}
              >
                {copiedInvoiceId === inv.id ? (
                  <Check className="h-3 w-3 text-emerald-500" />
                ) : (
                  <Copy className="h-3 w-3" />
                )}
              </button>
            </div>
            <VortexDateBadge date={inv.created_at} variant="subtle" size="sm" showTime />
          </div>
        ),
      },
      {
        key: "supplier",
        header: t("common.supplier"),
        sortable: true,
        width: "w-[200px]",
        sortValue: (inv) => inv.suppliers?.name ?? "",
        cell: (inv) => {
          const supplierName = inv.suppliers?.name ?? "—";
          return (
            <div className="flex items-center gap-2 py-0.5">
              <span className="grid size-7 shrink-0 place-items-center rounded-full bg-surface-2 text-[10px] font-bold text-muted-foreground">
                {supplierName.slice(0, 1).toUpperCase()}
              </span>
              <div className="min-w-0">
                <span className="block truncate text-xs font-medium text-foreground">
                  {supplierName}
                </span>
                {inv.suppliers?.phone && (
                  <span className="dir-ltr block truncate font-mono text-[10px] text-muted-foreground">
                    {toSystemDigits(inv.suppliers.phone)}
                  </span>
                )}
              </div>
            </div>
          );
        },
      },
    ];

    if (hasMultiWarehouse) {
      cols.push({
        key: "warehouse",
        header: t("common.warehouse"),
        sortable: true,
        width: "w-[130px]",
        sortValue: (inv) => whName(inv.warehouses),
        cell: (inv) => (
          <span className="block truncate text-xs text-muted-foreground">
            {whName(inv.warehouses)}
          </span>
        ),
      });
    }

    cols.push(
      {
        key: "payment_method",
        header: t("sales.payment"),
        sortable: true,
        width: "w-[130px]",
        sortValue: (inv) => pmLabel(inv.payment_method),
        cell: (inv) => (
          <span className="inline-flex items-center whitespace-nowrap rounded-lg border border-border/80 bg-surface-2/60 px-2 py-0.5 text-[11px] text-muted-foreground">
            {pmLabel(inv.payment_method)}
          </span>
        ),
      },
      {
        key: "status",
        header: t("common.status"),
        sortable: true,
        width: "w-[110px]",
        sortValue: (inv) => inv.status,
        cell: (inv) => statusBadge(inv.status),
      },
      {
        key: "total",
        header: t("common.total"),
        align: "end",
        sortable: true,
        width: "w-[124px]",
        sortValue: (inv) => Number(inv.total) || 0,
        cell: (inv) => (
          <span className="font-mono text-xs font-bold tabular-nums text-foreground">
            {toSystemDigits(money(Number(inv.total) || 0))}
          </span>
        ),
      },
      {
        key: "paid",
        header: isRtl ? "المدفوع / المتبقي" : "Paid / Due",
        align: "end",
        sortable: true,
        width: "w-[140px]",
        sortValue: (inv) => Number(inv.paid) || 0,
        cell: (inv) => {
          const total = Number(inv.total) || 0;
          const paid = Number(inv.paid) || 0;
          const remaining = Math.max(0, total - paid);
          return (
            <div className="flex flex-col py-0.5">
              <span className="font-mono text-xs font-medium tabular-nums text-emerald-500">
                {toSystemDigits(money(paid))}
              </span>
              {remaining > 0 ? (
                <span className="font-mono text-[10px] font-semibold tabular-nums text-rose-500">
                  {toSystemDigits(money(remaining))}
                </span>
              ) : (
                <span className="text-[10px] text-muted-foreground">
                  {isRtl ? "خالص" : "Settled"}
                </span>
              )}
            </div>
          );
        },
      },
      {
        key: "actions",
        header: t("common.actions"),
        align: "end",
        width: "w-[130px]",
        cell: (inv) => (
          <div className="inline-flex items-center gap-1 pe-2" onClick={(e) => e.stopPropagation()}>
            <button
              type="button"
              disabled={!inv.suppliers?.phone}
              onClick={() => shareInvoiceWhatsApp(inv)}
              className={cn(
                "rounded-lg p-1.5 transition",
                inv.suppliers?.phone
                  ? "text-muted-foreground hover:bg-surface-2 hover:text-emerald-500 cursor-pointer"
                  : "text-muted-foreground/30 cursor-not-allowed opacity-50",
              )}
              title={isRtl ? "واتساب للمورد" : "WhatsApp"}
            >
              <WhatsAppIcon className="h-4 w-4" />
            </button>
            <button
              type="button"
              onClick={() => void openDirectPrint(inv)}
              className="rounded-lg p-1.5 text-muted-foreground hover:bg-surface-2 hover:text-foreground transition"
              title={isRtl ? "طباعة" : "Print"}
            >
              <Printer className="h-4 w-4" />
            </button>
            <button
              type="button"
              onClick={() => void openInvoice(inv)}
              className="rounded-lg p-1.5 text-muted-foreground hover:bg-surface-2 hover:text-foreground transition"
              title={isRtl ? "عرض التفاصيل" : "View Details"}
            >
              <Eye className="h-4 w-4" />
            </button>
          </div>
        ),
      },
    );

    return cols;
  }, [isRtl, hasMultiWarehouse, t, copiedInvoiceId]);

  return (
    <div className="space-y-5 pb-12">
      {/* ─── Unified Top Header & Quick Action Bar — Full width & responsive ─── */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between w-full">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-xl sm:text-2xl font-black text-foreground tracking-tight">
              {t("purchases.title")}
            </h1>
            <span className="inline-flex items-center rounded-full bg-primary/10 px-2.5 py-0.5 text-xs font-semibold text-primary">
              {toSystemDigits(rows.length.toString())}
            </span>
          </div>
          <p className="text-xs text-muted-foreground mt-0.5">
            {t("purchases.subtitle") ||
              (isRtl
                ? "إدارة وتتبع فواتير المشتريات والتوريد والموردين"
                : "Manage and track purchase invoices, supplies, and vendors")}
          </p>
        </div>

        {/* Quick action buttons row: stretched full width on mobile with refresh on the left */}
        <div className="flex w-full sm:w-auto items-center justify-between sm:justify-end gap-2">
          {/* Main action buttons */}
          <div className="flex items-center gap-1.5 sm:gap-2">
            <Link
              to="/purchase-pos"
              className="inline-flex h-9 items-center gap-1.5 rounded-xl border border-primary/30 bg-primary/10 px-2.5 sm:px-3 text-xs font-semibold text-primary hover:bg-primary/20 transition shadow-xs"
              title={isRtl ? "شراء سريع (POS)" : "Fast Purchase (POS)"}
            >
              <ShoppingCart className="h-3.5 w-3.5 shrink-0 text-primary" />
              <span className="hidden xs:inline sm:inline">
                {t("purchases.fast_purchase") || (isRtl ? "شراء سريع (POS)" : "Fast Purchase")}
              </span>
              <span className="xs:hidden sm:hidden">POS</span>
            </Link>

            <button
              type="button"
              onClick={() => setCreating(true)}
              className="inline-flex h-9 items-center gap-1.5 rounded-xl bg-primary px-3 sm:px-3.5 text-xs font-semibold text-primary-foreground shadow-xs hover:opacity-95 transition"
              title={isRtl ? "فاتورة شراء جديدة" : "New Purchase"}
            >
              <Plus className="h-3.5 w-3.5 shrink-0" />
              <span className="hidden xs:inline sm:inline">
                {t("purchases.new_invoice") || (isRtl ? "فاتورة شراء جديدة" : "New Purchase")}
              </span>
              <span className="xs:hidden sm:hidden">{isRtl ? "جديدة" : "New"}</span>
            </button>
          </div>

          {/* Refresh Button placed on the left edge (end in RTL) */}
          <button
            type="button"
            onClick={() => void load()}
            disabled={loading}
            className="inline-flex h-9 items-center gap-1.5 rounded-xl border border-border/80 bg-surface px-2.5 sm:px-3.5 text-xs font-medium text-foreground transition hover:bg-surface-2 hover:border-primary/40 disabled:opacity-50 shadow-xs"
            title={t("common.refresh") || (isRtl ? "تحديث الفواتير" : "Refresh")}
            aria-label={t("common.refresh") || (isRtl ? "تحديث" : "Refresh")}
          >
            <RefreshCw
              className={cn("h-3.5 w-3.5 shrink-0", loading && "animate-spin text-primary")}
            />
            <span className="hidden sm:inline font-semibold">
              {t("common.refresh") || (isRtl ? "تحديث" : "Refresh")}
            </span>
          </button>
        </div>
      </div>

      {/* ─── Luxury Vortex KPI Metrics Cards (2 columns on mobile, 4 on desktop) ─── */}
      <div className="grid grid-cols-2 gap-2.5 sm:gap-4 lg:grid-cols-4">
        <VortexMetricCard
          title={isRtl ? "إجمالي المشتريات" : "Total Purchases"}
          value={toSystemDigits(money(metrics.totalValue))}
          subtitle={`${toSystemDigits(metrics.totalCount.toString())} ${isRtl ? "فاتورة مسجلة" : "invoices"}`}
          icon={<ShoppingCart className="size-5" />}
          iconClassName="bg-primary/10 text-primary border border-primary/20"
          badge={isRtl ? "المشتريات" : "Purchases"}
          onClick={() => setStatusTab("all")}
          highlight={statusTab === "all"}
          className="cursor-pointer"
        />
        <VortexMetricCard
          title={isRtl ? "المبالغ المدفوعة" : "Paid to Vendors"}
          value={toSystemDigits(money(metrics.totalPaid))}
          subtitle={`${toSystemDigits(metrics.paidCount.toString())} ${isRtl ? "مسددة بالكامل" : "fully paid"}`}
          icon={<CheckCircle2 className="size-5" />}
          iconClassName="bg-blue-500/10 text-blue-500 border border-blue-500/20"
          badge={isRtl ? "مدفوع" : "Paid"}
          onClick={() => setStatusTab("paid")}
          highlight={statusTab === "paid"}
          className="cursor-pointer"
        />
        <VortexMetricCard
          title={isRtl ? "المتبقي والآجل" : "Outstanding & Due"}
          value={toSystemDigits(money(metrics.totalPending))}
          subtitle={`${toSystemDigits((metrics.unpaidCount + metrics.partialCount).toString())} ${isRtl ? "فواتير معلقة" : "pending invoices"}`}
          icon={<Clock className="size-5" />}
          iconClassName="bg-amber-500/10 text-amber-500 border border-amber-500/20"
          badge={isRtl ? "التزامات" : "Liabilities"}
          onClick={() => setStatusTab("unpaid")}
          highlight={statusTab === "unpaid"}
          className="cursor-pointer"
        />
        <VortexMetricCard
          title={isRtl ? "متوسط قيمة الفاتورة" : "Average Ticket"}
          value={toSystemDigits(money(metrics.avgTicket))}
          subtitle={isRtl ? "لكل عملية شراء نشطة" : "per active purchase"}
          icon={<TrendingDown className="size-5" />}
          iconClassName="bg-purple-500/10 text-purple-500 border border-purple-500/20"
          badge={isRtl ? "متوسط" : "Average"}
        />
      </div>

      {/* ─── Standard VORTEX TableToolbar: Search + Filters + Sort + View Toggle + Action ─── */}
      <TableToolbar
        sticky
        search={{
          value: search,
          onValueChange: setSearch,
          placeholder: isRtl
            ? "ابحث برقم الفاتورة، المورد، الهاتف..."
            : "Search PO number, supplier, phone...",
          resultCount: filtered.length,
        }}
        filters={{
          definitions: purchaseFilterDefinitions,
          values: filters,
          onValueChange: setFilters,
        }}
        sort={{
          options: purchaseSortOptions,
          value: sortKey,
          onValueChange: (value) => {
            setSortKey(value);
            setSort(null);
          },
          label: isRtl ? "ترتيب" : "Sort",
        }}
        viewToggle={<RecordsViewToggle value={viewMode} onChange={setViewMode} />}
        action={
          <PrimaryAction
            label={isRtl ? "فاتورة شراء جديدة" : "New Purchase"}
            icon={<Plus />}

            onClick={() => setCreating(true)}
          />
        }
      >
        {/* Quick Filter Tabs with custom dedicated colors for each status — Visible in ALL view modes */}
        <div className="flex items-center gap-1.5 overflow-x-auto pb-0.5 scrollbar-x-none">
          {[
            {
              id: "all",
              label: isRtl ? "الكل" : "All",
              count: metrics.totalCount,
              activeCls:
                "border-primary bg-primary text-primary-foreground shadow-xs shadow-primary/20",
              inactiveCls:
                "border-border/70 bg-surface/70 text-muted-foreground hover:bg-surface-2 hover:text-foreground",
              pillCls: "bg-muted text-muted-foreground",
            },
            {
              id: "paid",
              label: isRtl ? "مسددة" : "Paid",
              count: metrics.paidCount,
              activeCls:
                "border-emerald-600 bg-emerald-600 text-white shadow-xs shadow-emerald-600/20",
              inactiveCls:
                "border-emerald-500/30 bg-emerald-500/10 text-emerald-600 hover:bg-emerald-500/20",
              pillCls: "bg-emerald-500/20 text-emerald-600",
            },
            {
              id: "partial",
              label: isRtl ? "دفع جزئي" : "Partial",
              count: metrics.partialCount,
              activeCls: "border-amber-600 bg-amber-600 text-white shadow-xs shadow-amber-600/20",
              inactiveCls:
                "border-amber-500/30 bg-amber-500/10 text-amber-600 hover:bg-amber-500/20",
              pillCls: "bg-amber-500/20 text-amber-600",
            },
            {
              id: "unpaid",
              label: isRtl ? "غير مسددة (آجلة)" : "Unpaid",
              count: metrics.unpaidCount,
              activeCls: "border-rose-600 bg-rose-600 text-white shadow-xs shadow-rose-600/20",
              inactiveCls: "border-rose-500/30 bg-rose-500/10 text-rose-600 hover:bg-rose-500/20",
              pillCls: "bg-rose-500/20 text-rose-600",
            },
            {
              id: "cancelled",
              label: isRtl ? "ملغاة" : "Cancelled",
              count: metrics.cancelledCount,
              activeCls: "border-red-600 bg-red-600 text-white shadow-xs shadow-red-600/20",
              inactiveCls: "border-red-500/30 bg-red-500/10 text-red-500 hover:bg-red-500/20",
              pillCls: "bg-red-500/20 text-red-500",
            },
          ].map((f) => {
            const isSelected = statusTab === f.id;
            return (
              <button
                key={f.id}
                type="button"
                onClick={() => setStatusTab(f.id as StatusTab)}
                className={`flex shrink-0 items-center gap-1.5 rounded-full border px-3 py-1 text-xs font-bold transition ${
                  isSelected ? f.activeCls : f.inactiveCls
                }`}
              >
                <span>{f.label}</span>
                <span
                  className={`rounded-full px-1.5 py-0.2 text-[10px] font-mono ${
                    isSelected ? "bg-white/20 text-white" : f.pillCls
                  }`}
                >
                  {toSystemDigits(f.count.toString())}
                </span>
              </button>
            );
          })}
        </div>
      </TableToolbar>

      {/* ─── Main Content: Cards Grid vs List vs Classic Table ─── */}
      {loading ? (
        <div className="card-mullak p-12 text-center">
          <div className="mx-auto size-8 animate-spin rounded-full border-2 border-primary border-t-transparent" />
          <p className="mt-3 text-sm text-muted-foreground">
            {isRtl ? "جارِ تحميل فواتير المشتريات..." : "Loading purchases…"}
          </p>
        </div>
      ) : filtered.length === 0 ? (
        <div className="card-mullak flex flex-col items-center gap-3 p-12 text-center">
          <div className="grid size-16 place-items-center rounded-3xl border border-primary/20 bg-primary/10 text-primary shadow-sm">
            <ShoppingCart className="size-8" />
          </div>
          <h3 className="text-base font-bold text-foreground">
            {search || statusTab !== "all"
              ? isRtl
                ? "لا توجد فواتير مشتريات مطابقة"
                : "No matching purchase invoices"
              : t("purchases.no_purchases")}
          </h3>
          <p className="max-w-sm text-xs text-muted-foreground">
            {search || statusTab !== "all"
              ? isRtl
                ? "جرب تعديل خيارات البحث أو التصفية"
                : "Try adjusting your search query or filters"
              : isRtl
                ? "ابدأ بتسجيل أول أمر شراء من نقطة المشتريات."
                : "Start by recording your first purchase order."}
          </p>
          <Link
            to="/purchase-pos"
            className="mt-2 inline-flex items-center gap-2 rounded-full bg-primary px-5 py-2.5 text-xs font-bold text-primary-foreground shadow-sm transition hover:bg-primary/90 active:scale-95"
          >
            <ShoppingCart className="size-4" />
            <span>{isRtl ? "إنشاء أمر شراء الآن" : "Create Purchase Now"}</span>
          </Link>
        </div>
      ) : viewMode === "cards" ? (
        /* ─── The shared unified grid (2-up mobile, 3 md, 4 lg, 5 2xl) ─── */
        <div className="grid grid-cols-2 gap-2.5 sm:gap-4 md:grid-cols-3 lg:grid-cols-4 2xl:grid-cols-5">
          {filtered.map((inv) => {
            const total = Number(inv.total) || 0;
            const paid = Number(inv.paid) || 0;
            const remaining = Math.max(0, total - paid);
            const supplierName = inv.suppliers?.name ?? "—";

            return (
              <div
                key={inv.id}
                data-qa="purchase-card"
                onClick={() => void openInvoice(inv)}
                className="card-mullak group relative flex cursor-pointer flex-col justify-between overflow-hidden rounded-2xl p-3.5 transition-all duration-200 hover:shadow-md sm:p-4.5"
              >
                <div>
                  {/* Header: PO number + Copy + status */}
                  <div className="flex items-start justify-between gap-2">
                    <div className="min-w-0">
                      <div className="flex items-center gap-1">
                        <span className="truncate font-mono text-sm font-bold text-foreground transition group-hover:text-primary">
                          {inv.invoice_number}
                        </span>
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            copyInvoiceNumber(inv.invoice_number, inv.id);
                          }}
                          className="grid size-7 shrink-0 place-items-center rounded-lg text-muted-foreground hover:bg-surface-2 hover:text-foreground transition"
                          aria-label={isRtl ? "نسخ رقم الفاتورة" : "Copy invoice number"}
                        >
                          {copiedInvoiceId === inv.id ? (
                            <Check className="h-3.5 w-3.5 text-emerald-500" />
                          ) : (
                            <Copy className="h-3.5 w-3.5" />
                          )}
                        </button>
                      </div>
                      <div className="mt-1">
                        <VortexDateBadge
                          date={inv.created_at}
                          variant="formal"
                          size="sm"
                          showTime
                        />
                      </div>
                    </div>
                    <div className="shrink-0">{statusBadge(inv.status)}</div>
                  </div>

                  {/* Supplier + payment */}
                  <div className="mt-3 flex items-center justify-between gap-2 border-t border-border/60 pt-2.5 text-xs">
                    <div className="flex min-w-0 items-center gap-1.5">
                      <div className="grid size-6 shrink-0 place-items-center rounded-full bg-surface-2 text-[10px] font-bold">
                        {supplierName.slice(0, 1).toUpperCase()}
                      </div>
                      <div className="min-w-0">
                        <div className="truncate font-medium text-foreground">{supplierName}</div>
                        {inv.suppliers?.phone && (
                          <div className="dir-ltr truncate font-mono text-[10px] text-muted-foreground">
                            {toSystemDigits(inv.suppliers.phone)}
                          </div>
                        )}
                      </div>
                    </div>
                    <div className="inline-flex max-w-[45%] shrink-0 items-center gap-1 truncate rounded-lg border border-border/80 bg-surface-2/60 px-2 py-1 text-[11px] text-muted-foreground">
                      <span className="truncate">{pmLabel(inv.payment_method)}</span>
                    </div>
                  </div>

                  {hasMultiWarehouse && inv.warehouses && (
                    <div className="mt-2 truncate text-[11px] text-muted-foreground">
                      {isRtl ? "المستودع: " : "Warehouse: "}
                      {whName(inv.warehouses)}
                    </div>
                  )}

                  {/* Financial summary */}
                  <div className="mt-3 space-y-1.5 rounded-xl border border-border/60 bg-surface-2/40 p-2.5 text-xs">
                    <div className="flex items-center justify-between gap-2">
                      <span className="text-muted-foreground">{t("common.total")}</span>
                      <span className="truncate font-mono text-sm font-bold text-foreground">
                        <Ltr>{money(total)}</Ltr>
                      </span>
                    </div>
                    <div className="flex items-center justify-between gap-2">
                      <span className="text-muted-foreground">{t("common.paid")}</span>
                      <span className="truncate font-mono font-medium text-emerald-500">
                        <Ltr>{money(paid)}</Ltr>
                      </span>
                    </div>
                    {remaining > 0 && (
                      <div className="flex items-center justify-between gap-2 border-t border-border/40 pt-1.5 font-semibold text-rose-500">
                        <span>{isRtl ? "المتبقي للمورد" : "Due to Supplier"}</span>
                        <span className="truncate font-mono">
                          <Ltr>{money(remaining)}</Ltr>
                        </span>
                      </div>
                    )}
                  </div>
                </div>

                {/* Actions Footer */}
                <div
                  className="mt-3.5 flex items-center justify-between gap-2 border-t border-border/60 pt-3"
                  onClick={(e) => e.stopPropagation()}
                >
                  <div className="flex items-center gap-1.5">
                    <button
                      type="button"
                      disabled={!inv.suppliers?.phone}
                      onClick={() => shareInvoiceWhatsApp(inv)}
                      className={`grid size-8 place-items-center rounded-lg border transition ${
                        inv.suppliers?.phone
                          ? "border-border/70 text-muted-foreground hover:bg-surface-2 hover:text-emerald-500 cursor-pointer"
                          : "border-border/40 text-muted-foreground/30 cursor-not-allowed opacity-50"
                      }`}
                      title={
                        !inv.suppliers?.phone
                          ? isRtl
                            ? "هذا المورد لا يوجد لديه رقم هاتف مسجل"
                            : "No phone registered"
                          : isRtl
                            ? "مشاركة عبر واتساب"
                            : "Share via WhatsApp"
                      }
                    >
                      <WhatsAppIcon className="h-4 w-4" />
                    </button>
                    <button
                      type="button"
                      disabled={!inv.suppliers?.phone}
                      onClick={() => shareInvoiceSms(inv)}
                      className={`grid size-8 place-items-center rounded-lg border transition ${
                        inv.suppliers?.phone
                          ? "border-border/70 text-muted-foreground hover:bg-surface-2 hover:text-blue-500 cursor-pointer"
                          : "border-border/40 text-muted-foreground/30 cursor-not-allowed opacity-50"
                      }`}
                      title={
                        !inv.suppliers?.phone
                          ? isRtl
                            ? "هذا المورد لا يوجد لديه رقم هاتف مسجل"
                            : "No phone registered"
                          : isRtl
                            ? "مشاركة عبر SMS"
                            : "Share via SMS"
                      }
                    >
                      <MessageSquare className="h-4 w-4" />
                    </button>
                    <button
                      type="button"
                      onClick={() => void openInvoice(inv)}
                      className="grid size-8 place-items-center rounded-lg border border-border/70 text-muted-foreground transition hover:bg-surface-2 hover:text-foreground"
                      title={isRtl ? "عرض التفاصيل" : "View Details"}
                    >
                      <Eye className="h-4 w-4" />
                    </button>
                  </div>
                  <button
                    type="button"
                    onClick={() => void openDirectPrint(inv)}
                    className="inline-flex h-8 items-center gap-1.5 rounded-lg border border-border bg-surface px-3 text-xs font-medium text-foreground transition hover:bg-surface-2"
                  >
                    <Printer className="h-3.5 w-3.5" />
                    <span>{isRtl ? "طباعة" : "Print"}</span>
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      ) : viewMode === "list" ? (
        /* ─── Luxury Row-Cards View (List with Accent Strip) ─── */
        <div className="space-y-2.5">
          {filtered.map((inv) => {
            const total = Number(inv.total) || 0;
            const paid = Number(inv.paid) || 0;
            const remaining = Math.max(0, total - paid);
            const supplierName = inv.suppliers?.name ?? "—";
            const barColor =
              inv.status === "paid"
                ? "bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.4)]"
                : inv.status === "partial"
                  ? "bg-amber-500 shadow-[0_0_8px_rgba(245,158,11,0.5)]"
                  : inv.status === "unpaid"
                    ? "bg-rose-500 shadow-[0_0_8px_rgba(244,63,94,0.5)]"
                    : "bg-muted-foreground/30";

            return (
              <div
                key={inv.id}
                onClick={() => void openInvoice(inv)}
                className="card-mullak group relative flex cursor-pointer flex-col justify-between gap-3 rounded-2xl border p-3.5 transition-all duration-200 hover:border-primary/50 hover:shadow-md sm:flex-row sm:items-center sm:p-4"
              >
                <div className="flex min-w-0 flex-1 items-center gap-3">
                  <span
                    aria-hidden
                    className={`h-11 w-1.5 shrink-0 rounded-full sm:h-12 ${barColor}`}
                  />
                  <div className="grid size-11 shrink-0 place-items-center rounded-xl border border-primary/20 bg-primary/10 text-primary transition-all group-hover:scale-105 group-hover:bg-primary group-hover:text-primary-foreground">
                    <Receipt className="size-5" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="truncate font-mono text-sm font-bold text-foreground transition-colors group-hover:text-primary sm:text-base">
                        {inv.invoice_number}
                      </span>
                      <div className="shrink-0">{statusBadge(inv.status)}</div>
                      <div className="inline-flex items-center gap-1 truncate text-[11px] text-muted-foreground">
                        <span className="truncate">{pmLabel(inv.payment_method)}</span>
                      </div>
                    </div>
                    <div className="mt-1 flex flex-wrap items-center gap-3 text-[11px] text-muted-foreground">
                      <span className="truncate font-medium text-foreground">{supplierName}</span>
                      {inv.suppliers?.phone && (
                        <span className="dir-ltr truncate font-mono text-muted-foreground/80">
                          {toSystemDigits(inv.suppliers.phone)}
                        </span>
                      )}
                      <VortexDateBadge date={inv.created_at} variant="formal" size="sm" showTime />
                    </div>
                  </div>
                </div>

                <div className="flex items-center justify-between gap-4 border-t border-border/60 pt-2 sm:justify-end sm:border-t-0 sm:pt-0">
                  <div className="min-w-0 text-start sm:min-w-[120px] sm:text-end">
                    <div className="text-[10px] text-muted-foreground">
                      {isRtl ? "الإجمالي:" : "Total:"}
                    </div>
                    <div className="truncate font-mono text-sm font-bold text-foreground sm:text-base">
                      <Ltr>{money(total)}</Ltr>
                    </div>
                    {remaining > 0 ? (
                      <div className="truncate font-mono text-[10px] font-semibold text-rose-500">
                        {isRtl ? "متبقي: " : "Due: "}
                        <Ltr>{money(remaining)}</Ltr>
                      </div>
                    ) : (
                      <div className="text-[10px] font-medium text-emerald-500">
                        {isRtl ? "مدفوعة بالكامل" : "Fully paid"}
                      </div>
                    )}
                  </div>

                  <div
                    className="flex shrink-0 items-center gap-1"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <button
                      type="button"
                      disabled={!inv.suppliers?.phone}
                      onClick={() => shareInvoiceWhatsApp(inv)}
                      className={`rounded-lg p-1.5 transition ${
                        inv.suppliers?.phone
                          ? "text-muted-foreground hover:bg-surface-2 hover:text-emerald-500 cursor-pointer"
                          : "text-muted-foreground/30 cursor-not-allowed opacity-50"
                      }`}
                      title={isRtl ? "واتساب للمورد" : "WhatsApp"}
                    >
                      <WhatsAppIcon className="h-4 w-4" />
                    </button>
                    <button
                      type="button"
                      disabled={!inv.suppliers?.phone}
                      onClick={() => shareInvoiceSms(inv)}
                      className={`rounded-lg p-1.5 transition ${
                        inv.suppliers?.phone
                          ? "text-muted-foreground hover:bg-surface-2 hover:text-blue-500 cursor-pointer"
                          : "text-muted-foreground/30 cursor-not-allowed opacity-50"
                      }`}
                      title={isRtl ? "رسالة SMS" : "SMS"}
                    >
                      <MessageSquare className="h-4 w-4" />
                    </button>
                    <button
                      type="button"
                      onClick={() => void openDirectPrint(inv)}
                      className="rounded-lg p-1.5 text-muted-foreground hover:bg-surface-2 hover:text-foreground transition"
                      title={isRtl ? "طباعة" : "Print"}
                    >
                      <Printer className="h-4 w-4" />
                    </button>
                    <button
                      type="button"
                      onClick={() => void openInvoice(inv)}
                      className="rounded-lg p-1.5 text-muted-foreground hover:bg-surface-2 hover:text-foreground transition"
                      title={isRtl ? "تفاصيل" : "Details"}
                    >
                      <Eye className="h-4 w-4" />
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        /* ─── Classic Table View: same DataTable as products/sales ─── */
        <div className="panel-elevated -mx-1 overflow-hidden rounded-2xl border border-border/70 sm:mx-0">
          <DataTable
            className="px-0"
            columns={columns}
            rows={filtered}
            rowKey={(inv) => inv.id}
            loading={loading}
            initialLoading={loading}
            error={null}
            sort={sort}
            onSortChange={setSort}
            minWidth={hasMultiWarehouse ? 1120 : 980}
            horizontalScroll={tableUsesHorizontalScroll}
            stickyHeader
            onRowClick={(inv) => void openInvoice(inv)}
            empty={{
              icon: <ShoppingCart />,
              title: t("purchases.no_purchases"),
              description: isRtl
                ? "ابدأ بتسجيل أول أمر شراء من نقطة المشتريات."
                : "Start by recording your first purchase order.",
            }}
          />
        </div>
      )}

      {/* ─── Luxury Invoice Details Sheet (Vortex UI) ─── */}
      <VortexInvoiceDetailsSheet
        open={Boolean(selected)}
        onOpenChange={(isOpen) => {
          if (!isOpen) setSelected(null);
        }}
        type="purchase"
        invoice={
          selected
            ? {
                id: selected.id,
                invoice_number: selected.invoice_number,
                created_at: selected.created_at,
                status: selected.status,
                subtotal: selected.subtotal,
                discount: selected.discount,
                tax: selected.tax,
                total: selected.total,
                paid: selected.paid,
                payment_method: selected.payment_method,
                note: selected.note,
                warehouseName: whName(selected.warehouses),
              }
            : null
        }
        party={{
          name: selected?.suppliers?.name ?? (lang === "ar" ? "مورد عام" : "General Vendor"),
          phone: selected?.suppliers?.phone,
          roleLabel: t("common.supplier") || (lang === "ar" ? "المورد" : "Supplier"),
        }}
        items={lines.map((l) => ({
          id: l.id,
          name: l.products?.name || "—",
          name_ar: l.products?.name_ar,
          sku: l.products?.sku,
          quantity: l.quantity,
          unitPrice: l.unit_cost,
          total: l.total,
        }))}
        loadingItems={loadingLines}
        hasMultiWarehouse={hasMultiWarehouse}
        pmLabel={pmLabel}
        statusLabel={statusLabel}
        statusBadge={statusBadge}
        onPrint={() => {
          if (selected) {
            setDirectPrintInvoice(selected);
            setDirectPrintLines(lines);
          }
        }}
        onWhatsApp={() => {
          if (selected) shareInvoiceWhatsApp(selected);
        }}
        onSms={() => {
          if (selected) shareInvoiceSms(selected);
        }}
        copyInvoiceNumber={copyInvoiceNumber}
        copiedInvoiceId={copiedInvoiceId}
      />

      {/* Direct print modal when opened from card or table */}
      {directPrintInvoice && (
        <LuxuryPrintPreviewModal
          open={Boolean(directPrintInvoice)}
          onClose={() => setDirectPrintInvoice(null)}
          doc={{
            docType: "purchase_invoice",
            title: t("purchases.title") || "فاتورة مشتريات وتوريد",
            number: directPrintInvoice.invoice_number,
            date: new Date(directPrintInvoice.created_at).toLocaleString(
              lang === "ar" ? "ar-EG" : "en-US",
            ),
            partyLabel: t("common.supplier") || "المورد",
            partyName: directPrintInvoice.suppliers?.name ?? "",
            partyPhone: directPrintInvoice.suppliers?.phone ?? "",
            warehouse: hasMultiWarehouse ? whName(directPrintInvoice.warehouses) : undefined,
            payment: pmLabel(directPrintInvoice.payment_method),
            status: statusLabel(directPrintInvoice.status),
            lines: directPrintLines.map((l) => ({
              product: l.products?.name_ar || l.products?.name || "—",
              qty: Number(l.quantity),
              price: Number(l.unit_cost),
              total: Number(l.total),
              code: l.products?.sku || undefined,
            })),
            subtotal: Number(directPrintInvoice.subtotal),
            tax: Number(directPrintInvoice.tax),
            discount: Number(directPrintInvoice.discount),
            total: Number(directPrintInvoice.total),
            paid: Number(directPrintInvoice.paid),
            balance: Math.max(
              0,
              Number(directPrintInvoice.total) - Number(directPrintInvoice.paid),
            ),
          }}
          documentType="purchase_invoice"
          title={
            lang === "ar" ? "معاينة وطباعة فاتورة المشتريات" : "Purchase Invoice Print Preview"
          }
          defaultFormat="standard"
          customerName={directPrintInvoice.suppliers?.name ?? undefined}
        />
      )}

      {creating && (
        <CreateDialog
          onClose={() => setCreating(false)}
          onDone={() => {
            setCreating(false);
            void load();
          }}
          hasMultiWarehouse={hasMultiWarehouse}
        />
      )}
    </div>
  );
}

function ViewDialog({
  invoice,
  lines,
  loadingLines,
  onClose,
  pmLabel,
  statusLabel,
  hasMultiWarehouse,
  onWhatsApp,
  onSms,
  copyInvoiceNumber,
  copiedInvoiceId,
}: {
  invoice: Invoice;
  lines: Line[];
  loadingLines: boolean;
  onClose: () => void;
  pmLabel: (m: string) => string;
  statusLabel: (s: string) => string;
  hasMultiWarehouse?: boolean;
  onWhatsApp: () => void;
  onSms: () => void;
  copyInvoiceNumber: (num: string, id: string) => void;
  copiedInvoiceId: string | null;
}) {
  const { t, lang } = useI18n();
  const isRtl = lang === "ar";
  const [previewOpen, setPreviewOpen] = useState(false);
  const wh = invoice.warehouses;
  const whLabel = !wh ? "—" : lang === "ar" ? wh.name_ar || wh.name : wh.name || wh.name_ar || "—";
  const supplierName = invoice.suppliers?.name ?? (isRtl ? "مورد عام" : "General Vendor");
  const remaining = Math.max(0, Number(invoice.total) - Number(invoice.paid));

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-end bg-black/65 backdrop-blur-xs animate-in fade-in duration-200"
      onClick={onClose}
    >
      <div
        className="h-full w-full max-w-2xl border-s border-border/80 bg-background/95 backdrop-blur-md p-6 shadow-2xl overflow-y-auto animate-in slide-in-from-left duration-200 relative flex flex-col justify-between"
        onClick={(e) => e.stopPropagation()}
        dir={isRtl ? "rtl" : "ltr"}
      >
        {/* Ambient decorative glow */}
        <div className="absolute -top-12 -right-12 size-48 rounded-full bg-primary/20 blur-3xl pointer-events-none" />

        {/* Modal Header */}
        <div className="flex items-center justify-between border-b border-border/80 bg-surface-2/40 px-6 py-4 -mx-6 -mt-6 mb-5">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-primary/10 text-primary">
              <Receipt className="h-5 w-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="font-mono text-lg font-bold text-foreground">
                  {invoice.invoice_number}
                </h3>
                <button
                  type="button"
                  onClick={() => copyInvoiceNumber(invoice.invoice_number, invoice.id)}
                  className="rounded p-1 text-muted-foreground hover:text-foreground"
                >
                  {copiedInvoiceId === invoice.id ? (
                    <Check className="h-3.5 w-3.5 text-emerald-500" />
                  ) : (
                    <Copy className="h-3.5 w-3.5" />
                  )}
                </button>
              </div>
              <div className="mt-0.5">
                <VortexDateBadge date={invoice.created_at} variant="formal" showTime />
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={onClose}
              className="rounded-lg p-1.5 text-muted-foreground hover:bg-surface-2 hover:text-foreground"
            >
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>

        {/* Modal Body */}
        <div className="flex-1 overflow-y-auto space-y-5">
          {/* Info Grid */}
          <div
            className={`grid gap-3 rounded-xl border border-border/80 bg-surface-2/30 p-4 text-xs ${
              hasMultiWarehouse ? "grid-cols-2 sm:grid-cols-4" : "grid-cols-1 sm:grid-cols-3"
            }`}
          >
            <div>
              <span className="text-[10px] uppercase font-semibold text-muted-foreground">
                {isRtl ? "المورد" : "Supplier"}
              </span>
              <p className="mt-0.5 text-sm font-semibold text-foreground">{supplierName}</p>
              {invoice.suppliers?.phone && (
                <p className="text-[11px] text-muted-foreground dir-ltr font-mono">
                  {toSystemDigits(invoice.suppliers.phone)}
                </p>
              )}
            </div>

            {hasMultiWarehouse && (
              <div>
                <span className="text-[10px] uppercase font-semibold text-muted-foreground">
                  {isRtl ? "المستودع / الفرع" : "Warehouse"}
                </span>
                <p className="mt-0.5 text-sm font-semibold text-foreground">{whLabel}</p>
              </div>
            )}

            <div>
              <span className="text-[10px] uppercase font-semibold text-muted-foreground">
                {isRtl ? "طريقة السداد" : "Payment Method"}
              </span>
              <p className="mt-0.5 text-sm font-medium text-foreground">
                {pmLabel(invoice.payment_method)}
              </p>
            </div>

            <div>
              <span className="text-[10px] uppercase font-semibold text-muted-foreground">
                {isRtl ? "حالة الفاتورة" : "Status"}
              </span>
              <p className="mt-0.5 text-sm font-semibold text-foreground">
                {statusLabel(invoice.status)}
              </p>
            </div>
          </div>

          {/* Note / Terms if present */}
          {invoice.note && (
            <div className="rounded-xl border border-border/80 bg-surface-2/40 p-3 text-xs text-muted-foreground">
              <span className="font-semibold text-foreground me-1">
                {isRtl ? "الملاحظات وشروط التوريد:" : "Note & Terms:"}
              </span>
              {invoice.note}
            </div>
          )}

          {/* Items Table */}
          <div>
            <h4 className="mb-2 text-xs font-bold uppercase tracking-wider text-muted-foreground">
              {isRtl ? "أصناف وبنود أمر الشراء" : "Purchase Items"}
            </h4>
            <div className="overflow-hidden rounded-xl border border-border">
              <table className="w-full text-xs">
                <thead className="bg-surface-2/70 text-muted-foreground">
                  <tr>
                    <th className="px-3 py-2.5 text-start font-medium">
                      {isRtl ? "المنتج / الصنف" : "Item"}
                    </th>
                    <th className="px-3 py-2.5 text-center font-medium">
                      {isRtl ? "الكمية" : "Qty"}
                    </th>
                    <th className="px-3 py-2.5 text-end font-medium">
                      {isRtl ? "تكلفة الوحدة" : "Unit Cost"}
                    </th>
                    <th className="px-3 py-2.5 text-end font-medium">
                      {isRtl ? "الإجمالي" : "Total"}
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/60">
                  {loadingLines ? (
                    <tr>
                      <td colSpan={4} className="py-6 text-center text-muted-foreground">
                        <RefreshCw className="mx-auto h-4 w-4 animate-spin mb-1 text-primary" />
                        {isRtl ? "جاري جلب تفاصيل البنود..." : "Loading items..."}
                      </td>
                    </tr>
                  ) : lines.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="py-6 text-center text-muted-foreground">
                        {isRtl ? "لا توجد بنود مسجلة لهذه الفاتورة" : "No items recorded"}
                      </td>
                    </tr>
                  ) : (
                    lines.map((l) => (
                      <tr key={l.id} className="hover:bg-surface-2/30">
                        <td className="px-3 py-2.5">
                          <div className="font-medium text-foreground">
                            {l.products?.name_ar || l.products?.name || "—"}
                          </div>
                          {l.products?.sku && (
                            <div className="text-[10px] font-mono text-muted-foreground">
                              SKU: {l.products.sku}
                            </div>
                          )}
                        </td>
                        <td className="px-3 py-2.5 text-center">
                          <span className="inline-block rounded-md bg-surface-2 px-2 py-0.5 font-mono font-semibold text-foreground">
                            {toSystemDigits(l.quantity.toString())}
                          </span>
                        </td>
                        <td className="px-3 py-2.5 text-end font-mono">
                          {toSystemDigits(money(Number(l.unit_cost)))}
                        </td>
                        <td className="px-3 py-2.5 text-end font-mono font-semibold text-foreground">
                          {toSystemDigits(money(Number(l.total)))}
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>

          {/* Financial Breakdown */}
          <div className="rounded-xl border border-border/80 bg-surface-2/30 p-4 text-xs space-y-1.5">
            <div className="flex justify-between text-muted-foreground">
              <span>{isRtl ? "المجموع الفرعي (قبل الضريبة):" : "Subtotal:"}</span>
              <span className="font-mono">{toSystemDigits(money(Number(invoice.subtotal)))}</span>
            </div>
            {Number(invoice.discount) > 0 && (
              <div className="flex justify-between text-emerald-500">
                <span>{isRtl ? "الخصم المكتسب:" : "Discount:"}</span>
                <span className="font-mono">
                  -{toSystemDigits(money(Number(invoice.discount)))}
                </span>
              </div>
            )}
            {Number(invoice.tax) > 0 && (
              <div className="flex justify-between text-muted-foreground">
                <span>{isRtl ? "ضريبة القيمة المضافة:" : "VAT / Tax:"}</span>
                <span className="font-mono">{toSystemDigits(money(Number(invoice.tax)))}</span>
              </div>
            )}
            <div className="flex justify-between border-t border-border pt-1.5 text-sm font-bold text-foreground">
              <span>{isRtl ? "الإجمالي الكلي:" : "Grand Total:"}</span>
              <span className="font-mono text-base">
                {toSystemDigits(money(Number(invoice.total)))}
              </span>
            </div>
            <div className="flex justify-between text-emerald-500 font-medium">
              <span>{isRtl ? "المسدد نقداً للمورد:" : "Paid:"}</span>
              <span className="font-mono">{toSystemDigits(money(Number(invoice.paid)))}</span>
            </div>
            {remaining > 0 && (
              <div className="flex justify-between text-rose-500 font-bold border-t border-border/60 pt-1 text-xs">
                <span>{isRtl ? "المتبقي (دين آجل للمورد):" : "Remaining Due:"}</span>
                <span className="font-mono">{toSystemDigits(money(remaining))}</span>
              </div>
            )}
          </div>
        </div>

        {/* Modal Footer / Actions */}
        <div className="flex flex-wrap items-center justify-between gap-2 border-t border-border/80 bg-surface-2/40 px-6 py-4 -mx-6 -mb-6 mt-5">
          <div className="flex items-center gap-2">
            <button
              type="button"
              disabled={!invoice.suppliers?.phone}
              onClick={onWhatsApp}
              title={
                !invoice.suppliers?.phone
                  ? isRtl
                    ? "هذا المورد لا يوجد لديه رقم هاتف مسجل في النظام"
                    : "This supplier has no phone number registered"
                  : isRtl
                    ? "مشاركة واتساب"
                    : "WhatsApp"
              }
              className={`inline-flex h-9 items-center gap-1.5 rounded-lg px-3 text-xs font-semibold transition ${
                invoice.suppliers?.phone
                  ? "border border-emerald-500/30 bg-emerald-500/10 text-emerald-500 hover:bg-emerald-500/20 cursor-pointer"
                  : "border border-border/60 bg-muted/40 text-muted-foreground/40 cursor-not-allowed opacity-50"
              }`}
            >
              <WhatsAppIcon className="h-4 w-4" />
              <span>{isRtl ? "واتساب للمورد" : "WhatsApp"}</span>
            </button>

            <button
              type="button"
              disabled={!invoice.suppliers?.phone}
              onClick={onSms}
              title={
                !invoice.suppliers?.phone
                  ? isRtl
                    ? "هذا المورد لا يوجد لديه رقم هاتف مسجل في النظام"
                    : "This supplier has no phone number registered"
                  : isRtl
                    ? "مشاركة عبر SMS"
                    : "SMS"
              }
              className={`inline-flex h-9 items-center gap-1.5 rounded-lg px-3 text-xs font-semibold transition ${
                invoice.suppliers?.phone
                  ? "border border-blue-500/30 bg-blue-500/10 text-blue-500 hover:bg-blue-500/20 cursor-pointer"
                  : "border border-border/60 bg-muted/40 text-muted-foreground/40 cursor-not-allowed opacity-50"
              }`}
            >
              <MessageSquare className="h-4 w-4" />
              <span>{isRtl ? "رسالة SMS" : "SMS"}</span>
            </button>
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => setPreviewOpen(true)}
              className="inline-flex h-9 items-center gap-1.5 rounded-lg bg-primary px-4 text-xs font-semibold text-primary-foreground shadow-sm hover:opacity-95 transition"
            >
              <Printer className="h-4 w-4" />
              <span>{isRtl ? "طباعة الفاتورة" : "Print"}</span>
            </button>

            <button
              type="button"
              onClick={onClose}
              className="inline-flex h-9 items-center rounded-lg border border-border bg-surface px-4 text-xs font-medium text-foreground hover:bg-surface-2 transition"
            >
              {t("common.close")}
            </button>
          </div>
        </div>
      </div>

      {previewOpen && (
        <LuxuryPrintPreviewModal
          open={previewOpen}
          onClose={() => setPreviewOpen(false)}
          doc={{
            docType: "purchase_invoice",
            title: t("purchases.title") || "فاتورة مشتريات وتوريد",
            number: invoice.invoice_number,
            date: new Date(invoice.created_at).toLocaleString(lang === "ar" ? "ar-EG" : "en-US"),
            partyLabel: t("common.supplier") || "المورد",
            partyName: invoice.suppliers?.name ?? "",
            partyPhone: invoice.suppliers?.phone ?? "",
            warehouse: hasMultiWarehouse ? whLabel : undefined,
            payment: pmLabel(invoice.payment_method),
            status: statusLabel(invoice.status),
            lines: lines.map((l) => ({
              product: l.products?.name_ar || l.products?.name || "—",
              qty: Number(l.quantity),
              price: Number(l.unit_cost),
              total: Number(l.total),
              code: l.products?.sku || undefined,
            })),
            subtotal: Number(invoice.subtotal),
            tax: Number(invoice.tax),
            discount: Number(invoice.discount),
            total: Number(invoice.total),
            paid: Number(invoice.paid),
            balance: Math.max(0, Number(invoice.total) - Number(invoice.paid)),
          }}
          documentType="purchase_invoice"
          title={
            lang === "ar" ? "معاينة وطباعة فاتورة المشتريات" : "Purchase Invoice Print Preview"
          }
          defaultFormat="standard"
          customerName={invoice.suppliers?.name ?? undefined}
        />
      )}
    </div>
  );
}

function CreateDialog({
  onClose,
  onDone,
  hasMultiWarehouse,
}: {
  onClose: () => void;
  onDone: () => void;
  hasMultiWarehouse?: boolean;
}) {
  const { t, lang } = useI18n();
  const [products, setProducts] = useState<Product[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
  const [warehouseId, setWarehouseId] = useState("");
  const [supplierId, setSupplierId] = useState("");
  const [search, setSearch] = useState("");
  const [stockMap, setStockMap] = useState<Record<string, number>>({});
  const [cart, setCart] = useState<CartLine[]>([]);
  const [paid, setPaid] = useState<number | null>(null);
  const [discount, setDiscount] = useState<number | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<string>("bank_transfer");
  const [note, setNote] = useState("");
  const [loading, setLoading] = useState(false);
  const productLabel = (p?: Pick<Product, "name" | "name_ar"> | null) =>
    !p ? "—" : lang === "ar" ? p.name_ar || p.name : p.name || p.name_ar || "—";
  const lowStockSuggestions = useMemo(
    () => products.filter((p) => Number(stockMap[p.id] ?? 0) <= 10).slice(0, 6),
    [products, stockMap],
  );

  useEffect(() => {
    void (async () => {
      const [{ data: ps }, { data: ss }, { data: ws }] = await Promise.all([
        supabase
          .from("products")
          .select(
            "id,name,name_ar,sku,barcode,cost_price,tax_rate,unit:units!products_unit_id_fkey(short_name,name,name_ar),category:categories(name,name_ar),inventory!inventory_product_id_fkey(warehouse_id,quantity)",
          )
          .eq("is_active", true)
          .order("name")
          .limit(500),
        supabase.from("suppliers").select("id,name").eq("is_active", true).order("name"),
        supabase.from("warehouses").select("id,name,name_ar").eq("is_active", true).order("name"),
      ]);
      setProducts((ps ?? []) as Product[]);
      setSuppliers(ss ?? []);
      setWarehouses(ws ?? []);
      if (ws?.[0]) setWarehouseId(ws[0].id);
      if (ss?.[0]) setSupplierId(ss[0].id);
    })();
  }, []);

  useEffect(() => {
    if (!warehouseId) {
      setStockMap({});
      return;
    }
    void (async () => {
      const { data, error } = await supabase
        .from("inventory")
        .select("product_id,quantity")
        .eq("warehouse_id", warehouseId);
      if (error) return;
      const next: Record<string, number> = {};
      for (const row of data ?? []) {
        next[row.product_id] = Number(row.quantity ?? 0);
      }
      setStockMap(next);
    })();
  }, [warehouseId]);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    return (
      q
        ? products.filter((p) =>
            [p.name, p.name_ar, p.sku, p.barcode].some((value) =>
              (value ?? "").toLowerCase().includes(q),
            ),
          )
        : products
    ).slice(0, 30);
  }, [products, search]);

  function addToCart(p: Product) {
    const available = Number(stockMap[p.id] ?? 0);
    setCart((prev) => {
      const idx = prev.findIndex((l) => l.product_id === p.id);
      if (idx >= 0) {
        const n = [...prev];
        const nextQty = n[idx].quantity + 1;
        n[idx] = { ...n[idx], quantity: nextQty };
        return n;
      }
      return [
        ...prev,
        {
          product_id: p.id,
          name: productLabel(p),
          unit_cost: Number(p.cost_price),
          tax_rate: Number(p.tax_rate ?? 0),
          quantity: 1,
        },
      ];
    });
    if (available === 0 && warehouseId) {
      toast.info(
        lang === "ar"
          ? "سيتم إضافة هذا المنتج كإضافة جديدة إلى المخزون في المستودع المحدد"
          : "This product will be added as a new stock entry in the selected warehouse.",
      );
    }
  }

  function clearCart() {
    setCart([]);
    setPaid(null);
    setDiscount(null);
  }

  function update(pid: string, patch: Partial<CartLine>) {
    setCart((c) => c.map((l) => (l.product_id === pid ? { ...l, ...patch } : l)));
  }

  const subtotal = cart.reduce((s, l) => s + l.unit_cost * l.quantity, 0);
  const taxTotal = cart.reduce((s, l) => s + l.unit_cost * l.quantity * (l.tax_rate / 100), 0);
  const discountN = discount ?? 0;
  const total = Math.max(0, subtotal + taxTotal - discountN);
  const paidN = paid ?? 0;

  async function submit() {
    if (loading) return;
    if (!warehouseId || !supplierId) return toast.error(t("purchases.select_ws"));
    if (cart.length === 0) return toast.error(t("purchases.add_items"));

    const invalidLine = cart.find(
      (line) =>
        !Number.isFinite(line.quantity) ||
        line.quantity <= 0 ||
        !Number.isFinite(line.unit_cost) ||
        line.unit_cost < 0 ||
        !Number.isFinite(line.tax_rate) ||
        line.tax_rate < 0,
    );
    if (invalidLine) {
      return toast.error(
        lang === "ar"
          ? "يجب أن تكون الكمية والسعر والضريبة أرقامًا صحيحة وموجبة"
          : "Quantity, cost, and tax must be valid positive numbers.",
      );
    }

    setLoading(true);
    try {
      const { error } = await supabase.rpc("create_purchase", {
        _warehouse_id: warehouseId,
        _supplier_id: supplierId,
        // The picker holds a catalogue id. Convert at the boundary, exactly as
        // the POS screen does, so `create_purchase` receives the stored value it
        // casts into the ENUM.
        _payment_method: toLegacyPaymentValue(paymentMethod),
        _paid: paymentMethod === "credit" ? 0 : paidN || total,
        _discount: discountN,
        _note: (note || null) as any,
        _items: cart.map((l) => ({
          product_id: l.product_id,
          quantity: Number(l.quantity),
          unit_cost: Number(l.unit_cost),
          tax_rate: Number(l.tax_rate),
        })),
      });
      if (error) throw error;
      toast.success(t("purchases.recorded"));
      onDone();
    } catch (e: any) {
      toast.error(e.message ?? t("common.failed"));
    } finally {
      setLoading(false);
    }
  }

  const pmKey = (m: string) => paymentMethodLabel(m, lang === "ar" ? "ar" : "en");

  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-background/80 backdrop-blur-sm p-4">
      <div className="panel-elevated flex max-h-[90vh] w-full max-w-4xl flex-col p-6">
        <div className="mb-4 flex items-center justify-between">
          <h3 className="text-lg font-semibold">{t("purchases.new_po")}</h3>
          <button onClick={onClose} className="rounded p-1 hover:bg-surface-2">
            <X className="h-4 w-4" />
          </button>
        </div>

        <div className="mb-3 grid grid-cols-2 gap-3">
          <div>
            <label className="mb-1 block text-xs text-muted-foreground">
              {t("common.supplier")} *
            </label>
            <select
              value={supplierId}
              onChange={(e) => setSupplierId(e.target.value)}
              className="h-9 w-full rounded-md border border-input bg-surface px-2 text-sm"
            >
              {suppliers.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.name}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="mb-1 block text-xs text-muted-foreground">
              {t("common.warehouse")} *
            </label>
            <select
              value={warehouseId}
              onChange={(e) => setWarehouseId(e.target.value)}
              className="h-9 w-full rounded-md border border-input bg-surface px-2 text-sm"
            >
              {warehouses.map((w) => (
                <option key={w.id} value={w.id}>
                  {lang === "ar" ? w.name_ar || w.name : w.name || w.name_ar || ""}
                </option>
              ))}
            </select>
          </div>
        </div>

        <div className="mb-3 flex items-center justify-between gap-2 rounded-xl border border-border/70 bg-surface/80 px-3 py-2 text-[11px] text-muted-foreground">
          <div className="flex items-center gap-2">
            <span className="inline-flex rounded-full bg-primary/10 px-2 py-1 font-medium text-primary">
              {cart.length} {t("purchases.items")}
            </span>
            <span>{money(total)}</span>
          </div>
          {cart.length > 0 && (
            <button
              type="button"
              onClick={clearCart}
              className="rounded-md border border-border px-2 py-1 text-[10px] font-medium hover:bg-surface-2"
            >
              {lang === "ar" ? "مسح السلة" : "Clear cart"}
            </button>
          )}
        </div>

        <div className="grid flex-1 grid-cols-1 gap-4 overflow-hidden md:grid-cols-2">
          <div className="flex flex-col overflow-hidden">
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder={t("purchases.search_products")}
              className="mb-2 h-9 rounded-md border border-input bg-surface px-3 text-sm"
            />
            {!search && lowStockSuggestions.length > 0 && (
              <div className="mb-2 flex flex-wrap gap-1.5">
                {lowStockSuggestions.map((p) => (
                  <button
                    key={p.id}
                    type="button"
                    onClick={() => addToCart(p)}
                    className="inline-flex items-center gap-1 rounded-full border border-amber-500/40 bg-amber-500/10 px-2 py-1 text-[10px] font-medium text-amber-700 dark:text-amber-300"
                  >
                    {productLabel(p)}
                    <span className="font-mono">({Number(stockMap[p.id] ?? 0)})</span>
                  </button>
                ))}
              </div>
            )}
            <div className="flex-1 overflow-y-auto space-y-1 pr-1">
              {filtered.map((p) => {
                const available = Number(stockMap[p.id] ?? 0);
                return (
                  <button
                    key={p.id}
                    onClick={() => addToCart(p)}
                    className="flex w-full items-center justify-between gap-3 rounded border border-border bg-surface px-3 py-2 text-sm hover:border-ring hover:bg-surface-2"
                  >
                    <div className="min-w-0 flex-1 text-start">
                      <div className="truncate font-medium">{productLabel(p)}</div>
                      <div className="flex items-center gap-2 text-[11px] text-muted-foreground">
                        <span>{p.sku ?? "—"}</span>
                        {p.barcode && <span className="font-mono">{p.barcode}</span>}
                      </div>
                    </div>
                    <div className="text-end">
                      <div className="text-xs text-muted-foreground">
                        {money(Number(p.cost_price))}
                      </div>
                      <div className="text-[10px] text-muted-foreground">
                        {lang === "ar" ? `المخزون: ${available}` : `Stock: ${available}`}
                      </div>
                    </div>
                  </button>
                );
              })}
            </div>
          </div>

          <div className="flex flex-col overflow-hidden">
            <div className="mb-2 text-xs font-medium text-muted-foreground">
              {t("purchases.items")} ({cart.length})
            </div>
            <div className="flex-1 overflow-y-auto space-y-2 pr-1">
              {cart.length === 0 ? (
                <div className="grid place-items-center py-10 text-sm text-muted-foreground">
                  {t("purchases.click_to_add")}
                </div>
              ) : (
                cart.map((l) => (
                  <div key={l.product_id} className="rounded border border-border bg-surface p-2">
                    <div className="flex items-start justify-between gap-2">
                      <div className="truncate text-sm font-medium">{l.name}</div>
                      <button
                        onClick={() =>
                          setCart((c) => c.filter((x) => x.product_id !== l.product_id))
                        }
                        className="text-muted-foreground hover:text-destructive"
                      >
                        <Trash2 className="h-3.5 w-3.5" />
                      </button>
                    </div>
                    <div className="mt-2 grid grid-cols-3 gap-1">
                      <QuantityInput
                        aria-label={t("common.qty")}
                        value={l.quantity}
                        onValueChange={(v) => update(l.product_id, { quantity: v ?? 0 })}
                        decimals={3}
                        emptyAsZero
                        min={0}
                        className="h-7 text-xs"
                      />
                      <AmountInput
                        aria-label={t("common.cost")}
                        value={l.unit_cost}
                        onValueChange={(v) => update(l.product_id, { unit_cost: v ?? 0 })}
                        min={0}
                        showInWords={false}
                        hideClear
                        containerClassName="[&_input]:h-7 [&_input]:rounded [&_input]:text-xs"
                      />
                      <QuantityInput
                        aria-label={t("purchases.tax_pct")}
                        value={l.tax_rate}
                        onValueChange={(v) => update(l.product_id, { tax_rate: v ?? 0 })}
                        decimals={2}
                        emptyAsZero
                        min={0}
                        max={100}
                        unit="%"
                        className="h-7 text-xs"
                      />
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>

        <div className="mt-4 grid grid-cols-2 gap-3 border-t border-border pt-3 text-sm">
          <div className="space-y-2">
            {/*
              طريقة دفع المشتريات — المكوّن الموحّد.

              These four hard-coded buttons were a fourth, independent copy of
              the payment-method list. The picker now offers whatever the
              business enabled for purchases, and آجل appears only because the
              catalogue allows it here.
            */}
            <PaymentMethodPicker
              context="purchases"
              value={paymentMethod}
              onChange={(method) => {
                setPaymentMethod(method);
                const definition = getPaymentMethodDefinition(method);
                if (definition?.isCreditTerm) setPaid(0);
              }}
              ensureIds={[paymentMethod]}
              ariaLabel={t("common.method")}
            />
            {!(getPaymentMethodDefinition(paymentMethod)?.isCreditTerm ?? false) && (
              <AmountInput
                value={paid}
                onValueChange={setPaid}
                min={0}
                placeholder={total > 0 ? String(total.toFixed(2)) : undefined}
                containerClassName="[&_input]:h-9 [&_input]:rounded-md [&_input]:bg-surface"
              />
            )}
            <input
              value={note}
              onChange={(e) => setNote(e.target.value)}
              placeholder={t("purchases.note_optional")}
              className="h-9 w-full rounded-md border border-input bg-surface px-2 text-sm"
            />
          </div>
          <div className="space-y-1.5">
            <Row label={t("common.subtotal")} value={money(subtotal)} />
            <Row label={t("common.tax")} value={money(taxTotal)} />
            <div className="flex items-center justify-between gap-2">
              <span className="text-muted-foreground">{t("common.discount")}</span>
              <AmountInput
                value={discount}
                onValueChange={setDiscount}
                min={0}
                showInWords={false}
                containerClassName="w-28 shrink-0 [&_input]:h-7 [&_input]:rounded [&_input]:bg-surface [&_input]:text-xs"
              />
            </div>
            <Row label={t("common.total")} value={money(total)} bold />
            <button
              onClick={submit}
              disabled={loading || cart.length === 0}
              className="mt-1 flex h-10 w-full items-center justify-center gap-2 rounded-md bg-primary text-sm font-semibold text-primary-foreground hover:opacity-90 disabled:opacity-50"
            >
              {loading && <Loader2 className="h-4 w-4 animate-spin" />}
              {t("purchases.save")}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

function Field({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <p className="text-[11px] uppercase tracking-wide text-muted-foreground">{label}</p>
      <p className="capitalize">{value}</p>
    </div>
  );
}
function Row({ label, value, bold }: { label: string; value: string; bold?: boolean }) {
  return (
    <div
      className={`flex items-center justify-between ${bold ? "text-base font-semibold" : "text-muted-foreground"}`}
    >
      <span>{label}</span>
      <span className={bold ? "text-foreground" : ""}>{value}</span>
    </div>
  );
}

import { createFileRoute } from "@tanstack/react-router";
import { useEffect, useMemo, useState } from "react";
import { AlertCircle, RotateCcw, Save } from "lucide-react";
import { PageHeader } from "@/components/page-header";
import { ActionButton } from "@/components/ui/action-button";
import { useI18n } from "@/lib/i18n";
import { useAuth } from "@/lib/auth";
import { SettingsLayout } from "@/components/settings/settings-layout";
import { supabase } from "@/integrations/supabase/client";
import { setCompanySettingsCache } from "@/lib/format";
import { cacheCompanyProfile, COMPANY_SUPPORT_CONTACT_LINE } from "@/lib/printing";

interface SettingsSnapshot {
  form: Record<string, unknown>;
  enablePosServiceFee: boolean;
}

function cloneSnapshot(value: Record<string, unknown>): Record<string, unknown> {
  return JSON.parse(JSON.stringify(value)) as Record<string, unknown>;
}

export const Route = createFileRoute("/_app/settings")({
  head: () => ({ meta: [{ title: "الإعدادات — فورتيكس ERP" }] }),
  /*
   * `?section=` selects which settings screen opens.
   *
   * Without this the route accepted the parameter and silently ignored it, so
   * every settings link in the sidebar (/settings?section=printing, …) landed on
   * the settings hub and the operator had to find the section again by hand.
   * Validating it here means a bad or unknown value degrades to the hub rather
   * than rendering nothing.
   */
  validateSearch: (search: Record<string, unknown>) => ({
    section: typeof search.section === "string" && search.section ? search.section : undefined,
  }),
  component: SettingsPage,
});

function SettingsPage() {
  const { t, lang } = useI18n();
  const { section: sectionFromUrl } = Route.useSearch();
  const { hasRole } = useAuth();
  const canEdit = hasRole("owner") || hasRole("manager");
  const [form, setForm] = useState<any>({
    name: "",
    legal_name: "",
    tax_number: "",
    currency: "YER",
    currency_symbol: "ر.ي",
    tax_rate: 0,
    address: "",
    phone: "",
    email: "",
    invoice_prefix: "INV-",
    purchase_invoice_prefix: "PO-",
    invoice_number_period: "year_month",
    invoice_number_digits: 4,
    logo_url: null,
    barcode_enabled: true,
  });
  const [hasLoadedSettings, setHasLoadedSettings] = useState(false);
  const [saveState, setSaveState] = useState<"idle" | "saving" | "error">("idle");
  const [savedSnapshot, setSavedSnapshot] = useState<SettingsSnapshot | null>(null);

  const [enablePosServiceFee, setEnablePosServiceFee] = useState<boolean>(() => {
    if (typeof window !== "undefined") {
      const saved = localStorage.getItem("pos_enable_service_fee");
      return saved !== null ? saved === "true" : true;
    }
    return true;
  });

  useEffect(() => {
    supabase
      .from("company_settings")
      .select("*")
      .order("id")
      .limit(1)
      .maybeSingle()
      .then(({ data }) => {
        let nextForm: Record<string, unknown> = form;
        let nextServiceFee = enablePosServiceFee;
        if (data) {
          nextForm = data as Record<string, unknown>;
          const catalog = ((data as any).catalog_modules as any) || {};
          if (catalog.enablePosServiceFee !== undefined) {
            nextServiceFee = Boolean(catalog.enablePosServiceFee);
          } else if ((data as any).enable_pos_service_fee !== undefined) {
            nextServiceFee = Boolean((data as any).enable_pos_service_fee);
          }
          setCompanySettingsCache({
            currency: data.currency,
          });
        }
        setForm(nextForm);
        setEnablePosServiceFee(nextServiceFee);
        setSavedSnapshot({
          form: cloneSnapshot(nextForm),
          enablePosServiceFee: nextServiceFee,
        });
        setHasLoadedSettings(true);
      });
  }, []);

  const isDirty = useMemo(() => {
    if (!savedSnapshot) return false;
    return (
      JSON.stringify(form) !== JSON.stringify(savedSnapshot.form) ||
      enablePosServiceFee !== savedSnapshot.enablePosServiceFee
    );
  }, [enablePosServiceFee, form, savedSnapshot]);

  useEffect(() => {
    if (!isDirty) return;
    const preventAccidentalExit = (event: BeforeUnloadEvent) => {
      event.preventDefault();
      event.returnValue = "";
    };
    window.addEventListener("beforeunload", preventAccidentalExit);
    return () => window.removeEventListener("beforeunload", preventAccidentalExit);
  }, [isDirty]);

  const resetChanges = () => {
    if (!savedSnapshot || saveState === "saving") return;
    setForm(cloneSnapshot(savedSnapshot.form));
    setEnablePosServiceFee(savedSnapshot.enablePosServiceFee);
    setSaveState("idle");
  };

  const saveChanges = async () => {
    if (!hasLoadedSettings || !canEdit || !isDirty) return;

    const taxRate = Number(form.tax_rate);
    if (!Number.isFinite(taxRate) || taxRate < 0 || taxRate > 100) {
      setSaveState("error");
      return;
    }

    setSaveState("saving");
    const currentCatalog = (form.catalog_modules as Record<string, unknown>) || {};
    const payload = {
      ...form,
      id: form.id ?? 1,
      tax_rate: taxRate,
      footer_contact: COMPANY_SUPPORT_CONTACT_LINE,
      catalog_modules: { ...currentCatalog, enablePosServiceFee },
    };

    try {
      const result = form.id
        ? await supabase
            .from("company_settings")
            .update(payload)
            .eq("id", payload.id)
            .select()
            .single()
        : await supabase.from("company_settings").insert(payload).select().single();
      if (result.error) {
        setSaveState("error");
        return;
      }

      const persisted = (result.data ?? payload) as Record<string, unknown>;
      if (typeof window !== "undefined") {
        localStorage.setItem("pos_enable_service_fee", String(enablePosServiceFee));
      }
      cacheCompanyProfile(persisted);
      setCompanySettingsCache({ currency: String(persisted.currency ?? "YER") });
      setForm(persisted);
      setSavedSnapshot({
        form: cloneSnapshot(persisted),
        enablePosServiceFee,
      });
      setSaveState("idle");
    } catch {
      setSaveState("error");
    }
  };

  return (
    <div className="space-y-6 pb-10">
      {canEdit && hasLoadedSettings && isDirty && (
        <div
          className="sticky top-2 z-30 flex w-fit max-w-full items-center justify-start gap-1.5 rounded-2xl border border-border/70 bg-card/95 p-1.5 shadow-lg backdrop-blur-md"
          role="status"
          aria-live="polite"
        >
          {saveState === "error" ? (
            <span className="flex max-w-48 items-center gap-1 px-1 text-[11px] font-medium text-destructive">
              <AlertCircle className="size-3.5 shrink-0" />
              {lang === "ar" ? "تعذر الحفظ" : "Could not save"}
            </span>
          ) : null}
          <ActionButton
            size="sm"
            tone="ghost"
            icon={<RotateCcw />}
            onClick={resetChanges}
            disabled={saveState === "saving"}
          >
            {lang === "ar" ? "تراجع" : "Discard"}
          </ActionButton>
          <ActionButton
            size="sm"
            icon={<Save />}
            onClick={saveChanges}
            loading={saveState === "saving"}
          >
            {lang === "ar" ? "حفظ" : "Save"}
          </ActionButton>
        </div>
      )}

      <PageHeader
        title={t("settings.title")}
        subtitle={
          lang === "ar"
            ? "إدارة إعدادات النظام الموجودة: المنشأة، المبيعات، الطباعة، النشاط، الباقة، النسخ الاحتياطي، الأرقام، والمظهر"
            : "Manage company, sales, printing, catalog, plan, backup, numbers, and appearance settings"
        }
      />

      <SettingsLayout
        form={form}
        setForm={setForm}
        enablePosServiceFee={enablePosServiceFee}
        setEnablePosServiceFee={setEnablePosServiceFee}
        printMode={"ask" as any}
        setPrintMode={() => {}}
        defaultPrintTemplate={undefined}
        setDefaultPrintTemplate={() => {}}
        canEdit={canEdit}
        lang={lang}
        initialSectionId={sectionFromUrl}
      />
    </div>
  );
}

