function formatArabicDateTime(dateStr: string): string {
  try {
    const d = new Date(dateStr);
    const datePart = d.toLocaleDateString("ar-EG", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
    const timePart = d.toLocaleTimeString("ar-EG", {
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hour12: true,
    });
    return `${datePart} — ${timePart}`;
  } catch {
    return dateStr;
  }
}

function SettlementsPage() {
  const { lang } = useI18n();
  const isRtl = lang === "ar";
  const { hasRole, user, isPlatformAdmin, isPlatformSuperadmin } = useAuth();
  const queryClient = useQueryClient();
  const breakpoint = useBreakpoint();
  const tableUsesHorizontalScroll =
    breakpoint === "xs" || breakpoint === "sm" || breakpoint === "md";
  const canManageSettlement =
    hasRole("owner") ||
    hasRole("manager") ||
    hasRole("warehouse") ||
    hasRole("accountant") ||
    isPlatformAdmin ||
    isPlatformSuperadmin;

  const [query, setQuery] = useState("");
  const [filters, setFilters] = useState<FilterValues>({});
  const [sortKey, setSortKey] = useState<string>("date_desc");
  const [sort, setSort] = useState<DataTableSort | null>(null);
  const [viewMode, setViewMode] = usePersistedViewMode("settlements", "cards");
  const [isAdjustmentOpen, setIsAdjustmentOpen] = useState(false);
  const [selectedMovement, setSelectedMovement] = useState<SettlementRow | null>(null);

  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if (e.key === "Escape" && selectedMovement) {
        setSelectedMovement(null);
      }
    }
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [selectedMovement]);

  // اشتراك لحظي في أي حركة مخزون جديدة أو معدلة
  useRealtimeTable<SettlementRow>(
    { table: "stock_movements", queryKey: QUERY_KEYS.settlements, debounceMs: 150 },
    queryClient,
  );

  const { data, isLoading, isFetching, error, refetch } = useQuery({
    queryKey: QUERY_KEYS.settlements,
    queryFn: async (): Promise<SettlementRow[]> => {
      // جلب كافة حركات المخزون بلا استثناء (تسويات، مشتريات، مبيعات، تحويلات، رصيد أول مدة، إنتاج)
      const { data, error } = await supabase
        .from("stock_movements")
        .select(
          "id, movement_type, quantity, note, created_at, product_id, warehouse_id, created_by, unit_cost, reference, reference_type, products(id,name,name_ar,sku), warehouses(id,name,name_ar,code)",
        )
        .order("created_at", { ascending: false })
        .limit(300);
      if (error) throw error;

      const rows = data ?? [];

      // لا توجد علاقة مباشرة بين stock_movements و profiles،
      // لذا نجلب أسماء المستخدمين بطلب منفصل ونطابقها عبر created_by.
      const creatorIds = Array.from(
        new Set(rows.map((row) => row.created_by).filter((id): id is string => Boolean(id))),
      );
      let profilesByUser: Record<string, { full_name: string | null }> = {};
      if (creatorIds.length > 0) {
        const { data: profiles, error: profilesError } = await supabase
          .from("profiles")
          .select("id, full_name")
          .in("id", creatorIds);
        if (!profilesError && profiles) {
          profilesByUser = Object.fromEntries(
            profiles.map((profile) => [profile.id, { full_name: profile.full_name }]),
          );
        }
      }

      return rows.map((row) => ({
        ...row,
        profiles: row.created_by ? (profilesByUser[row.created_by] ?? null) : null,
      }));
    },
    enabled: canManageSettlement,
  });

  const productLabel = useCallback(
    (row: SettlementRow) =>
      isRtl
        ? row.products?.name_ar || row.products?.name
        : row.products?.name || row.products?.name_ar,
    [isRtl],
  );
  const warehouseLabel = useCallback(
    (row: SettlementRow) =>
      isRtl
        ? row.warehouses?.name_ar || row.warehouses?.name
        : row.warehouses?.name || row.warehouses?.name_ar,
    [isRtl],
  );

  const movementLabel = useCallback(
    (type: string) => {
      const map: Record<string, { ar: string; en: string }> = {
        adjustment: { ar: "تسوية جردية", en: "Stock adjustment" },
        opening: { ar: "رصيد أول المدة", en: "Opening stock" },
        purchase: { ar: "شراء / توريد", en: "Purchase / Stock in" },
        sale: { ar: "بيع / صرف", en: "Sale / Stock out" },
        transfer_in: { ar: "تحويل وارد", en: "Transfer in" },
        transfer_out: { ar: "تحويل صادر", en: "Transfer out" },
        return_in: { ar: "مرتجع وارد", en: "Return in" },
        return_out: { ar: "مرتجع صادر", en: "Return out" },
        purchase_return: { ar: "مرتجع مشتريات", en: "Purchase return" },
        sale_return: { ar: "مرتجع مبيعات", en: "Sales return" },
        production_in: { ar: "ناتج إنتاج", en: "Production output" },
        production_out: { ar: "صرف إنتاج", en: "Production issue" },
      };
      const entry = map[type];
      return entry ? (isRtl ? entry.ar : entry.en) : type;
    },
    [isRtl],
  );

  const sourceLabel = useCallback(
    (type: string | null) => {
      const map: Record<string, { ar: string; en: string }> = {
        purchase: { ar: "فاتورة شراء", en: "Purchase invoice" },
        stock_opening: { ar: "مستند رصيد أول المدة", en: "Opening-stock document" },
        stock_adjustment: { ar: "مستند تسوية مخزون", en: "Stock-adjustment document" },
        sales_invoice: { ar: "فاتورة بيع", en: "Sales invoice" },
        stock_transfer: { ar: "تحويل مخزون", en: "Stock transfer" },
        direct_stock_in: { ar: "توريد مخزني مباشر", en: "Direct stock-in" },
        production: { ar: "أمر تشغيل إنتاج", en: "Production order" },
      };
      if (!type) return "—";
      const entry = map[type];
      return entry ? (isRtl ? entry.ar : entry.en) : type;
    },
    [isRtl],
  );

  /* ---------------- search + filter ---------------- */
  const searched = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return data ?? [];
    return (data ?? []).filter((row) => {
      const productText =
        `${row.products?.name ?? ""} ${row.products?.name_ar ?? ""} ${row.products?.sku ?? ""}`.toLowerCase();
      const warehouseText =
        `${row.warehouses?.name ?? ""} ${row.warehouses?.name_ar ?? ""}`.toLowerCase();
      const userText = row.profiles?.full_name?.toLowerCase() ?? "";
      return (
        productText.includes(q) ||
        warehouseText.includes(q) ||
        userText.includes(q) ||
        (row.note ?? "").toLowerCase().includes(q)
      );
    });
  }, [data, query]);

  const filterDefinitions: FilterDefinition[] = useMemo(() => {
    const rows = data ?? [];
    const defs: FilterDefinition[] = [];
    const typeOptions = Array.from(new Set(rows.map((r) => r.movement_type))).map((value) => ({
      value,
      label: movementLabel(value),
    }));
    if (typeOptions.length) {
      defs.push({
        key: "movement_type",
        label: isRtl ? "نوع الحركة" : "Movement type",
        type: "select",
        options: typeOptions,
      });
    }
    const whOptions = Array.from(
      new Map(
        rows
          .filter((r) => r.warehouse_id)
          .map((r) => [r.warehouse_id, { value: r.warehouse_id, label: warehouseLabel(r) ?? "—" }]),
      ).values(),
    );
    if (whOptions.length) {
      defs.push({
        key: "warehouse_id",
        label: isRtl ? "المستودع" : "Warehouse",
        type: "select",
        options: whOptions,
      });
    }
    const userOptions = Array.from(
      new Map(
        rows
          .filter((r) => r.created_by && r.profiles?.full_name)
          .map((r) => [
            r.created_by as string,
            { value: r.created_by as string, label: r.profiles?.full_name ?? "" },
          ]),
      ).values(),
    );
    if (userOptions.length) {
      defs.push({
        key: "created_by",
        label: isRtl ? "المستخدم" : "User",
        type: "select",
        options: userOptions,
      });
    }
    defs.push({ key: "created_at", label: isRtl ? "التاريخ" : "Date", type: "date-range" });
    return defs;
  }, [data, isRtl, movementLabel, warehouseLabel]);

  const filtered = useMemo(() => {
    return searched.filter((row) => {
      if (filters.movement_type && row.movement_type !== filters.movement_type) return false;
      if (filters.warehouse_id && row.warehouse_id !== filters.warehouse_id) return false;
      if (filters.created_by && row.created_by !== filters.created_by) return false;
      if (filters.created_at && typeof filters.created_at === "object") {
        const rowTime = new Date(row.created_at).getTime();
        if (filters.created_at.from && rowTime < new Date(filters.created_at.from).getTime())
          return false;
        if (filters.created_at.to) {
          const to = new Date(filters.created_at.to);
          to.setHours(23, 59, 59, 999);
          if (rowTime > to.getTime()) return false;
        }
      }
      return true;
    });
  }, [searched, filters]);

  /* ---------------- KPI ---------------- */
  const kpi = useMemo(() => {
    const rows = data ?? [];
    let additions = 0;
    let deductions = 0;
    for (const row of rows) {
      if (Number(row.quantity) >= 0) additions++;
      else deductions++;
    }
    return { total: rows.length, additions, deductions };
  }, [data]);

  /* ---------------- sort ---------------- */
  const sortOptions: SortOption[] = useMemo(
    () => [
      { value: "date_desc", label: isRtl ? "الأحدث أولاً" : "Newest first" },
      { value: "date_asc", label: isRtl ? "الأقدم أولاً" : "Oldest first" },
      { value: "qty_desc", label: isRtl ? "الكمية (الأعلى)" : "Quantity (high)" },
      { value: "qty_asc", label: isRtl ? "الكمية (الأقل)" : "Quantity (low)" },
      { value: "type", label: isRtl ? "نوع الحركة" : "Movement type" },
    ],
    [isRtl],
  );

  const sortedRows = useMemo(() => {
    const list = [...filtered];
    if (sort) {
      const dir = sort.direction === "asc" ? 1 : -1;
      switch (sort.key) {
        case "quantity":
          return list.sort((a, b) => (Number(a.quantity) - Number(b.quantity)) * dir);
        case "type":
          return list.sort((a, b) => a.movement_type.localeCompare(b.movement_type) * dir);
        case "date":
          return list.sort(
            (a, b) => (new Date(a.created_at).getTime() - new Date(b.created_at).getTime()) * dir,
          );
        default:
          break;
      }
    }
    switch (sortKey) {
      case "date_asc":
        return list.sort(
          (a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime(),
        );
      case "qty_desc":
        return list.sort((a, b) => Number(b.quantity) - Number(a.quantity));
      case "qty_asc":
        return list.sort((a, b) => Number(a.quantity) - Number(b.quantity));
      case "type":
        return list.sort((a, b) => a.movement_type.localeCompare(b.movement_type));
      default:
        return list.sort(
          (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
        );
    }
  }, [filtered, sort, sortKey]);

  /* ---------------- classic table columns ---------------- */
  const columns = useMemo<DataTableColumn<SettlementRow>[]>(() => {
    const cols: DataTableColumn<SettlementRow>[] = [
      {
        key: "product",
        header: isRtl ? "المنتج" : "Product",
        width: "w-[240px]",
        cell: (row) => (
          <div className="py-0.5">
            <div className="truncate font-medium text-foreground">{productLabel(row) ?? "—"}</div>
            <div className="font-mono text-[11px] text-muted-foreground">
              {row.products?.sku ?? "—"}
            </div>
          </div>
        ),
      },
      {
        key: "warehouse",
        header: isRtl ? "المستودع" : "Warehouse",
        width: "w-[180px]",
        cell: (row) => (
          <div className="flex items-center gap-2 text-muted-foreground">
            <Warehouse className="h-3.5 w-3.5" />
            <span>{warehouseLabel(row) ?? "—"}</span>
          </div>
        ),
      },
      {
        key: "type",
        header: isRtl ? "النوع" : "Type",
        sortable: true,
        width: "w-[150px]",
        sortValue: (row) => row.movement_type,
        cell: (row) => {
          const isPositive = Number(row.quantity) >= 0;
          return (
            <span
              className={`inline-flex whitespace-nowrap rounded-full border px-2 py-0.5 text-[10px] ${isPositive ? "border-emerald-500/25 bg-emerald-500/10 text-emerald-600 dark:text-emerald-300" : "border-rose-500/25 bg-rose-500/10 text-rose-600 dark:text-rose-300"}`}
            >
              {movementLabel(row.movement_type)}
            </span>
          );
        },
      },
      {
        key: "source",
        header: isRtl ? "المستند المصدر" : "Source document",
        width: "w-[170px]",
        cell: (row) => (
          <span className="text-[11px] text-muted-foreground">
            {sourceLabel(row.reference_type)}
          </span>
        ),
      },
      {
        key: "quantity",
        header: isRtl ? "الكمية" : "Qty",
        sortable: true,
        align: "end",
        width: "w-[120px]",
        sortValue: (row) => Number(row.quantity),
        cell: (row) => <span className="font-mono text-foreground">{formatQty(row.quantity)}</span>,
      },
      {
        key: "reason",
        header: isRtl ? "السبب" : "Reason",
        width: "w-[220px]",
        cell: (row) => (
          <span className="block truncate text-muted-foreground">
            {row.note || row.reference || (isRtl ? "بدون سبب" : "No note")}
          </span>
        ),
      },
      {
        key: "user",
        header: isRtl ? "المستخدم" : "User",
        width: "w-[160px]",
        cell: (row) => (
          <span className="text-muted-foreground">
            {row.profiles?.full_name ?? user?.email ?? (isRtl ? "غير معروف" : "Unknown")}
          </span>
        ),
      },
      {
        key: "date",
        header: isRtl ? "التاريخ/الوقت" : "Date & time",
        sortable: true,
        width: "w-[180px]",
        sortValue: (row) => new Date(row.created_at).getTime(),
        cell: (row) => (
          <span className="text-muted-foreground">{new Date(row.created_at).toLocaleString()}</span>
        ),
      },
      {
        key: "actions",
        header: isRtl ? "معاينة" : "View",
        width: "w-[70px]",
        align: "center",
        cell: (row) => (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              setSelectedMovement(row);
            }}
            className="grid size-7 place-items-center rounded-lg border border-border/70 bg-surface hover:bg-primary hover:border-primary hover:text-primary-foreground text-muted-foreground transition shadow-2xs mx-auto"
            title="عرض تفاصيل الحركة"
          >
            <Eye className="size-3.5" />
          </button>
        ),
      },
    ];
    return cols;
  }, [isRtl, productLabel, warehouseLabel, movementLabel, sourceLabel, user?.email]);

  const rendererProps = (row: SettlementRow) => ({
    row,
    isRtl,
    productName: productLabel(row) ?? "—",
    warehouseName: warehouseLabel(row) ?? "—",
    movementName: movementLabel(row.movement_type),
    sourceName: sourceLabel(row.reference_type),
    userName: row.profiles?.full_name ?? user?.email ?? (isRtl ? "غير معروف" : "Unknown"),
    onViewDetails: () => setSelectedMovement(row),
  });

  const hasActiveCriteria = Boolean(query.trim()) || Object.keys(filters).length > 0;

  if (!canManageSettlement) {
    return (
      <div className="panel-elevated rounded-3xl border border-border/80 bg-surface/90 p-8 text-center">
        <ShieldCheck className="mx-auto mb-3 h-10 w-10 text-muted-foreground" />
        <h3 className="text-lg font-semibold text-foreground">
          {isRtl ? "لا توجد صلاحية لعرض حركات المخزون" : "Stock movements access denied"}
        </h3>
        <p className="mt-2 text-sm text-muted-foreground">
          {isRtl
            ? "يحتاج المستخدم إلى صلاحية المخزون أو الإدارة لمشاهدة سجل حركات المخزون."
            : "Inventory or admin access is required to view stock movement records."}
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-4 pb-12">
      <PageHeader
        title={isRtl ? "حركة المخزون" : "Stock Movements"}
        subtitle={
          isRtl
            ? "سجل كامل لكافة حركات وتوريدات وصرف وتسويات المخزون"
            : "Complete log of all stock movements, receipts, issues, and adjustments"
        }
        guide={settlementGuideConfig}
      />

      {/* ─── KPI cards ─── */}
      <div className="grid grid-cols-2 gap-3 sm:gap-4 lg:grid-cols-4">
        <VortexMetricCard
          title={isRtl ? "إجمالي الحركات" : "Total movements"}
          value={kpi.total}
          subtitle={isRtl ? "المحمّلة حالياً" : "Currently loaded"}
          icon={<ClipboardList className="size-5" />}
          tone="info"
        />
        <VortexMetricCard
          title={isRtl ? "إضافات (فائض/توريد)" : "Additions (receipts)"}
          value={kpi.additions}
          subtitle={isRtl ? "حركات موجبة" : "Positive movements"}
          icon={<TrendingUp className="size-5" />}
          tone="success"
        />
        <VortexMetricCard
          title={isRtl ? "خصومات (صرف/عجز)" : "Deductions (issues)"}
          value={kpi.deductions}
          subtitle={isRtl ? "حركات سالبة" : "Negative movements"}
          icon={<TrendingDown className="size-5" />}
          tone="danger"
        />
        <VortexMetricCard
          title={isRtl ? "النتائج المطابقة" : "Matching results"}
          value={filtered.length}
          subtitle={isRtl ? "بعد البحث والفلترة" : "After search & filters"}
          icon={<Boxes className="size-5" />}
          tone="default"
        />
      </div>

      {/* ─── Standard VORTEX TableToolbar ─── */}
      <TableToolbar
        sticky
        lang={lang}
        search={{
          value: query,
          onValueChange: setQuery,
          placeholder: isRtl
            ? "بحث في المنتج أو المستودع أو المستخدم أو السبب"
            : "Search product, warehouse, user or reason",
          resultCount: filtered.length,
          loading: isFetching && !isLoading,
        }}
        filters={{ definitions: filterDefinitions, values: filters, onValueChange: setFilters }}
        sort={{
          options: sortOptions,
          value: sortKey,
          onValueChange: (value) => {
            setSortKey(value);
            setSort(null);
          },
          label: isRtl ? "ترتيب" : "Sort",
        }}
        viewToggle={<RecordsViewToggle value={viewMode} onChange={setViewMode} />}
        action={
          <PrimaryAction
            label={isRtl ? "تسوية مخزون" : "Stock adjustment"}
            icon={<Plus />}
            onClick={() => setIsAdjustmentOpen(true)}
          />
        }
      />

      {/* ─── Records: cards / list / classic table — shared scaffold ─── */}
      <RecordsView<SettlementRow>
        rows={sortedRows}
        getRowId={(row) => row.id}
        viewMode={viewMode}
        loading={isLoading}
        refreshing={isFetching && !isLoading}
        error={error}
        onRetry={() => void refetch()}
        columns={columns}
        sort={sort}
        onSortChange={setSort}
        minWidth={1180}
        horizontalScroll={tableUsesHorizontalScroll}
        renderCard={(row) => <SettlementCard {...rendererProps(row)} />}
        renderListRow={(row) => <SettlementListRow {...rendererProps(row)} />}
        empty={{
          icon: <ClipboardList />,
          title: hasActiveCriteria
            ? isRtl
              ? "لا توجد حركات مطابقة"
              : "No matching movements"
            : isRtl
              ? "لا توجد حركات مخزون بعد"
              : "No stock movements yet",
          description: hasActiveCriteria
            ? isRtl
              ? "جرّب تعديل البحث أو الفلاتر."
              : "Try adjusting your search or filters."
            : isRtl
              ? "سجل أول حركة أو تسوية مخزنية لتظهر هنا."
              : "Record a stock movement or adjustment to see it here.",
        }}
      />

      {isAdjustmentOpen && (
        <StockAdjustmentDialog
          onClose={() => setIsAdjustmentOpen(false)}
          onSaved={() => {
            setIsAdjustmentOpen(false);
            queryClient.invalidateQueries({ queryKey: QUERY_KEYS.settlements });
            queryClient.invalidateQueries({ queryKey: ["inventory"] });
          }}
        />
      )}

      {/* ─── نافذة تفاصيل حركة المخزون من اليمين (مستوحاة من شاشة العملاء) ─── */}
      {selectedMovement && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-end bg-black/65 backdrop-blur-xs animate-in fade-in duration-200"
          onClick={() => setSelectedMovement(null)}
        >
          <div
            className="relative h-full w-full max-w-lg border-s border-border/80 bg-background/95 backdrop-blur-md p-6 shadow-2xl overflow-y-auto animate-in slide-in-from-right duration-200"
            onClick={(e) => e.stopPropagation()}
            dir="rtl"
          >
            {/* إضاءة جمالية في خلفية النافذة */}
            <div className="absolute -top-10 -right-10 size-40 rounded-full bg-primary/20 blur-3xl pointer-events-none" />

            {/* ترويسة النافذة مع زر الإغلاق */}
            <div className="flex items-start justify-between pb-4 border-b border-border/60">
              <div className="flex items-center gap-3.5">
                <div
                  className={`grid size-14 place-items-center rounded-2xl border text-xl font-bold shadow-sm ${
                    Number(selectedMovement.quantity) >= 0
                      ? "bg-emerald-500/10 border-emerald-500/30 text-emerald-500"
                      : "bg-rose-500/10 border-rose-500/30 text-rose-500"
                  }`}
                >
                  {Number(selectedMovement.quantity) >= 0 ? (
                    <TrendingUp className="size-6" />
                  ) : (
                    <TrendingDown className="size-6" />
                  )}
                </div>
                <div>
                  <h3 className="text-lg font-bold text-foreground">
                    {selectedMovement.products?.name_ar ||
                      selectedMovement.products?.name ||
                      "صنف مخزني"}
                  </h3>
                  <div className="mt-1 flex items-center gap-2">
                    <span
                      className={`inline-flex rounded-full border px-2.5 py-0.5 text-[11px] font-bold ${
                        Number(selectedMovement.quantity) >= 0
                          ? "border-emerald-500/25 bg-emerald-500/10 text-emerald-600 dark:text-emerald-400"
                          : "border-rose-500/25 bg-rose-500/10 text-rose-600 dark:text-rose-400"
                      }`}
                    >
                      {getArabicMovementLabel(selectedMovement.movement_type)}
                    </span>
                    {selectedMovement.products?.sku && (
                      <span className="font-mono text-xs text-muted-foreground bg-muted/60 px-2 py-0.5 rounded-md">
                        {selectedMovement.products.sku}
                      </span>
                    )}
                  </div>
                </div>
              </div>
              <button
                onClick={() => setSelectedMovement(null)}
                className="grid size-9 place-items-center rounded-full bg-surface-2 text-muted-foreground hover:text-foreground transition"
                title="إغلاق النافذة"
              >
                <X className="size-4" />
              </button>
            </div>

            {/* بطاقات المؤشرات السريعة */}
            <div className="mt-5 grid grid-cols-2 gap-3">
              <div className="rounded-xl border border-border/70 bg-surface/60 p-3.5">
                <div className="text-xs text-muted-foreground font-medium">كمية الحركة</div>
                <div
                  className={`mt-1 font-mono text-xl font-bold ${
                    Number(selectedMovement.quantity) >= 0
                      ? "text-emerald-500"
                      : "text-rose-500"
                  }`}
                >
                  {Number(selectedMovement.quantity) >= 0
                    ? `+${formatQty(selectedMovement.quantity)}`
                    : formatQty(selectedMovement.quantity)}
                </div>
              </div>

              <div className="rounded-xl border border-border/70 bg-surface/60 p-3.5">
                <div className="text-xs text-muted-foreground font-medium">الأثر المخزني</div>
                <div className="mt-1.5 text-xs font-bold text-foreground flex items-center gap-1.5">
                  <span
                    className={`size-2 rounded-full ${
                      Number(selectedMovement.quantity) >= 0
                        ? "bg-emerald-500"
                        : "bg-rose-500"
                    }`}
                  />
                  <span>
                    {Number(selectedMovement.quantity) >= 0
                      ? "إضافة إلى رصيد المستودع"
                      : "خصم من رصيد المستودع"}
                  </span>
                </div>
              </div>

              {selectedMovement.unit_cost != null && (
                <>
                  <div className="rounded-xl border border-border/70 bg-surface/60 p-3.5">
                    <div className="text-xs text-muted-foreground font-medium">سعر تكلفة الوحدة</div>
                    <div className="mt-1 font-mono text-base font-bold text-foreground">
                      {money(Number(selectedMovement.unit_cost))}
                    </div>
                  </div>

                  <div className="rounded-xl border border-border/70 bg-surface/60 p-3.5">
                    <div className="text-xs text-muted-foreground font-medium">إجمالي قيمة الحركة</div>
                    <div className="mt-1 font-mono text-base font-bold text-primary">
                      {money(
                        Math.abs(
                          Number(selectedMovement.quantity) * Number(selectedMovement.unit_cost),
                        ),
                      )}
                    </div>
                  </div>
                </>
              )}
            </div>

            {/* تفاصيل السجل المخزني الكاملة باللغة العربية حصراً */}
            <div className="mt-6 space-y-3">
              <h4 className="text-xs font-bold uppercase tracking-wider text-muted-foreground">
                البيانات التفصيلية للحركة
              </h4>

              <div className="divide-y divide-border/60 rounded-2xl border border-border/70 bg-surface/50 text-xs overflow-hidden">
