interface PartyOption {
  id: string;
  name: string;
  phone?: string | null;
  balance?: number;
}

function periodPresets() {
  const today = new Date();
  const iso = (d: Date) => d.toISOString().slice(0, 10);
  const startOfMonth = new Date(today.getFullYear(), today.getMonth(), 1);
  const startOfYear = new Date(today.getFullYear(), 0, 1);
  const daysAgo = (n: number) => {
    const d = new Date(today);
    d.setDate(d.getDate() - n);
    return d;
  };
  return [
    { key: "all", ar: "الكل", en: "All", from: "", to: "" },
    { key: "m30", ar: "30 يوم", en: "30d", from: iso(daysAgo(30)), to: iso(today) },
    { key: "m90", ar: "90 يوم", en: "90d", from: iso(daysAgo(90)), to: iso(today) },
    { key: "ytd", ar: "هذه السنة", en: "YTD", from: iso(startOfYear), to: iso(today) },
    { key: "month", ar: "هذا الشهر", en: "This month", from: iso(startOfMonth), to: iso(today) },
  ];
}

export function StatementPage() {
  const { t, lang } = useI18n();
  const ar = lang === "ar";
  const searchParams = Route.useSearch();
  const { entityType: partyType } = Route.useParams();
  const { settings } = useStatementSettings();
  const savedPreferences = useMemo(() => getReportPreferences(), []);

  // مسار كل نوع كشف هو مصدر الحقيقة؛ لا تختلط الأنواع في شاشة واحدة.
  const [partyId, setPartyId] = useState<string>(
    searchParams.entityId ?? searchParams.customerId ?? savedPreferences.entityId ?? "",
  );
  const [partyList, setPartyList] = useState<PartyOption[]>([]);
  const [loadingParties, setLoadingParties] = useState(false);
  const [detailEntry, setDetailEntry] = useState<StatementTransaction | null>(null);
  const [shareOpen, setShareOpen] = useState(false);
  const [customerFormOpen, setCustomerFormOpen] = useState(false);
  const [supplierFormOpen, setSupplierFormOpen] = useState(false);

  // ── البحث والفرز في جدول كشف الحساب ──
  const [tableSearch, setTableSearch] = useState("");
  const [sortField, setSortField] = useState<"date" | "debit" | "credit" | "balance">("date");
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("desc");
  const [sortMenuOpen, setSortMenuOpen] = useState(false);

  // ── خيارات الفلترة والفترة ──
  const [from, setFrom] = useState(savedPreferences.from);
  const [to, setTo] = useState(savedPreferences.to);
  const [activePreset, setActivePreset] = useState(savedPreferences.preset);
  const [includeZero, setIncludeZero] = useState(
    savedPreferences.includeZeroRows || settings.includeZeroRowsDefault,
  );
  const [visibleColumns, setVisibleColumns] = useState<Record<StatementFieldKey, boolean>>({
    index: true,
    date: true,
    reference: true,
    kind: true,
    description: true,
    debit: true,
    credit: true,
    balance: true,
    paymentMethod: true,
    ...savedPreferences.visibleColumns,
  });

  useEffect(() => {
    saveReportPreferences({
      reportType: reportTypeForEntity(partyType),
      entityType: partyType,
      entityId: partyId,
      from,
      to,
      preset: activePreset,
      includeZeroRows: includeZero,
      visibleColumns,
    });
  }, [partyType, partyId, from, to, activePreset, includeZero, visibleColumns]);

  // جلب أطراف الحسابات
  useEffect(() => {
    let cancelled = false;

    async function loadParties() {
      if (partyType === "cash") {
        setPartyList([]);
        setPartyId(CASH_ENTITY_ID);
        return;
      }

      setLoadingParties(true);
      setPartyId("");
      setDetailEntry(null);
      const table = partyType === "customer" ? "customers" : "suppliers";
      const { data } = await supabase
        .from(table)
        .select("id, name, phone, balance")
        .eq("is_active", true)
        .order("name")
        .limit(1000);

      if (cancelled) return;
      const list = (data ?? []) as PartyOption[];
      setPartyList(list);
      setLoadingParties(false);

      const deepLink =
        partyType === "customer"
          ? (searchParams.customerId ?? searchParams.entityId)
          : searchParams.entityId;
      if (deepLink && list.some((p) => p.id === deepLink)) setPartyId(deepLink);
      else if (list.length > 0) setPartyId(list[0].id);
    }

    void loadParties();
    return () => {
      cancelled = true;
    };
  }, [partyType]);

  // استدعاء محرك كشف الحساب
  const { result, layout, company, isLoading, hasSourceData, derived, refetch } = useStatement({
    entityType: partyType,
    entityId: partyId,
    from: from || null,
    to: to || null,
    includeZeroRows: includeZero,
    enabled: Boolean(partyId),
  });

  const currencySymbol = useMemo(
    () =>
      resolveCurrencySymbol(
        settings.currencySymbolOverride,
        company?.currencySymbol ?? DEFAULT_COMPANY_INFO.currencySymbol,
      ),
    [settings.currencySymbolOverride, company?.currencySymbol],
  );

  const totalDebit = result?.totalDebit ?? 0;
  const totalCredit = result?.totalCredit ?? 0;
  const closingBalance = result?.closingBalance ?? 0;
  const rawRows = result?.transactions ?? [];

  // تصفية وفرز الحركات
  const statementRows = useMemo(() => {
    let rows = [...rawRows];

    if (tableSearch.trim()) {
      const q = tableSearch.toLowerCase().trim();
      rows = rows.filter((r) => {
        const ref = (r.reference || "").toLowerCase();
        const desc = (r.description || "").toLowerCase();
        const kind = kindLabel(r.kind, partyType, lang).toLowerCase();
        const pm = String(r.meta?.paymentMethod ?? "").toLowerCase();
        const deb = String(r.debit ?? "");
        const cred = String(r.credit ?? "");
        return (
          ref.includes(q) ||
          desc.includes(q) ||
          kind.includes(q) ||
          pm.includes(q) ||
          deb.includes(q) ||
          cred.includes(q)
        );
      });
    }

    rows.sort((a, b) => {
      if (sortField === "date") {
        const t1 = new Date(a.occurredAt).getTime();
        const t2 = new Date(b.occurredAt).getTime();
        return sortDirection === "asc" ? t1 - t2 : t2 - t1;
      }
      if (sortField === "debit") {
        const v1 = a.debit ?? 0;
        const v2 = b.debit ?? 0;
        return sortDirection === "asc" ? v1 - v2 : v2 - v1;
      }
      if (sortField === "credit") {
        const v1 = a.credit ?? 0;
        const v2 = b.credit ?? 0;
        return sortDirection === "asc" ? v1 - v2 : v2 - v1;
      }
      if (sortField === "balance") {
        return sortDirection === "asc"
          ? a.runningBalance - b.runningBalance
          : b.runningBalance - a.runningBalance;
      }
      return 0;
    });

    return rows;
  }, [rawRows, tableSearch, sortField, sortDirection, partyType, lang]);

  const toggleSort = (field: "date" | "debit" | "credit" | "balance") => {
    if (sortField === field) {
      setSortDirection(sortDirection === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortDirection("desc");
    }
  };

  const filterPresets: ReportFilterPreset[] = periodPresets().map((preset) => ({
    key: preset.key,
    label: ar ? preset.ar : preset.en,
    from: preset.from,
    to: preset.to,
  }));

  const filterValues: ReportFilterValues = {
    from,
    to,
    preset: activePreset,
    includeZeroRows: includeZero,
  };

  function updateFilterValues(next: ReportFilterValues) {
    setActivePreset(next.preset);
    setFrom(next.from);
    setTo(next.to);
    setIncludeZero(next.includeZeroRows);
  }

  function resetOptions() {
    setActivePreset("all");
    setFrom("");
    setTo("");
    setIncludeZero(settings.includeZeroRowsDefault);
  }

  function handlePrintPDF() {
    if (!result || !layout || !company) return;
    printStatementDocument({
      result,
      layout,
      lang,
      currencySymbol,
      company: company as StatementCompanyInfo,
      includeOpeningRow: layout.showOpeningRow,
    });
  }

  function handleExportCsv() {
    if (!result || !layout) return;
    exportStatementToCsv({
      result,
      layout,
      lang,
      filename: statementFilename(result, lang),
      currencySymbol,
    });
    toast.success(ar ? "تم تصدير الملف (CSV)" : "File exported (CSV)");
  }

  const activeParty = useMemo(
    () => partyList.find((p) => p.id === partyId) ?? null,
    [partyList, partyId],
  );

  const shareContext = useMemo(() => {
    if (!result) return null;
    return statementToContext(result);
  }, [result]);

  function handleShareStatement() {
    if (!result) return;
    if (partyType === "cash") {
      toast.info(
        ar
          ? "مشاركة كشف الصندوق غير متاحة — اختر حساب عميل أو مورد."
          : "Treasury statement sharing is not available — select a customer or supplier.",
      );
      return;
    }
    if (statementRows.length === 0) {
      toast.warning(
        ar
          ? "لا توجد أي حركات مالية في هذه الفترة لمشاركتها"
          : "No transactions in this period to share",
      );
      return;
    }
    setShareOpen(true);
  }

  const alignClass = (align: "start" | "center" | "end") =>
    align === "end" ? "text-end" : align === "center" ? "text-center" : "text-start";

  const columns = (layout?.columns ?? []).filter((column) => visibleColumns[column.key]);
  const columnOptions = (layout?.columns ?? []).map((column) => ({
    key: column.key,
    label: column.label,
  }));

  const renderCell = (row: StatementTransaction, key: StatementFieldKey): React.ReactNode => {
    switch (key) {
      case "index":
        return <Ltr className="font-mono text-xs text-muted-foreground">{row.index}</Ltr>;
      case "date":
        return <VortexDateBadge date={row.occurredAt} size="sm" showWeekday={false} />;
      case "kind":
        return (
          <span className="text-xs font-semibold">{kindLabel(row.kind, partyType, lang)}</span>
        );
      case "reference":
        return (
          <Ltr className="font-mono text-xs text-primary font-medium">{row.reference ?? "—"}</Ltr>
        );
      case "description":
        return <span className="text-xs text-muted-foreground">{row.description ?? "—"}</span>;
      case "debit":
        return <Ltr className="font-mono text-rose-500 font-bold">{fmtOrDash(row.debit)}</Ltr>;
      case "credit":
        return <Ltr className="font-mono text-emerald-500 font-bold">{fmtOrDash(row.credit)}</Ltr>;
      case "balance":
        return (
          <Ltr className="font-mono font-bold text-foreground">{fmtAmount(row.runningBalance)}</Ltr>
        );
      case "paymentMethod": {
        const rawPm = String(row.meta?.paymentMethod ?? "")
          .trim()
          .toLowerCase();
        const breakdown = String(row.meta?.paymentBreakdown ?? "").trim();
        const pmLabel = paymentMethodLabelFromCatalog(rawPm, ar ? "ar" : "en");
        return (
          <span
            className={`text-xs ${rawPm ? "font-medium text-foreground" : "text-muted-foreground"}`}
            title={breakdown || undefined}
          >
            {pmLabel}
            {breakdown && (
              <span className="block text-[10px] font-normal text-muted-foreground">
                {breakdown}
              </span>
            )}
          </span>
        );
      }
      default:
        return "—";
    }
  };

  return (
    <>
      <PageHeader
        title={
          ar
            ? partyType === "customer"
              ? "كشف حساب العملاء"
              : partyType === "supplier"
                ? "كشف حساب الموردين"
                : "كشف الصندوق والبنك"
            : partyType === "customer"
              ? "Customer Statements"
              : partyType === "supplier"
                ? "Supplier Statements"
                : "Cash & Bank Statement"
        }
        subtitle={
          ar
            ? "حركات الحساب والرصيد المتسلسل مع الطباعة والتصدير والمشاركة"
            : "Account movements and running balance with printing, export, and sharing"
        }
        actions={
          <div className="flex items-center gap-2">
            <>
              <Button
                onClick={handleShareStatement}
                variant="outline"
                size="sm"
                disabled={!result || partyType === "cash"}
                className="h-8 gap-1.5 text-xs text-primary border-primary/30 hover:bg-primary/10 rounded-xl"
              >
                <Share2 className="h-3.5 w-3.5" />
                {ar ? "مشاركة الكشف" : "Share"}
              </Button>
              <Button
                onClick={handleExportCsv}
                variant="outline"
                size="sm"
                disabled={!result}
                className="h-8 gap-1.5 text-xs text-emerald-500 border-emerald-500/30 hover:bg-emerald-500/10 rounded-xl"
              >
                <FileSpreadsheet className="h-3.5 w-3.5" />
                {ar ? "تصدير CSV" : "CSV"}
              </Button>
              <Button
                onClick={handlePrintPDF}
                size="sm"
                disabled={!result}
                className="h-8 gap-1.5 text-xs bg-primary rounded-xl"
              >
                <Printer className="h-3.5 w-3.5" />
                {ar ? "طباعة PDF فاخر" : "Print PDF"}
              </Button>
            </>
          </div>
        }
      />

      <div className="space-y-4">
        {/* بطاقة اختيار الحساب النظيفة والمرتبة بقوائم منسدلة */}
        <div className="panel-elevated p-3.5 sm:p-4 flex flex-wrap items-center justify-between gap-3">
          <div className="flex flex-wrap items-center gap-2.5">
            {/* قائمة منسدلة لاختيار الطرف */}
            {partyType !== "cash" && (
              <Select value={partyId} onValueChange={setPartyId}>
                <SelectTrigger className="h-9 w-48 sm:w-64 text-xs font-medium bg-surface rounded-xl border-border/80 shadow-sm">
                  <SelectValue
                    placeholder={
                      loadingParties
                        ? t("common.loading")
                        : ar
                          ? "اختر الحساب..."
                          : "Select account..."
                    }
                  />
                </SelectTrigger>
                <SelectContent className="max-h-[300px]">
                  {partyList.length > 0 ? (
                    partyList.map((p) => (
                      <SelectItem key={p.id} value={p.id}>
                        <div className="flex w-full items-center justify-between gap-4 text-xs">
                          <span className="truncate font-medium">{p.name}</span>
                          {p.balance !== undefined && (
                            <span className="font-mono text-[11px] text-muted-foreground">
                              {money(Number(p.balance))}
                            </span>
                          )}
                        </div>
                      </SelectItem>
                    ))
                  ) : (
                    <div className="space-y-2 p-2 text-center">
                      <p className="text-xs text-muted-foreground">
                        {loadingParties
                          ? t("common.loading")
                          : ar
                            ? partyType === "customer"
                              ? "لا يوجد عملاء حتى الآن"
                              : "لا يوجد موردون حتى الآن"
                            : partyType === "customer"
                              ? "No customers yet"
                              : "No suppliers yet"}
                      </p>
                      {!loadingParties && (
                        <Button
                          type="button"
                          size="sm"
                          className="h-8 w-full rounded-xl text-xs"
                          onClick={() => {
                            setCustomerFormOpen(partyType === "customer");
                            setSupplierFormOpen(partyType === "supplier");
                          }}
                        >
                          {ar
                            ? partyType === "customer"
                              ? "إضافة عميل"
                              : "إضافة مورد"
                            : partyType === "customer"
                              ? "Add customer"
                              : "Add supplier"}
                        </Button>
                      )}
                    </div>
                  )}
                </SelectContent>
              </Select>
            )}
          </div>

          {/* المجاميع المالية المدمجة */}
          {result && (
            <div className="flex flex-wrap items-center gap-4 sm:gap-6 bg-surface-2/60 px-3.5 py-1.5 rounded-xl border border-border/60">
              <div className="text-end">
                <span className="text-[10px] text-muted-foreground block">
                  {ar ? "إجمالي المدين (له)" : "Total Debit"}
                </span>
                <span className="font-bold font-mono text-rose-500 text-xs sm:text-sm">
                  <Ltr>{money(totalDebit)}</Ltr>
                </span>
              </div>

              <div className="h-6 w-px bg-border/60 hidden sm:block" />

              <div className="text-end">
                <span className="text-[10px] text-muted-foreground block">
                  {ar ? "إجمالي الدائن (عليه)" : "Total Credit"}
                </span>
                <span className="font-bold font-mono text-emerald-500 text-xs sm:text-sm">
                  <Ltr>{money(totalCredit)}</Ltr>
                </span>
              </div>

              <div className="h-6 w-px bg-border/60 hidden sm:block" />

              <div className="text-end">
                <span className="text-[10px] text-muted-foreground block">
                  {ar ? "الرصيد المتبقي" : "Net Balance"}
                </span>
                <span className="font-bold font-mono text-primary text-sm sm:text-base">
                  <Ltr>{money(closingBalance)}</Ltr>
                </span>
              </div>
            </div>
          )}
        </div>

        {/* شريط الأدوات الموحد: البحث + الفرز + الفلاتر + الأعمدة */}
        <div className="flex flex-wrap items-center justify-between gap-2.5">
          <div className="flex-1 min-w-[220px] max-w-md">
            <SearchInput
              value={tableSearch}
              onValueChange={setTableSearch}
              placeholder={
                ar
                  ? "ابحث في حركات الكشف (رقم الفاتورة، السند، البيان...) (/)"
                  : "Search statement records... (/)"
              }
              resultCountText={
                statementRows.length !== rawRows.length
                  ? `${statementRows.length}/${rawRows.length}`
                  : String(statementRows.length)
              }
              enableSlashShortcut
              containerClassName="w-full"
            />
          </div>

          <div className="flex items-center gap-2">
            {/* قائمة الفرز المنسدلة */}
            <Popover open={sortMenuOpen} onOpenChange={setSortMenuOpen}>
              <PopoverTrigger asChild>
                <Button
                  variant={sortField !== "date" || sortDirection !== "desc" ? "default" : "outline"}
                  size="sm"
                  className={cn(
                    "h-8 gap-1.5 px-2.5 text-xs rounded-xl",
                    sortField !== "date" && "bg-primary text-primary-foreground",
                  )}
                >
                  <ArrowDownUp className="h-3.5 w-3.5" />
                  <span>{ar ? "ترتيب" : "Sort"}</span>
                </Button>
              </PopoverTrigger>
              <PopoverContent align="end" className="w-[200px] p-1.5">
                <div className="border-b border-border/60 px-2 py-1.5 text-xs font-semibold">
                  {ar ? "خيارات الترتيب" : "Sort options"}
                </div>
                <div className="space-y-0.5 pt-1 text-xs">
                  <button
                    type="button"
                    onClick={() => {
                      setSortField("date");
                      setSortDirection("desc");
                      setSortMenuOpen(false);
                    }}
                    className={cn(
                      "flex w-full items-center justify-between rounded-md px-2 py-1.5 transition hover:bg-surface-2",
                      sortField === "date" &&
                        sortDirection === "desc" &&
                        "font-semibold text-primary",
                    )}
                  >
                    <span>{ar ? "التاريخ: الأحدث أولاً" : "Date: Newest"}</span>
                    {sortField === "date" && sortDirection === "desc" && "✓"}
                  </button>

                  <button
                    type="button"
                    onClick={() => {
                      setSortField("date");
                      setSortDirection("asc");
                      setSortMenuOpen(false);
                    }}
                    className={cn(
                      "flex w-full items-center justify-between rounded-md px-2 py-1.5 transition hover:bg-surface-2",
                      sortField === "date" &&
                        sortDirection === "asc" &&
                        "font-semibold text-primary",
                    )}
                  >
                    <span>{ar ? "التاريخ: الأقدم أولاً" : "Date: Oldest"}</span>
                    {sortField === "date" && sortDirection === "asc" && "✓"}
                  </button>

                  <button
                    type="button"
                    onClick={() => {
                      setSortField("debit");
                      setSortDirection("desc");
                      setSortMenuOpen(false);
                    }}
                    className={cn(
                      "flex w-full items-center justify-between rounded-md px-2 py-1.5 transition hover:bg-surface-2",
                      sortField === "debit" &&
                        sortDirection === "desc" &&
                        "font-semibold text-primary",
                    )}
                  >
                    <span>{ar ? "المدين: الأكبر أولاً" : "Debit: Highest"}</span>
                    {sortField === "debit" && sortDirection === "desc" && "✓"}
                  </button>

                  <button
                    type="button"
                    onClick={() => {
                      setSortField("credit");
                      setSortDirection("desc");
                      setSortMenuOpen(false);
                    }}
                    className={cn(
                      "flex w-full items-center justify-between rounded-md px-2 py-1.5 transition hover:bg-surface-2",
                      sortField === "credit" &&
                        sortDirection === "desc" &&
                        "font-semibold text-primary",
                    )}
                  >
                    <span>{ar ? "الدائن: الأكبر أولاً" : "Credit: Highest"}</span>
                    {sortField === "credit" && sortDirection === "desc" && "✓"}
                  </button>

                  <button
                    type="button"
                    onClick={() => {
                      setSortField("balance");
                      setSortDirection("desc");
                      setSortMenuOpen(false);
                    }}
                    className={cn(
                      "flex w-full items-center justify-between rounded-md px-2 py-1.5 transition hover:bg-surface-2",
                      sortField === "balance" &&
                        sortDirection === "desc" &&
                        "font-semibold text-primary",
                    )}
                  >
                    <span>{ar ? "الرصيد: الأكبر أولاً" : "Balance: Highest"}</span>
                    {sortField === "balance" && sortDirection === "desc" && "✓"}
                  </button>
                </div>
              </PopoverContent>
            </Popover>

            <ReportFilterMenu
              values={filterValues}
              presets={filterPresets}
              onChange={updateFilterValues}
              onReset={resetOptions}
              labels={{
                trigger: ar ? "تصفية الكشف" : "Filter statement",
                title: ar ? "تصفية الكشف" : "Statement filters",
                date: ar ? "التاريخ والفترة" : "Date and period",
                period: ar ? "الفترة" : "Period",
                options: ar ? "خيارات إضافية" : "More options",
                includeZeroRows: ar ? "إظهار الفواتير المسددة" : "Include settled",
                reset: ar ? "إعادة ضبط الفلاتر" : "Reset filters",
                back: ar ? "رجوع" : "Back",
                from: ar ? "من" : "From",
                to: ar ? "إلى" : "To",
              }}
            />

            <ColumnVisibilityMenu
              columns={columnOptions}
              visible={visibleColumns}
              onChange={(key, value) =>
                setVisibleColumns((current) => ({ ...current, [key]: value }))
              }
              label={ar ? "الأعمدة" : "Columns"}
              title={ar ? "إظهار أعمدة الكشف" : "Visible columns"}
            />
          </div>
        </div>

        {result?.integrity.hasGap && (
          <StatementIntegrityBadge integrity={result.integrity} variant="panel" />
        )}
        {from && to && from > to && (
          <div className="rounded-xl border border-amber-500/40 bg-amber-500/5 px-3.5 py-2 text-[11px] text-amber-700">
            {ar
              ? "تاريخ البداية بعد تاريخ النهاية — سيظهر الكشف فارغًا."
              : "Start date is after end date — the statement will be empty."}
          </div>
        )}

        {/* ═══ الجدول الموحد لكشف الحساب ═══ */}
        <div className="panel-elevated p-0 overflow-hidden rounded-2xl border border-border/70 shadow-sm">
          <div className="p-3.5 flex flex-wrap items-center justify-between gap-2 border-b border-border/60">
            <div className="flex items-center gap-2">
              <SourceBadge derived={derived} hasSourceData={hasSourceData} />
              {result && (
                <span className="text-[11px] text-muted-foreground font-medium">
                  {statementRows.length} {ar ? "حركة معروضة" : "entries shown"}
                </span>
              )}
            </div>
            <span className="text-[11px] text-muted-foreground">
              {result ? directionLabel(result.direction, result.entityType, lang) : ""}
            </span>
          </div>

          <div className="overflow-x-auto">
            <Table>
              <TableHeader className="bg-surface-2/60">
                <TableRow>
                  {columns.map((col) => {
                    const isSortableCol = ["date", "debit", "credit", "balance"].includes(col.key);
                    const isActiveSort = sortField === col.key;

                    return (
                      <TableHead
                        key={col.key}
                        onClick={() => {
                          if (isSortableCol) {
                            toggleSort(col.key as "date" | "debit" | "credit" | "balance");
                          }
                        }}
                        className={cn(
                          col.key === "debit" && "text-end text-rose-500 font-semibold",
                          col.key === "credit" && "text-end text-emerald-500 font-semibold",
                          col.key === "balance" && "text-end font-semibold",
                          isSortableCol && "cursor-pointer hover:bg-surface-3 transition-colors",
                          alignClass(col.align),
                        )}
                        style={col.width ? { width: col.width } : undefined}
                      >
                        <div
                          className={cn(
                            "inline-flex items-center gap-1.5",
                            col.align === "end" && "justify-end w-full",
                          )}
                        >
                          <span>{col.label}</span>
                          {isSortableCol &&
                            (isActiveSort ? (
                              sortDirection === "asc" ? (
                                <ArrowUp className="h-3 w-3 text-primary" />
                              ) : (
                                <ArrowDown className="h-3 w-3 text-primary" />
                              )
                            ) : (
                              <ChevronsUpDown className="h-3 w-3 opacity-40" />
                            ))}
                        </div>
                      </TableHead>
                    );
                  })}
                </TableRow>
              </TableHeader>
              <TableBody>
                {isLoading ? (
                  <TableRow>
                    <TableCell colSpan={Math.max(columns.length, 1)} className="py-12 text-center">
                      <Loader2 className="mx-auto h-5 w-5 animate-spin text-muted-foreground" />
                    </TableCell>
                  </TableRow>
                ) : !partyId ? (
                  <TableRow>
                    <TableCell
                      colSpan={Math.max(columns.length, 1)}
                      className="py-12 text-center text-muted-foreground text-xs"
                    >
                      {ar ? "اختر حسابًا لعرض الكشف" : "Select an account to view the statement"}
                    </TableCell>
                  </TableRow>
                ) : statementRows.length === 0 ? (
                  <TableRow>
                    <TableCell
                      colSpan={Math.max(columns.length, 1)}
                      className="py-12 text-center text-muted-foreground text-xs"
                    >
                      {tableSearch
                        ? ar
                          ? "لا توجد نتائج مطابقة لبحثك في هذا الكشف"
                          : "No matching records found"
                        : ar
                          ? "لا توجد حركات حسابية مسجلة لهذه الفترة"
                          : "No statement records for this period"}
                    </TableCell>
                  </TableRow>
                ) : (
                  <>
                    {layout?.showOpeningRow && !tableSearch && (
                      <TableRow className="bg-surface/70 hover:bg-surface/70">
                        {columns.map((col) => {
                          let content: React.ReactNode = "—";
                          if (col.key === "index")
                            content = (
                              <span className="font-mono text-xs text-muted-foreground">—</span>
                            );
                          else if (col.key === "kind")
                            content = (
                              <span className="text-xs font-medium italic text-muted-foreground">
                                {kindLabel("opening", partyType, lang)}
                              </span>
                            );
                          else if (col.key === "description")
                            content = (
                              <span className="text-xs italic text-muted-foreground">
                                {ar ? "رصيد ما قبل بداية الفترة" : "Balance before period start"}
                              </span>
                            );
                          else if (col.key === "date")
                            content = result?.period.from ? (
                              <VortexDateBadge
                                date={result.period.from}
                                size="sm"
                                showWeekday={false}
                              />
                            ) : (
                              <span className="text-xs text-muted-foreground">—</span>
                            );
                          else if (col.key === "balance")
                            content = (
                              <span className="font-mono text-xs font-bold">
                                <Ltr>{fmtAmount(result?.openingBalance ?? 0)}</Ltr>
                              </span>
                            );
                          return (
                            <TableCell key={col.key} className={alignClass(col.align)}>
                              {content}
                            </TableCell>
                          );
                        })}
                      </TableRow>
                    )}

                    {statementRows.map((row) => (
                      <TableRow
                        key={row.id}
                        className="cursor-pointer hover:bg-surface-2/60 transition-colors"
                        onClick={() => setDetailEntry(row)}
                        title={ar ? "عرض تفاصيل القيد" : "View entry details"}
                      >
                        {columns.map((col) => (
                          <TableCell key={col.key} className={alignClass(col.align)}>
                            {renderCell(row, col.key)}
                          </TableCell>
                        ))}
                      </TableRow>
                    ))}
                  </>
                )}

                {statementRows.length > 0 && (
                  <TableRow className="border-t-2 border-border font-bold bg-surface-2/50">
                    {columns.map((col) => {
                      let content: React.ReactNode = "";
                      if (col.key === "kind")
                        content = (
                          <span className="text-xs">{ar ? "الإجمالي الكلي:" : "Total:"}</span>
                        );
                      else if (col.key === "debit")
                        content = (
                          <span className="font-mono text-rose-500 font-bold">
                            <Ltr>{money(totalDebit)}</Ltr>
                          </span>
                        );
                      else if (col.key === "credit")
                        content = (
                          <span className="font-mono text-emerald-500 font-bold">
                            <Ltr>{fmtOrDash(totalCredit)}</Ltr>
                          </span>
                        );
                      else if (col.key === "balance")
                        content = (
                          <span className="font-mono text-primary text-sm font-bold">
                            <Ltr>{money(closingBalance)}</Ltr>
                          </span>
                        );
                      return (
                        <TableCell key={col.key} className={cn(alignClass(col.align), "text-xs")}>
                          {content}
                        </TableCell>
                      );
                    })}
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </div>

          {statementRows.length > 0 && (
            <div className="p-3.5 flex flex-wrap items-center justify-between gap-2 border-t border-border/60 text-[11px] text-muted-foreground">
              <span>
                {ar ? "الرصيد الختامي" : "Closing balance"}:{" "}
                <b className="font-mono text-foreground font-bold">
                  {money(closingBalance)} {currencySymbol}
                </b>
              </span>
            </div>
          )}
        </div>
      </div>

      {/* تفاصيل القيد المنبثقة */}
      <StatementEntryDetails
        entry={detailEntry}
        entityType={partyType}
        onClose={() => setDetailEntry(null)}
      />

      {/* نافذة مشاركة الكشف */}
      {shareContext && activeParty && (
        <DocumentShareDialog
          open={shareOpen}
          onClose={() => setShareOpen(false)}
          title={ar ? "مشاركة كشف الحساب" : "Share Statement"}
          documentType="statement"
          customer={{
            id: activeParty.id,
            name: activeParty.name,
            phone: activeParty.phone ?? null,
            balance: Number(activeParty.balance ?? closingBalance),
            hasLedgerActivity: statementRows.length > 0,
          }}
          statement={shareContext}
          onPrintPdf={handlePrintPDF}
          onExportExcel={handleExportCsv}
        />
      )}

      <CustomerFormDialog
        open={customerFormOpen}
        onClose={() => setCustomerFormOpen(false)}
        onSaved={(record: CustomerRecord) => {
          setPartyList((current) => [...current, record]);
          setPartyId(record.id);
          setCustomerFormOpen(false);
        }}
      />
      <SupplierFormDialog
        open={supplierFormOpen}
        onClose={() => setSupplierFormOpen(false)}
        onSaved={(record: SupplierRecord) => {
          setPartyList((current) => [...current, record]);
          setPartyId(record.id);
          setSupplierFormOpen(false);
        }}
      />
    </>
  );
}

import { useModules } from "@/lib/modules";
import { createFileRoute } from "@tanstack/react-router";
import { useEffect, useMemo, useState } from "react";
import { PageHeader } from "@/components/page-header";
import { useI18n } from "@/lib/i18n";
import { useAuth } from "@/lib/auth";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from "@/components/ui/sheet";
import { toast } from "sonner";
import {
  ShieldCheck,
  Trash2,
  Crown,
  Users,
  Lock,
  Sparkles,
  UserPlus,
  UserX,
  UserCheck,
  Copy,
  Check,
  KeyRound,
  Loader2,
  Search,
  Phone,
  Mail,
  Calendar,
  Eye,
  Pencil,
  Send,
  MessageCircle,
  Briefcase,
  Shield,
  Filter,
  CheckCircle2,
  XCircle,
} from "lucide-react";
import { RolePermissionsDialog } from "@/components/role-permissions-dialog";
import { VortexMetricCard, VortexSearchInput, VortexDateBadge } from "@/components/vortex-ui";
import { toSystemDigits, formatLuxuryDate } from "@/lib/format-preferences";
import { cn } from "@/lib/utils";
import { CountrySelector } from "@/components/country-selector";
import { DEFAULT_COUNTRY, Country } from "@/lib/country-data";
import { formatPhoneE164, phoneToAuthEmail } from "@/lib/phone-utils";

const STORE_ROLES = ["owner", "manager", "accountant", "cashier", "warehouse"] as const;
type StoreRole = (typeof STORE_ROLES)[number];

const DEFAULT_NEW_ROLE: StoreRole = "cashier";

type IssuedCredentials = {
  email: string;
  password: string;
  full_name: string;
  role: string;
  phone?: string;
};

// Role styling & icons helper
function getRoleMeta(role: string) {
  switch (role) {
    case "owner":
      return {
        labelAr: "المالك",
        icon: Crown,
        badgeClass: "bg-amber-500/15 text-amber-700 dark:text-amber-300 border-amber-500/30",
        colorClass: "text-amber-500",
      };
    case "manager":
      return {
        labelAr: "المدير",
        icon: ShieldCheck,
        badgeClass: "bg-blue-500/15 text-blue-700 dark:text-blue-300 border-blue-500/30",
        colorClass: "text-blue-500",
      };
    case "accountant":
      return {
        labelAr: "المحاسب",
        icon: Briefcase,
        badgeClass:
          "bg-emerald-500/15 text-emerald-700 dark:text-emerald-300 border-emerald-500/30",
        colorClass: "text-emerald-500",
      };
    case "cashier":
      return {
        labelAr: "الكاشير",
        icon: Sparkles,
        badgeClass: "bg-purple-500/15 text-purple-700 dark:text-purple-300 border-purple-500/30",
        colorClass: "text-purple-500",
      };
    case "warehouse":
      return {
        labelAr: "أمين المستودع",
        icon: Shield,
        badgeClass: "bg-orange-500/15 text-orange-700 dark:text-orange-300 border-orange-500/30",
        colorClass: "text-orange-500",
      };
    default:
      return {
        labelAr: role,
        icon: Shield,
        badgeClass: "bg-muted text-muted-foreground border-border",
        colorClass: "text-muted-foreground",
      };
  }
}

export const Route = createFileRoute("/_app/users")({
  head: () => ({ meta: [{ title: "إدارة المستخدمين والصلاحيات — Vortex ERP" }] }),
  component: UsersPage,
});

function UsersPage() {
  const { checkQuota } = useModules();
  const { t, lang } = useI18n();
  const isAr = lang === "ar";
  const { hasRole, user, isPlatformAdmin, isPlatformSuperadmin } = useAuth();
  const isOwner = hasRole("owner");
  const isSuper = isPlatformAdmin || isPlatformSuperadmin;
  const canManageStore = isOwner || isSuper;

  const [activeTab, setActiveTab] = useState<"store" | "platform">("store");
  const [storeRows, setStoreRows] = useState<any[]>([]);
  const [platformAdminRows, setPlatformAdminRows] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  // Search & Filter state
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState<string>("all");
  const [statusFilter, setStatusFilter] = useState<string>("all");

  // User detail sheet state
  const [selectedUser, setSelectedUser] = useState<any | null>(null);

  // Create-user dialog state
  const [addOpen, setAddOpen] = useState(false);
  const [addName, setAddName] = useState("");
  const [addCountry, setAddCountry] = useState<Country>(DEFAULT_COUNTRY);
  const [addPhone, setAddPhone] = useState("");
  const [addEmail, setAddEmail] = useState("");
  const [addRole, setAddRole] = useState<StoreRole>(DEFAULT_NEW_ROLE);
  const [addPassword, setAddPassword] = useState("");
  const [addConfirmPassword, setAddConfirmPassword] = useState("");
  const [useGeneratedPassword, setUseGeneratedPassword] = useState(true);
  const [addSaving, setAddSaving] = useState(false);
  const [issued, setIssued] = useState<IssuedCredentials | null>(null);

  const [editOpen, setEditOpen] = useState(false);
  const [editUser, setEditUser] = useState<any | null>(null);
  const [editName, setEditName] = useState("");
  const [editPhone, setEditPhone] = useState("");
  const [editLanguage, setEditLanguage] = useState("ar");
  const [editSaving, setEditSaving] = useState(false);
  const [copiedField, setCopiedField] = useState<"password" | "all" | null>(null);

  async function load() {
    setLoading(true);
    try {
      const [profilesRes, rolesRes, platformRes] = await Promise.all([
        supabase
          .from("profiles")
          .select("id, full_name, avatar_url, phone, language, created_at, is_active"),
        supabase.from("user_roles").select("id, user_id, role"),
        isSuper
          ? (supabase as any)
              .from("platform_admins")
              .select("id, user_id, role, is_active, created_at")
          : Promise.resolve({ data: [] as any[] }),
      ]);

      const profiles = profilesRes.data;
      const roles = rolesRes.data;
      const platformAdmins = platformRes.data;

      const byUser = new Map<string, any[]>();
      (roles ?? []).forEach((r) => {
        const arr = byUser.get(r.user_id) ?? [];
        arr.push(r);
        byUser.set(r.user_id, arr);
      });

      const profileMap = new Map<string, any>();
      (profiles ?? []).forEach((p) => profileMap.set(p.id, p));

      // Build the set of platform admin user IDs to exclude from store staff
      const platformAdminSet = new Set<string>();

      if (isSuper) {
        // Superadmin has full RLS read on platform_admins table
        (platformAdmins ?? []).forEach((pa: any) => {
          if (pa?.user_id) {
            platformAdminSet.add(pa.user_id);
          }
        });
      } else {
        // Non-platform admin (owner, manager, etc.): check candidate users via SECURITY DEFINER RPC
        // Collect candidates: users in profiles who hold at least one store role
        const candidateUserIds = (profiles ?? [])
          .filter((p) => (byUser.get(p.id) ?? []).length > 0)
          .map((p) => p.id);

        if (candidateUserIds.length > 0) {
          const rpcResults = await Promise.all(
            candidateUserIds.map(async (uid) => {
              try {
                const { data, error } = await (supabase as any).rpc("is_platform_admin", {
                  p_user_id: uid,
                });
                if (error) {
                  console.error(`[loadUsers] is_platform_admin RPC error for ${uid}:`, error);
                  return { uid, isPlatformAdmin: false };
                }
                return { uid, isPlatformAdmin: data === true };
              } catch (rpcErr) {
                console.error(`[loadUsers] is_platform_admin invoke failed for ${uid}:`, rpcErr);
                return { uid, isPlatformAdmin: false };
              }
            }),
          );

          rpcResults.forEach((res) => {
            if (res.isPlatformAdmin) {
              platformAdminSet.add(res.uid);
            }
          });
        }
      }

      const storeUsers: any[] = [];
      (profiles ?? []).forEach((p) => {
        if (platformAdminSet.has(p.id)) return;
        const uRoles = byUser.get(p.id) ?? [];
        if (uRoles.length === 0) return;
        storeUsers.push({ ...p, roles: uRoles });
      });

      const platformUsers: any[] = (platformAdmins ?? []).map((pa: any) => {
        const prof = profileMap.get(pa.user_id);
        return {
          id: pa.id,
          user_id: pa.user_id,
          full_name: prof?.full_name ?? (isAr ? "مسؤول منصة" : "Platform admin"),
          role: pa.role,
          is_active: pa.is_active,
          created_at: pa.created_at,
        };
      });

      setStoreRows(storeUsers);
      setPlatformAdminRows(platformUsers);
    } catch (err) {
      console.error("Error loading users:", err);
      toast.error(isAr ? "تعذر تحميل قائمة المستخدمين" : "Failed to load users");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    void load();
  }, [isSuper]);

  // Statistics calculation
  const stats = useMemo(() => {
    const total = storeRows.length;
    const active = storeRows.filter((r) => r.is_active !== false).length;
    const disabled = storeRows.filter((r) => r.is_active === false).length;
    const managers = storeRows.filter((r) =>
      r.roles.some((ro: any) => ro.role === "owner" || ro.role === "manager"),
    ).length;

    return { total, active, disabled, managers };
  }, [storeRows]);

  // Filtered staff rows
  const filteredStoreRows = useMemo(() => {
    const q = search.trim().toLowerCase();
    return storeRows.filter((r) => {
      // Text search
      if (q) {
        const name = (r.full_name || "").toLowerCase();
        const phone = (r.phone || "").toLowerCase();
        const rolesStr = (r.roles || [])
          .map((ro: any) => ro.role)
          .join(" ")
          .toLowerCase();
        const rolesArStr = (r.roles || []).map((ro: any) => getRoleMeta(ro.role).labelAr).join(" ");
        if (
          !name.includes(q) &&
          !phone.includes(q) &&
          !rolesStr.includes(q) &&
          !rolesArStr.includes(q)
        ) {
          return false;
        }
      }

      // Role filter
      if (roleFilter !== "all") {
        const has = r.roles.some((ro: any) => ro.role === roleFilter);
        if (!has) return false;
      }

      // Status filter
      if (statusFilter !== "all") {
        if (statusFilter === "active" && r.is_active === false) return false;
        if (statusFilter === "disabled" && r.is_active !== false) return false;
      }

      return true;
    });
  }, [storeRows, search, roleFilter, statusFilter]);

  async function assignStoreRole(userId: string, role: string) {
    const qCheck = checkQuota("users", storeRows.length);
    if (!qCheck.allowed) {
      return toast.error(isAr ? qCheck.message?.ar : qCheck.message?.en);
    }
    const { error } = await supabase
      .from("user_roles")
      .insert({ user_id: userId, role: role as any });
    if (error) return toast.error(error.message);
    toast.success(t("users.role_granted") || (isAr ? "تم منح الدور بنجاح" : "Role granted"));
    void load();
  }

  async function removeStoreRole(id: string) {
    if (!confirm(isAr ? "هل تريد إزالة هذا الدور عن الموظف؟" : "Remove role?")) return;
    const { error } = await supabase.from("user_roles").delete().eq("id", id);
    if (error) return toast.error(error.message);
    toast.success(isAr ? "تم حذف الدور" : "Role removed");
    void load();
  }

  async function setUserActive(userId: string, active: boolean) {
    if (userId === user?.id && !active) {
      return toast.error(
        isAr ? "لا يمكنك تعطيل حسابك الخاص." : "You cannot disable your own account.",
      );
    }
    if (
      !confirm(
        active
          ? isAr
            ? "إعادة تفعيل هذا المستخدم؟ سيستعيد وصوله بنفس الحساب وبياناته."
            : "Reactivate this user? They regain access with the same account."
          : isAr
            ? "تعطيل هذا المستخدم؟ سيتم إيقاف وصوله مع الاحتفاظ ببياناته وسجلاته بالكامل."
            : "Disable this user? Access is revoked but all data and history is kept.",
      )
    )
      return;

    const { error } = await supabase
      .from("profiles")
      .update({ is_active: active } as any)
      .eq("id", userId);

    if (error) return toast.error(error.message);
    toast.success(
      active
        ? isAr
          ? "تمت إعادة تفعيل المستخدم بنجاح"
          : "User reactivated"
        : isAr
          ? "تم تعطيل المستخدم مع الاحتفاظ ببياناته"
          : "User disabled (data preserved)",
    );
    void load();
  }

  function openEditUser(row: any) {
    setEditUser(row);
    setEditName(row.full_name ?? "");
    setEditPhone(row.phone ?? "");
    setEditLanguage(row.language ?? "ar");
    setEditOpen(true);
  }

  async function saveEditUser() {
    if (!editUser) return;
    const name = editName.trim();
    const phone = editPhone.trim();

    if (name.length < 2) {
      return toast.error(isAr ? "يرجى إدخال اسم صحيح." : "Please enter a valid name.");
    }

    setEditSaving(true);
    try {
      const { error } = await supabase
        .from("profiles")
        .update({ full_name: name, phone: phone || null, language: editLanguage })
        .eq("id", editUser.id);

      if (error) throw error;
      toast.success(isAr ? "تم تحديث بيانات الموظف" : "Employee details updated");
      setEditOpen(false);
      setEditUser(null);
      void load();
    } catch (err: any) {
      toast.error(
        err?.message ?? (isAr ? "تعذر تحديث بيانات الموظف" : "Failed to update employee"),
      );
    } finally {
      setEditSaving(false);
    }
  }

  async function createStoreUser() {
    const name = addName.trim();
    const phoneInput = addPhone.trim();
    const customEmail = addEmail.trim().toLowerCase();
    const password = addPassword;
    const confirmPassword = addConfirmPassword;

    if (name.length < 2) {
      return toast.error(isAr ? "يرجى إدخال اسم المستخدم." : "Please enter the user's name.");
    }

    if (!phoneInput && !customEmail) {
      return toast.error(
        isAr
          ? "يرجى إدخال رقم الهاتف أو البريد الإلكتروني للموظف."
          : "Please enter the employee's phone number or email.",
      );
    }

    // Determine the authentication email and formatted phone
    let authEmail = "";
    let finalPhone = "";

    if (phoneInput) {
      finalPhone = formatPhoneE164(phoneInput, addCountry.dialCode);
      authEmail = phoneToAuthEmail(finalPhone);
    } else {
      authEmail = customEmail;
    }

    // If custom email provided and no phone, validate email syntax
    if (customEmail && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(customEmail)) {
      return toast.error(
        isAr ? "يرجى إدخال بريد إلكتروني صحيح." : "Please enter a valid email address.",
      );
    }

    if (STORE_ROLES.indexOf(addRole) === -1) {
      return toast.error(isAr ? "الدور المحدد غير مسموح." : "The selected role is not allowed.");
    }
    if (!useGeneratedPassword) {
      if (password.length < 8) {
        return toast.error(
          isAr
            ? "كلمة المرور يجب أن تحتوي على 8 أحرف على الأقل."
            : "Password must be at least 8 characters.",
        );
      }
      if (password !== confirmPassword) {
        return toast.error(isAr ? "كلمتا المرور غير متطابقتين." : "Passwords do not match.");
      }
    }

    setAddSaving(true);
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const accessToken = sessionData.session?.access_token;
      if (!accessToken) {
        toast.error(isAr ? "انتهت جلسة الدخول. يرجى إعادة تسجيل الدخول." : "Session expired.");
        return;
      }

      console.log("[CreateUser] Invoking admin-create-user...", {
        email: authEmail,
        full_name: name,
        phone: finalPhone || phoneInput || null,
        role: addRole,
      });

      const { data, error } = await supabase.functions.invoke("admin-create-user", {
        body: {
          email: authEmail,
          full_name: name,
          phone: finalPhone || phoneInput || null,
          role: addRole,
          language: lang,
          ...(useGeneratedPassword ? {} : { password }),
        },
        headers: { Authorization: `Bearer ${accessToken}` },
      });

      console.log("[CreateUser] Result:", { data, error });

      if (error) {
        let errorMsg = error.message;
        try {
          const ctx = (error as any).context;
          if (ctx && typeof ctx.json === "function") {
            const body = await ctx.json();
            if (body?.message) {
              errorMsg = body.message;
            } else if (body?.error && typeof body.error === "string") {
              errorMsg = body.error;
            }
          }
        } catch {
          // fallback to error.message
        }
        console.error("[CreateUser] invoke error detail:", error, errorMsg);
        throw new Error(
          errorMsg ||
            (isAr ? "تعذر إنشاء المستخدم. يرجى المحاولة مرة أخرى." : "Failed to create user."),
        );
      }

      if (!data?.ok) {
        throw new Error(
          data?.message ??
            (isAr ? "تعذر إنشاء المستخدم. يرجى المحاولة مرة أخرى." : "Failed to create user."),
        );
      }

      if (useGeneratedPassword) {
        setIssued({
          email: data.email,
          password: data.password,
          full_name: data.full_name,
          role: data.role,
          phone: finalPhone || phoneInput || undefined,
        });
        setCopiedField(null);
      } else {
        toast.success(isAr ? "تم إنشاء حساب المستخدم بنجاح" : "User account created successfully");
        setAddOpen(false);
        resetCreateDialog();
      }
      void load();
    } catch (err: any) {
      toast.error(err?.message ?? (isAr ? "تعذر إنشاء المستخدم" : "Failed to create user"));
    } finally {
      setAddSaving(false);
    }
  }

  function resetCreateDialog() {
    setIssued(null);
    setCopiedField(null);
    setAddName("");
    setAddCountry(DEFAULT_COUNTRY);
    setAddPhone("");
    setAddEmail("");
    setAddRole(DEFAULT_NEW_ROLE);
    setAddPassword("");
    setAddConfirmPassword("");
    setUseGeneratedPassword(true);
  }

  async function copyToClipboard(text: string, field: "password" | "all") {
    try {
      await navigator.clipboard.writeText(text);
      setCopiedField(field);
      toast.success(isAr ? "تم النسخ بنجاح" : "Copied");
      setTimeout(() => setCopiedField(null), 2000);
    } catch {
      toast.error(isAr ? "تعذر النسخ تلقائيًا" : "Copy failed.");
    }
  }

  async function revokePlatformAdmin(adminRecordId: string) {
    if (
      !confirm(
        isAr
          ? "هل أنت متأكد من إلغاء صلاحية مدير المنصة لهذا المستخدم؟"
          : "Revoke Platform Admin privileges?",
      )
    )
      return;
    const { error } = await (supabase as any)
      .from("platform_admins")
      .delete()
      .eq("id", adminRecordId);
    if (error) return toast.error(error.message);
    toast.success(isAr ? "تم إلغاء صلاحية مدير المنصة" : "Platform admin revoked");
    void load();
  }

  return (
    <div className="space-y-6 pb-12">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-black tracking-tight text-foreground">
            {isAr ? "إدارة المستخدمين وطاقم العمل" : "Staff & Access Control"}
          </h1>
          <p className="text-xs sm:text-sm text-muted-foreground mt-1">
            {isAr
              ? "إدارة حسابات الموظفين وتعيين الأدوار التشغيلية والصلاحيات المعتمدة للمتجر"
              : "Manage staff accounts, assign operational roles, and enforce security policies"}
          </p>
        </div>

        <div className="flex items-center gap-2">
          {canManageStore && (
            <RolePermissionsDialog
              showPlatformRole={isSuper}
              trigger={
                <Button
                  variant="outline"
                  size="sm"
                  className="rounded-2xl gap-2 h-10 px-3.5 border-border/80 hover:bg-muted text-xs font-semibold"
                >
                  <Sparkles className="size-4 text-primary" />
                  <span>{isAr ? "مصفوفة الصلاحيات" : "Permissions Matrix"}</span>
                </Button>
              }
            />
          )}

          {canManageStore && (
            <Button
              size="sm"
              onClick={() => setAddOpen(true)}
              className="rounded-2xl gap-2 h-10 px-4 text-xs font-bold shadow-md shadow-primary/20"
            >
              <UserPlus className="size-4" />
              <span>{isAr ? "إضافة موظف جديد" : "Add Staff"}</span>
            </Button>
          )}
        </div>
      </div>

      {/* Warning banner for non-owners */}
      {!canManageStore && (
        <div className="p-4 rounded-3xl border border-amber-500/30 bg-amber-500/5 text-xs text-amber-700 dark:text-amber-400 flex items-center gap-2.5">
          <Lock className="size-4 shrink-0 text-amber-500" />
          <span>
            {isAr
              ? "ملاحظة: صلاحية المالك والمدير المخول فقط هي التي تملك حق تعيين أو تعديل أدوار الموظفين."
              : "Notice: Only Owner and authorized Managers can modify staff role assignments."}
          </span>
        </div>
      )}

      {/* Top Metric Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
        <VortexMetricCard
          title={isAr ? "إجمالي طاقم العمل" : "Total Staff"}
          value={toSystemDigits(stats.total)}
          currency=""
          subtitle={isAr ? "موظف مسجل بالمنشأة" : "Registered store staff"}
          icon={<Users className="size-5" />}
          iconClassName="bg-primary/10 text-primary"
        />
        <VortexMetricCard
          title={isAr ? "الحسابات النشطة" : "Active Staff"}
          value={toSystemDigits(stats.active)}
          currency=""
          subtitle={isAr ? "جاهزون للعمل والدخول" : "Ready for operations"}
          icon={<UserCheck className="size-5" />}
          iconClassName="bg-emerald-500/10 text-emerald-600"
          highlight={stats.active > 0}
        />
        <VortexMetricCard
          title={isAr ? "الحسابات المعطلة" : "Disabled Staff"}
          value={toSystemDigits(stats.disabled)}
          currency=""
          subtitle={isAr ? "تم إيقاف وصولهم مؤقتاً" : "Access currently revoked"}
          icon={<UserX className="size-5" />}
          iconClassName={
            stats.disabled > 0 ? "bg-rose-500/10 text-rose-600" : "bg-muted text-muted-foreground"
          }
        />
        <VortexMetricCard
          title={isAr ? "القيادة والإدارة" : "Managers & Owners"}
          value={toSystemDigits(stats.managers)}
          currency=""
          subtitle={isAr ? "صلاحيات إدارية متقدمة" : "Elevated privileges"}
          icon={<Crown className="size-5" />}
          iconClassName="bg-amber-500/10 text-amber-600"
        />
      </div>

      {/* Superadmin Tab Navigation */}
      {isSuper && (
        <div className="flex items-center gap-2 border-b border-border/70 pb-3">
          <button
            onClick={() => setActiveTab("store")}
            className={cn(
              "flex items-center gap-2 rounded-2xl px-4 py-2 text-xs font-bold transition-all",
              activeTab === "store"
                ? "bg-primary text-primary-foreground shadow-sm"
                : "bg-card hover:bg-muted text-muted-foreground hover:text-foreground border border-border/70",
            )}
          >
            <Users className="size-4" />
            <span>{isAr ? "طاقم موظفي المنشأة" : "Store Staff Team"}</span>
            <span className="rounded-full bg-primary-foreground/20 px-2 py-0.5 text-[10px] font-mono">
              {toSystemDigits(storeRows.length)}
            </span>
          </button>

          <button
            onClick={() => setActiveTab("platform")}
            className={cn(
              "flex items-center gap-2 rounded-2xl px-4 py-2 text-xs font-bold transition-all",
              activeTab === "platform"
                ? "bg-gradient-to-r from-amber-500 to-orange-500 text-white shadow-sm"
                : "bg-card hover:bg-muted text-muted-foreground hover:text-foreground border border-border/70",
            )}
          >
            <Crown className="size-4 text-amber-200" />
            <span>{isAr ? "مدراء المنصة السحابية" : "Platform Superadmins"}</span>
            <span className="rounded-full bg-white/20 px-2 py-0.5 text-[10px] font-mono">
              {toSystemDigits(platformAdminRows.length)}
            </span>
          </button>
        </div>
      )}

      {/* Store Staff Tab View */}
      {activeTab === "store" && (
        <div className="space-y-4">
          {/* Search & Quick Filter Toolbar */}
          <div className="flex flex-col sm:flex-row items-center gap-3">
            <div className="w-full sm:flex-1">
              <VortexSearchInput
                value={search}
                onValueChange={setSearch}
                placeholder={
                  isAr
                    ? "ابحث بالاسم، الدور، أو رقم الهاتف..."
                    : "Search staff by name, role, or phone..."
                }
                className="w-full"
              />
            </div>

            {/* Quick role filter pills */}
            <div className="flex items-center gap-1.5 overflow-x-auto w-full sm:w-auto pb-1 sm:pb-0 scrollbar-none">
              <Button
                size="sm"
                variant={roleFilter === "all" ? "default" : "outline"}
                onClick={() => setRoleFilter("all")}
                className="rounded-full text-xs h-9 px-3 shrink-0"
              >
                {isAr ? "جميع الأدوار" : "All"}
              </Button>
              {STORE_ROLES.map((r) => {
                const meta = getRoleMeta(r);
                const Icon = meta.icon;
                return (
                  <Button
                    key={r}
                    size="sm"
                    variant={roleFilter === r ? "default" : "outline"}
                    onClick={() => setRoleFilter(r)}
                    className="rounded-full text-xs h-9 px-3 shrink-0 gap-1.5"
                  >
                    <Icon
                      className={cn(
                        "size-3.5",
                        roleFilter === r ? "text-primary-foreground" : meta.colorClass,
                      )}
                    />
                    <span>{meta.labelAr}</span>
                  </Button>
                );
              })}

              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger className="w-32 h-9 text-xs rounded-full border-border/80">
                  <SelectValue placeholder={isAr ? "الحالة" : "Status"} />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all" className="text-xs">
                    {isAr ? "كل الحالات" : "All Status"}
                  </SelectItem>
                  <SelectItem value="active" className="text-xs">
                    {isAr ? "نشط فقط" : "Active only"}
                  </SelectItem>
                  <SelectItem value="disabled" className="text-xs">
                    {isAr ? "معطّل فقط" : "Disabled only"}
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Staff Cards & Table List */}
          <Card className="rounded-3xl border border-border/70 shadow-sm overflow-hidden bg-card">
            <CardContent className="p-0">
              {loading ? (
                <div className="p-12 text-center space-y-3">
                  <Loader2 className="size-8 animate-spin mx-auto text-primary" />
                  <p className="text-xs text-muted-foreground">
                    {isAr ? "جارٍ تحميل طاقم العمل..." : "Loading staff..."}
                  </p>
                </div>
              ) : filteredStoreRows.length === 0 ? (
                <div className="p-16 text-center">
                  <div className="mx-auto mb-4 grid size-16 place-items-center rounded-3xl bg-muted/60 text-muted-foreground">
                    <Users className="size-8 opacity-60" />
                  </div>
                  <h3 className="text-base font-bold text-foreground mb-1">
                    {isAr ? "لا يوجد موظفون مطابقون" : "No matching staff"}
                  </h3>
                  <p className="text-xs text-muted-foreground max-w-sm mx-auto">
                    {isAr
                      ? "لم نجد أي موظف يطابق معايير البحث والفلترة المحددة حالياً."
                      : "No staff member matched your current search filters."}
                  </p>
                  {(search || roleFilter !== "all" || statusFilter !== "all") && (
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => {
                        setSearch("");
                        setRoleFilter("all");
                        setStatusFilter("all");
                      }}
                      className="mt-4 rounded-2xl text-xs"
                    >
                      {isAr ? "إعادة ضبط البحث" : "Reset Filters"}
                    </Button>
                  )}
                </div>
              ) : (
                <div className="divide-y divide-border/50">
                  {filteredStoreRows.map((r) => {
                    const isCurrentUser = r.id === user?.id;
                    const hasOwner = r.roles.some((ro: any) => ro.role === "owner");
                    const initials = (r.full_name ?? "?").slice(0, 2).toUpperCase();

                    return (
                      <div
                        key={r.id}
                        className="group flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-4 sm:p-5 hover:bg-muted/30 transition-colors"
                      >
                        {/* Left Info Column */}
                        <div className="flex items-start sm:items-center gap-3.5">
                          {/* Avatar */}
                          <div className="size-11 rounded-2xl bg-primary/10 text-primary grid place-items-center text-sm font-black border border-primary/20 shrink-0 shadow-2xs">
                            {initials}
                          </div>

                          {/* Details */}
                          <div className="space-y-1">
                            <div className="flex flex-wrap items-center gap-2">
                              <span className="text-sm font-black text-foreground">
                                {r.full_name ?? "—"}
                              </span>
                              {isCurrentUser && (
                                <Badge
                                  variant="secondary"
                                  className="text-[10px] font-bold rounded-lg px-2 py-0.5 bg-primary/15 text-primary border-primary/20"
                                >
                                  {isAr ? "أنت (حسابك)" : "You"}
                                </Badge>
                              )}
                              {r.is_active === false ? (
                                <Badge
                                  variant="outline"
                                  className="text-[10px] font-bold rounded-lg px-2 py-0.5 border-rose-500/40 text-rose-600 bg-rose-500/10"
                                >
                                  <XCircle className="size-3 me-1 inline" />
                                  {isAr ? "معطّل" : "Disabled"}
                                </Badge>
                              ) : (
                                <Badge
                                  variant="outline"
                                  className="text-[10px] font-bold rounded-lg px-2 py-0.5 border-emerald-500/40 text-emerald-600 bg-emerald-500/10"
                                >
                                  <CheckCircle2 className="size-3 me-1 inline" />
                                  {isAr ? "نشط" : "Active"}
                                </Badge>
                              )}
                            </div>

                            {/* Phone & Date */}
                            <div className="flex flex-wrap items-center gap-3 text-xs text-muted-foreground">
                              {r.phone && (
                                <span className="flex items-center gap-1 font-mono text-[11px] dir-ltr text-foreground/80">
                                  <Phone className="size-3 text-muted-foreground" />
                                  {toSystemDigits(r.phone)}
                                </span>
                              )}
                              <span className="flex items-center gap-1 text-[11px]">
                                <Calendar className="size-3 text-muted-foreground" />
                                <span>{isAr ? "انضم:" : "Joined:"}</span>
                                <span>{formatLuxuryDate(r.created_at).full}</span>
                              </span>
                            </div>

                            {/* Roles badges list */}
                            <div className="flex flex-wrap items-center gap-1.5 pt-1">
                              {r.roles.map((ro: any) => {
                                const meta = getRoleMeta(ro.role);
                                const Icon = meta.icon;
                                return (
                                  <Badge
                                    key={ro.id}
                                    variant="outline"
                                    className={cn(
                                      "gap-1.5 py-1 px-2.5 text-xs font-bold rounded-xl border",
                                      meta.badgeClass,
                                    )}
                                  >
                                    <Icon className="size-3.5" />
                                    <span>{meta.labelAr}</span>
                                    {canManageStore && !isCurrentUser && !hasOwner && (
                                      <button
                                        type="button"
                                        onClick={(e) => {
                                          e.stopPropagation();
                                          removeStoreRole(ro.id);
                                        }}
                                        className="ms-1 opacity-60 hover:opacity-100 hover:text-rose-600 transition"
                                        title={isAr ? "حذف هذا الدور" : "Remove role"}
                                      >
                                        <Trash2 className="size-3" />
                                      </button>
                                    )}
                                  </Badge>
                                );
                              })}
                            </div>
                          </div>
                        </div>

                        {/* Right Actions Column */}
                        <div className="flex items-center justify-between sm:justify-end gap-2 pt-2 sm:pt-0 border-t sm:border-t-0 border-border/40">
                          {canManageStore && !hasOwner && (
                            <Select onValueChange={(v) => assignStoreRole(r.id, v)}>
                              <SelectTrigger className="w-32 h-8 text-xs rounded-xl border-border/70">
                                <SelectValue placeholder={isAr ? "+ إضافة دور" : "+ Add role"} />
                              </SelectTrigger>
                              <SelectContent>
                                {STORE_ROLES.filter(
                                  (ro) => !r.roles.find((x: any) => x.role === ro),
                                ).map((ro) => (
                                  <SelectItem key={ro} value={ro} className="text-xs">
                                    {getRoleMeta(ro).labelAr}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          )}

                          {canManageStore &&
                            !hasOwner &&
                            !isCurrentUser &&
                            (r.is_active === false ? (
                              <Button
                                type="button"
                                size="sm"
                                variant="outline"
                                onClick={() => setUserActive(r.id, true)}
                                className="h-8 text-xs gap-1.5 rounded-xl border-emerald-500/40 text-emerald-600 hover:bg-emerald-500/10"
                              >
                                <UserCheck className="size-3.5" />
                                <span>{isAr ? "إعادة تفعيل" : "Reactivate"}</span>
                              </Button>
                            ) : (
                              <Button
                                type="button"
                                size="sm"
                                variant="ghost"
                                onClick={() => setUserActive(r.id, false)}
                                className="h-8 text-xs gap-1.5 rounded-xl text-muted-foreground hover:text-rose-600 hover:bg-rose-500/10"
                              >
                                <UserX className="size-3.5" />
                                <span>{isAr ? "تعطيل" : "Disable"}</span>
                              </Button>
                            ))}

                          {canManageStore && !isCurrentUser && !hasOwner && (
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => openEditUser(r)}
                              className="size-8 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted"
                              title={isAr ? "تعديل بيانات الموظف" : "Edit employee"}
                            >
                              <Pencil className="size-4" />
                            </Button>
                          )}

                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => setSelectedUser(r)}
                            className="size-8 rounded-xl text-muted-foreground hover:text-foreground hover:bg-muted"
                            title={isAr ? "عرض بطاقة الموظف" : "View Card"}
                          >
                            <Eye className="size-4" />
                          </Button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      )}

      {/* Platform Admins View (Superadmins Only) */}
      {isSuper && activeTab === "platform" && (
        <Card className="border-amber-500/40 shadow-sm overflow-hidden rounded-3xl bg-card">
          <CardHeader className="p-5 border-b border-border/70 bg-amber-500/5">
            <div className="flex items-center justify-between">
              <div>
                <CardTitle className="text-sm font-bold text-foreground flex items-center gap-2">
                  <Crown className="size-4.5 text-amber-500" />
                  <span>
                    {isAr
                      ? "مدراء المنصة السحابية (جدول platform_admins)"
                      : "Platform Superadmins Registry"}
                  </span>
                </CardTitle>
                <CardDescription className="text-xs text-muted-foreground mt-0.5">
                  {isAr
                    ? "سجل مستقل تماماً يختص بالتحكم في الباقات والموديلات السحابية والتراخيص العامة."
                    : "Strictly isolated infrastructure ledger for platform governance."}
                </CardDescription>
              </div>
              <Badge className="bg-amber-500/20 text-amber-700 dark:text-amber-300 border-amber-500/40 text-xs font-semibold">
                SaaS Infrastructure
              </Badge>
            </div>
          </CardHeader>
          <CardContent className="p-0">
            <div className="divide-y divide-border/60">
              {platformAdminRows.map((pa) => (
                <div
                  key={pa.id}
                  className="flex items-center justify-between p-4 sm:p-5 hover:bg-muted/30 transition-colors"
                >
                  <div className="flex items-center gap-3">
                    <div className="size-10 rounded-2xl bg-amber-500/15 text-amber-600 dark:text-amber-400 grid place-items-center text-xs font-bold border border-amber-500/30">
                      <Crown className="size-5" />
                    </div>
                    <div>
                      <div className="font-bold text-sm text-foreground flex items-center gap-2">
                        <span>{pa.full_name}</span>
                        {pa.user_id === user?.id && (
                          <span className="text-[11px] font-normal text-amber-500">
                            ({isAr ? "أنت" : "You"})
                          </span>
                        )}
                      </div>
                      <div className="text-[11px] text-muted-foreground font-mono">
                        User ID: {pa.user_id.slice(0, 8)}...
                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-3">
                    <VortexDateBadge date={pa.created_at} size="sm" variant="subtle" />
                    {pa.user_id !== user?.id && (
                      <Button
                        type="button"
                        size="sm"
                        variant="ghost"
                        onClick={() => revokePlatformAdmin(pa.id)}
                        className="h-8 text-xs text-muted-foreground hover:text-rose-600 hover:bg-rose-500/10 rounded-xl"
                      >
                        {isAr ? "إلغاء الصلاحية" : "Revoke"}
                      </Button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* User Detail Sheet */}
      <Sheet open={Boolean(selectedUser)} onOpenChange={(open) => !open && setSelectedUser(null)}>
        <SheetContent side="left" className="sm:max-w-md w-full p-0 flex flex-col">
          {selectedUser && (
            <>
              <div className="p-6 border-b border-border/60 bg-muted/20">
                <div className="flex items-center gap-3">
                  <div className="size-12 rounded-2xl bg-primary/10 text-primary grid place-items-center text-base font-black border border-primary/20">
                    {(selectedUser.full_name ?? "?").slice(0, 2).toUpperCase()}
                  </div>
                  <div>
                    <SheetTitle className="text-lg font-black text-foreground">
                      {selectedUser.full_name ?? "—"}
                    </SheetTitle>
                    <SheetDescription className="text-xs text-muted-foreground">
                      معرف الموظف: {selectedUser.id}
                    </SheetDescription>
                  </div>
                </div>
              </div>

              <div className="flex-1 overflow-y-auto p-6 space-y-5">
                {/* Details list */}
                <div className="space-y-3 p-4 rounded-3xl bg-card border border-border/70">
                  <div className="flex items-center justify-between text-xs">
                    <span className="font-bold text-muted-foreground">حالة الحساب</span>
                    {selectedUser.is_active === false ? (
                      <Badge
                        variant="outline"
                        className="border-rose-500/40 text-rose-600 bg-rose-500/10 font-bold"
                      >
                        معطّل
                      </Badge>
                    ) : (
                      <Badge
                        variant="outline"
                        className="border-emerald-500/40 text-emerald-600 bg-emerald-500/10 font-bold"
                      >
                        نشط
                      </Badge>
                    )}
                  </div>

                  {selectedUser.phone && (
                    <div className="flex items-center justify-between text-xs pt-2 border-t border-border/40">
                      <span className="font-bold text-muted-foreground">رقم الهاتف</span>
                      <span className="font-mono font-bold text-foreground dir-ltr">
                        {toSystemDigits(selectedUser.phone)}
                      </span>
                    </div>
                  )}

                  <div className="flex items-center justify-between text-xs pt-2 border-t border-border/40">
                    <span className="font-bold text-muted-foreground">تاريخ التسجيل</span>
                    <span className="font-bold text-foreground">
                      {formatLuxuryDate(selectedUser.created_at, { showDayName: true }).full}
                    </span>
                  </div>
                </div>

                {/* Roles & Permissions Card */}
                <div className="space-y-2.5">
                  <span className="text-xs font-black text-foreground block">
                    الأدوار والصلاحيات المسندة
                  </span>
                  <div className="space-y-2">
                    {selectedUser.roles.map((ro: any) => {
                      const meta = getRoleMeta(ro.role);
                      const Icon = meta.icon;
                      return (
                        <div
                          key={ro.id}
                          className="flex items-center justify-between p-3 rounded-2xl border border-border/70 bg-card"
                        >
                          <div className="flex items-center gap-2.5">
                            <div
                              className={cn(
                                "size-8 rounded-xl grid place-items-center border",
                                meta.badgeClass,
                              )}
                            >
                              <Icon className="size-4" />
                            </div>
                            <span className="text-xs font-bold text-foreground">
                              {meta.labelAr}
                            </span>
                          </div>
                          <Badge variant="secondary" className="text-[10px] font-bold">
                            صلاحية متجر
                          </Badge>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>
            </>
          )}
        </SheetContent>
      </Sheet>

      {/* Edit Employee Dialog */}
      <Dialog
        open={editOpen}
        onOpenChange={(open) => {
          setEditOpen(open);
          if (!open) setEditUser(null);
        }}
      >
        <DialogContent className="max-w-md rounded-3xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-base font-black">
              <Pencil className="size-5 text-primary" />
              <span>{isAr ? "تعديل بيانات الموظف" : "Edit Employee"}</span>
            </DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground">
              {isAr
                ? "يمكنك تعديل الاسم ورقم الهاتف واللغة فقط."
                : "You can edit the name, phone, and language only."}
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-2">
            <div className="space-y-1.5">
              <label className="text-xs font-bold text-foreground">
                {isAr ? "الاسم الكامل" : "Full Name"}
              </label>
              <Input
                value={editName}
                onChange={(e) => setEditName(e.target.value)}
                maxLength={120}
                className="h-10 text-xs rounded-2xl border-border/70"
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-foreground">
                {isAr ? "رقم الهاتف (اختياري)" : "Phone (optional)"}
              </label>
              <Input
                type="tel"
                value={editPhone}
                onChange={(e) => setEditPhone(e.target.value)}
                maxLength={40}
                dir="ltr"
                className="h-10 text-xs rounded-2xl border-border/70"
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-bold text-foreground">
                {isAr ? "اللغة" : "Language"}
              </label>
              <Select value={editLanguage} onValueChange={setEditLanguage}>
                <SelectTrigger className="w-full h-10 text-xs rounded-2xl border-border/70">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ar" className="text-xs">
                    العربية
                  </SelectItem>
                  <SelectItem value="en" className="text-xs">
                    English
                  </SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <DialogFooter className="gap-2">
            <Button
              variant="outline"
              size="sm"
              className="rounded-2xl h-10 px-4"
              disabled={editSaving}
              onClick={() => setEditOpen(false)}
            >
              {isAr ? "إلغاء" : "Cancel"}
            </Button>
            <Button
              size="sm"
              className="rounded-2xl h-10 px-5 gap-1.5 font-bold"
              disabled={editSaving || !editName.trim()}
              onClick={() => void saveEditUser()}
            >
              {editSaving && <Loader2 className="size-4 animate-spin" />}
              <span>
                {editSaving
                  ? isAr
                    ? "جارٍ الحفظ..."
                    : "Saving..."
                  : isAr
                    ? "حفظ التغييرات"
                    : "Save Changes"}
              </span>
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Create-User Dialog */}
      <Dialog
        open={addOpen}
        onOpenChange={(open) => {
          if (!open && issued) return;
          setAddOpen(open);
          if (!open) resetCreateDialog();
        }}
      >
        <DialogContent
          className="max-w-md rounded-3xl"
          onEscapeKeyDown={(e) => {
            if (issued) e.preventDefault();
          }}
          onPointerDownOutside={(e) => {
            if (issued) e.preventDefault();
          }}
          onInteractOutside={(e) => {
            if (issued) e.preventDefault();
          }}
        >
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-base font-black">
              <UserPlus className="size-5 text-primary" />
              <span>
                {issued
                  ? isAr
                    ? "بيانات دخول الموظف الجديد"
                    : "Staff Sign-in Credentials"
                  : isAr
                    ? "إضافة موظف جديد للمتجر"
                    : "Add Store Staff Member"}
              </span>
            </DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground">
              {issued
                ? isAr
                  ? "انسخ بيانات الدخول وسلّمها للموظف. لن يتم عرض كلمة المرور مرة أخرى لدواعي الأمان."
                  : "Copy these credentials and hand them to the user. The password is not shown again."
                : isAr
                  ? "سيتم إنشاء الحساب وتعيين الدور التشغيلي فوراً دون الحاجة لتسجيل مسبق."
                  : "The account and its store role are provisioned immediately."}
            </DialogDescription>
          </DialogHeader>

          {issued ? (
            /* Success View */
            <div className="space-y-4 py-2">
              <div className="rounded-2xl border border-emerald-500/30 bg-emerald-500/10 p-3.5 text-xs text-emerald-700 dark:text-emerald-400 flex items-start gap-2.5">
                <Check className="size-4 shrink-0 mt-0.5 text-emerald-600" />
                <span className="font-semibold">
                  {isAr
                    ? "تم إنشاء الحساب بنجاح وتعيين الصلاحيات! سلّم البيانات التالية للموظف الآن."
                    : "Account created and role assigned successfully."}
                </span>
              </div>

              <div className="space-y-3 rounded-2xl border border-border/70 bg-muted/30 p-4">
                <CredentialRow label={isAr ? "الاسم" : "Name"} value={issued.full_name} />
                {issued.phone && (
                  <CredentialRow label={isAr ? "رقم الهاتف" : "Phone"} value={issued.phone} />
                )}
                <CredentialRow
                  label={isAr ? "معرف الدخول / البريد" : "Login Identifier / Email"}
                  value={issued.email}
                />
                <div className="flex items-center justify-between gap-3 pt-1 border-t border-border/40">
                  <span className="text-[11px] font-bold text-muted-foreground">
                    {isAr ? "كلمة المرور" : "Password"}
                  </span>
                  <div className="flex items-center gap-2">
                    <code className="rounded-xl bg-background px-2.5 py-1 font-mono text-xs text-foreground font-black border border-border/70">
                      {issued.password}
                    </code>
                    <Button
                      type="button"
                      size="sm"
                      variant="outline"
                      className="h-7 gap-1 rounded-xl px-2 text-[11px]"
                      onClick={() => void copyToClipboard(issued.password, "password")}
                    >
                      {copiedField === "password" ? (
                        <Check className="size-3 text-emerald-500" />
                      ) : (
                        <Copy className="size-3" />
                      )}
                      <span>{isAr ? "نسخ" : "Copy"}</span>
                    </Button>
                  </div>
                </div>
                <CredentialRow
                  label={isAr ? "الدور" : "Role"}
                  value={getRoleMeta(issued.role).labelAr}
                />
              </div>

              <Button
                type="button"
                variant="outline"
                className="w-full gap-2 rounded-2xl text-xs h-10 font-bold border-primary/30 text-primary hover:bg-primary/10"
                onClick={() =>
                  void copyToClipboard(
                    isAr
                      ? `مرحباً بك في نظام فورتكس!\nبيانات الدخول لحسابك:\n${issued.phone ? `الهاتف: ${issued.phone}\n` : ""}معرف الدخول: ${issued.email}\nكلمة المرور: ${issued.password}\nرابط الدخول: ${window.location.origin}/auth`
                      : `Welcome to Vortex ERP!\nYour sign-in credentials:\n${issued.phone ? `Phone: ${issued.phone}\n` : ""}Login: ${issued.email}\nPassword: ${issued.password}\nLink: ${window.location.origin}/auth`,
                    "all",
                  )
                }
              >
                {copiedField === "all" ? (
                  <Check className="size-4 text-emerald-500" />
                ) : (
                  <MessageCircle className="size-4" />
                )}
                <span>
                  {isAr ? "نسخ رسالة الترحيب وبيانات الدخول كاملة" : "Copy Full Welcome Message"}
                </span>
              </Button>
            </div>
          ) : (
            /* Input Form */
            <div className="space-y-4 py-2">
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-foreground">
                  {isAr ? "الاسم الكامل للموظف" : "Full Name"}
                </label>
                <Input
                  value={addName}
                  onChange={(e) => setAddName(e.target.value)}
                  placeholder={isAr ? "مثال: عبد الرحمن محمد" : "e.g. Ahmed Ali"}
                  className="h-10 text-xs rounded-2xl border-border/70"
                  maxLength={120}
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-foreground">
                  {isAr ? "رقم الهاتف (لتسجيل الدخول الفوري)" : "Phone number (for sign in)"}
                </label>
                <div className="flex gap-2">
                  <CountrySelector
                    value={addCountry}
                    onChange={setAddCountry}
                    disabled={addSaving}
                  />
                  <Input
                    type="tel"
                    value={addPhone}
                    onChange={(e) => setAddPhone(e.target.value)}
                    placeholder={addCountry.placeholder}
                    className="h-10 text-xs rounded-2xl border-border/70 flex-1 dir-ltr text-right"
                    maxLength={addCountry.maxLength + 4}
                  />
                </div>
                <p className="text-[11px] text-muted-foreground">
                  {isAr
                    ? "يُستخدم رقم الهاتف لتسجيل الدخول مباشرة بدون تعقيد."
                    : "Used directly to sign in by phone number."}
                </p>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-foreground">
                  {isAr
                    ? "البريد الإلكتروني (اختياري، في حال عدم استخدام الهاتف)"
                    : "Email (optional, if no phone)"}
                </label>
                <Input
                  type="email"
                  value={addEmail}
                  onChange={(e) => setAddEmail(e.target.value)}
                  placeholder="employee@vortex.app"
                  className="h-10 text-xs rounded-2xl border-border/70"
                  dir="ltr"
                  maxLength={255}
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-foreground">
                  {isAr ? "الدور التشغيلي الأولي" : "Store Role"}
                </label>
                <Select value={addRole} onValueChange={(v) => setAddRole(v as StoreRole)}>
                  <SelectTrigger className="w-full h-10 text-xs rounded-2xl border-border/70">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {STORE_ROLES.map((ro) => (
                      <SelectItem key={ro} value={ro} className="text-xs">
                        {getRoleMeta(ro).labelAr}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="rounded-2xl border border-border/60 bg-muted/20 p-3 text-[11px] leading-relaxed text-muted-foreground">
                <div className="flex items-center justify-between gap-3">
                  <label className="text-xs font-bold text-foreground">
                    {isAr ? "كلمة المرور" : "Password"}
                  </label>
                  <label className="flex items-center gap-2 text-[11px] text-muted-foreground">
                    <input
                      type="checkbox"
                      checked={useGeneratedPassword}
                      onChange={(e) => setUseGeneratedPassword(e.target.checked)}
                      className="accent-primary"
                    />
                    <span>{isAr ? "توليد تلقائي" : "Generate automatically"}</span>
                  </label>
                </div>
                {!useGeneratedPassword && (
                  <>
                    <label className="block pt-2 text-[11px] font-semibold text-foreground">
                      {isAr ? "كلمة المرور" : "Password"}
                    </label>
                    <Input
                      type="password"
                      value={addPassword}
                      onChange={(e) => setAddPassword(e.target.value)}
                      placeholder={isAr ? "8 أحرف على الأقل" : "At least 8 characters"}
                      className="h-10 text-xs rounded-2xl border-border/70"
                      autoComplete="new-password"
                      maxLength={128}
                    />
                    <label className="block pt-2 text-[11px] font-semibold text-foreground">
                      {isAr ? "تأكيد كلمة المرور" : "Confirm Password"}
                    </label>
                    <Input
                      type="password"
                      value={addConfirmPassword}
                      onChange={(e) => setAddConfirmPassword(e.target.value)}
                      placeholder={isAr ? "أعد كتابة كلمة المرور" : "Re-enter password"}
                      className="h-10 text-xs rounded-2xl border-border/70"
                      autoComplete="new-password"
                      maxLength={128}
                    />
                  </>
                )}
                <p className="text-[11px] leading-relaxed text-muted-foreground">
                  {useGeneratedPassword
                    ? isAr
                      ? "سيتم توليد كلمة مرور آمنة في السيرفر وعرضها مرة واحدة بعد نجاح الإنشاء."
                      : "A secure password will be generated on the server and shown once after creation."
                    : isAr
                      ? "لن يتم حفظ كلمة المرور أو عرضها بعد إنشاء الحساب."
                      : "The password will not be stored or shown after account creation."}
                </p>
              </div>
            </div>
          )}

          <DialogFooter className="gap-2">
            {issued ? (
              <Button
                size="sm"
                className="rounded-2xl h-10 px-6 font-bold"
                onClick={() => {
                  setAddOpen(false);
                  resetCreateDialog();
                }}
              >
                {isAr ? "تم، إنهاء" : "Done"}
              </Button>
            ) : (
              <>
                <Button
                  variant="outline"
                  size="sm"
                  className="rounded-2xl h-10 px-4"
                  onClick={() => setAddOpen(false)}
                >
                  {isAr ? "إلغاء" : "Cancel"}
                </Button>
                <Button
                  size="sm"
                  className="rounded-2xl h-10 px-5 gap-1.5 font-bold"
                  disabled={addSaving || !addName.trim() || (!addPhone.trim() && !addEmail.trim())}
                  onClick={() => void createStoreUser()}
                >
                  {addSaving && <Loader2 className="size-4 animate-spin" />}
                  <span>
                    {addSaving
                      ? isAr
                        ? "جارٍ إنشاء الحساب..."
                        : "Creating..."
                      : isAr
                        ? "إنشاء الحساب فوراً"
                        : "Create Account"}
                  </span>
                </Button>
              </>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

function CredentialRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between gap-3">
      <span className="text-[11px] font-bold text-muted-foreground">{label}</span>
      <code className="rounded-xl bg-background px-2.5 py-1 font-mono text-xs text-foreground font-semibold border border-border/70 break-all">
        {value}
      </code>
    </div>
  );
}

import { ModuleGuard, useModules } from "@/lib/modules";
import { createFileRoute } from "@tanstack/react-router";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useCallback, useMemo, useState } from "react";
import { PageHeader } from "@/components/page-header";
import { supabase } from "@/integrations/supabase/client";
import { useI18n } from "@/lib/i18n";
import {
  Boxes,
  LayoutGrid,
  List,
  Pencil,
  Plus,
  Star,
  TableProperties,
  Trash2,
  Warehouse,
  X,
  Lock,
} from "lucide-react";
import { toast } from "sonner";

export function isSystemMainWarehouse(
  wh?: { is_default?: boolean | null; code?: string | null; name?: string | null } | null,
): boolean {
  if (!wh) return false;
  return Boolean(
    wh.is_default || wh.code?.toUpperCase() === "MAIN" || wh.name?.trim() === "المخزن الرئيسي",
  );
}
import { VortexMetricCard } from "@/components/vortex-ui";
import { IconButton } from "@/components/ui/icon-button";
import { RecordsView, type RecordsViewMode } from "@/components/ui/records-view";
import {
  TableToolbar,
  ToolbarAction,
  type FilterDefinition,
  type FilterValues,
  type SortOption,
} from "@/components/ui/table-toolbar";
import { RecordsViewToggle } from "@/components/ui/records-view-toggle";
import { usePersistedViewMode } from "@/hooks/use-persisted-view-mode";
import { QuickFilterBar } from "@/components/ui/quick-filter-bar";
import { PrimaryAction } from "@/components/ui/primary-action";
import { type DataTableColumn, type DataTableSort } from "@/components/ui/data-table";
import { useBreakpoint } from "@/design/breakpoints";
import { useRealtimeTable } from "@/lib/realtime";
import { QUERY_KEYS } from "@/lib/query-keys";

export const Route = createFileRoute("/_app/warehouses")({
  head: () => ({ meta: [{ title: "المستودعات — فورتيكس ERP" }] }),
  component: () => (
    <ModuleGuard moduleId="multi_warehouse">
      <WarehousesPage />
    </ModuleGuard>
  ),
});

type Row = {
  id: string;
  name: string;
  name_ar: string | null;
  code: string | null;
  address: string | null;
  is_default: boolean;
  is_active: boolean;
};

type ViewMode = RecordsViewMode;
type QuickFilter = "all" | "active" | "inactive" | "default";

function WarehousesPage() {
  const { checkQuota } = useModules();
  const { t, lang } = useI18n();
  const isRtl = lang === "ar";
  const qc = useQueryClient();
  const breakpoint = useBreakpoint();
  const tableUsesHorizontalScroll =
    breakpoint === "xs" || breakpoint === "sm" || breakpoint === "md";

  const [q, setQ] = useState("");
  const [filters, setFilters] = useState<FilterValues>({});
  const [sortKey, setSortKey] = useState<string>("default_first");
  const [sort, setSort] = useState<DataTableSort | null>(null);
  const [quickFilter, setQuickFilter] = useState<QuickFilter>("all");
  const [viewMode, setViewMode] = usePersistedViewMode("warehouses", "cards");
  const [editing, setEditing] = useState<Row | null>(null);
  const [open, setOpen] = useState(false);
  const [deleting, setDeleting] = useState<string | null>(null);

  /*
   * The warehouse directory now flows through the shared QueryClient instead of
   * an ad-hoc `useQuery` with a bespoke key, so sign-out drops it, Realtime can
   * patch it, and a save/delete invalidates exactly this key. The read itself is
   * unchanged: same table, same columns, same ordering.
   */
  const {
    data = [],
    isLoading,
    isFetching,
    error,
    refetch,
  } = useQuery({
    queryKey: QUERY_KEYS.warehouses,
    queryFn: async () => {
      const { data, error } = await supabase
        .from("warehouses")
        .select("id, name, name_ar, code, address, is_default, is_active")
        .order("is_default", { ascending: false })
        .order("name");
      if (error) throw error;
      return (data ?? []) as Row[];
    },
    staleTime: 60_000,
  });

  /*
   * Rows are the raw table rows but the screen enriches the display (bilingual
   * name fallbacks, default/active tone). `invalidate` keeps a half-built row
   * from ever rendering, at the cost of one authoritative refetch per burst.
   */
  useRealtimeTable<Row>(
    { table: "warehouses", queryKey: QUERY_KEYS.warehouses, mode: "invalidate", debounceMs: 150 },
    qc,
  );

  const label = useCallback(
    (r: Row) => (isRtl ? r.name_ar || r.name : r.name || r.name_ar || "—"),
    [isRtl],
  );

  /* ---------------- search + filter + quick chips ---------------- */
  const searched = useMemo(() => {
    const s = q.trim().toLowerCase();
    if (!s) return data;
    return data.filter((r) =>
      [r.name, r.name_ar, r.code, r.address].some((x) => (x ?? "").toLowerCase().includes(s)),
    );
  }, [data, q]);

  const filterDefinitions: FilterDefinition[] = useMemo(
    () => [
      {
        key: "is_active",
        label: isRtl ? "حالة المستودع" : "Status",
        type: "select",
        options: [
          { value: "true", label: isRtl ? "نشط فقط" : "Active only" },
          { value: "false", label: isRtl ? "غير نشط فقط" : "Inactive only" },
        ],
      },
      {
        key: "is_default",
        label: isRtl ? "المستودع الافتراضي" : "Default warehouse",
        type: "boolean",
      },
    ],
    [isRtl],
  );

  const filtered = useMemo(() => {
    return searched.filter((r) => {
      if (filters.is_active && String(r.is_active) !== filters.is_active) return false;
      if (filters.is_default === "true" && !r.is_default) return false;
      if (filters.is_default === "false" && r.is_default) return false;
      if (quickFilter === "active" && !r.is_active) return false;
      if (quickFilter === "inactive" && r.is_active) return false;
      if (quickFilter === "default" && !r.is_default) return false;
      return true;
    });
  }, [searched, filters, quickFilter]);

  /* ---------------- KPI ---------------- */
  const { activeCount, inactiveCount, defaultCount } = useMemo(() => {
    let active = 0;
    let inactive = 0;
    let isDefault = 0;
    for (const r of data) {
      if (r.is_active) active++;
      else inactive++;
      if (r.is_default) isDefault++;
    }
    return { activeCount: active, inactiveCount: inactive, defaultCount: isDefault };
  }, [data]);

  /* ---------------- sort ---------------- */
  const sortOptions: SortOption[] = useMemo(
    () => [
      { value: "default_first", label: isRtl ? "الافتراضي أولاً" : "Default first" },
      { value: "name_asc", label: isRtl ? "الاسم (أ - ي)" : "Name (A - Z)" },
      { value: "name_desc", label: isRtl ? "الاسم (ي - أ)" : "Name (Z - A)" },
      { value: "code_asc", label: isRtl ? "الرمز (أ - ي)" : "Code (A - Z)" },
      { value: "status", label: isRtl ? "الحالة" : "Status" },
    ],
    [isRtl],
  );

  const sortedRows = useMemo(() => {
    const list = [...filtered];
    const byName = (a: Row, b: Row) => label(a).localeCompare(label(b), isRtl ? "ar" : "en");

    // A column-header click (classic table) takes precedence over the preset.
    if (sort) {
      const dir = sort.direction === "asc" ? 1 : -1;
      switch (sort.key) {
        case "name":
          return list.sort((a, b) => byName(a, b) * dir);
        case "code":
          return list.sort((a, b) => (a.code ?? "").localeCompare(b.code ?? "") * dir);
        case "status":
          return list.sort((a, b) => (Number(a.is_active) - Number(b.is_active)) * dir);
        case "is_default":
          return list.sort((a, b) => (Number(a.is_default) - Number(b.is_default)) * dir);
        default:
          break;
      }
    }

    switch (sortKey) {
      case "name_asc":
        return list.sort(byName);
      case "name_desc":
        return list.sort((a, b) => byName(b, a));
      case "code_asc":
        return list.sort((a, b) => (a.code ?? "").localeCompare(b.code ?? ""));
      case "status":
        return list.sort((a, b) => Number(b.is_active) - Number(a.is_active));
      default:
        return list.sort((a, b) => Number(b.is_default) - Number(a.is_default) || byName(a, b));
    }
  }, [filtered, sort, sortKey, label, isRtl]);

  /* ---------------- mutations (unchanged behaviour) ---------------- */
  const remove = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.from("warehouses").delete().eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      toast.success(t("common.deleted") || "Deleted");
      qc.invalidateQueries({ queryKey: QUERY_KEYS.warehouses });
      qc.invalidateQueries({ queryKey: ["warehouses-admin"] });
    },
    onError: (e: Error) => toast.error(e.message),
  });

  const setDefault = useMutation({
    mutationFn: async (id: string) => {
      await supabase.from("warehouses").update({ is_default: false }).neq("id", id);
      const { error } = await supabase
        .from("warehouses")
        .update({ is_default: true, is_active: true })
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: QUERY_KEYS.warehouses });
      qc.invalidateQueries({ queryKey: ["warehouses-admin"] });
    },
    onError: (e: Error) => toast.error(e.message),
  });

  /* Stable per-row handlers so a card is not re-created on every parent render. */
  const openNew = useCallback(() => {
    const qCheck = checkQuota("warehouses", data.length);
    if (!qCheck.allowed) {
      toast.error(isRtl ? qCheck.message?.ar : qCheck.message?.en);
      return;
    }
    setEditing(null);
    setOpen(true);
  }, [checkQuota, data.length, isRtl]);

  const openEdit = useCallback((row: Row) => {
    setEditing(row);
    setOpen(true);
  }, []);

  const removeRow = useCallback(
    (id: string) => {
      if (deleting) return;
      const target = data.find((w) => w.id === id);
      if (target && isSystemMainWarehouse(target)) {
        toast.error(
          isRtl
            ? "لا يمكن حذف المخزن الرئيسي الافتراضي — هذا المخزن أساسي للنظام وحركات المخزون."
            : "Cannot delete default main warehouse — it is essential for system inventory.",
        );
        return;
      }
      if (!confirm(`${t("common.delete")}?`)) return;
      setDeleting(id);
      remove.mutate(id, { onSettled: () => setDeleting(null) });
    },
    [deleting, remove, t, data, isRtl],
  );

  const handleSetDefault = useCallback((id: string) => setDefault.mutate(id), [setDefault]);

  /* ---------------- classic table columns ---------------- */
  const columns = useMemo<DataTableColumn<Row>[]>(
    () => [
      {
        key: "name",
        header: t("warehouses.name"),
        sortable: true,
        width: "w-[280px]",
        sortValue: (r) => label(r),
        cell: (r) => (
          <div className="py-0.5">
            <div className="flex items-center gap-2 font-medium text-foreground">
              <span className="truncate">{label(r)}</span>
              {r.is_default && (
                <span className="inline-flex items-center gap-1 rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-medium text-primary">
                  <Star className="h-3 w-3" />
                  {t("warehouses.is_default")}
                </span>
              )}
            </div>
            {(isRtl ? r.name : r.name_ar) && (
              <div className="text-[11px] text-muted-foreground">{isRtl ? r.name : r.name_ar}</div>
            )}
          </div>
        ),
      },
      {
        key: "code",
        header: t("warehouses.code"),
        sortable: true,
        width: "w-[140px]",
        sortValue: (r) => r.code ?? "",
        cell: (r) => (
          <span className="font-mono text-xs text-muted-foreground">{r.code ?? "—"}</span>
        ),
      },
      {
        key: "address",
        header: t("warehouses.address"),
        width: "w-[260px]",
        cell: (r) => (
          <span className="block truncate text-muted-foreground">{r.address ?? "—"}</span>
        ),
      },
      {
        key: "status",
        header: t("common.status"),
        sortable: true,
        align: "end",
        width: "w-[120px]",
        sortValue: (r) => Number(r.is_active),
        cell: (r) => (
          <span
            className={`inline-flex rounded-full px-2 py-0.5 text-[10px] font-medium ${r.is_active ? "bg-success/10 text-success" : "bg-muted text-muted-foreground"}`}
          >
            {r.is_active ? t("common.active") : t("common.inactive")}
          </span>
        ),
      },
      {
        key: "actions",
        header: t("common.actions"),
        align: "end",
        width: "w-[150px]",
        cell: (r) => (
          <div className="flex items-center justify-end gap-1">
            {!r.is_default && (
              <IconButton
                size="sm"
                variant="outline"
                tooltip
                ariaLabel={t("warehouses.set_default")}
                icon={<Star className="size-3.5" />}
                round
                onClick={() => handleSetDefault(r.id)}
              />
            )}
            <IconButton
              size="sm"
              variant="outline"
              tooltip
              ariaLabel={t("common.edit")}
              icon={<Pencil className="size-3.5" />}
              round
              onClick={() => openEdit(r)}
            />
            {isSystemMainWarehouse(r) ? (
              <span
                title={
                  isRtl
                    ? "المخزن الرئيسي الافتراضي — محمي من الحذف"
                    : "Default Main Warehouse — protected from deletion"
                }
                className="grid size-8 place-items-center rounded-full border border-amber-500/30 bg-amber-500/10 text-amber-600 dark:text-amber-400"
              >
                <Lock className="size-3.5" />
              </span>
            ) : (
              <IconButton
                size="sm"
                variant="danger"
                tooltip
                ariaLabel={t("common.delete")}
                icon={<Trash2 className="size-3.5" />}
                round
                loading={deleting === r.id}
                onClick={() => removeRow(r.id)}
              />
            )}
          </div>
        ),
      },
    ],
    [t, label, isRtl, handleSetDefault, openEdit, removeRow, deleting],
  );

  const hasActiveCriteria = Boolean(q.trim()) || Object.keys(filters).length > 0;

  const rendererProps = (r: Row) => ({
    row: r,
    isRtl,
    label,
    onEdit: openEdit,
    onDelete: removeRow,
    onSetDefault: handleSetDefault,
    deleting: deleting === r.id,
    editLabel: t("common.edit"),
    deleteLabel: t("common.delete"),
    setDefaultLabel: t("warehouses.set_default"),
    defaultLabel: t("warehouses.is_default"),
    activeLabel: t("common.active"),
    inactiveLabel: t("common.inactive"),
  });

  return (
    <div className="space-y-4 pb-12">
      <PageHeader title={t("warehouses.title")} subtitle={t("warehouses.subtitle")} />

      {/* ─── KPI cards ─── */}
      <div className="grid grid-cols-2 gap-3 sm:gap-4 lg:grid-cols-4">
        <VortexMetricCard
          title={isRtl ? "إجمالي المستودعات" : "Total warehouses"}
          value={data.length}
          subtitle={isRtl ? "المحمّلة حالياً" : "Currently loaded"}
          icon={<Warehouse className="size-5" />}
          tone="info"
        />
        <VortexMetricCard
          title={isRtl ? "نشط" : "Active"}
          value={activeCount}
          subtitle={isRtl ? "جاهز للاستخدام" : "Ready to use"}
          icon={<Boxes className="size-5" />}
          tone="success"
          highlight={quickFilter === "active"}
          onClick={() => setQuickFilter("active")}
        />
        <VortexMetricCard
          title={isRtl ? "غير نشط" : "Inactive"}
          value={inactiveCount}
          subtitle={isRtl ? "موقوف مؤقتاً" : "Temporarily disabled"}
          icon={<Boxes className="size-5" />}
          tone="warning"
          highlight={quickFilter === "inactive"}
          onClick={() => setQuickFilter("inactive")}
        />
        <VortexMetricCard
          title={isRtl ? "الافتراضي" : "Default"}
          value={defaultCount}
          subtitle={isRtl ? "مستودع الترحيل الافتراضي" : "Default posting warehouse"}
          icon={<Star className="size-5" />}
          tone="default"
          highlight={quickFilter === "default"}
          onClick={() => setQuickFilter("default")}
        />
      </div>

      {/* ─── Standard VORTEX TableToolbar: search + filters + sort + view + add ─── */}
      <TableToolbar
        sticky
        lang={lang}
        search={{
          value: q,
          onValueChange: setQ,
          placeholder: isRtl
            ? "ابحث بالاسم أو الرمز أو العنوان..."
            : "Search by name, code or address…",
          resultCount: filtered.length,
          loading: isFetching && !isLoading,
        }}
        filters={{ definitions: filterDefinitions, values: filters, onValueChange: setFilters }}
        sort={{
          options: sortOptions,
          value: sortKey,
          onValueChange: (value) => {
            setSortKey(value);
            // A preset replaces whatever the table header had selected.
            setSort(null);
          },
          label: isRtl ? "ترتيب" : "Sort",
        }}
        viewToggle={<RecordsViewToggle value={viewMode} onChange={setViewMode} />}
        action={
          <PrimaryAction
            label={t("warehouses.new")}
            icon={<Plus />}

            onClick={openNew}
          />
        }
      >
        <QuickFilterBar
          ariaLabel={isRtl ? "فلاتر سريعة للمستودعات" : "Warehouse quick filters"}
          value={quickFilter}
          onChange={(id) => setQuickFilter(id as QuickFilter)}
          items={[
            { id: "all", label: isRtl ? "الكل" : "All", count: data.length, tone: "primary" },
            {
              id: "active",
              label: isRtl ? "النشطة" : "Active",
              count: activeCount,
              tone: "success",
            },
            {
              id: "inactive",
              label: isRtl ? "غير النشطة" : "Inactive",
              count: inactiveCount,
              tone: "warning",
            },
            {
              id: "default",
              label: isRtl ? "الافتراضي" : "Default",
              count: defaultCount,
              tone: "info",
            },
          ]}
        />
      </TableToolbar>

      {/* ─── Records: cards / list / classic table — shared scaffold ─── */}
      <RecordsView<Row>
        rows={sortedRows}
        getRowId={(r) => r.id}
        viewMode={viewMode}
        loading={isLoading}
        refreshing={isFetching && !isLoading}
        error={error}
        onRetry={() => void refetch()}
        columns={columns}
        sort={sort}
        onSortChange={setSort}
        minWidth={1000}
        horizontalScroll={tableUsesHorizontalScroll}
        onRowClick={openEdit}
        renderCard={(r) => <WarehouseCard {...rendererProps(r)} />}
        renderListRow={(r) => <WarehouseListRow {...rendererProps(r)} />}
        empty={{
          icon: <Boxes />,
          title: hasActiveCriteria
            ? isRtl
              ? "لا توجد سجلات مطابقة"
              : "No matching warehouses"
            : t("warehouses.empty"),
          description: hasActiveCriteria
            ? isRtl
              ? "جرّب تعديل البحث أو الفلاتر."
              : "Try adjusting your search or filters."
            : t("warehouses.empty_hint"),
          action: (
            <button
              type="button"
              onClick={openNew}
              className="mt-2 inline-flex items-center gap-2 rounded-full bg-primary px-5 py-2.5 text-xs font-bold text-primary-foreground shadow-sm transition hover:bg-primary/90 active:scale-95"
            >
              <Plus className="size-4" />
              <span>{t("warehouses.new")}</span>
            </button>
          ),
        }}
      />

      {open && (
        <WarehouseDialog
          initial={editing}
          onClose={() => setOpen(false)}
          onSaved={() => {
            setOpen(false);
            qc.invalidateQueries({ queryKey: QUERY_KEYS.warehouses });
            qc.invalidateQueries({ queryKey: ["warehouses-admin"] });
          }}
        />
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Warehouse renderers                                                */
/* ------------------------------------------------------------------ */

interface WarehouseRendererProps {
  row: Row;
  isRtl: boolean;
  label: (r: Row) => string;
  onEdit: (row: Row) => void;
  onDelete: (id: string) => void;
  onSetDefault: (id: string) => void;
  deleting: boolean;
  editLabel: string;
  deleteLabel: string;
  setDefaultLabel: string;
  defaultLabel: string;
  activeLabel: string;
  inactiveLabel: string;
}

function WarehouseRowActions({
  row,
  onEdit,
  onDelete,
  onSetDefault,
  deleting,
  editLabel,
  deleteLabel,
  setDefaultLabel,
}: Pick<
  WarehouseRendererProps,
  | "row"
  | "onEdit"
  | "onDelete"
  | "onSetDefault"
  | "deleting"
  | "editLabel"
  | "deleteLabel"
  | "setDefaultLabel"
>) {
  return (
    <div className="flex shrink-0 items-center gap-1" onClick={(event) => event.stopPropagation()}>
      {!row.is_default && (
        <IconButton
          size="sm"
          variant="outline"
          tooltip
          ariaLabel={setDefaultLabel}
          icon={<Star className="size-3.5" />}
          round
          onClick={() => onSetDefault(row.id)}
        />
      )}
      <IconButton
        size="sm"
        variant="outline"
        tooltip
        ariaLabel={editLabel}
        icon={<Pencil className="size-3.5" />}
        round
        onClick={() => onEdit(row)}
      />
      {isSystemMainWarehouse(row) ? (
        <span
          title="المخزن الرئيسي الافتراضي — محمي من الحذف"
          className="grid size-8 place-items-center rounded-full border border-amber-500/30 bg-amber-500/10 text-amber-600 dark:text-amber-400"
        >
          <Lock className="size-3.5" />
        </span>
      ) : (
        <IconButton
          size="sm"
          variant="danger"
          tooltip
          ariaLabel={deleteLabel}
          icon={<Trash2 className="size-3.5" />}
          round
          loading={deleting}
          onClick={() => onDelete(row.id)}
        />
      )}
    </div>
  );
}

function WarehouseCard({
  row: r,
  isRtl,
  label,
  onEdit,
  onDelete,
  onSetDefault,
  deleting,
  editLabel,
  deleteLabel,
  setDefaultLabel,
  defaultLabel,
  activeLabel,
  inactiveLabel,
}: WarehouseRendererProps) {
  const secondary = isRtl ? r.name : r.name_ar;
  return (
    <div className="card-mullak group relative flex h-full flex-col justify-between rounded-2xl p-3 transition-all duration-200 hover:shadow-md sm:p-4.5">
      <div className="flex items-start gap-2.5">
        <span
          aria-hidden
          className={`h-12 w-1.5 shrink-0 rounded-full transition-all duration-300 ${
            r.is_active
              ? "bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.3)]"
              : "bg-muted-foreground/40"
          }`}
        />
        <div className="grid size-11 shrink-0 place-items-center rounded-2xl border border-primary/20 bg-primary/10 text-primary transition-transform group-hover:scale-105">
          <Warehouse className="size-5" />
        </div>
        <div className="min-w-0 flex-1">
          <h4 className="truncate text-xs font-bold text-foreground transition-colors group-hover:text-primary sm:text-sm">
            {label(r)}
          </h4>
          <div className="mt-1 flex flex-wrap items-center gap-1">
            <span
              className={`inline-flex items-center gap-1 whitespace-nowrap rounded-full border px-2 py-0.5 text-[9px] font-bold ${
                r.is_active
                  ? "bg-emerald-500/10 text-emerald-400 border-emerald-500/20"
                  : "bg-muted text-muted-foreground border-border"
              }`}
            >
              <span
                className={`size-1.5 rounded-full ${r.is_active ? "bg-emerald-500" : "bg-muted-foreground/50"}`}
              />
              {r.is_active ? activeLabel : inactiveLabel}
            </span>
            {r.is_default && (
              <span className="inline-flex items-center gap-1 whitespace-nowrap rounded-full border border-primary/25 bg-primary/10 px-2 py-0.5 text-[9px] font-bold text-primary">
                <Star className="size-2.5" />
                {defaultLabel}
              </span>
            )}
          </div>
        </div>
      </div>

      <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 text-[10px] text-muted-foreground">
        {r.code && (
          <span className="inline-flex items-center gap-1 font-mono">
            {isRtl ? "الرمز:" : "Code:"} {r.code}
          </span>
        )}
        {secondary && <span className="truncate">{secondary}</span>}
        {r.address && <span className="line-clamp-1 w-full">{r.address}</span>}
      </div>

      <div className="mt-3 flex items-center justify-end border-t border-border/60 pt-2.5">
        <WarehouseRowActions
          row={r}
          onEdit={onEdit}
          onDelete={onDelete}
          onSetDefault={onSetDefault}
          deleting={deleting}
          editLabel={editLabel}
          deleteLabel={deleteLabel}
          setDefaultLabel={setDefaultLabel}
        />
      </div>
    </div>
  );
}

function WarehouseListRow({
  row: r,
  isRtl,
  label,
  onEdit,
  onDelete,
  onSetDefault,
  deleting,
  editLabel,
  deleteLabel,
  setDefaultLabel,
  defaultLabel,
  activeLabel,
  inactiveLabel,
}: WarehouseRendererProps) {
  const secondary = isRtl ? r.name : r.name_ar;
  return (
    <div className="card-mullak group relative flex flex-col justify-between gap-3 rounded-2xl border p-3.5 transition-all duration-200 hover:border-primary/50 hover:shadow-md sm:p-4 md:flex-row md:items-center">
      <div className="flex min-w-0 flex-1 items-center gap-3">
        <span
          aria-hidden
          className={`h-11 w-1.5 shrink-0 rounded-full sm:h-12 ${
            r.is_active
              ? "bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.4)]"
              : "bg-muted-foreground/30"
          }`}
        />
        <div className="grid size-11 shrink-0 place-items-center rounded-xl border border-primary/20 bg-primary/10 text-primary transition-all group-hover:scale-105 group-hover:bg-primary group-hover:text-primary-foreground">
          <Warehouse className="size-5" />
        </div>
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-2">
            <h4 className="truncate text-sm font-bold leading-snug text-foreground">{label(r)}</h4>
            <span
              className={`inline-flex items-center gap-1 whitespace-nowrap rounded-full border px-2 py-0.5 text-[9px] font-bold ${
                r.is_active
                  ? "bg-emerald-500/10 text-emerald-400 border-emerald-500/20"
                  : "bg-muted text-muted-foreground border-border"
              }`}
            >
              {r.is_active ? activeLabel : inactiveLabel}
            </span>
            {r.is_default && (
              <span className="inline-flex items-center gap-1 whitespace-nowrap rounded-full border border-primary/25 bg-primary/10 px-2 py-0.5 text-[9px] font-bold text-primary">
                <Star className="size-2.5" />
                {defaultLabel}
              </span>
            )}
          </div>
          <div className="mt-1 flex flex-wrap items-center gap-2 text-[11px] text-muted-foreground">
            {r.code && <span className="font-mono">{r.code}</span>}
            {secondary && <span className="truncate">{secondary}</span>}
            {r.address && <span className="truncate">— {r.address}</span>}
          </div>
        </div>
      </div>

      <WarehouseRowActions
        row={r}
        onEdit={onEdit}
        onDelete={onDelete}
        onSetDefault={onSetDefault}
        deleting={deleting}
        editLabel={editLabel}
        deleteLabel={deleteLabel}
        setDefaultLabel={setDefaultLabel}
      />
    </div>
  );
}

const inputCls =
  "h-9 w-full rounded-md border border-border bg-surface px-3 text-sm text-foreground outline-none focus:border-primary/60 focus:ring-1 focus:ring-primary/30 transition";

function WarehouseDialog({
  initial,
  onClose,
  onSaved,
}: {
  initial: Row | null;
  onClose: () => void;
  onSaved: () => void;
}) {
  const { t } = useI18n();
  const [form, setForm] = useState({
    name: initial?.name ?? "",
    name_ar: initial?.name_ar ?? "",
    code: initial?.code ?? "",
    address: initial?.address ?? "",
    is_default: initial?.is_default ?? false,
    is_active: initial?.is_active ?? true,
  });
  const [saving, setSaving] = useState(false);

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    if (!form.name_ar.trim() && !form.name.trim()) {
      toast.error(t("catalog.name_required"));
      return;
    }
    if (initial?.is_default) {
      if (!form.is_active) {
        toast.error("لا يمكن إلغاء تفعيل المخزن الافتراضي للنظام.");
        return;
      }
      if (!form.is_default) {
        toast.error("لا يمكن إلغاء افتراضية هذا المخزن؛ قم بتعيين مخزن آخر كافتراضي أولاً.");
        return;
      }
    }
    setSaving(true);
    try {
      const payload = {
        name: form.name.trim() || form.name_ar.trim(),
        name_ar: form.name_ar.trim() || null,
        code: form.code.trim() || null,
        address: form.address.trim() || null,
        is_default: form.is_default,
        is_active: form.is_active,
      };
      if (form.is_default) {
        await supabase
          .from("warehouses")
          .update({ is_default: false })
          .neq("id", initial?.id ?? "00000000-0000-0000-0000-000000000000");
      }
      const { error } = initial
        ? await supabase.from("warehouses").update(payload).eq("id", initial.id)
        : await supabase.from("warehouses").insert(payload);
      if (error) {
        toast.error(error.message);
        return;
      }
      toast.success(t("common.saved") || "Saved");
      onSaved();
    } finally {
      setSaving(false);
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 grid place-items-center bg-black/60 backdrop-blur-sm p-4"
      onClick={onClose}
    >
      <form
        onSubmit={submit}
        onClick={(e) => e.stopPropagation()}
        className="panel-elevated w-full max-w-lg overflow-hidden"
      >
        <div className="flex items-center justify-between border-b border-border px-5 py-3">
          <h2 className="text-sm font-semibold text-foreground">
            {initial ? t("warehouses.edit") : t("warehouses.new")}
          </h2>
          <button
            type="button"
            onClick={onClose}
            className="grid h-7 w-7 place-items-center rounded-md text-muted-foreground hover:bg-accent"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
        <div className="grid grid-cols-1 gap-3 p-5 sm:grid-cols-2">
          <Field label={`${t("warehouses.name_ar")} *`}>
            <input
              value={form.name_ar}
              onChange={(e) => setForm({ ...form, name_ar: e.target.value })}
              className={inputCls}
              dir="rtl"
              required
            />
          </Field>
          <Field label={t("warehouses.name")}>
            <input
              value={form.name}
              onChange={(e) => setForm({ ...form, name: e.target.value })}
              className={inputCls}
            />
          </Field>
          <Field label={t("warehouses.code")}>
            <input
              value={form.code}
              onChange={(e) => setForm({ ...form, code: e.target.value })}
              className={inputCls}
            />
          </Field>
          <Field label={t("common.status")}>
            <label className="flex h-9 items-center gap-2 rounded-md border border-border bg-surface px-3 text-sm">
              <input
                type="checkbox"
                checked={form.is_active}
                onChange={(e) => setForm({ ...form, is_active: e.target.checked })}
              />
              <span className="text-muted-foreground">{t("common.active")}</span>
            </label>
          </Field>
          <Field label={t("warehouses.address")} className="sm:col-span-2">
            <input
              value={form.address}
              onChange={(e) => setForm({ ...form, address: e.target.value })}
              className={inputCls}
            />
          </Field>
          <Field label={t("warehouses.is_default")} className="sm:col-span-2">
            <label className="flex h-9 items-center gap-2 rounded-md border border-border bg-surface px-3 text-sm">
              <input
                type="checkbox"
                checked={form.is_default}
                onChange={(e) => setForm({ ...form, is_default: e.target.checked })}
              />
              <span className="text-muted-foreground">{t("warehouses.set_default")}</span>
            </label>
          </Field>
        </div>
        <div className="flex items-center justify-end gap-2 border-t border-border bg-surface/40 px-5 py-3">
          <button
            type="button"
            onClick={onClose}
            className="flex h-9 items-center rounded-md border border-border bg-surface px-3 text-xs font-medium text-muted-foreground hover:text-foreground transition"
          >
            {t("common.cancel")}
          </button>
          <button
            type="submit"
            disabled={saving}
            className="flex h-9 items-center rounded-md bg-primary px-4 text-xs font-medium text-primary-foreground hover:opacity-90 transition disabled:opacity-50"
          >
            {saving ? t("common.saving") : t("common.save")}
          </button>
        </div>
      </form>
    </div>
  );
}

function Field({
  label,
  children,
  className = "",
}: {
  label: string;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <label className={`flex flex-col gap-1.5 ${className}`}>
      <span className="text-[11px] font-medium uppercase tracking-wider text-muted-foreground">
        {label}
      </span>
      {children}
    </label>
  );
}
